const fs = require('fs');
const path = require('path');

const now = new Date().toISOString();
const sessionId = msg.sessionId || msg.submission?.sessionId || msg._msgid || msg.msgid;

if (!sessionId) {
    node.error('Falta sessionId');
    return null;
}

const storeDir = msg.projectDocsDir || path.join(
    '/internal-storage-files/files',
    'codex-workspace',
    sessionId,
    'codex-docs'
);

const STORE_PATH = path.join(storeDir, 'SESSION_STATE.json');
const TMP_PATH = path.join(storeDir, 'SESSION_STATE.tmp');

fs.mkdirSync(storeDir, { recursive: true });

function deepMerge(target, source) {
    if (!source || typeof source !== 'object' || Array.isArray(source)) return target;

    for (const key of Object.keys(source)) {
        const value = source[key];
        if (value === undefined) continue;

        if (value && typeof value === 'object' && !Array.isArray(value)) {
            if (!target[key] || typeof target[key] !== 'object' || Array.isArray(target[key])) {
                target[key] = {};
            }
            deepMerge(target[key], value);
        } else {
            target[key] = value;
        }
    }

    return target;
}

/** @type {any} */
let state = {};

try {
    if (fs.existsSync(STORE_PATH)) {
        const raw = fs.readFileSync(STORE_PATH, 'utf8').trim();
        state = raw ? JSON.parse(raw) : {};
    }
} catch (err) {
    node.warn('No se pudo leer store previo: ' + err.message);
    state = {};
}

if (!state || typeof state !== 'object' || Array.isArray(state)) {
    state = {};
}

state._id = sessionId;
state.sessionId = sessionId;
if (!state.createdAt) state.createdAt = now;
state.updatedAt = now;

if (msg._sessionCheckpoint) {
    state.lastCheckpoint = msg._sessionCheckpoint;
    state.timeline = Array.isArray(state.timeline) ? state.timeline : [];
    state.timeline.push({ checkpoint: msg._sessionCheckpoint, ts: now });
    if (state.timeline.length > 300) {
        state.timeline = state.timeline.slice(-300);
    }
}

deepMerge(state, msg._sessionPatch || {});

// Escritura atómica básica
fs.writeFileSync(TMP_PATH, JSON.stringify(state, null, 2), 'utf8');
fs.renameSync(TMP_PATH, STORE_PATH);

msg.sessionState = state;
msg.sessionStatePath = STORE_PATH;
msg.payload = state;

return msg;

