const fs = require('fs');
const path = require('path');

const projectPath = msg.projectPath;
const projectDocsDir = path.join(projectPath, 'codex-docs');

if (!projectPath || !fs.existsSync(projectDocsDir)) {
    node.error('Faltan projectPath o codex-docs');
    return null;
}

const selectedSources = Array.isArray(msg.selectedSources) && msg.selectedSources.length ? msg.selectedSources : [String(msg.sourceType || 'processed')];
const sourceType = selectedSources.length > 1 ? 'mixed' : selectedSources[0];
const manifestPath = msg.manifestPath || path.join(projectDocsDir, 'MANIFEST.json');
const mergedInputPath = msg.mergedInputPath || path.join(projectPath, 'merged');
const inputBreakdown = msg.inputBreakdown || msg.sourceSummary || {};
let manifest = null;
try { if (fs.existsSync(manifestPath)) manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8')); } catch (e) { node.warn(`⚠️ No se pudo leer MANIFEST.json: ${e.message}`); }

node.warn('📋 Generando índice del proyecto y contexto persistente con fuentes unificadas...');

function scanDirectory(dir, relativePath = '', maxDepth = 15, currentDepth = 0) {
    if (!dir || !fs.existsSync(dir) || currentDepth >= maxDepth) return [];
    const files = [];
    const IGNORE_DIRS = ['.git', 'node_modules', 'target', 'build', '.codex', 'dist', 'out', '.idea', '.vscode'];
    const RELEVANT_EXTS = ['.java', '.js', '.ts', '.py', '.go', '.xml', '.yml', '.yaml', '.json', '.properties', '.md', '.sql', '.sh', '.bat', '.pdf', '.csv', '.txt', '.docx', '.pptx', '.xlsx'];
    try {
        const items = fs.readdirSync(dir, { withFileTypes: true });
        for (const item of items) {
            if (IGNORE_DIRS.includes(item.name)) continue;
            const fullPath = path.join(dir, item.name);
            const relPath = path.join(relativePath, item.name);
            if (item.isDirectory()) {
                files.push({ type: 'directory', path: relPath, name: item.name });
                files.push(...scanDirectory(fullPath, relPath, maxDepth, currentDepth + 1));
            } else if (item.isFile()) {
                const ext = path.extname(item.name).toLowerCase();
                if (RELEVANT_EXTS.includes(ext)) {
                    const stats = fs.statSync(fullPath);
                    files.push({ type: 'file', path: relPath.replace(/\\/g, '/'), absolutePath: fullPath, name: item.name, extension: ext, size: stats.size, modified: stats.mtime.toISOString() });
                }
            }
        }
    } catch (error) { node.warn(`⚠️ Error escaneando ${dir}: ${error.message}`); }
    return files;
}

const projectFiles = scanDirectory(projectPath);
const mergedFiles = scanDirectory(mergedInputPath);
const mainFiles = projectFiles.filter(f => f.type === 'file' && (f.name.includes('Configuration') || f.name.includes('Mapper') || f.name.includes('Repository') || f.name.includes('Controller') || f.name.includes('Service') || f.name.includes('Constantes') || f.name === 'pom.xml' || f.name === 'package.json' || f.name === 'requirements.txt' || f.name === 'go.mod'));
const projectType = mergedFiles.length ? 'Reference generation workspace' : (projectFiles.some(f => f.name === 'pom.xml') ? 'Maven/Java' : projectFiles.some(f => f.name === 'package.json') ? 'Node.js' : projectFiles.some(f => f.name === 'requirements.txt') ? 'Python' : projectFiles.some(f => f.name === 'go.mod') ? 'Go' : 'Unknown');
const modules = [...new Set(projectFiles.filter(f => f.type === 'directory' && f.path.split('/').length === 1).map(f => f.name))];

const markdownDir = msg.projectMarkdownDir || msg.mergedInputPath || path.join(projectPath, 'merged');
let dtFiles = [];
let tasks = [];
if (fs.existsSync(markdownDir)) {
    dtFiles = fs.readdirSync(markdownDir).filter(f => f.endsWith('.md'));
    if (dtFiles.length > 0) {
        const dtPath = path.join(markdownDir, dtFiles[0]);
        let dtContent = fs.readFileSync(dtPath, 'utf8');
        const taskMatches = dtContent.matchAll(/(?:^|\n)(?:###?\s+)?Tarea\s+(\d+)[.:]\s+(.+?)(?=\n)/gi);
        for (const match of taskMatches) tasks.push({ id: parseInt(match[1]), title: match[2].trim() });
    }
}

const sourceFiles = mergedFiles.filter(f => f.type === 'file').map(f => ({ name: f.name, path: f.absolutePath, relativePath: f.path, size: f.size, modified: f.modified, source: manifest?.finalFiles?.find(x => x.logicalName === f.path)?.source || null }));

const projectIndex = {
    generated: new Date().toISOString(),
    projectName: path.basename(projectPath),
    projectPath,
    projectType,
    sourceType,
    selectedSources,
    manifestPath,
    mergedInputPath,
    inputBreakdown,
    manifestStats: manifest?.stats || null,
    structure: {
        directories: projectFiles.filter(f => f.type === 'directory').map(f => f.path),
        files: projectFiles.filter(f => f.type === 'file').map(f => ({ path: f.path, size: f.size, type: f.extension }))
    },
    mainFiles: mainFiles.map(f => ({ path: f.path, name: f.name, type: f.extension })),
    modules,
    documentation: { dtFiles, tasksIdentified: tasks.length, sourceFiles, mergedFiles: sourceFiles },
    stats: {
        totalFiles: projectFiles.filter(f => f.type === 'file').length,
        totalDirectories: projectFiles.filter(f => f.type === 'directory').length,
        mergedFiles: sourceFiles.length,
        sourceFiles: sourceFiles.length,
        conflicts: manifest?.stats?.totalConflicts || 0
    }
};

const indexPath = path.join(projectDocsDir, 'PROJECT_INDEX.json');
fs.writeFileSync(indexPath, JSON.stringify(projectIndex, null, 2));

const contextPath = path.join(projectDocsDir, 'CONTEXT.json');
const persistentContext = {
    created: new Date().toISOString(),
    lastUpdated: new Date().toISOString(),
    projectType,
    sourceType,
    selectedSources,
    sourceSummary: inputBreakdown,
    manifestPath,
    mergedInputPath,
    inputBreakdown,
    sessionId: msg.sessionId || msg.submission?.sessionId || null,
    phases: { planning: { status: 'pending', startTime: null, endTime: null }, implementation: { status: 'pending', startTime: null, endTime: null } },
    filesRead: {}, tasksCompleted: [], filesModified: [], commandsExecuted: [],
    metrics: { totalCommands: 0, planningTime: 0, implementationTime: 0, totalTokens: 0 }
};
fs.writeFileSync(contextPath, JSON.stringify(persistentContext, null, 2));

node.warn('✅ Índice y contexto generados:');
node.warn(`   📦 Fuentes: ${selectedSources.join(', ')}`);
node.warn(`   📎 merged-files: ${sourceFiles.length}`);
node.warn(`   💾 MANIFEST.json: ${manifestPath}`);
node.warn(`   💾 PROJECT_INDEX.json: ${indexPath}`);
node.warn(`   💾 CONTEXT.json: ${contextPath}`);

msg.projectIndex = projectIndex;
msg.projectIndexPath = indexPath;
msg.contextPath = contextPath;
msg.projectType = projectType;
return msg;

