const fs = require('fs');
const path = require('path');

function resolveSessionId(msg) {
    return (
        msg.sessionId ||
        msg.submission?.sessionId ||
        msg.onInitSubmission?.sessionId ||
        msg.payload?.sessionId ||
        null
    );
}

function resolveProjectPath(msg, sessionId) {
    return path.resolve(
        msg.projectPath ||
        msg.submission?.projectPath ||
        msg.onInitSubmission?.projectPath ||
        path.join('/internal-storage-files/files', 'codex-workspace', sessionId || '')
    );
}

function isWithin(basePath, targetPath) {
    const rel = path.relative(basePath, targetPath);
    return rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel));
}

function normalizeName(value) {
    return String(value || '').trim().toLowerCase();
}

const sessionId = resolveSessionId(msg);
const projectPath = resolveProjectPath(msg, sessionId);

if (!sessionId || !projectPath || !fs.existsSync(projectPath)) {
    node.warn('⚠️ Cleanup omitido: falta sessionId/projectPath o no existe el workspace');
    return msg;
}

const projectDocsDir = path.resolve(path.join(projectPath, 'codex-docs'));
const deleted = [];
const skipped = [];
const kept = [];
const errors = [];

const KEEP_ROOT_FILE_REGEX = /^codex-unified.*\.log$/i;

const KEEP_ROOT_DIRS = new Set([
    'codex-docs'
]);

const KEEP_CODEX_DOCS_FILES = new Set([
    'execution_report.md',
    'plan.md',
    'session_state.json'
]);

const KEEP_CODEX_DOCS_DIRS = new Set([
    'output'
]);

function safeRemove(targetPath) {
    const absPath = path.resolve(targetPath);

    if (!isWithin(projectPath, absPath)) {
        errors.push(`Fuera del workspace: ${absPath}`);
        return;
    }

    if (!fs.existsSync(absPath)) {
        skipped.push(path.relative(projectPath, absPath));
        return;
    }

    try {
        const stat = fs.statSync(absPath);

        if (stat.isDirectory()) {
            fs.rmSync(absPath, { recursive: true, force: true });
        } else {
            fs.unlinkSync(absPath);
        }

        deleted.push(path.relative(projectPath, absPath));
    } catch (err) {
        errors.push(`${path.relative(projectPath, absPath)} -> ${err.message}`);
    }
}

function keep(targetPath) {
    kept.push(path.relative(projectPath, path.resolve(targetPath)) || '.');
}

// 1. Limpieza estricta de la raíz del workspace.
//    Se conserva únicamente:
//    - codex-unified*.log
//    - codex-docs/ para filtrar dentro después
try {
    const rootEntries = fs.readdirSync(projectPath, { withFileTypes: true });

    for (const entry of rootEntries) {
        const name = entry.name;
        const fullPath = path.join(projectPath, name);

        if (entry.isFile()) {
            if (KEEP_ROOT_FILE_REGEX.test(name)) {
                keep(fullPath);
                continue;
            }

            safeRemove(fullPath);
            continue;
        }

        if (entry.isDirectory()) {
            if (KEEP_ROOT_DIRS.has(name)) {
                keep(fullPath);
                continue;
            }

            // Esto borra input/, merged/, logs/, .codex/, batches temporales,
            // prompts, snapshots y cualquier otra carpeta de trabajo.
            safeRemove(fullPath);
            continue;
        }

        // Symlinks u otros tipos: eliminarlos salvo que sean el unified log, que no aplica aquí.
        safeRemove(fullPath);
    }
} catch (err) {
    errors.push(`Listado root -> ${err.message}`);
}

// 2. Limpieza estricta dentro de codex-docs.
//    Se conserva únicamente:
//    - EXECUTION_REPORT.md
//    - PLAN.md
//    - SESSION_STATE.json
//    - output/
try {
    if (fs.existsSync(projectDocsDir)) {
        const docEntries = fs.readdirSync(projectDocsDir, { withFileTypes: true });

        for (const entry of docEntries) {
            const name = entry.name;
            const fullPath = path.join(projectDocsDir, name);
            const normalizedName = normalizeName(name);

            if (entry.isFile()) {
                if (KEEP_CODEX_DOCS_FILES.has(normalizedName)) {
                    keep(fullPath);
                    continue;
                }

                safeRemove(fullPath);
                continue;
            }

            if (entry.isDirectory()) {
                if (KEEP_CODEX_DOCS_DIRS.has(normalizedName)) {
                    keep(fullPath);
                    continue;
                }

                // Borra markdown/, batches/, notes/, debug/, source-files/,
                // conversiones temporales y cualquier carpeta residual.
                // IMPORTANTE: conserva output/.
                safeRemove(fullPath);
                continue;
            }

            // Symlinks u otros tipos: eliminarlos.
            safeRemove(fullPath);
        }
    } else {
        skipped.push(path.relative(projectPath, projectDocsDir));
    }
} catch (err) {
    errors.push(`Listado codex-docs -> ${err.message}`);
}

msg.cleanupSummary = {
    sessionId,
    projectPath,
    kept,
    deleted,
    skipped,
    errors,
    keptCount: kept.length,
    deletedCount: deleted.length,
    errorCount: errors.length,
    policy: {
        root: 'keep only codex-unified*.log and codex-docs/',
        codexDocs: 'keep EXECUTION_REPORT.md, PLAN.md, SESSION_STATE.json and output/'
    }
};

node.warn(`🧹 Cleanup final completado | conservados=${kept.length} | borrados=${deleted.length} | errores=${errors.length}`);

if (kept.length) {
    node.warn(`✅ Conservados: ${kept.join(', ')}`);
}
if (deleted.length) {
    node.warn(`🗑️ Eliminados: ${deleted.join(', ')}`);
}
if (errors.length) {
    node.warn(`⚠️ Errores cleanup: ${errors.join(' | ')}`);
}

return msg;

