        msg.onInitSubmission?.projectPath ||
        msg.submission?.projectPath ||
        msg.projectPath ||
        (sessionId ? path.join('/internal-storage-files/files', 'codex-workspace', sessionId) : null);

    const sessionStatePath =
        sessionId && projectPath
            ? path.join(projectPath, 'codex-docs', 'SESSION_STATE.json')
            : null;

    let state = null;
    try {
        if (sessionStatePath && fs.existsSync(sessionStatePath)) {
            const raw = fs.readFileSync(sessionStatePath, 'utf8').trim();
            state = raw ? JSON.parse(raw) : null;
        }
    } catch (err) {
        node.warn(`⚠️ No se pudo leer SESSION_STATE.json: ${err.message}`);
    }

