}


const projectCodexDir = path.join(projectPath, '.codex');
const authFilePath = path.join(projectCodexDir, 'auth.json');

// ==========================================
// FUNCIONES AUXILIARES
// ==========================================

function parseUrl(urlString) {
    const url = require('url');
    return url.parse(urlString);
}

function httpRequest(urlString, options) {
    return new Promise((resolve, reject) => {
        const https = require('https');
        const urlParsed = parseUrl(urlString);

        const requestOptions = {
            hostname: urlParsed.hostname,
            port: urlParsed.port || 443,
            path: urlParsed.path || '/',
            method: options.method || 'GET',
            headers: options.headers || {}
        };

        const req = https.request(requestOptions, (res) => {
            let data = '';
            res.on('data', (chunk) => { data += chunk; });
            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    resolve(data);
                } else {
                    reject(new Error(`HTTP ${res.statusCode}: ${data}`));
                }
            });
        });

        req.on('error', reject);
        if (options.body) req.write(options.body);
        req.end();
    });
}

function createFormBody(params) {
    return Object.keys(params)
        .map(key => encodeURIComponent(key) + '=' + encodeURIComponent(params[key]))
        .join('&');
}

async function refreshAccessToken(issuer, clientId, refreshToken) {
    const tokenUrl = `${issuer}/v1/token`;

    const body = createFormBody({
        grant_type: 'refresh_token',
        refresh_token: refreshToken,
        client_id: clientId,
        scope: 'offline_access openid email'
    });

    try {
        const response = await httpRequest(tokenUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: body
        });

        return JSON.parse(response);
    } catch (error) {
        throw new Error(`Failed to refresh token: ${error.message}`);
    }
}

// ==========================================
// LÓGICA PRINCIPAL
// ==========================================

if (!fs.existsSync(authFilePath)) {
    node.error('❌ auth.json no encontrado');
    msg.statusCode = 500;
    msg.payload = { error: 'auth.json not found' };
    return msg;
}

try {
    const authData = JSON.parse(fs.readFileSync(authFilePath, 'utf8'));

    if (!authData.tokens || !authData.tokens.refresh_token) {
        throw new Error('No refresh_token found in auth.json');
    }

    const oldRefreshToken = authData.tokens.refresh_token;
    const accountId = authData.tokens.account_id;

    node.warn('📖 auth.json leído correctamente');
    node.warn(`   Account ID: ${accountId}`);
    node.warn(`   Last refresh: ${authData.last_refresh || 'never'}`);

    const securityContext = msg.__axetFlowsSecurityContext;
    const idpInfo = securityContext?.externalIdpUserInfo;

    if (!idpInfo || !idpInfo.iss || !idpInfo.cid) {
        throw new Error('Missing Okta configuration in security context');
    }

    const issuer = idpInfo.iss;
    const clientId = idpInfo.cid;

    node.warn('🔄 Renovando tokens con Okta...');
    node.warn(`   Issuer: ${issuer}`);
    node.warn(`   Client ID: ${clientId}`);
    node.status({ fill: 'blue', shape: 'ring', text: 'renovando...' });

    const tokenResponse = await refreshAccessToken(issuer, clientId, oldRefreshToken);

    const newAuthData = {
        OPENAI_API_KEY: authData.OPENAI_API_KEY || null,
        tokens: {
            id_token: tokenResponse.id_token || authData.tokens.id_token,
            access_token: tokenResponse.access_token,
            refresh_token: tokenResponse.refresh_token || oldRefreshToken,
            account_id: accountId
        },
        last_refresh: new Date().toISOString()
    };

    fs.writeFileSync(authFilePath, JSON.stringify(newAuthData, null, 2), {
        encoding: 'utf8',
        mode: 0o600
    });

    node.warn('✅ auth.json actualizado');
    node.warn(`   Expires in: ${tokenResponse.expires_in}s (${Math.floor(tokenResponse.expires_in / 60)} min)`);
    node.status({ fill: 'green', shape: 'dot', text: 'renovado' });

    if (securityContext && idpInfo) {
        idpInfo.access_token = tokenResponse.access_token;
        idpInfo.id_token = tokenResponse.id_token || idpInfo.id_token;
        if (tokenResponse.refresh_token) {
            idpInfo.refresh_token = tokenResponse.refresh_token;
        }
        if (tokenResponse.expires_in) {
            idpInfo.exp = Math.floor(Date.now() / 1000) + tokenResponse.expires_in;
        }
        securityContext.sessionUpdated = Date.now();
    }

    msg.tokensRefreshed = true;
    msg.tokenExpiresIn = tokenResponse.expires_in;

    return msg;

} catch (error) {
    const errorMsg = String(error.message || '');

    if (errorMsg.includes('HTTP 429')) {
        node.warn(`⚠️ Rate limit de Okta al renovar token: ${errorMsg}`);
        node.status({ fill: 'yellow', shape: 'ring', text: 'rate limit, sigo con token actual' });

        msg.tokensRefreshed = false;
        msg.skippedReason = 'Rate limited by Okta';
        msg.tokenRefreshRateLimited = true;
        return msg;
    }

    node.error(`❌ Error renovando tokens: ${errorMsg}`);
    node.status({ fill: 'red', shape: 'ring', text: 'error' });

    msg.statusCode = 500;
    msg.payload = {
        error: 'Token refresh failed',
        details: errorMsg
    };
    msg.tokensRefreshed = false;

    return msg;
}

