            method: options.method || 'GET',
            headers: options.headers || {}
        };

        const req = https.request(requestOptions, (res) => {
            let data = '';
            res.on('data', (chunk) => { data += chunk; });
            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    resolve(data);
                } else {
                    reject(new Error(`HTTP ${res.statusCode}: ${data}`));
                }
            });
        });

        req.setTimeout(20000, () => {
            req.destroy(new Error('HTTP timeout after 20s'));
        });

        req.on('error', reject);
        if (options.body) req.write(options.body);
        req.end();
    });
}

function createFormBody(params) {
    return Object.keys(params)
        .map(key => encodeURIComponent(key) + '=' + encodeURIComponent(params[key]))
        .join('&');
}

async function refreshAccessToken(issuer, clientId, refreshToken) {
    const tokenUrl = `${issuer}/v1/token`;

    const body = createFormBody({
        grant_type: 'refresh_token',
        refresh_token: refreshToken,
        client_id: clientId,
        scope: 'offline_access openid email'
    });

    const response = await httpRequest(tokenUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: body
    });

    return JSON.parse(response);
}

