    const lastRefresh = new Date(authData.last_refresh || 0);
    const secondsSinceRefresh = (Date.now() - lastRefresh.getTime()) / 1000;

    const MIN_REFRESH_INTERVAL_SECONDS = 10 * 60;

    if (secondsSinceRefresh < MIN_REFRESH_INTERVAL_SECONDS) {
        node.warn(`⏭️ Tokens renovados hace ${Math.floor(secondsSinceRefresh)}s - saltando renovación`);
        node.status({ fill: 'green', shape: 'dot', text: 'tokens frescos' });

        msg.tokensRefreshed = false;
        msg.skippedReason = 'Recently refreshed';
        return msg;
    }
}

