    }

    node.warn('🔄 Renovando tokens con Okta...');
    node.status({ fill: 'blue', shape: 'ring', text: 'renovando...' });

    const tokenResponse = await refreshAccessToken(idpInfo.iss, idpInfo.cid, oldRefreshToken);

    const newAuthData = {
        OPENAI_API_KEY: authData.OPENAI_API_KEY || null,
        tokens: {
            id_token: tokenResponse.id_token || authData.tokens.id_token,
            access_token: tokenResponse.access_token,
            refresh_token: tokenResponse.refresh_token || oldRefreshToken,
            account_id: accountId
        },
        last_refresh: new Date().toISOString()
    };

    fs.writeFileSync(authFilePath, JSON.stringify(newAuthData, null, 2), {
        encoding: 'utf8',
        mode: 0o600
    });

    node.warn(`✅ auth.json actualizado | expires=${tokenResponse.expires_in}s`);
    node.status({ fill: 'green', shape: 'dot', text: 'renovado' });

    if (securityContext && idpInfo) {
