  const line = '[' + nowIso() + '] ' + String(message || '') + '\n';

  if (job && job.workerLogPath) {
    appendFileSafe(job.workerLogPath, line);
  }

  writeUnifiedLog(message, source || 'WORKER', level || 'INFO');
}

function writeBatchLog(message) {
  if (!job || !job.batchLogPath) return;
  appendFileSafe(job.batchLogPath, String(message || ''));
}

function initBatchLog() {
  try {
    fs.writeFileSync(job.batchLogPath, '', 'utf8');
  } catch (e) {
    writeWorkerLog('batchLog init failed: ' + e.message, 'WORKER', 'ERROR');
  }
}

function writeCodexOutputToLogs(chunk, source) {
  const raw = String(chunk || '');
  if (!raw) return;

  const lines = raw.split(/\r?\n/);

  if (source === 'STDOUT') {
    writeBatchLog(raw);
  }

  if (source === 'STDERR') {
    for (const line of lines) {
      if (!line || !line.trim()) continue;
      const cleanLine = stripAnsi(line);
      writeBatchLog('[STDERR] ' + cleanLine + '\n');
    }
  }

  for (const line of lines) {
    if (!line || !line.trim()) continue;

    const cleanLine = stripAnsi(line);
    const level = source === 'STDERR' ? 'WARN' : 'TRACE';

    writeUnifiedLog(cleanLine, source, level);
  }
}

function persistExecutionPatch(checkpoint, patch) {
  try {
    let state = readJson(job.storePath) || {};

    if (!state || typeof state !== 'object' || Array.isArray(state)) {
      state = {};
    }

    state._id = job.sessionId;
    state.sessionId = job.sessionId;

    if (!state.createdAt) {
      state.createdAt = nowIso();
    }

    state.updatedAt = nowIso();
    state.lastCheckpoint = checkpoint;

    state.timeline = Array.isArray(state.timeline) ? state.timeline : [];
    state.timeline.push({
      checkpoint: checkpoint,
      ts: nowIso()
    });

    if (state.timeline.length > 300) {
      state.timeline = state.timeline.slice(-300);
    }

    deepMerge(state, patch || {});
    writeJsonAtomic(job.storePath, state);
  } catch (e) {
    writeWorkerLog('persist error: ' + e.message, 'WORKER', 'ERROR');
  }
}

function isManualStopRequested(state) {
  return state && (
    state.execution?.stopRequested === true ||
    state.execution?.reason === 'manual-stop' ||
    state.runtime?.manualStop === true
  );
}

function countTasksFromPlan(content) {
  const pending = (content.match(/^\s*(?:[-*]\s*)?\[\s*\]\s+/gim) || []).length;
  const done = (content.match(/^\s*(?:[-*]\s*)?\[[xX]\]\s+/gim) || []).length;

  return {
    pending: pending,
    done: done,
    total: pending + done
  };
}

function readPlanCountsSafe() {
  try {
    return countTasksFromPlan(fs.readFileSync(job.planPath, 'utf8'));
  } catch (_) {
    return {
      pending: 0,
      done: 0,
      total: 0
    };
  }
}

function killChildTree(pid) {
  if (!pid) return;

  try {
    if (job.isWin) {
      spawn('taskkill', ['/PID', String(pid), '/T', '/F'], {
        detached: true,
        stdio: 'ignore'
      }).unref();
    } else {
      spawn(
        'sh',
        [
          '-c',
          'pkill -TERM -P ' + pid + ' 2>/dev/null; ' +
          'kill -TERM ' + pid + ' 2>/dev/null; ' +
          'sleep 4; ' +
          'pkill -KILL -P ' + pid + ' 2>/dev/null; ' +
          'kill -KILL ' + pid + ' 2>/dev/null'
        ],
        {
          detached: true,
          stdio: 'ignore'
        }
      ).unref();
    }
  } catch (e) {
    writeWorkerLog('kill error: ' + e.message, 'WORKER', 'ERROR');
  }
}

function writeDone(exitCode, extra) {
  if (doneWritten || !job) return;

  doneWritten = true;

  const counts = readPlanCountsSafe();
  const endedAt = nowIso();
  const elapsed = Number(((Date.now() - startTime) / 1000).toFixed(2));

  const marker = Object.assign({
    sessionId: job.sessionId,
    batchIteration: job.batchIteration,
    exitCode: exitCode,
    startedAt: job.startedAt,
    endedAt: endedAt,
    elapsedBatchSeconds: elapsed,
    tasksDone: counts.done,
    tasksTotal: counts.total,
    tasksRemaining: counts.pending,
    codexSessionId: job.codexSessionId || null,
    batchLogPath: job.batchLogPath,
    workerLogPath: job.workerLogPath,
    jobPath: jobPath
  }, extra || {});

  try {
    writeJsonAtomic(job.donePath, marker);
  } catch (e) {
    writeWorkerLog('done write error: ' + e.message, 'WORKER', 'ERROR');
  }
}

function updateTasksFromPlan(reason) {
  const c = readPlanCountsSafe();

  if (c.total <= 0) return c;

  const p = Math.max(1, Math.min(99, Math.round((c.done / c.total) * 100)));

  persistExecutionPatch('implementation-worker-plan-sync', {
    runtime: {
      status: 'Implementando: ' + c.done + '/' + c.total + ' tareas...',
      progress: p,
      completed: false,
      success: false
    },
    tasksLive: {
      completed: c.done,
      total: c.total,
      remaining: c.pending,
      batch: job.batchIteration,
      timestamp: nowIso(),
      source: reason || 'worker'
    },
    tasks: {
      completed: c.done,
      total: c.total,
      remaining: c.pending,
      batch: job.batchIteration,
      live: true
    }
  });

  return c;
}

function tryCaptureCodexSessionId(cleanText) {
  if (job.codexSessionId) return;

  const m = cleanText.match(/session\s*id:\s*([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})/i);
  if (!m) return;

  job.codexSessionId = m[1];

  writeUnifiedLog('Session ID capturado: ' + job.codexSessionId, 'CODEX', 'SUCCESS');

  try {
    const ctx = readJson(job.contextPath) || {};
    ctx.codexSessionId = job.codexSessionId;
    fs.writeFileSync(job.contextPath, JSON.stringify(ctx, null, 2), 'utf8');
  } catch (_) { }

  persistExecutionPatch('implementation-session-captured', {
    execution: {
      codexSessionId: job.codexSessionId,
      batchIteration: job.batchIteration
    }
  });
}

function cleanupTimers() {
  if (planPoller) {
    clearInterval(planPoller);
    planPoller = null;
  }

  if (stopPoller) {
    clearInterval(stopPoller);
    stopPoller = null;
  }
}

process.on('uncaughtException', function (err) {
  try {
    cleanupTimers();

    if (job) {
      writeWorkerLog('uncaughtException: ' + err.stack, 'WORKER', 'ERROR');

      persistExecutionPatch('implementation-worker-error', {
        runtime: {
          status: 'Worker error: ' + err.message,
          completed: true,
          success: false,
          error: err.message
        },
        execution: {
          stopped: true,
          finished: true,
          reason: 'worker-error',
          workerPid: process.pid
        }
      });

      writeDone(98, {
        workerError: err.message
      });
    }
  } finally {
    process.exit(0);
  }
});

