    const requestedSessionId =
        msg.onInitSubmission?.sessionId ||
        msg.submission?.sessionId ||
        msg.req?.query?.sessionId ||
        msg.payload?.data?.sessionId ||
        msg.payload?.sessionId ||
        msg.sessionId ||
        null;

    const requestedProjectPath =
        msg.onInitSubmission?.projectPath ||
        msg.submission?.projectPath ||
        msg.payload?.data?.projectPath ||
        msg.payload?.projectPath ||
        msg.projectPath ||
        (requestedSessionId ? path.join(FILES_ROOT, 'codex-workspace', requestedSessionId) : null);

    const activeSessionId = activeInfo.active?.sessionId || null;
    const activeProjectPath =
        activeInfo.active?.projectPath ||
        (activeSessionId ? path.join(FILES_ROOT, 'codex-workspace', activeSessionId) : null);

    const sessionId = activeSessionId || requestedSessionId;
    const projectPath =
        activeProjectPath ||
        requestedProjectPath ||
        (sessionId ? path.join(FILES_ROOT, 'codex-workspace', sessionId) : null);

    const sessionStatePath =
        sessionId && projectPath
            ? path.join(projectPath, 'codex-docs', 'SESSION_STATE.json')
            : null;

    if (activeSessionId && requestedSessionId && activeSessionId !== requestedSessionId) {
        node.warn(
            `[ANTI-CONTAMINATION] excel user=${activeInfo.userKey} requested=${shortId(requestedSessionId)} active=${shortId(activeSessionId)} resolved=${shortId(sessionId)}`
        );
    }

    return {
        userKey: activeInfo.userKey,
        sessionId,
        projectPath,
        sessionStatePath
    };
}

function loadSessionState(sessionStatePath) {
    let state = {};
    try {
        if (sessionStatePath && fs.existsSync(sessionStatePath)) {
            const raw = fs.readFileSync(sessionStatePath, 'utf8').trim();
            state = raw ? JSON.parse(raw) : {};
        }
    } catch (err) {
        node.warn(`WARN load SESSION_STATE ${err.message}`);
        state = {};
    }
    return state;
}

function deepMerge(target, source) {
    if (!source || typeof source !== 'object' || Array.isArray(source)) return target;

    for (const key of Object.keys(source)) {
        const value = source[key];
        if (value === undefined) continue;

        if (value && typeof value === 'object' && !Array.isArray(value)) {
            if (!target[key] || typeof target[key] !== 'object' || Array.isArray(target[key])) {
                target[key] = {};
            }
            deepMerge(target[key], value);
        } else {
            target[key] = value;
        }
    }

    return target;
}

function saveSessionPatch(sessionId, sessionStatePath, patch) {
    if (!sessionId || !sessionStatePath) return;

    const dir = path.dirname(sessionStatePath);
    const tmpPath = path.join(dir, 'SESSION_STATE.tmp');
    const now = new Date().toISOString();
    /** @type {any} */
    let state = {};

    try {
        if (fs.existsSync(sessionStatePath)) {
            const raw = fs.readFileSync(sessionStatePath, 'utf8').trim();
            state = raw ? JSON.parse(raw) : {};
        }
    } catch (_err) {
        state = {};
    }

    if (!state || typeof state !== 'object' || Array.isArray(state)) {
        state = {};
    }

    state._id = state._id || sessionId;
    state.sessionId = state.sessionId || sessionId;
    state.createdAt = state.createdAt || now;
    state.updatedAt = now;

    deepMerge(state, patch || {});

    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(tmpPath, JSON.stringify(state, null, 2), 'utf8');
    fs.renameSync(tmpPath, sessionStatePath);
}

function normalizePart(v, fallback) {
    const s = String(v || fallback || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-zA-Z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '')
        .toLowerCase();

    return s || fallback;
}

const { userKey, sessionId, projectPath, sessionStatePath } = resolveSessionContext(msg);

if (!sessionId) {
    node.error('No sessionId found for export', msg);
    return null;
}

msg.sessionId = sessionId;
msg.projectPath = projectPath;
msg.sessionStatePath = sessionStatePath;

const requestedPath = normalizeFilePath(msg.respuestasJsonPath);
const submissionPath = normalizeFilePath(msg.submission?.respuestasJsonPath);

if (requestedPath && !isValidRespuestasPath(requestedPath, sessionId, projectPath)) {
    node.warn(`[ANTI-CONTAMINATION] excel ignored msg.respuestasJsonPath for ${userKey}: ${requestedPath}`);
}

if (submissionPath && !isValidRespuestasPath(submissionPath, sessionId, projectPath)) {
    node.warn(`[ANTI-CONTAMINATION] excel ignored submission.respuestasJsonPath for ${userKey}: ${submissionPath}`);
}

const candidatePaths = [
    isValidRespuestasPath(requestedPath, sessionId, projectPath) ? requestedPath : null,
    isValidRespuestasPath(submissionPath, sessionId, projectPath) ? submissionPath : null,
    sessionId ? path.join(FILES_ROOT, 'codex-workspace', sessionId, 'codex-docs', 'output', 'respuestas.json') : null,
    projectPath ? path.join(projectPath, 'codex-docs', 'output', 'respuestas.json') : null
].filter(Boolean);

const state = loadSessionState(sessionStatePath);

const rawUnidad = msg.unit || msg.submission?.unidad || msg.submission?.data?.unidad ||
    msg.onInitSubmission?.unidad || msg.onInitSubmission?.data?.unidad ||
    state?.context?.unidad || state?.context?.unit || 'unidad';

const rawProyecto = msg.project || msg.submission?.proyecto || msg.submission?.data?.proyecto ||
    msg.onInitSubmission?.proyecto || msg.onInitSubmission?.data?.proyecto ||
    state?.context?.proyecto || state?.context?.project || 'proyecto';

const unidad = normalizePart(rawUnidad, 'unidad');
const proyecto = normalizePart(rawProyecto, 'proyecto');

msg.unit = rawUnidad;
msg.project = rawProyecto;
msg.submission = msg.submission || {};
msg.submission.unidad = msg.submission.unidad || rawUnidad;
msg.submission.proyecto = msg.submission.proyecto || rawProyecto;

saveSessionPatch(sessionId, sessionStatePath, {
    context: {
        unidad: rawUnidad,
        proyecto: rawProyecto,
        unit: rawUnidad,
        project: rawProyecto
    }
});

const inputJson = candidatePaths.find(p => fs.existsSync(p));

if (!inputJson) {
    node.error(`No respuestas.json resolved for user=${userKey} session=${sessionId}`, msg);
    return null;
}

// --- Naming por fuente (unidad/cliente/proyecto/oportunidad) ---
function nameKey(v) { return normalizePart(v, ''); }
function nameRespValue(v) {
    if (v == null) return '';
    if (typeof v !== 'object' || Array.isArray(v)) return String(v);
    const c = [v.respuesta, v.valor, v.aiSuggestion, v.answer, v.value, v.texto, v.text];
    for (const x of c) { if (x != null) return String(x); }
    return '';
}
function findCampo(obj, aliases) {
    if (!obj || typeof obj !== 'object') return '';
    const al = aliases.map(nameKey);
    for (const k of Object.keys(obj)) {
        const nk = nameKey(k);
        if (al.some(a => a && (nk === a || nk.indexOf(a) >= 0 || a.indexOf(nk) >= 0))) {
            const val = nameRespValue(obj[k]);
            if (val) return val;
        }
    }
    return '';
}
function extractCampo(data, aliases) {
    if (!data || typeof data !== 'object') return '';
    if (data.general && typeof data.general === 'object') {
        const g = findCampo(data.general, aliases);
        if (g) return g;
    }
    return findCampo(data, aliases);
}

let namingData = {};
try { namingData = JSON.parse(fs.readFileSync(inputJson, 'utf8')); } catch (e) { namingData = {}; }

const ctxNaming = (state && state.context) ? state.context : {};
let selectedSourcesNaming = Array.isArray(ctxNaming.selectedSources) && ctxNaming.selectedSources.length
    ? ctxNaming.selectedSources
    : (Array.isArray(msg.selectedSources) && msg.selectedSources.length
        ? msg.selectedSources
        : (Array.isArray(msg.submission?.selectedSources) && msg.submission.selectedSources.length
            ? msg.submission.selectedSources
            : [String(ctxNaming.sourceType || msg.sourceType || 'processed')]));
const hasProcessed = selectedSourcesNaming.indexOf('processed') >= 0;
const hasOpportunity = selectedSourcesNaming.indexOf('opportunity') >= 0;

const rawCliente = extractCampo(namingData, ['cliente', 'client', 'customer'])
    || ctxNaming.opportunityCustomer || msg.customerName || 'cliente';
const rawOportunidad = ctxNaming.opportunityTitle || msg.selectedOpportunity?.title || rawProyecto || 'oportunidad';
const rawTitulo = extractCampo(namingData, ['titulo del proyecto', 'titulo proyecto', 'titulo', 'nombre del proyecto', 'project title', 'title']) || rawProyecto;

const cliente = normalizePart(rawCliente, 'cliente');
const oportunidad = normalizePart(rawOportunidad, 'oportunidad');
const proyectoDoc = normalizePart(rawTitulo, 'proyecto');

const now = new Date();
const pad = n => String(n).padStart(2, '0');
const stamp = `${pad(now.getMonth() + 1)}${pad(now.getDate())}_${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;

let nameParts;
if (hasOpportunity) {
    // Oportunidad sola o mezclada -> unidad_cliente_oportunidad
    nameParts = [unidad, cliente, oportunidad];
} else if (selectedSourcesNaming.length === 1 && hasProcessed) {
    // Solo procesado -> unidad_proyecto
    nameParts = [unidad, proyecto];
} else {
    // Solo uploads o mezcla sin oportunidad -> cliente_proyecto
    nameParts = [cliente, proyectoDoc];
}
const outputFilename = `${nameParts.filter(Boolean).join('_')}_${stamp}.xlsx`;

node.warn(`[naming] excel sources=${selectedSourcesNaming.join(',')} -> ${outputFilename}`);

const C = {
    headerBg: '1F4E79',
    headerFg: 'FFFFFF',
    campoBg: 'D6E4F0',
    respBg: 'EBF5FB',
    fragOdd: 'FDFEFE',
    fragEven: 'F2F3F4',
    border: 'AEB6BF'
};

const bdr = () => ({
    top: { style: 'thin', color: { argb: C.border } },
    left: { style: 'thin', color: { argb: C.border } },
    bottom: { style: 'thin', color: { argb: C.border } },
    right: { style: 'thin', color: { argb: C.border } }
});

const fill = hex => ({
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: hex }
});

const font = ({ bold = false, color = '000000', size = 10 } = {}) => ({
    name: 'Calibri',
    bold,
    color: { argb: color },
    size
});

const align = ({ wrap = true, vertical = 'top', horizontal = 'left' } = {}) => ({
    wrapText: wrap,
    vertical,
    horizontal
});

// Importante: new RegExp para evitar que el editor interprete /* como comentario.
const INVALID_SHEET_CHARS = new RegExp('[\\\\/*?:\\[\\]]', 'g');
const MAX_SHEET_NAME_LEN = 31;

function sanitizeWorksheetName(rawName, usedNames) {
    const used = usedNames || new Set();

    let base = String(rawName || 'Hoja')
        .normalize('NFC')
        .replace(/[\u0000-\u001F]/g, '')
        .replace(INVALID_SHEET_CHARS, ' - ')
        .replace(/\s+/g, ' ')
        .trim();

    base = base.replace(/^'+|'+$/g, '').trim();

    if (!base) {
        base = 'Hoja';
    }

    base = base.slice(0, MAX_SHEET_NAME_LEN).trim();
    base = base.replace(/[-_. ]+$/g, '').replace(/^[-_. ]+/g, '').trim();

    if (!base) {
        base = 'Hoja';
    }

    let candidate = base;
    let counter = 2;

    while (used.has(candidate.toLowerCase())) {
        const suffix = '_' + counter;
        const maxBaseLen = MAX_SHEET_NAME_LEN - suffix.length;
        const truncated = base
            .slice(0, maxBaseLen)
            .trim()
            .replace(/[-_. ]+$/g, '')
            .trim() || 'Hoja';

        candidate = truncated + suffix;
        counter++;
    }

    used.add(candidate.toLowerCase());

    if (candidate !== String(rawName || 'Hoja').slice(0, MAX_SHEET_NAME_LEN)) {
        node.warn('Nombre de hoja Excel saneado: "' + rawName + '" -> "' + candidate + '"');
    }

    return candidate;
}

function normalizeFragmentos(fragmentos) {
    if (fragmentos && !Array.isArray(fragmentos) && typeof fragmentos === 'object') {
        return [fragmentos];
    }

    if (Array.isArray(fragmentos)) {
        return fragmentos;
    }

    return [];
}

function getRespuestaValue(value) {
    if (value == null) {
        return '';
    }

    if (typeof value !== 'object' || Array.isArray(value)) {
        return String(value ?? '');
    }

    const candidates = [
        value.respuesta,
        value.valor,
        value.aiSuggestion,
        value.answer,
        value.value,
        value.texto,
        value.text
    ];

    for (const candidate of candidates) {
        if (candidate !== undefined && candidate !== null) {
            return String(candidate);
        }
    }

    return '';
}

function getFragmentosValue(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        return [];
    }

    return normalizeFragmentos(
        value.fragmentosDeReferencia ||
        value.fragments ||
        value.references ||
        value.fragmentos ||
        []
    );
}

function getFragmentFuente(frag) {
    if (!frag || typeof frag !== 'object') {
        return '';
    }

    return String(
        frag.fuente ||
        frag.source ||
        frag.referencePage ||
        frag.page ||
        ''
    );
}

function getFragmentTexto(frag) {
    if (!frag || typeof frag !== 'object') {
        return '';
    }

    return String(
        frag.texto ||
        frag.text ||
        frag.fragmento ||
        frag.fragment ||
        ''
    );
}



function normalizeTraceText(value) {
    return String(value ?? '')
        .normalize('NFC')
        .replace(/[\u200B-\u200D\uFEFF]/g, '')
        .replace(/\u00A0/g, ' ')
        .trim();
}

function getSpecificInstructionForExcel() {
    return normalizeTraceText(
        msg.instruccionEspecifica ||
        msg.submission?.instruccionEspecifica ||
        msg.submission?.data?.instruccionEspecifica ||
        msg.onInitSubmission?.instruccionEspecifica ||
        msg.onInitSubmission?.data?.instruccionEspecifica ||
        state?.context?.instruccionEspecifica ||
        state?.selection?.instruccionEspecifica ||
        ''
    );
}

function addUniqueUsedFile(files, seen, file, fallbackSource) {
    if (!file || typeof file !== 'object') return;

    const logicalName = normalizeTraceText(
        file.logicalName ||
        file.relativePath ||
        file.name ||
        file.fileName ||
        file.filename ||
        (file.mergedPath ? path.basename(file.mergedPath) : '') ||
        (file.localPath ? path.basename(file.localPath) : '') ||
        (file.originalPath ? path.basename(file.originalPath) : '') ||
        (file.path ? path.basename(file.path) : '')
    );

    if (!logicalName) return;

    const source = normalizeTraceText(file.source || fallbackSource || 'unknown');
    const originalPath = normalizeTraceText(file.originalPath || file.localPath || file.path || '');
    const mergedPath = normalizeTraceText(file.mergedPath || '');
    const size = Number(file.size || 0) || null;
    const sha256 = normalizeTraceText(file.sha256 || '');
    const key = `${source}|${logicalName}|${originalPath}|${mergedPath}`.toLowerCase();

    if (seen.has(key)) return;
    seen.add(key);

    files.push({
        source,
        logicalName,
        originalPath,
        mergedPath,
        size,
        sha256
    });
}

function readFirstJson(paths) {
    for (const candidate of paths || []) {
        try {
            if (candidate && fs.existsSync(candidate)) {
                const raw = fs.readFileSync(candidate, 'utf8').trim();
                if (raw) return JSON.parse(raw);
            }
        } catch (err) {
            node.warn(`WARN traceability json ${candidate}: ${err.message}`);
        }
    }
    return null;
}

function collectUsedFilesForExcel() {
    const files = [];
    const seen = new Set();

    function addMany(list, fallbackSource) {
        if (!Array.isArray(list)) return;
        for (const item of list) addUniqueUsedFile(files, seen, item, fallbackSource);
    }

    addMany(state?.input?.finalFiles, 'merged');
    addMany(state?.input?.usedFiles, 'merged');
    addMany(state?.traceability?.usedFiles, 'merged');
    addMany(state?.context?.finalFiles, 'merged');

    const manifest = readFirstJson([
        state?.input?.manifestPath,
        state?.context?.manifestPath,
        state?.workspace?.manifestPath,
        projectPath ? path.join(projectPath, 'codex-docs', 'MANIFEST.json') : null
    ]);

    addMany(manifest?.finalFiles, 'merged');
    addMany(manifest?.traceability?.usedFiles, 'merged');

    const summarySources = [
        manifest?.sourceSummary,
        state?.input?.sourceSummary,
        state?.context?.sourceSummary,
        state?.sourceSummary
    ].filter(Boolean);

    for (const sourceSummary of summarySources) {
        for (const sourceName of ['processed', 'opportunity', 'uploads']) {
            addMany(sourceSummary?.[sourceName]?.files, sourceName);
        }
    }

    return files;
}

function usedFileLine(file) {
    const parts = [];
    if (file.source) parts.push(`[${file.source}]`);
    parts.push(file.logicalName || file.name || 'fichero');
    if (file.originalPath) parts.push(`origen=${file.originalPath}`);
    if (file.mergedPath) parts.push(`merged=${file.mergedPath}`);
    return parts.join(' ');
}

function buildExcelTraceability() {
    const specificInstruction = getSpecificInstructionForExcel();
    const usedFiles = collectUsedFilesForExcel();
    const rows = {};

    if (specificInstruction) {
        rows['Instruccion especifica del usuario'] = {
            respuesta: specificInstruction,
            fragmentosDeReferencia: [
                {
                    fuente: 'Formulario de ejecucion',
                    texto: 'Instruccion capturada y persistida para trazabilidad de esta generacion.'
                }
            ]
        };
    }

    rows['Ficheros usados en el proceso'] = {
        respuesta: usedFiles.length
            ? usedFiles.map(usedFileLine).join('\n')
            : 'No se han podido resolver ficheros usados en SESSION_STATE/MANIFEST.',
        fragmentosDeReferencia: usedFiles.length
            ? usedFiles.map(file => ({
                fuente: file.source || 'unknown',
                texto: usedFileLine(file)
            }))
            : [
                {
                    fuente: 'SESSION_STATE',
                    texto: 'Sin finalFiles/sourceSummary disponibles para esta ejecucion.'
                }
            ]
    };

    return { specificInstruction, usedFiles, rows };
}

function applyExcelTraceabilityRows(data, traceability) {
    const rows = traceability?.rows || {};
    const rowKeys = Object.keys(rows);
    if (!rowKeys.length) return data;

    if (
        data &&
        typeof data === 'object' &&
        !Array.isArray(data) &&
        data.general &&
        typeof data.general === 'object' &&
        !Array.isArray(data.general)
    ) {
        return {
            ...data,
            general: {
                ...rows,
                ...(data.general || {})
            }
        };
    }

    if (data && typeof data === 'object' && !Array.isArray(data)) {
        return {
            ...rows,
            ...data
        };
    }

    return {
        ...rows,
        Respuestas: {
            respuesta: JSON.stringify(data || null),
            fragmentosDeReferencia: []
        }
    };
}

function prepareSheet(ws) {
    ws.columns = [
        { header: 'Campo', key: 'campo', width: 30 },
        { header: 'Respuesta', key: 'respuesta', width: 50 },
        { header: 'Fuente', key: 'fuente', width: 45 },
        { header: 'Fragmento de referencia', key: 'fragmento', width: 70 }
    ];

    const headerRow = ws.getRow(1);
    headerRow.height = 22;

    headerRow.eachCell(cell => {
        cell.font = font({ bold: true, color: C.headerFg, size: 11 });
        cell.fill = fill(C.headerBg);
        cell.alignment = align({ horizontal: 'center', vertical: 'middle' });
        cell.border = bdr();
    });

    ws.views = [{ state: 'frozen', ySplit: 1 }];
}

function writeSheetData(ws, dataObj) {
    prepareSheet(ws);

    let curRow = 2;

    for (const [key, value] of Object.entries(dataObj || {})) {
        if (key === '_comment') {
            continue;
        }

        if (value === null || value === undefined) {
            continue;
        }

        const respuesta = getRespuestaValue(value);
        const fragmentos = getFragmentosValue(value);
        const fragRows = fragmentos.length > 0 ? fragmentos : [{}];

        for (let i = 0; i < fragRows.length; i++) {
            const frag = fragRows[i] || {};
            const rn = curRow + i;
            const fragBg = i % 2 === 0 ? C.fragOdd : C.fragEven;

            ws.getCell(`A${rn}`).value = i === 0 ? key : '';
            ws.getCell(`A${rn}`).font = font({ bold: true });
            ws.getCell(`A${rn}`).fill = fill(C.campoBg);
            ws.getCell(`A${rn}`).alignment = align({ horizontal: 'left', vertical: 'top' });
            ws.getCell(`A${rn}`).border = bdr();

            ws.getCell(`B${rn}`).value = i === 0 ? respuesta : '';
            ws.getCell(`B${rn}`).font = font();
            ws.getCell(`B${rn}`).fill = fill(C.respBg);
            ws.getCell(`B${rn}`).alignment = align({ vertical: 'top' });
            ws.getCell(`B${rn}`).border = bdr();

            ws.getCell(`C${rn}`).value = getFragmentFuente(frag);
            ws.getCell(`C${rn}`).font = font({ size: 9, color: '1A5276' });
            ws.getCell(`C${rn}`).fill = fill(fragBg);
            ws.getCell(`C${rn}`).alignment = align({ vertical: 'top' });
            ws.getCell(`C${rn}`).border = bdr();

            ws.getCell(`D${rn}`).value = getFragmentTexto(frag);
            ws.getCell(`D${rn}`).font = font({ size: 9 });
            ws.getCell(`D${rn}`).fill = fill(fragBg);
            ws.getCell(`D${rn}`).alignment = align({ vertical: 'top' });
            ws.getCell(`D${rn}`).border = bdr();
        }

        curRow += fragRows.length;
    }
}

async function buildExcelSimple(data, outPath) {
    const wb = new ExcelJS.Workbook();
    const usedSheetNames = new Set();

    const sheetName = sanitizeWorksheetName('Analisis', usedSheetNames);
    const ws = wb.addWorksheet(sheetName);

    writeSheetData(ws, data);

    await fs.promises.mkdir(EXCEL_DIR, { recursive: true });
    await wb.xlsx.writeFile(outPath);
}

async function buildExcelLotes(data, outPath) {
    const wb = new ExcelJS.Workbook();
    const usedSheetNames = new Set();

    const generalSheetName = sanitizeWorksheetName('general', usedSheetNames);
    const generalWs = wb.addWorksheet(generalSheetName);

    writeSheetData(generalWs, data.general || {});

    (Array.isArray(data.lotes) ? data.lotes : []).forEach((lote, idx) => {
        if (!lote || typeof lote !== 'object') {
            return;
        }

        const campos = lote.campos;

        if (!campos || typeof campos !== 'object' || Array.isArray(campos)) {
            return;
        }

        const rawSheetName = String(lote.lote || ('Lote ' + (idx + 1)));
        const sheetName = sanitizeWorksheetName(rawSheetName, usedSheetNames);
        const ws = wb.addWorksheet(sheetName);

        writeSheetData(ws, campos);
    });

    await fs.promises.mkdir(EXCEL_DIR, { recursive: true });
    await wb.xlsx.writeFile(outPath);
}

async function buildExcel(data, outPath) {
    const isLotesFormat = data &&
        typeof data === 'object' &&
        !Array.isArray(data) &&
        data.general &&
        typeof data.general === 'object' &&
        !Array.isArray(data.general);

    return isLotesFormat
        ? buildExcelLotes(data, outPath)
        : buildExcelSimple(data, outPath);
}

(async () => {
    try {
        const raw = fs.readFileSync(inputJson, 'utf8');
        let data = JSON.parse(raw);
        const outputXlsx = path.join(EXCEL_DIR, outputFilename);
        const excelTraceability = buildExcelTraceability();

        data = applyExcelTraceabilityRows(data, excelTraceability);

        await buildExcel(data, outputXlsx);

        msg.generatedExcelFilename = outputFilename;
        msg.generatedExcelDir = EXCEL_DIR;

        saveSessionPatch(sessionId, sessionStatePath, {
            output: {
                generatedExcelFilename: outputFilename,
                generatedExcelDir: EXCEL_DIR,
                excelTraceability: {
                    generatedAt: new Date().toISOString(),
                    hasSpecificInstruction: Boolean(excelTraceability.specificInstruction),
                    specificInstruction: excelTraceability.specificInstruction || null,
                    usedFilesCount: excelTraceability.usedFiles.length,
                    usedFiles: excelTraceability.usedFiles
                }
            }
        });

        node.warn(`Excel generated for ${userKey}: ${outputXlsx}`);
        node.send(msg);
    } catch (err) {
