const fs = require('fs');
const path = require('path');

const FILES_ROOT = '/internal-storage-files/files';
const ACTIVE_SESSIONS_DIR = path.join(FILES_ROOT, '_active-sessions');

function getUserKey(msg) {
  const sec = msg.__axetFlowsSecurityContext || {};
  const idp = sec.externalIdpUserInfo || {};
  return (
    idp.preferred_username ||
    idp.email ||
    idp.sub ||
    msg.req?.user?.email ||
    msg.req?.user?.id ||
    msg.userId ||
    'anonymous'
  );
}

function safeReadJson(filePath) {
  try {
    if (!filePath || !fs.existsSync(filePath)) return null;
    const raw = fs.readFileSync(filePath, 'utf8').trim();
    return raw ? JSON.parse(raw) : null;
  } catch (err) {
    node.warn('WARN read json ' + filePath + ': ' + err.message);
    return null;
  }
}

function getActiveSession(msg) {
  const userKey = getUserKey(msg);
  const activePath = path.join(ACTIVE_SESSIONS_DIR, userKey + '.json');
  return {
    userKey,
    activePath,
    active: safeReadJson(activePath)
  };
}

function normalizeFilePath(filePath) {
  if (typeof filePath !== 'string') return null;
  const trimmed = filePath.trim();
  return trimmed ? path.normalize(trimmed) : null;
}

function pathStartsWith(parentPath, childPath) {
  const parent = normalizeFilePath(parentPath);
  const child = normalizeFilePath(childPath);
  if (!parent || !child) return false;
  const rel = path.relative(parent, child);
  return rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel));
}

function isValidRespuestasPath(filePath, sessionId, projectPath) {
  const candidate = normalizeFilePath(filePath);
  if (!candidate || path.basename(candidate) !== 'respuestas.json') return false;

  const allowedDirs = [
    sessionId ? path.join(FILES_ROOT, 'codex-workspace', sessionId, 'codex-docs', 'output') : null,
    projectPath ? path.join(projectPath, 'codex-docs', 'output') : null
  ].filter(Boolean);

  return allowedDirs.some((dir) => pathStartsWith(dir, candidate));
}

function shortId(value) {
  return value ? String(value).slice(0, 8) : '-';
}

function resolveSessionContext(msg) {
  const activeInfo = getActiveSession(msg);

  const requestedSessionId =
    msg.onInitSubmission?.sessionId ||
    msg.submission?.sessionId ||
    msg.req?.query?.sessionId ||
    msg.payload?.data?.sessionId ||
    msg.payload?.sessionId ||
    msg.sessionId ||
    null;

  const requestedProjectPath =
    msg.onInitSubmission?.projectPath ||
    msg.submission?.projectPath ||
    msg.payload?.data?.projectPath ||
    msg.payload?.projectPath ||
    msg.projectPath ||
    (requestedSessionId ? path.join(FILES_ROOT, 'codex-workspace', requestedSessionId) : null);

  const activeSessionId = activeInfo.active?.sessionId || null;
  const activeProjectPath =
    activeInfo.active?.projectPath ||
    (activeSessionId ? path.join(FILES_ROOT, 'codex-workspace', activeSessionId) : null);

  const sessionId = activeSessionId || requestedSessionId;
  const projectPath =
    activeProjectPath ||
    requestedProjectPath ||
    (sessionId ? path.join(FILES_ROOT, 'codex-workspace', sessionId) : null);

  const sessionStatePath = sessionId && projectPath
    ? path.join(projectPath, 'codex-docs', 'SESSION_STATE.json')
    : null;

  if (activeSessionId && requestedSessionId && activeSessionId !== requestedSessionId) {
    node.warn('[ANTI-CONTAMINATION] plantilla user=' + activeInfo.userKey + ' requested=' + shortId(requestedSessionId) + ' active=' + shortId(activeSessionId) + ' resolved=' + shortId(sessionId));
  }

  return {
    userKey: activeInfo.userKey,
    sessionId,
    projectPath,
    sessionStatePath
  };
}

function loadSessionState(sessionStatePath) {
  let state = {};
  try {
    if (sessionStatePath && fs.existsSync(sessionStatePath)) {
      const raw = fs.readFileSync(sessionStatePath, 'utf8').trim();
      state = raw ? JSON.parse(raw) : {};
    }
  } catch (_err) {
    state = {};
  }
  return state;
}

function deepMerge(target, source) {
  if (!source || typeof source !== 'object' || Array.isArray(source)) return target;

  for (const key of Object.keys(source)) {
    const value = source[key];
    if (value === undefined) continue;

    if (value && typeof value === 'object' && !Array.isArray(value)) {
      if (!target[key] || typeof target[key] !== 'object' || Array.isArray(target[key])) {
        target[key] = {};
      }
      deepMerge(target[key], value);
    } else {
      target[key] = value;
    }
  }

  return target;
}

function saveSessionPatch(sessionId, sessionStatePath, patch) {
  if (!sessionId || !sessionStatePath) return;

  const dir = path.dirname(sessionStatePath);
  const tmpPath = path.join(dir, 'SESSION_STATE.tmp');
  const now = new Date().toISOString();
  /** @type {any} */
  let state = {};

  try {
    if (fs.existsSync(sessionStatePath)) {
      const raw = fs.readFileSync(sessionStatePath, 'utf8').trim();
      state = raw ? JSON.parse(raw) : {};
    }
  } catch (_err) {
    state = {};
  }

  if (!state || typeof state !== 'object' || Array.isArray(state)) {
    state = {};
  }

  state._id = state._id || sessionId;
  state.sessionId = state.sessionId || sessionId;
  state.createdAt = state.createdAt || now;
  state.updatedAt = now;

  deepMerge(state, patch || {});

  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(tmpPath, JSON.stringify(state, null, 2), 'utf8');
  fs.renameSync(tmpPath, sessionStatePath);
}

function asArray(v) {
  if (Array.isArray(v)) return v;
  if (v && typeof v === 'object') return [v];
  return [];
}

function normalizePart(v, fallback) {
  const s = String(v || fallback || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .toLowerCase();

  return s || fallback;
}

function normalizeText(v) {
  return String(v ?? '')
    .normalize('NFC')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\u00A0/g, ' ')
    .trim();
}

function firstText() {
  for (const value of arguments) {
    if (value !== undefined && value !== null) {
      const text = normalizeText(value);
      if (text) return text;
    }
  }
  return '';
}

function keyNorm(value) {
  return normalizeText(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function getRuleFromEntry(entry, fallback) {
  if (!entry || typeof entry !== 'object') return fallback;

  return firstText(
    entry.rule,
    entry.campo,
    entry.key,
    entry.nombre,
    entry.name,
    entry.header,
    entry.label,
    fallback
  );
}

function getRespuestaValue(value) {
  if (value == null) return '';

  if (typeof value !== 'object' || Array.isArray(value)) {
    return String(value ?? '');
  }

  const candidates = [
    value.respuesta,
    value.valor,
    value.aiSuggestion,
    value.answer,
    value.value,
    value.texto,
    value.text
  ];

  for (const candidate of candidates) {
    if (candidate !== undefined && candidate !== null) {
      return String(candidate);
    }
  }

  return '';
}

function normalizeFragment(frag) {
  if (!frag) return null;

  if (typeof frag !== 'object' || Array.isArray(frag)) {
    const text = normalizeText(frag);
    return text ? { fuente: '', texto: text } : null;
  }

  const fuente = firstText(
    frag.fuente,
    frag.source,
    frag.referencePage,
    frag.page,
    frag.file,
    frag.document,
    frag.filename
  );

  const texto = firstText(
    frag.texto,
    frag.text,
    frag.fragmento,
    frag.fragment,
    frag.content,
    frag.value
  );

  if (!fuente && !texto) return null;

  return { fuente, texto };
}

function getFragmentosValue(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return [];

  const raw =
    value.fragmentosDeReferencia ||
    value.fragments ||
    value.references ||
    value.fragmentos ||
    [];

  return asArray(raw)
    .map(normalizeFragment)
    .filter(Boolean);
}

function buildReferenceTextForAi(fragmentos) {
  return fragmentos
    .map((f) => [f.fuente, f.texto].filter(Boolean).join(': '))
    .filter(Boolean)
    .join('\n\n');
}

function buildReferencePage(fragmentos) {
  return fragmentos
    .map((f) => f.fuente)
    .filter(Boolean)
    .join(' | ');
}

function canonicalItem(ruleRaw, value, fallbackRule) {
  const rule = normalizeText(ruleRaw || fallbackRule || 'Campo');
  const respuesta = getRespuestaValue(value);
  const fragmentos = getFragmentosValue(value);
  const referenceTextForAi = buildReferenceTextForAi(fragmentos);
  const referencePage = buildReferencePage(fragmentos);

  return {
    rule,
    respuesta,
    valor: respuesta,
    aiSuggestion: respuesta,
    fragmentosDeReferencia: fragmentos,
    referenceTextForAi,
    referencePage: referencePage || ''
  };
}

function normalizeDataObjectToObject(obj) {
  const out = {};
  for (const [ruleRaw, value] of Object.entries(obj || {})) {
    if (ruleRaw === '_comment') continue;
    const rule = normalizeText(ruleRaw);
    if (!rule) continue;
    out[rule] = canonicalItem(rule, value, rule);
  }
  return out;
}

function normalizeArrayToItems(arr) {
  const items = [];
  (Array.isArray(arr) ? arr : []).forEach((entry, i) => {
    if (!entry || typeof entry !== 'object') return;
    const rule = getRuleFromEntry(entry, 'Campo_' + (i + 1));
    if (!rule) return;
    items.push(canonicalItem(rule, entry, 'Campo_' + (i + 1)));
  });
  return items;
}

function normalizePlainObjectToItems(obj) {
  const items = [];
  for (const [ruleRaw, value] of Object.entries(obj || {})) {
    if (ruleRaw === '_comment') continue;
    const rule = normalizeText(ruleRaw);
    if (!rule) continue;
    items.push(canonicalItem(rule, value, rule));
  }
  return items;
}

function flattenLotesForTemplates(generalObj, lotesArr) {
  const items = [];
  for (const [rule, value] of Object.entries(generalObj || {})) {
    if (rule === '_comment') continue;
    items.push(canonicalItem(rule, value, rule));
  }
  (Array.isArray(lotesArr) ? lotesArr : []).forEach((lote, loteIdx) => {
    const loteName = normalizeText(lote?.lote || 'Lote ' + (loteIdx + 1));
    const campos = lote?.campos || {};
    for (const [rule, value] of Object.entries(campos || {})) {
      if (rule === '_comment') continue;
      const item = canonicalItem(rule, value, rule);
      item.lote = loteName;
      items.push(item);
    }
  });
  return items;
}

