    TIPO_SERVICIO: { min: 7.6, base: 8.4, max: 9.0, soft: 46, hard: 70, maxLines: 2 },
    TIPO_PROYECTO: { min: 7.6, base: 8.4, max: 9.0, soft: 26, hard: 38, maxLines: 1 },
    OBJETIVOS: { min: 7.8, base: 9.0, max: 10.2, soft: 360, hard: 560, maxLines: 8 },
    TAREAS: { min: 7.6, base: 8.8, max: 9.8, soft: 420, hard: 650, maxLines: 9 },
    RESULTADOS: { min: 7.4, base: 8.4, max: 9.2, soft: 320, hard: 560, maxLines: 8 },
    TECNOLOGIAS: { min: 6.9, base: 7.6, max: 8.3, soft: 160, hard: 240, maxLines: 5 },
    METODOLOGIAS: { min: 6.9, base: 7.6, max: 8.3, soft: 95, hard: 150, maxLines: 4 },
    PERFILES_PROFESIONALES: { min: 6.8, base: 7.5, max: 8.2, soft: 140, hard: 220, maxLines: 5 },
    PALABRAS_CLAVE: { min: 6.4, base: 7.0, max: 7.4, soft: 105, hard: 160, maxLines: 4 },
    FUENTES: { min: 6.2, base: 7.0, max: 7.4, soft: 105, hard: 160, maxLines: 4 }
  },
  instanceFontRules: {
    CLIENTE_HEADER: { min: 10.8, base: 12.2, max: 13.2, soft: 34, hard: 62, maxLines: 2 },
    CLIENTE_CARD: { min: 14.2, base: 15.8, max: 17.0, soft: 42, hard: 72, maxLines: 3 },
    TITULO_PROYECTO_CARD: { min: 11.8, base: 15.2, max: 16.8, soft: 66, hard: 105, maxLines: 4 }
  },
  shapeGeometry: {
    // En EMUs. Ajusta cajas que la plantilla trae demasiado pequeñas para nombres largos.
    CLIENTE_HEADER: { x: 6400000, y: 64000, cx: 3720000, cy: 370000 },
    CLIENTE_CARD: { x: 457200, y: 1040000, cx: 2761488, cy: 700000 },
    TITULO_PROYECTO_CARD: { x: 493776, y: 1780000, cx: 2688336, cy: 800000 }
  },
  llm: {
    enabled: true,
    model: 'gpt-5.2',
    batchSize: 4,
    timeoutMs: 90000,
    callMode: 'risk_or_overflow_only',
    riskThreshold: 0.90,
    fallback: 'deterministic_compact_no_overcompress'
  }
};

const BULLET = String.fromCharCode(8226);

function mergeProfile(input) {
  const p = input && typeof input === 'object' ? input : {};
  return {
    ...p,
    templateCode: DEFAULT_PROFILE.templateCode,
    strategy: DEFAULT_PROFILE.strategy,
    // V13 visual-fit limits and geometry hints must win over older limits coming from prepare payload plantilla.
    limits: { ...(p.limits || {}), ...DEFAULT_PROFILE.limits },
    fontRules: { ...(p.fontRules || {}), ...DEFAULT_PROFILE.fontRules },
    instanceFontRules: { ...(p.instanceFontRules || {}), ...DEFAULT_PROFILE.instanceFontRules },
    shapeGeometry: { ...(p.shapeGeometry || {}), ...DEFAULT_PROFILE.shapeGeometry },
    llm: { ...DEFAULT_PROFILE.llm, ...(p.llm || {}) }
  };
}

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFC')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\u00A0/g, ' ')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

function clean(value) {
  return normalizeText(value)
    .replace(/[\t ]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function keyNorm(value) {
  return clean(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function isNoData(value) {
  const raw = clean(value);
  const s = keyNorm(raw);
  if (!s || ['no hallado', 'no encontrado', 'no disponible', 'n a', 'na', 'null', '-'].includes(s)) {
    return true;
  }

  const noDataPatterns = [
    /^no exact\b/,
    /^no explicit\b/,
    /^no specific\b/,
    /^not specified\b/,
    /^not available\b/,
    /^not found\b/,
    /^not identified\b/,
    /^not provided\b/,
    /^no\s+.*\s+found\b/,
    /^no\s+cpv\b/,
    /\bwas not found\b/,
    /\bwas found in the parseable documentation\b/,
    /\bprovided documentation\b.*\bdoes not specify\b/,
    /^sin informacion\b/,
    /^sin datos\b/,
    /^no se ha encontrado\b/,
    /^no se han encontrado\b/,
    /^no se ha identificado\b/,
    /^no se han identificado\b/,
    /^no se encontro\b/,
    /^no consta\b/
  ];

  return noDataPatterns.some((rx) => rx.test(s));
}

function removeEllipses(value) {
  return clean(value)
    .replace(/\.{3,}/g, '')
    .replace(/\u2026/g, '')
    .replace(/[\s,;:.\-]+$/g, '')
    .trim();
}

function repairOpenTail(value) {
  let s = removeEllipses(value);
  const opens = (s.match(/\(/g) || []).length;
  const closes = (s.match(/\)/g) || []).length;
  if (opens > closes) {
    const idx = s.lastIndexOf('(');
    if (idx > Math.floor(s.length * 0.45)) {
      s = s.slice(0, idx).trim();
    }
  }
  s = s.replace(/\b(including|incluyendo|and|y|with|con|plus|mas|de|del|la|el|los|las|para|por|sobre|su|sus|fecha)$/i, '').trim();
  return s;
}

function smartCut(value, maxChars) {
  let s = clean(value);
  if (!maxChars || s.length <= maxChars) return repairOpenTail(s);

  let cut = s.slice(0, maxChars).trim();
  const lastStop = Math.max(
    cut.lastIndexOf('. '),
    cut.lastIndexOf('; '),
    cut.lastIndexOf('\n'),
    cut.lastIndexOf(', '),
    cut.lastIndexOf(' - ')
  );

  if (lastStop > Math.floor(maxChars * 0.55)) {
    cut = cut.slice(0, lastStop + 1).trim();
  } else {
    const lastSpace = cut.lastIndexOf(' ');
    if (lastSpace > Math.floor(maxChars * 0.68)) cut = cut.slice(0, lastSpace).trim();
  }

  return repairOpenTail(cut);
}

function valueOrDash(value, limit) {
  let s = clean(value);
  if (isNoData(s)) return '-';
  const max = limit && limit.maxChars ? Number(limit.maxChars) : null;
  if (max && s.length > max) s = smartCut(s, max);
  return repairOpenTail(s) || '-';
}

function splitCandidates(value) {
  if (Array.isArray(value)) {
    return value.map(clean).filter((x) => x && !isNoData(x));
  }

  const text = clean(value);
  if (!text || isNoData(text)) return [];

  let parts = text
    .split(/\n+/g)
    .map((line) => line.replace(/^\s*[-*\u2022]+\s*/g, '').replace(/^\s*[0-9]+[.)]\s*/g, '').trim())
    .filter(Boolean);

  if (parts.length <= 1 && text.includes(';')) {
    parts = text.split(/;\s*/g).map((x) => x.trim()).filter(Boolean);
  }

  if (parts.length <= 1) {
    parts = text.split(/(?<=[.!?])\s+(?=[A-Z0-9\u00c0-\u017f])/g).map((x) => x.trim()).filter(Boolean);
  }

  const out = [];
  const seen = new Set();
  for (const item of parts) {
    const s = clean(item);
    if (!s || isNoData(s)) continue;
    const k = keyNorm(s);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(s);
  }
  return out;
}

function formatBullets(value, limit) {
  const opts = limit || {};
  const maxBullets = opts.maxBullets || 5;
  const maxCharsPerBullet = opts.maxCharsPerBullet || 105;
  const maxTotalChars = opts.maxTotalChars || (maxBullets * maxCharsPerBullet);
  const items = splitCandidates(value);

  if (!items.length) {
    return { text: '-', items: [], rawCount: 0, totalChars: 0, overflow: false, utilization: 0 };
  }

  const selected = [];
  let used = 0;
  let overflow = false;

  for (const raw of items) {
    let item = repairOpenTail(raw);
    if (item.length > maxCharsPerBullet) {
      item = smartCut(item, maxCharsPerBullet);
      overflow = true;
    }

    const projected = used + item.length + 3;
    if (selected.length < maxBullets && projected <= maxTotalChars) {
      selected.push(item);
      used = projected;
    } else {
      overflow = true;
    }
  }

  return {
    text: selected.map((x) => BULLET + ' ' + x).join('\n') || '-',
    items: selected,
    rawCount: items.length,
    totalChars: items.join(' ').length,
    overflow,
    utilization: Math.max(items.length / maxBullets, items.join(' ').length / maxTotalChars)
  };
}

function uniqueItems(values, maxItems) {
  const out = [];
  const seen = new Set();
  for (const raw of values || []) {
    const s = repairOpenTail(raw);
    if (!s || isNoData(s)) continue;
    const k = keyNorm(s);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(s);
    if (maxItems && out.length >= maxItems) break;
  }
  return out;
}

function formatListText(value, limit) {
  const opts = limit || {};
  const maxItems = opts.maxItems || 8;
  const maxChars = opts.maxChars || 180;
  const rawItems = splitCandidates(value);
  const items = uniqueItems(rawItems, maxItems);
  const joined = items.length ? items.join(', ') : clean(value);
  const text = isNoData(joined) ? '-' : smartCut(joined, maxChars);

  return {
    text,
    rawChars: clean(value).length,
    rawCount: rawItems.length,
    utilization: maxChars ? clean(value).length / maxChars : 0,
    overflow: clean(value).length > maxChars || rawItems.length > maxItems
  };
}

function formatParagraph(value, limit) {
  const opts = limit || {};
  const maxChars = opts.maxChars || 640;
  let text = clean(value);
  if (isNoData(text)) {
    return { text: '-', rawChars: 0, overflow: false, utilization: 0 };
  }

  const rawChars = text.length;
  const overflow = rawChars > maxChars;
  text = smartCut(text, maxChars);
  return { text, rawChars, overflow, utilization: rawChars / maxChars };
}

function compactCountry(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  if (k.includes('union europea') || k.includes('european union') || k.includes('eu member states') || k.includes('estados miembros')) {
    return 'EU Member States';
  }
  return valueOrDash(raw.replace(/^main location:\s*/i, '').replace(/;\s*other locations:\s*/i, '; '), limit);
}

function compactLanguage(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  if (k.includes('english') || k.includes('ingles')) return 'English';
  if (k.includes('spanish') || k.includes('espanol')) return 'Spanish';
  if (k.includes('french') || k.includes('frances')) return 'French';
  return valueOrDash(raw.replace(/^working language:\s*/i, '').replace(/^idioma de trabajo:\s*/i, ''), limit);
}

function compactUsers(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  if (k.includes('4100') && k.includes('124') && (k.includes('4000') || k.includes('external'))) {
    return '4,100+ (124 int.; 4,000+ ext.)';
  }
  const m = raw.match(/over\s*([0-9.,+]+).*?including\s*([0-9.,+]+).*?internal.*?([0-9.,+]+).*?external/i);
  if (m) return String(m[1]).replace('.', ',') + '+ (' + m[2] + ' int.; ' + m[3] + ' ext.)';
  return valueOrDash(raw, limit);
}

function parseAmount(value) {
  const raw = clean(value);
  if (isNoData(raw)) return null;
  const m = raw.match(/([0-9]{1,3}(?:[.,][0-9]{3})*(?:[.,][0-9]{2})?)\s*(eur|euro|euros|\u20ac)?/i);
  if (!m) return null;
  let numText = m[1];
  if (numText.includes('.') && numText.includes(',')) numText = numText.replace(/\./g, '').replace(',', '.');
  else if (numText.includes(',') && /,\d{2}$/.test(numText)) numText = numText.replace(/\./g, '').replace(',', '.');
  else numText = numText.replace(/,/g, '');
  const n = Number(numText);
  if (!Number.isFinite(n)) return null;
  return n;
}

function formatAmountShort(n) {
  if (!Number.isFinite(n)) return '';
  if (n >= 1000000) return (Math.round((n / 1000000) * 100) / 100).toFixed(2).replace(/\.00$/, '') + 'M EUR';
  if (n >= 1000) return (Math.round((n / 1000) * 10) / 10).toFixed(1).replace(/\.0$/, '') + 'k EUR';
  return String(Math.round(n)) + ' EUR';
}

function compactAmount(value, limit, ref, allRefs, idx) {
  const raw = clean(value);
  if (!isNoData(raw)) return valueOrDash(raw, limit);

  const isGeneral = ref && (ref.referenceKind === 'general' || ref.tipoReferencia === 'general' || ref.lote === 'General' || idx === 1);
  if (isGeneral && Array.isArray(allRefs) && allRefs.length > 1) {
    const parts = [];
    for (let i = 1; i < allRefs.length; i++) {
      const amount = parseAmount(allRefs[i] && allRefs[i].importe);
      if (amount) parts.push('L' + i + ': ' + formatAmountShort(amount));
      if (parts.length >= 3) break;
    }
    if (parts.length) return smartCut(parts.join('; '), limit && limit.maxChars ? limit.maxChars : 56);
  }

  return '-';
}

function compactTechnologies(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  const out = [];
  function add(label, cond) { if (cond && !out.includes(label)) out.push(label); }
  add('Azure', k.includes('azure'));
  add('Databricks', k.includes('databricks'));
  add('Angular/eUI', k.includes('angular') || k.includes('eui'));
  add('Spring Boot', k.includes('spring boot'));
  add('SQL stack', k.includes('sql') || k.includes('postgres') || k.includes('mysql') || k.includes('mariadb'));
  add('Synapse/Data Lake', k.includes('synapse') || k.includes('data lake'));
  add('Docker/Kubernetes', k.includes('docker') || k.includes('kubernetes'));
  add('Azure DevOps', k.includes('devops'));
  add('Camunda/BPMN', k.includes('camunda') || k.includes('bpmn') || k.includes('dmn'));
  add('EU tools', k.includes('eu login') || k.includes('eu survey') || k.includes('eu send'));
  add('OpenSearch/Elastic', k.includes('opensearch') || k.includes('elasticsearch'));
  add('Kafka', k.includes('kafka'));

  if (!out.length) return formatListText(raw, limit).text;
  return smartCut(out.join(', '), limit && limit.maxChars ? limit.maxChars : 270);
}

function compactProfiles(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  const out = [];
  function add(label, cond) { if (cond && !out.includes(label)) out.push(label); }
  add('Project/Service Mgmt', k.includes('project') || k.includes('service manager') || k.includes('quality manager') || k.includes('quality assurance'));
  add('Scrum/Agile', k.includes('scrum') || k.includes('agile') || k.includes('methodology'));
  add('BA/TA', k.includes('business analyst') || k.includes('technical analyst') || k.includes('technical manager') || k.includes('functional'));
  add('Solution Architecture', k.includes('solution architect') || k.includes('architecture'));
  add('DevOps/Release', k.includes('devops') || k.includes('release'));
  add('QA/Testing', k.includes('testing') || k.includes('qa') || k.includes('cross testing'));
  add('Data Protection/Cybersecurity', k.includes('data protection') || k.includes('cyber') || k.includes('security') || k.includes('privacy'));
  add('Health Data/MCM experts', k.includes('health data') || k.includes('mcm') || k.includes('epidemiologist') || k.includes('supply chain') || k.includes('simulation'));
  add('Help Desk/Support', k.includes('help desk') || k.includes('helpdesk') || k.includes('support'));

  if (!out.length) return formatListText(raw, limit).text;
  return smartCut(out.join('; '), limit && limit.maxChars ? limit.maxChars : 250);
}

function compactKeywords(value, limit) {
  const rawItems = splitCandidates(value);
  const preferred = [];
  const seen = new Set();
  for (const item of rawItems) {
    const k = keyNorm(item);
    if (!k || seen.has(k)) continue;
    seen.add(k);
    preferred.push(item);
  }
  return smartCut(preferred.slice(0, (limit && limit.maxItems) || 11).join(', '), (limit && limit.maxChars) || 190) || '-';
}

function uniqueSources(ref, profile) {
  const limit = profile.limits.FUENTES || {};
  const maxItems = limit.maxItems || 4;
  const sources = [];
  const seen = new Set();
  const fromFuentes = Array.isArray(ref.fuentes) ? ref.fuentes : String(ref.fuentes || '').split('|');
  const fromFragments = Array.isArray(ref.fragmentosDeReferencia) ? ref.fragmentosDeReferencia.map((f) => f && f.fuente) : [];

  for (const v of [...fromFuentes, ...fromFragments]) {
    let s = clean(v).replace(/\|+$/g, '').trim();
    if (!s || isNoData(s)) continue;
    const k = keyNorm(s);
    if (seen.has(k)) continue;
    seen.add(k);
    sources.push(s);
    if (sources.length >= maxItems) break;
  }

  return smartCut(sources.join(' | '), limit.maxChars || 190) || '-';
}

function buildLayoutReference(ref, idx, total, profile, allRefs) {
  const l = profile.limits || DEFAULT_PROFILE.limits;
  const objetivos = formatParagraph(ref.objetivos, l.OBJETIVOS);
  const tareas = formatBullets(ref.tareas, l.TAREAS);
  const resultados = formatBullets(ref.resultados, l.RESULTADOS);
  const tecnologiasText = compactTechnologies(ref.tecnologias, l.TECNOLOGIAS);
  const metodologias = formatListText(ref.metodologias, l.METODOLOGIAS);
  const palabrasClaveText = compactKeywords(ref.palabrasClave, l.PALABRAS_CLAVE);
  const perfilesText = compactProfiles(ref.perfilesProfesionales || ref.perfiles, l.PERFILES_PROFESIONALES);

  const techRaw = clean(ref.tecnologias).length;
  const perfilesRaw = clean(ref.perfilesProfesionales || ref.perfiles).length;
  const riskThreshold = profile.llm && profile.llm.riskThreshold ? profile.llm.riskThreshold : 0.82;
  const risks = [];
  if (objetivos.overflow || objetivos.utilization >= riskThreshold) risks.push('OBJETIVOS');
  if (tareas.overflow || tareas.utilization >= riskThreshold) risks.push('TAREAS');
  if (resultados.overflow || resultados.utilization >= riskThreshold) risks.push('RESULTADOS');
  if (techRaw > (l.TECNOLOGIAS.maxChars || 270)) risks.push('TECNOLOGIAS');
  if (metodologias.overflow || metodologias.utilization >= 1.05) risks.push('METODOLOGIAS');
  if (clean(ref.palabrasClave).length > (l.PALABRAS_CLAVE.maxChars || 190)) risks.push('PALABRAS_CLAVE');
  if (perfilesRaw > (l.PERFILES_PROFESIONALES.maxChars || 250)) risks.push('PERFILES_PROFESIONALES');

  return {
    _referenceIndex: ref.index || idx,
    _referenceOrder: idx,
    _referenceKind: ref.referenceKind || ref.tipoReferencia || (idx === 1 && total > 1 ? 'general' : 'lote'),
    _layoutSource: 'deterministic_v11',
    _fit: {
      needsLlm: risks.length > 0,
      riskFields: risks,
      metrics: {
        objetivosChars: objetivos.rawChars,
        tareasRawCount: tareas.rawCount,
        tareasChars: tareas.totalChars,
        resultadosRawCount: resultados.rawCount,
        resultadosChars: resultados.totalChars,
        tecnologiasRawChars: techRaw,
        perfilesRawChars: perfilesRaw
      }
    },
    TITULO_PROYECTO: valueOrDash(ref.titulo || ('Referencia ' + idx), l.TITULO_PROYECTO),
    CLIENTE: valueOrDash(ref.cliente, l.CLIENTE),
    SECTOR: valueOrDash(ref.sector, l.SECTOR),
    PAIS_EJECUCION: compactCountry(ref.pais, l.PAIS_EJECUCION),
    FECHA_INICIO: valueOrDash(ref.fechaInicio, l.FECHA_INICIO),
    FECHA_FIN: valueOrDash(ref.fechaFin, l.FECHA_FIN),
    DURACION_MESES: valueOrDash(ref.duracion, l.DURACION_MESES),
    IMPORTE_TOTAL: compactAmount(ref.importe, l.IMPORTE_TOTAL, ref, allRefs, idx),
    VOLUMEN_USUARIOS: compactUsers(ref.volumenUsuarios, l.VOLUMEN_USUARIOS),
    IDIOMA_TRABAJO: compactLanguage(ref.idiomaTrabajo, l.IDIOMA_TRABAJO),
    TIPO_SERVICIO: valueOrDash(ref.tipoServicio, l.TIPO_SERVICIO),
    TIPO_PROYECTO: valueOrDash(ref.tipoProyecto, l.TIPO_PROYECTO),
    OBJETIVOS: objetivos.text,
    TAREAS: tareas.text,
    RESULTADOS: resultados.text,
    TECNOLOGIAS: tecnologiasText,
    METODOLOGIAS: metodologias.text,
    CPV: valueOrDash(ref.cpv, l.CPV),
    PALABRAS_CLAVE: palabrasClaveText,
    PERFILES_PROFESIONALES: perfilesText,
    FUENTES: uniqueSources(ref, profile),
    N: String(idx).padStart(2, '0')
  };
}

function promptText(value, maxChars) {
  const s = clean(value);
  if (!s || isNoData(s)) return '';
  return s.length > maxChars ? s.slice(0, maxChars).trim() + '...' : s;
}

function referenceForPrompt(ref, layoutRef) {
  return {
    index: layoutRef._referenceIndex,
    kind: layoutRef._referenceKind,
    riskFields: layoutRef._fit.riskFields,
    fields: {
      TITULO_PROYECTO: promptText(ref.titulo, 400),
      CLIENTE: promptText(ref.cliente, 160),
      SECTOR: promptText(ref.sector, 100),
      PAIS_EJECUCION: promptText(ref.pais, 180),
      FECHA_INICIO: promptText(ref.fechaInicio, 80),
      FECHA_FIN: promptText(ref.fechaFin, 80),
      DURACION_MESES: promptText(ref.duracion, 80),
      IMPORTE_TOTAL: promptText(ref.importe, 180),
      VOLUMEN_USUARIOS: promptText(ref.volumenUsuarios, 200),
      IDIOMA_TRABAJO: promptText(ref.idiomaTrabajo, 80),
      TIPO_SERVICIO: promptText(ref.tipoServicio, 200),
      TIPO_PROYECTO: promptText(ref.tipoProyecto, 160),
      OBJETIVOS: promptText(ref.objetivos, 3800),
      TAREAS: promptText(ref.tareas, 3800),
      RESULTADOS: promptText(ref.resultados, 2800),
      TECNOLOGIAS: promptText(ref.tecnologias, 1400),
      METODOLOGIAS: promptText(ref.metodologias, 900),
      PALABRAS_CLAVE: promptText(ref.palabrasClave, 900),
      PERFILES_PROFESIONALES: promptText(ref.perfilesProfesionales || ref.perfiles, 1200),
      FUENTES: Array.isArray(ref.fuentes) ? ref.fuentes.slice(0, 8) : promptText(ref.fuentes, 500)
    }
  };
}

const outputType = msg.payload?.outputType || msg.submission?.outputType || msg.outputType;
if (outputType !== 'pptx') {
  return msg;
}

const data = msg.payload.data || {};
const references = Array.isArray(data.references) ? data.references : [];
const profile = mergeProfile(data.layoutProfile || msg.pptxLayoutProfile || DEFAULT_PROFILE);
data.layoutProfile = profile;

if (!references.length) {
  msg._pptxLayout = { skipLlm: true, reason: 'no_references', profile, candidates: [] };
  msg.payload.data = data;
  return msg;
}

const layoutReferences = references.map((ref, idx) => buildLayoutReference(ref || {}, idx + 1, references.length, profile, references));
data.layoutReferences = layoutReferences;

const llmEnabled = profile.llm?.enabled !== false && msg.disablePptxLayoutLlm !== true && msg.payload?.disablePptxLayoutLlm !== true;
const forceLlm = profile.llm?.force === true || msg.forcePptxLayoutLlm === true || msg.payload?.forcePptxLayoutLlm === true;
const candidates = references
  .map((ref, idx) => ({ ref, layout: layoutReferences[idx] }))
  .filter((x) => forceLlm || x.layout._fit.needsLlm)
  .map((x) => referenceForPrompt(x.ref, x.layout));

const outputContract = {
  root: 'object with property references',
  references: 'array of adapted references',
  requiredPerReference: ['index'],
  allowedEditableFields: [
    'TITULO_PROYECTO', 'PAIS_EJECUCION', 'IMPORTE_TOTAL', 'VOLUMEN_USUARIOS', 'IDIOMA_TRABAJO',
    'OBJETIVOS', 'TAREAS', 'RESULTADOS', 'TECNOLOGIAS', 'METODOLOGIAS',
    'PALABRAS_CLAVE', 'PERFILES_PROFESIONALES', 'FUENTES', 'overflowNotes'
  ],
  notes: [
    'Return TAREAS and RESULTADOS as arrays of complete bullet strings, without bullet symbol.',
    'Use the available capacity: do not over-compress short references; target 75-95% of the stated limits when evidence exists.',
    'Never use ellipses (...). Do not cut text mid-sentence, leave dangling prepositions or leave open parentheses.',
    'Compact users, country and language instead of truncating them; respect the field maxChars.',
    'Group technologies by category when the list is long.',
    'Group professional profiles by capability when the list is long.',
    'Do not change dates, amounts or proper nouns unless compacting format without changing meaning.',
    'Do not invent data. If there is no evidence, omit or return an empty value.'
  ]
};

const systemPrompt = [
  'You are a PowerPoint executive reference slide editor for NTT DATA.',
  'Your job is to adapt already extracted project data to a fixed one-slide template.',
  'You must summarize and structure text so it fits the provided layout limits, including character, bullet and font hints.',
  'Use the capacity budget as a contract: enough detail to fill the block cleanly, but never beyond maxChars/maxBullets.',
  'Do not invent, do not add external knowledge, do not change facts.',
  'Never use ellipses (...), incomplete parentheses, or half-cut expressions.',
  'For metadata, compact rather than truncate: e.g. users, country, language, technologies and profiles.',
  'For technologies, group by capability if needed: Azure, Databricks, Angular/eUI, Spring Boot, SQL stack, Synapse/Data Lake, Docker/Kubernetes, DevOps, EU tools.',
  'For profiles, group by capability if needed: Project/Service Mgmt, Scrum/Agile, BA/TA, Solution Architecture, DevOps/Release, QA/Testing, Data Protection/Cybersecurity, Health Data/MCM experts.',
  'Preserve the source language of the input. Return only valid JSON. No markdown.'
].join('\n');

msg._pptxLayout = {
  skipLlm: !llmEnabled || candidates.length === 0,
  reason: !llmEnabled ? 'llm_disabled' : (candidates.length === 0 ? 'fits_by_rules' : 'needs_llm'),
  profile,
  candidates,
  outputContract,
  systemPrompt,
  deterministicCount: layoutReferences.length,
  warnings: []
};

if (msg._pptxLayout.skipLlm) {
  msg._pptxLayout.warnings.push('PPTX layout LLM skipped: ' + msg._pptxLayout.reason);
}

msg.payload.data = data;
node.warn('PPTX layout v12 prepared: refs=' + layoutReferences.length + ', llmCandidates=' + candidates.length + ', reason=' + msg._pptxLayout.reason);
return msg;

node.warn('PPTX layout: call LLM enabler');

const axios = require('axios');

const AXET_BASE_URL = 'https://axet.nttdata.com';
const LLM_URL = AXET_BASE_URL + '/api/llm-enabler/v3/ntt/v1/responses';
const ASSETS_URL = AXET_BASE_URL + '/api/core/v1/assets/search';

/**
 * Cambia estos flags si necesitas más o menos ruido en logs.
 * No se imprime el bearer token completo nunca.
 */
const DEBUG_LLM = true;
const DEBUG_PROMPT = false;
const DEBUG_RESPONSE = true;
const MAX_LOG_CHARS = 6000;

function firstValue() {
  for (const v of arguments) {
    if (v !== undefined && v !== null && String(v).trim()) {
      return String(v).trim();
    }
  }

  return '';
}

function firstValueWithSource(candidates) {
  for (const item of candidates) {
    if (!item) continue;

    const value = item.value;

    if (value !== undefined && value !== null && String(value).trim()) {
      return {
        value: String(value).trim(),
        source: item.source || 'unknown'
      };
    }
  }

  return {
    value: '',
    source: 'missing'
  };
}

function truncate(value, maxChars) {
  const text = typeof value === 'string' ? value : safeStringify(value);
  const limit = Number(maxChars || MAX_LOG_CHARS);

  if (!text || text.length <= limit) {
    return text;
  }

  return text.slice(0, limit) + '... [truncated ' + (text.length - limit) + ' chars]';
}

function safeStringify(value, maxChars) {
  let text = '';

  try {
    text = JSON.stringify(value, null, 2);
  } catch (err) {
    text = String(value);
  }

  return maxChars ? truncate(text, maxChars) : text;
}

function mask(value, visibleStart, visibleEnd) {
  const text = String(value || '');

  if (!text) {
    return '';
  }

  const start = Number(visibleStart ?? 6);
  const end = Number(visibleEnd ?? 4);

  if (text.length <= start + end) {
    return text[0] + '***' + text[text.length - 1];
  }

  return text.slice(0, start) + '...' + text.slice(-end);
}

function maskToken(value) {
  const text = String(value || '');

  if (!text) {
    return '';
  }

  return mask(text, 10, 8) + ' len=' + text.length;
}

function maskHeaders(headers) {
  const out = { ...(headers || {}) };

  if (out.Authorization) {
    out.Authorization = 'Bearer ' + maskToken(String(out.Authorization).replace(/^Bearer\s+/i, ''));
  }

  if (out.authorization) {
    out.authorization = 'Bearer ' + maskToken(String(out.authorization).replace(/^Bearer\s+/i, ''));
  }

  if (out['axet-project-id']) {
    out['axet-project-id'] = mask(out['axet-project-id'], 8, 6);
  }

  if (out['axet-user-id']) {
    out['axet-user-id'] = mask(out['axet-user-id'], 8, 6);
  }

  if (out['axet-asset-id']) {
    out['axet-asset-id'] = mask(out['axet-asset-id'], 8, 6);
  }

  return out;
}

function logBlock(title, value, maxChars) {
  if (!DEBUG_LLM) {
    return;
  }

  node.warn('===== ' + title + ' =====');
  node.warn(truncate(typeof value === 'string' ? value : safeStringify(value), maxChars || MAX_LOG_CHARS));
  node.warn('===== /' + title + ' =====');
}

function getLoginKey(msg) {
  const sec = msg.__axetFlowsSecurityContext || {};
  const idp = sec.externalIdpUserInfo || {};
  const raw = firstValue(sec.login, idp.preferred_username, idp.email, msg.axet_user_id, msg.userId, 'anonymous');

  return raw.includes('@') ? raw.split('@')[0] : raw;
}

async function resolveAssetIdIfNeeded(security, msg) {
  if (security.assetId) {
    node.warn('PPTX layout: assetId already available from ' + security.sources.assetId + ' -> ' + mask(security.assetId, 8, 6));
    return security.assetId;
  }

  if (!security.bearerToken) {
    node.warn('PPTX layout: assetId lookup skipped because bearerToken is missing');
    return '';
  }

  const userKey = getLoginKey(msg);
  const cache = global.get('assetId_cache') || {};

  if (cache[userKey]) {
    node.warn('PPTX layout: assetId cache HIT for ' + userKey + ' -> ' + mask(cache[userKey], 8, 6));
    security.sources.assetId = 'global.assetId_cache[' + userKey + ']';
    return cache[userKey];
  }

  node.warn('PPTX layout: assetId cache MISS for ' + userKey + '. Calling assets/search...');

  const headers = {
    authorization: 'Bearer ' + security.bearerToken,
    'content-type': 'application/json'
  };

  logBlock('ASSET LOOKUP REQUEST', {
    url: ASSETS_URL,
    method: 'POST',
    headers: maskHeaders(headers),
    payload: { search: {} }
  }, 3000);

  try {
    const rsp = await axios.post(ASSETS_URL, { search: {} }, {
      headers,
      timeout: 30000,
      validateStatus: () => true
    });

    logBlock('ASSET LOOKUP RESPONSE SUMMARY', {
      status: rsp.status,
      statusText: rsp.statusText,
      dataKeys: rsp.data && typeof rsp.data === 'object' ? Object.keys(rsp.data) : [],
      dataPreview: truncate(safeStringify(rsp.data), 3000)
    }, 5000);

    if (rsp.status < 200 || rsp.status >= 300) {
      node.warn('PPTX layout: assetId lookup HTTP error status=' + rsp.status + ' statusText=' + rsp.statusText);
      return '';
    }

    const arr = Array.isArray(rsp?.data?.data) ? rsp.data.data : [];

    node.warn('PPTX layout: assets/search returned ' + arr.length + ' assets');

    const assetSummary = arr.slice(0, 20).map((x) => ({
      id: mask(x?.id, 8, 6),
      code: x?.code,
      displayName: x?.displayName
    }));

    logBlock('ASSET LOOKUP ASSETS SUMMARY', assetSummary, 4000);

    const core = arr.find((x) => {
      return String(x.code || '').toUpperCase() === 'CORE' || String(x.displayName || '').toLowerCase() === 'core';
    });

    if (core && core.id) {
      cache[userKey] = core.id;
      global.set('assetId_cache', cache);
      security.sources.assetId = 'assets/search CORE';
      node.warn('PPTX layout: assetId resolved from CORE -> ' + mask(core.id, 8, 6));

      return core.id;
    }

    node.warn('PPTX layout: assetId lookup did not find CORE asset');
  } catch (err) {
    logAxiosError('ASSET LOOKUP ERROR', err, {
      url: ASSETS_URL,
      method: 'POST',
      headers: maskHeaders(headers),
      payload: { search: {} }
    });

    node.warn('PPTX layout: assetId lookup failed: ' + err.message);
  }

  return '';
}

async function resolveSecurity(msg) {
  const sec = msg.__axetFlowsSecurityContext || {};
  const idp = sec.externalIdpUserInfo || {};
  const loginKey = getLoginKey(msg);
  const globalSec = global.get('axetFlowsSecurityContext_' + loginKey) || {};
  const credentials = msg.credentials || msg.submission?.talkg_credentials || msg.onInitSubmission?.talkg_credentials || {};

  const bearer = firstValueWithSource([
    { source: 'msg.__axetFlowsSecurityContext.externalIdpUserInfo.access_token', value: idp.access_token },
    { source: 'msg.__axetFlowsSecurityContext.externalIdpUserInfo.access_token_alt', value: sec.externalIdpUserInfo?.access_token },
    { source: 'msg.credentials.bearer_token', value: credentials.bearer_token },
    { source: 'msg.credentials.bearerToken', value: credentials.bearerToken },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.bearerToken', value: globalSec.bearerToken },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.bearer_token', value: globalSec.bearer_token }
  ]);

  const user = firstValueWithSource([
    { source: 'msg.__axetFlowsSecurityContext.axetUserId', value: sec.axetUserId },
    { source: 'msg.axet_user_id', value: msg.axet_user_id },
    { source: 'msg.credentials.axet_user_id', value: credentials.axet_user_id },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.axet_user_id', value: globalSec.axet_user_id },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.user_id', value: globalSec.user_id }
  ]);

  const project = firstValueWithSource([
    { source: 'msg.__axetFlowsSecurityContext.axetProject.id', value: sec.axetProject?.id },
    { source: 'msg.axet_project_id', value: msg.axet_project_id },
    { source: 'msg.credentials.axet_project_id', value: credentials.axet_project_id },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.axet_project_id', value: globalSec.axet_project_id }
  ]);

  const asset = firstValueWithSource([
    { source: 'msg.assetId', value: msg.assetId },
    { source: 'msg.credentials.assetId', value: credentials.assetId },
    { source: 'msg.credentials.asset_id', value: credentials.asset_id },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.asset_id', value: globalSec.asset_id },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.assetId', value: globalSec.assetId }
  ]);

  const security = {
    bearerToken: bearer.value,
    userId: user.value,
    projectId: project.value,
    assetId: asset.value,
    sources: {
      bearerToken: bearer.source,
      userId: user.source,
      projectId: project.source,
      assetId: asset.source
    },
    loginKey
  };

  security.assetId = await resolveAssetIdIfNeeded(security, msg);

  return security;
}

function chunkArray(arr, size) {
  const out = [];

  for (let i = 0; i < arr.length; i += size) {
    out.push(arr.slice(i, i + size));
  }

  return out;
}

function slimProfile(profile) {
  const limits = profile?.limits || {};
  const keep = [
    'TITULO_PROYECTO', 'CLIENTE', 'SECTOR', 'PAIS_EJECUCION', 'FECHA_INICIO', 'FECHA_FIN',
    'DURACION_MESES', 'IMPORTE_TOTAL', 'VOLUMEN_USUARIOS', 'IDIOMA_TRABAJO', 'TIPO_SERVICIO',
    'TIPO_PROYECTO', 'OBJETIVOS', 'TAREAS', 'RESULTADOS', 'TECNOLOGIAS', 'METODOLOGIAS',
    'CPV', 'PALABRAS_CLAVE', 'PERFILES_PROFESIONALES', 'FUENTES'
  ];
  const outLimits = {};
  for (const key of keep) {
    if (limits[key]) outLimits[key] = limits[key];
  }

  return {
    templateCode: profile?.templateCode || 'PPTX_General_v13_header_geometry_fit',
    strategy: profile?.strategy || 'template_measured_content_font_and_geometry_fit',
    instruction: 'Fit every field to these exact character, bullet, font and geometry hints for PPTX_General.pptx. Prefer complete short sentences; never use ellipses.',
    limits: outLimits,
    fontRules: profile?.fontRules || {},
    instanceFontRules: profile?.instanceFontRules || {},
    shapeGeometry: profile?.shapeGeometry || {}
  };
}

function extractResponseText(data) {
  if (!data) {
    return '';
  }

  if (typeof data === 'string') {
    return data;
  }

  if (typeof data.output_text === 'string') {
    return data.output_text;
  }

  if (typeof data.text === 'string') {
    return data.text;
  }

  if (typeof data.content === 'string') {
    return data.content;
  }

  if (Array.isArray(data.choices) && data.choices[0]?.message?.content) {
    return String(data.choices[0].message.content);
  }

  const pieces = [];

  function walk(x) {
    if (!x) return;

    if (typeof x === 'string') {
      pieces.push(x);
      return;
    }

    if (Array.isArray(x)) {
      x.forEach(walk);
      return;
    }

    if (typeof x === 'object') {
      if (typeof x.text === 'string') pieces.push(x.text);
      if (typeof x.output_text === 'string') pieces.push(x.output_text);
      if (typeof x.content === 'string') pieces.push(x.content);
      if (Array.isArray(x.content)) walk(x.content);
      if (Array.isArray(x.output)) walk(x.output);
      if (Array.isArray(x.message?.content)) walk(x.message.content);
    }
  }

  walk(data.output || data);

  return pieces.join('\n').trim();
}

function buildErrorDetail(err) {
  const status = err.response?.status;
  const statusText = err.response?.statusText;
  const responseData = err.response?.data;
  const responseHeaders = err.response?.headers;
  const requestId =
    responseHeaders?.['x-request-id'] ||
    responseHeaders?.['x-correlation-id'] ||
    responseHeaders?.['x-amzn-requestid'] ||
    responseHeaders?.['x-ms-request-id'] ||
    '';

  return {
    message: err.message,
    code: err.code,
    name: err.name,
    status,
    statusText,
    requestId,
    responseData,
    responseHeaders,
    isAxiosError: Boolean(err.isAxiosError)
  };
}

function logAxiosError(title, err, requestSummary) {
  const detail = buildErrorDetail(err);

  logBlock(title, {
    error: {
      message: detail.message,
      code: detail.code,
      name: detail.name,
      isAxiosError: detail.isAxiosError,
      status: detail.status,
      statusText: detail.statusText,
      requestId: detail.requestId
    },
    responseHeaders: detail.responseHeaders,
    responseData: detail.responseData,
    request: requestSummary
  }, MAX_LOG_CHARS);

  if (detail.status === 401) {
    node.warn('PPTX layout LLM auth hint: 401 Unauthorized. Token may be expired or invalid.');
  }

  if (detail.status === 403) {
    node.warn('PPTX layout LLM auth hint: 403 Forbidden. Token is present but user/project/asset/model may not be authorized.');
  }

  if (detail.status === 404) {
    node.warn('PPTX layout LLM auth hint: 404 Not Found. Check endpoint URL or API route.');
  }

  if (detail.status === 429) {
    node.warn('PPTX layout LLM auth hint: 429 Rate limit/quota issue.');
  }

  if (detail.status >= 500) {
    node.warn('PPTX layout LLM auth hint: server-side error from enabler.');
  }
}

function dedupeWarnings(warnings) {
  const seen = new Set();
  const out = [];

  for (const warning of warnings || []) {
    const text = String(warning || '').trim();

    if (!text || seen.has(text)) {
      continue;
    }

    seen.add(text);
    out.push(text);
  }

  return out;
}

const layout = msg._pptxLayout || {};

if (msg.payload?.outputType !== 'pptx' || layout.skipLlm || !Array.isArray(layout.candidates) || !layout.candidates.length) {
  node.warn('PPTX layout: LLM call skipped. outputType=' + msg.payload?.outputType + ', skipLlm=' + layout.skipLlm + ', candidates=' + (Array.isArray(layout.candidates) ? layout.candidates.length : 0));
  return msg;
}

const security = await resolveSecurity(msg);

logBlock('LLM SECURITY RESOLUTION', {
  loginKey: security.loginKey,
  hasBearerToken: Boolean(security.bearerToken),
  bearerTokenMasked: maskToken(security.bearerToken),
  userId: mask(security.userId, 8, 6),
  projectId: mask(security.projectId, 8, 6),
  assetId: mask(security.assetId, 8, 6),
  sources: security.sources
}, 4000);

const missing = [];

if (!security.bearerToken) missing.push('bearerToken');
if (!security.userId) missing.push('axet-user-id');
if (!security.projectId) missing.push('axet-project-id');
if (!security.assetId) missing.push('axet-asset-id');

if (missing.length) {
  msg._pptxLayout.llmError = 'Missing credentials for LLM enabler: ' + missing.join(', ');
  msg._pptxLayout.warnings = msg._pptxLayout.warnings || [];
  msg._pptxLayout.warnings.push(msg._pptxLayout.llmError + '. Using deterministic layout.');
  msg._pptxLayout.warnings = dedupeWarnings(msg._pptxLayout.warnings);

  logBlock('LLM MISSING CREDENTIALS', {
    missing,
    security: {
      hasBearerToken: Boolean(security.bearerToken),
      bearerTokenMasked: maskToken(security.bearerToken),
      userId: mask(security.userId, 8, 6),
      projectId: mask(security.projectId, 8, 6),
      assetId: mask(security.assetId, 8, 6),
      sources: security.sources
    }
  }, 4000);

  node.warn(msg._pptxLayout.llmError);
  return msg;
}

const profile = layout.profile || {};
const model = firstValue(msg.pptxLayoutModel, msg.payload?.pptxLayoutModel, profile.llm?.model, 'gpt-5.2');
const batchSize = Number(profile.llm?.batchSize || 4);
const timeoutMs = Number(profile.llm?.timeoutMs || 90000);
const batches = chunkArray(layout.candidates, Math.max(1, batchSize));
const rawResponses = [];

logBlock('LLM CALL PLAN', {
  url: LLM_URL,
  model,
  batchSize,
  timeoutMs,
  totalCandidates: layout.candidates.length,
  totalBatches: batches.length,
  candidateIndexes: layout.candidates.map((x) => x.index),
  reason: layout.reason,
  outputContractKeys: layout.outputContract ? Object.keys(layout.outputContract) : [],
  profileTemplateCode: profile?.templateCode,
  profileStrategy: profile?.strategy
}, 5000);

for (let i = 0; i < batches.length; i++) {
  const batch = batches[i];

  const userPayload = {
    task: 'Adapt project reference data to the static PPTX template. Return only valid JSON.',
    layoutProfile: slimProfile(profile),
    outputContract: layout.outputContract,
    references: batch
  };

  const requestPayload = {
    model,
    stream: false,
    input: [
      {
        role: 'system',
        content: layout.systemPrompt
      },
      {
        role: 'user',
        content: JSON.stringify(userPayload, null, 2)
      }
    ]
  };

  const headers = {
    Authorization: 'Bearer ' + security.bearerToken,
    'axet-project-id': security.projectId,
    'axet-user-id': security.userId,
    'axet-asset-id': security.assetId,
    'Content-Type': 'application/json'
  };

  const requestSummary = {
    url: LLM_URL,
    method: 'POST',
    model,
    stream: false,
    batch: i + 1,
    totalBatches: batches.length,
    candidateIndexes: batch.map((x) => x.index),
    headers: maskHeaders(headers),
    payloadSizeChars: safeStringify(requestPayload).length,
    systemPromptChars: String(layout.systemPrompt || '').length,
    userPayloadChars: safeStringify(userPayload).length
  };

  logBlock('LLM REQUEST SUMMARY BATCH ' + (i + 1), requestSummary, 4000);

  if (DEBUG_PROMPT) {
    logBlock('LLM REQUEST PAYLOAD BATCH ' + (i + 1), {
      model: requestPayload.model,
      stream: requestPayload.stream,
      input: [
        {
          role: 'system',
          content: truncate(requestPayload.input[0].content, 2000)
        },
        {
          role: 'user',
          content: truncate(requestPayload.input[1].content, MAX_LOG_CHARS)
        }
      ]
    }, MAX_LOG_CHARS + 3000);
  }

  try {
    const startedAt = Date.now();

    const rsp = await axios.post(LLM_URL, requestPayload, {
      headers,
      timeout: timeoutMs,
      validateStatus: () => true
    });

    const elapsedMs = Date.now() - startedAt;
    const responseText = extractResponseText(rsp.data);

    logBlock('LLM RESPONSE SUMMARY BATCH ' + (i + 1), {
      status: rsp.status,
      statusText: rsp.statusText,
      elapsedMs,
      responseHeaders: rsp.headers,
      responseDataKeys: rsp.data && typeof rsp.data === 'object' ? Object.keys(rsp.data) : [],
      extractedTextChars: responseText.length,
      extractedTextPreview: truncate(responseText, 3000)
    }, 7000);

    if (DEBUG_RESPONSE) {
      logBlock('LLM RESPONSE RAW BATCH ' + (i + 1), rsp.data, MAX_LOG_CHARS);
    }

    if (rsp.status < 200 || rsp.status >= 300) {
      const detail = typeof rsp.data === 'string' ? rsp.data : safeStringify(rsp.data, 1000);
      const warning = 'LLM batch ' + (i + 1) + ' failed: HTTP ' + rsp.status + ' ' + (rsp.statusText || '') + ' - ' + detail;

      msg._pptxLayout.warnings = msg._pptxLayout.warnings || [];
      msg._pptxLayout.warnings.push(warning);
      msg._pptxLayout.warnings = dedupeWarnings(msg._pptxLayout.warnings);

      node.warn('PPTX layout LLM batch failed: HTTP ' + rsp.status + ' ' + (rsp.statusText || '') + ' detail=' + truncate(detail, 1000));

      if (rsp.status === 403) {
        logBlock('LLM 403 DIAGNOSTIC BATCH ' + (i + 1), {
          likelyCauses: [
            'Token is valid but not authorized for llm-enabler',
            'Project is not allowed for this asset',
            'Asset is not allowed for this model',
            'Model is not enabled for this user/project/asset',
            'Security context belongs to a different session or stale cache'
          ],
          model,
          userId: mask(security.userId, 8, 6),
          projectId: mask(security.projectId, 8, 6),
          assetId: mask(security.assetId, 8, 6),
          credentialSources: security.sources,
          responseData: rsp.data
        }, 5000);
      }

      continue;
    }

    rawResponses.push({
      batch: i + 1,
      candidateIndexes: batch.map((x) => x.index),
      status: rsp.status,
      elapsedMs,
      data: rsp.data
    });
  } catch (err) {
    const detail = err.response?.data ? safeStringify(err.response.data, 1000) : err.message;
    const warning = 'LLM batch ' + (i + 1) + ' failed: ' + detail;

    msg._pptxLayout.warnings = msg._pptxLayout.warnings || [];
    msg._pptxLayout.warnings.push(warning);
    msg._pptxLayout.warnings = dedupeWarnings(msg._pptxLayout.warnings);

    logAxiosError('LLM AXIOS ERROR BATCH ' + (i + 1), err, requestSummary);
    node.warn('PPTX layout LLM batch failed: ' + truncate(detail, 1000));
  }
}

