    VOLUMEN_USUARIOS: { min: 7.6, base: 8.1, max: 8.5, soft: 28, hard: 44, maxLines: 2 },
    IDIOMA_TRABAJO: { min: 7.8, base: 8.2, max: 8.6, soft: 14, hard: 22, maxLines: 1 },
    TIPO_SERVICIO: { min: 7.6, base: 8.4, max: 9.0, soft: 46, hard: 70, maxLines: 2 },
    TIPO_PROYECTO: { min: 7.6, base: 8.4, max: 9.0, soft: 26, hard: 38, maxLines: 1 },
    OBJETIVOS: { min: 7.8, base: 9.0, max: 10.2, soft: 360, hard: 560, maxLines: 8 },
    TAREAS: { min: 7.6, base: 8.8, max: 9.8, soft: 420, hard: 650, maxLines: 9 },
    RESULTADOS: { min: 7.4, base: 8.4, max: 9.2, soft: 320, hard: 560, maxLines: 8 },
    TECNOLOGIAS: { min: 6.9, base: 7.6, max: 8.3, soft: 160, hard: 240, maxLines: 5 },
    METODOLOGIAS: { min: 6.9, base: 7.6, max: 8.3, soft: 95, hard: 150, maxLines: 4 },
    PERFILES_PROFESIONALES: { min: 6.8, base: 7.5, max: 8.2, soft: 140, hard: 220, maxLines: 5 },
    PALABRAS_CLAVE: { min: 6.4, base: 7.0, max: 7.4, soft: 105, hard: 160, maxLines: 4 },
    FUENTES: { min: 6.2, base: 7.0, max: 7.4, soft: 105, hard: 160, maxLines: 4 }
  };

const DEFAULT_INSTANCE_FONT_RULES = {
    CLIENTE_HEADER: { min: 10.8, base: 12.2, max: 13.2, soft: 34, hard: 62, maxLines: 2 },
    CLIENTE_CARD: { min: 14.2, base: 15.8, max: 17.0, soft: 42, hard: 72, maxLines: 3 },
    TITULO_PROYECTO_CARD: { min: 11.8, base: 15.2, max: 16.8, soft: 66, hard: 105, maxLines: 4 }
  };

const DEFAULT_SHAPE_GEOMETRY = {
    // EMUs: PPT uses 914400 EMUs per inch. These overrides only touch matching placeholder boxes.
    CLIENTE_HEADER: { x: 6400000, y: 64000, cx: 3720000, cy: 370000 },
    CLIENTE_CARD: { x: 457200, y: 1040000, cx: 2761488, cy: 700000 },
    TITULO_PROYECTO_CARD: { x: 493776, y: 1780000, cx: 2688336, cy: 800000 }
  };

function clamp(n, min, max) {
  return Math.max(min, Math.min(max, n));
}

function mergeFontRules(profile) {
  const out = JSON.parse(JSON.stringify(DEFAULT_PPTX_FONT_RULES));
  const limits = profile?.limits || {};
  for (const key of Object.keys(limits)) {
    if (limits[key]?.fontPt) {
      out[key] = { ...(out[key] || {}), ...limits[key].fontPt };
    }
  }
  if (profile?.fontRules && typeof profile.fontRules === 'object') {
    for (const [key, rule] of Object.entries(profile.fontRules)) {
      out[key] = { ...(out[key] || {}), ...(rule || {}) };
    }
  }
  return out;
}


function mergeInstanceFontRules(profile) {
  const out = JSON.parse(JSON.stringify(DEFAULT_INSTANCE_FONT_RULES));
  if (profile?.instanceFontRules && typeof profile.instanceFontRules === 'object') {
    for (const [key, rule] of Object.entries(profile.instanceFontRules)) {
      out[key] = { ...(out[key] || {}), ...(rule || {}) };
    }
  }
  return out;
}

function mergeShapeGeometry(profile) {
  const out = JSON.parse(JSON.stringify(DEFAULT_SHAPE_GEOMETRY));
  if (profile?.shapeGeometry && typeof profile.shapeGeometry === 'object') {
    for (const [key, geom] of Object.entries(profile.shapeGeometry)) {
      out[key] = { ...(out[key] || {}), ...(geom || {}) };
    }
  }
  return out;
}

function nodeLocalName(node) {
  return String(node?.localName || node?.nodeName || '').split(':').pop();
}

function findAncestor(node, localName) {
  let cur = node;
  while (cur) {
    if (nodeLocalName(cur) === localName) return cur;
    cur = cur.parentNode;
  }
  return null;
}

function firstDescendantByLocalName(node, localName) {
  if (!node) return null;
  const stack = [];
  for (let child = node.firstChild; child; child = child.nextSibling) stack.push(child);
  while (stack.length) {
    const cur = stack.shift();
    if (nodeLocalName(cur) === localName) return cur;
    for (let child = cur.firstChild; child; child = child.nextSibling) stack.push(child);
  }
  return null;
}

function readShapeGeom(sp) {
  const xfrm = firstDescendantByLocalName(sp, 'xfrm');
  if (!xfrm) return null;
  let off = null;
  let ext = null;
  for (let child = xfrm.firstChild; child; child = child.nextSibling) {
    if (nodeLocalName(child) === 'off') off = child;
    if (nodeLocalName(child) === 'ext') ext = child;
  }
  if (!off || !ext) return null;
  return {
    x: Number(off.getAttribute('x') || 0),
    y: Number(off.getAttribute('y') || 0),
    cx: Number(ext.getAttribute('cx') || 0),
    cy: Number(ext.getAttribute('cy') || 0)
  };
}

function setShapeGeom(sp, geom) {
  if (!sp || !geom) return;
  const xfrm = firstDescendantByLocalName(sp, 'xfrm');
  if (!xfrm) return;
  let off = null;
  let ext = null;
  for (let child = xfrm.firstChild; child; child = child.nextSibling) {
    if (nodeLocalName(child) === 'off') off = child;
    if (nodeLocalName(child) === 'ext') ext = child;
  }
  if (off) {
    if (geom.x !== undefined) off.setAttribute('x', String(Math.round(Number(geom.x))));
    if (geom.y !== undefined) off.setAttribute('y', String(Math.round(Number(geom.y))));
  }
  if (ext) {
    if (geom.cx !== undefined) ext.setAttribute('cx', String(Math.round(Number(geom.cx))));
    if (geom.cy !== undefined) ext.setAttribute('cy', String(Math.round(Number(geom.cy))));
  }
}

function classifyPlaceholderInstance(phKey, geom) {
  if (phKey === 'CLIENTE') {
    if (geom && geom.y < 500000 && geom.x > 6000000) return 'CLIENTE_HEADER';
    if (geom && geom.x < 3300000 && geom.y > 850000 && geom.y < 1700000) return 'CLIENTE_CARD';
  }
  if (phKey === 'TITULO_PROYECTO' && geom && geom.x < 3300000) return 'TITULO_PROYECTO_CARD';
  return phKey;
}

function emuToPt(value) {
  return Number(value || 0) / 12700;
}

function estimateWrappedLines(text, pt, geom) {
  const widthPt = emuToPt(geom?.cx || 0);
  if (!widthPt || !pt) return clean(text).split(/\n+/).filter(Boolean).length || 1;
  const avgCharWidthPt = pt * 0.50;
  const charsPerLine = Math.max(8, Math.floor(widthPt / avgCharWidthPt));
  const lines = clean(text).split(/\n+/).filter((x) => x.trim() !== '');
  if (!lines.length) return 1;
  return lines.reduce((sum, line) => {
    const len = line.replace(/^[-*\u2022]\s*/, '').trim().length;
    return sum + Math.max(1, Math.ceil(len / charsPerLine));
  }, 0);
}

function visualLength(text) {
  const s = clean(text);
  const lines = s.split(/\n+/).map((x) => x.trim()).filter(Boolean);
  const bulletPenalty = lines.filter((x) => /^[-*\u2022]/.test(x)).length * 8;
  return s.replace(/\s+/g, ' ').length + Math.max(0, lines.length - 1) * 14 + bulletPenalty;
}

function detectPlaceholderKey(templateText) {
  const phs = [];
  const rx = /\{\{([A-Z0-9_]+)\}\}/g;
  let m;
  while ((m = rx.exec(String(templateText || ''))) !== null) phs.push(m[1]);
  if (!phs.length) return '';
  const priority = [
    'OBJETIVOS', 'TAREAS', 'RESULTADOS', 'TECNOLOGIAS', 'METODOLOGIAS',
    'PERFILES_PROFESIONALES', 'PALABRAS_CLAVE', 'FUENTES', 'TITULO_PROYECTO',
    'CLIENTE', 'TIPO_SERVICIO', 'TIPO_PROYECTO'
  ];
  for (const key of priority) if (phs.includes(key)) return key;
  return phs[0];
}

function computeFontPt(rule, text, geom) {
  if (!rule) return null;
  const min = Number(rule.min || rule.base || 7);
  const base = Number(rule.base || min);
  const max = Number(rule.max || base);
  const soft = Number(rule.soft || rule.hard || 100);
  const hard = Number(rule.hard || soft || 100);
  const chars = visualLength(text);
  const explicitLines = clean(text).split(/\n+/).filter(Boolean).length || 1;
  const lineDensity = rule.maxLines ? explicitLines / Number(rule.maxLines) : 0;
  const charDensity = hard ? chars / hard : 0;
  const density = Math.max(charDensity, lineDensity);

  let pt;
  if (density <= 0.55) pt = clamp(max, min, max);
  else if (density <= 0.80) pt = clamp(base + (max - base) * ((0.80 - density) / 0.25), min, max);
  else if (density >= 1.00) pt = clamp(min, min, max);
  else pt = clamp(base - (base - min) * ((density - 0.80) / 0.20), min, max);

  if (!geom) return Math.round(pt * 100) / 100;

  const heightPt = emuToPt(geom.cy);
  for (let candidate = pt; candidate >= min; candidate -= 0.10) {
    const wrappedLines = estimateWrappedLines(text, candidate, geom);
    const heightLines = heightPt ? Math.floor(heightPt / (candidate * 1.14)) : 99;
    const allowedLines = Math.max(1, Math.min(Number(rule.maxLines || 99), heightLines || 1));
    if (wrappedLines <= allowedLines) return Math.round(candidate * 100) / 100;
  }

  return Math.round(min * 100) / 100;
}

function applyFontStyleToParagraph(p, options, select) {
  const opts = options || {};
  const props = select(".//*[local-name()='rPr'] | .//*[local-name()='endParaRPr'] | .//*[local-name()='defRPr']", p);
  if (!props.length) return;
  if (opts.pt) {
    const sz = String(Math.round(Number(opts.pt) * 100));
    for (const pr of props) pr.setAttribute('sz', sz);
  }
  if (opts.bold !== undefined) {
    for (const pr of props) pr.setAttribute('b', opts.bold ? '1' : '0');
  }
}

function applyFontPtToParagraph(p, pt, select) {
  if (!pt) return;
  applyFontStyleToParagraph(p, { pt }, select);
}

function applySemanticStyleToParagraph(p, text, select) {
  const raw = clean(text);
  const k = raw.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  const mainSectionTitles = [
    'contexto y retos / objetivos',
    'actividades clave',
    'datos clave y capacidades',
    'trazabilidad',
    'resultados',
    'ficha resumen'
  ];

  if (mainSectionTitles.includes(k)) {
    applyFontStyleToParagraph(p, { pt: k === 'resultados' ? 9.3 : 9.2, bold: true }, select);
    return;
  }

  if (/^(tecnologias|metodologias|perfiles profesionales):$/.test(k)) {
    applyFontStyleToParagraph(p, { pt: 8.7, bold: true }, select);
    return;
  }

  if (/^(servicio|proyecto):\s+/.test(k)) {
    applyFontStyleToParagraph(p, { pt: 8.4, bold: true }, select);
    return;
  }

  if (/^(sector|pais de ejecucion|inicio \/ fin|duracion|importe total|volumen de usuarios|idioma de trabajo):\s+/.test(k)) {
    applyFontStyleToParagraph(p, { pt: 8.15, bold: false }, select);
  }
}

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFC')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\u00A0/g, ' ')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

function clean(value) {
  return normalizeText(value).replace(/[\t ]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}

function valueOrDash(value) {
  const s = clean(value);
  return s || '-';
}

function getEntry(zip, name) { return zip.getEntry(name); }
function readEntryText(zip, name) { const e = getEntry(zip, name); return e ? e.getData().toString('utf8') : null; }
function writeEntryText(zip, name, text) {
  const buf = Buffer.from(String(text), 'utf8');
  const entry = getEntry(zip, name);
  if (entry) zip.updateFile(name, buf); else zip.addFile(name, buf);
}
function copyEntry(zip, fromName, toName) {
  const entry = getEntry(zip, fromName);
  if (!entry) return false;
  const existing = getEntry(zip, toName);
  if (existing) zip.deleteFile(toName);
  zip.addFile(toName, Buffer.from(entry.getData()));
  return true;
}

function sanitizeSlideXmlForClone(xml) {
  return String(xml || '')
    .replace(/<p14:creationId\b[^/>]*\/>/g, '')
    .replace(/<p14:creationId\b[^>]*>[\s\S]*?<\/p14:creationId>/g, '')
    .replace(/<a16:creationId\b[^/>]*\/>/g, '')
    .replace(/<a16:creationId\b[^>]*>[\s\S]*?<\/a16:creationId>/g, '');
}

function sanitizeSlideRelsForClone(xml) {
  return String(xml || '')
    .replace(/<Relationship[^>]+Type="[^"]*\/notesSlide"[^>]*\/>/g, '')
    .replace(/<Relationship[^>]+Type="[^"]*\/comments"[^>]*\/>/g, '')
    .replace(/<Relationship[^>]+Type="[^"]*\/slideComments"[^>]*\/>/g, '')
    .replace(/<Relationship[^>]+Type="[^"]*\/tags"[^>]*\/>/g, '');
}

function slideNumber(name) {
  const m = String(name).match(/slide(\d+)\.xml$/i);
  return m ? parseInt(m[1], 10) : 0;
}

function listSlideFiles(zip) {
  return zip.getEntries()
    .map((e) => e.entryName)
    .filter((n) => /^ppt\/slides\/slide\d+\.xml$/i.test(n))
    .sort((a, b) => slideNumber(a) - slideNumber(b));
}

function detectTemplateSlide(zip, slideFiles) {
  for (const slideName of slideFiles) {
    const xml = readEntryText(zip, slideName) || '';
    if (xml.includes('{{TITULO_PROYECTO}}') || xml.includes('{{OBJETIVOS}}') || xml.includes('{{TAREAS}}') || xml.includes('{{RESULTADOS}}')) {
      return slideName;
    }
  }
  for (const slideName of slideFiles) {
    const xml = readEntryText(zip, slideName) || '';
    if (xml.includes('{{REF_TITULO}}') || xml.includes('{{REF_OBJETIVOS}}') || xml.includes('{{REF_TAREAS}}')) return slideName;
  }
  return slideFiles[0] || null;
}

function maxRegexNumber(text, regex, fallback) {
  let max = fallback || 0;
  let m;
  while ((m = regex.exec(text)) !== null) {
    const n = parseInt(m[1], 10);
    if (!Number.isNaN(n) && n > max) max = n;
  }
  return max;
}

function ensureSlideContentType(zip, slideNo) {
  const name = '[Content_Types].xml';
  let xml = readEntryText(zip, name);
  if (!xml) return;
  const part = '/ppt/slides/slide' + slideNo + '.xml';
  if (xml.includes('PartName="' + part + '"')) return;
  const override = '<Override PartName="' + part + '" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/>';
  xml = xml.replace('</Types>', override + '</Types>');
  writeEntryText(zip, name, xml);
}

function appendSlideToPresentation(zip, slideNo) {
  const presName = 'ppt/presentation.xml';
  const relsName = 'ppt/_rels/presentation.xml.rels';
  let presXml = readEntryText(zip, presName);
  let relsXml = readEntryText(zip, relsName);
  if (!presXml || !relsXml) throw new Error('No se pudo leer presentation.xml o presentation.xml.rels');

  const maxSlideId = maxRegexNumber(presXml, /<p:sldId[^>]*\sid="(\d+)"/g, 255);
  const maxRid = maxRegexNumber(relsXml, /Id="rId(\d+)"/g, 0);
  const newSlideId = maxSlideId + 1;
  const newRid = 'rId' + (maxRid + 1);

  const rel = '<Relationship Id="' + newRid + '" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide" Target="slides/slide' + slideNo + '.xml"/>';
  relsXml = relsXml.replace('</Relationships>', rel + '</Relationships>');

  const slideNode = '<p:sldId id="' + newSlideId + '" r:id="' + newRid + '"/>';
  if (presXml.includes('</p:sldIdLst>')) presXml = presXml.replace('</p:sldIdLst>', slideNode + '</p:sldIdLst>');
  else presXml = presXml.replace('</p:presentation>', '<p:sldIdLst>' + slideNode + '</p:sldIdLst></p:presentation>');

  writeEntryText(zip, presName, presXml);
  writeEntryText(zip, relsName, relsXml);
}

function createOrReuseSlide(zip, templateSlide, modelIndex, templateXmlOriginal, templateRelsXmlOriginal) {
  const templateNo = slideNumber(templateSlide);

  if (modelIndex === 0) {
    writeEntryText(zip, templateSlide, sanitizeSlideXmlForClone(templateXmlOriginal));
    return templateSlide;
  }

  const slideFiles = listSlideFiles(zip);
  const maxSlideNo = slideFiles.reduce((max, name) => Math.max(max, slideNumber(name)), 0);
  const newSlideNo = maxSlideNo + 1;
  const newSlideName = 'ppt/slides/slide' + newSlideNo + '.xml';
  const newRelsName = 'ppt/slides/_rels/slide' + newSlideNo + '.xml.rels';

  writeEntryText(zip, newSlideName, sanitizeSlideXmlForClone(templateXmlOriginal));

  if (templateRelsXmlOriginal) {
    writeEntryText(zip, newRelsName, sanitizeSlideRelsForClone(templateRelsXmlOriginal));
  } else {
    copyEntry(zip, 'ppt/slides/_rels/slide' + templateNo + '.xml.rels', newRelsName);
  }

  ensureSlideContentType(zip, newSlideNo);
  appendSlideToPresentation(zip, newSlideNo);
  return newSlideName;
}

function replaceAllPlaceholders(text, replacements) {
  let out = String(text ?? '');
  for (const [ph, val] of Object.entries(replacements || {})) {
    out = out.split(ph).join(String(val ?? ''));
  }
  return out;
}

function processSlideXml(xml, replacements, layoutProfile) {
  const doc = new DOMParser().parseFromString(xml, 'text/xml');
  const select = xpath.useNamespaces({
    a: 'http://schemas.openxmlformats.org/drawingml/2006/main',
    p: 'http://schemas.openxmlformats.org/presentationml/2006/main'
  });
  const fontRules = mergeFontRules(layoutProfile || {});
  const instanceFontRules = mergeInstanceFontRules(layoutProfile || {});
  const shapeGeometry = mergeShapeGeometry(layoutProfile || {});

  const paragraphs = select("//*[local-name()='txBody']/*[local-name()='p']", doc);
  for (const p of paragraphs) {
    const pTextNodes = select(".//*[local-name()='t']/text()", p);
    if (!pTextNodes.length) continue;
    const joined = pTextNodes.map((n) => n.data).join('');
    const phKey = detectPlaceholderKey(joined);
    const replaced = replaceAllPlaceholders(joined, replacements);
    const finalText = replaced !== joined ? replaced : joined;

    if (replaced !== joined) {
      const sp = findAncestor(p, 'sp');
      const originalGeom = readShapeGeom(sp);
      const instanceKey = classifyPlaceholderInstance(phKey, originalGeom);
      if (shapeGeometry[instanceKey]) setShapeGeom(sp, shapeGeometry[instanceKey]);
      const finalGeom = readShapeGeom(sp) || originalGeom;

      pTextNodes[0].data = replaced;
      for (let i = 1; i < pTextNodes.length; i++) pTextNodes[i].data = '';

      const rule = (instanceKey && instanceFontRules[instanceKey]) || (phKey ? fontRules[phKey] : null);
      const pt = computeFontPt(rule, replaced, finalGeom);
      applyFontPtToParagraph(p, pt, select);
    }

    applySemanticStyleToParagraph(p, finalText, select);
  }

  const tNodes = select("//*[local-name()='t']/text()", doc);
  for (const tn of tNodes) {
    const replaced = replaceAllPlaceholders(tn.data, replacements);
    if (replaced !== tn.data) tn.data = replaced;
  }
  return new XMLSerializer().serializeToString(doc);
}

function extractLegacyReplacements(data) {
  const rawItems = [];
  if (Array.isArray(data)) rawItems.push(...data.filter((x) => x && typeof x === 'object'));
  else if (data && typeof data === 'object') {
    if (Array.isArray(data.items)) rawItems.push(...data.items.filter((x) => x && typeof x === 'object'));
    else {
      for (const [maybeRule, value] of Object.entries(data)) {
        if (Array.isArray(value)) {
          for (let x of value) if (x && typeof x === 'object') rawItems.push(x.rule ? x : { ...x, rule: maybeRule });
        } else if (value && typeof value === 'object') rawItems.push(value.rule ? value : { ...value, rule: maybeRule });
      }
    }
  }
  const replacements = {};
  for (const item of rawItems) {
    if (!item.rule) continue;
    replacements['[' + item.rule + ']'] = String(item.aiSuggestion || item.respuesta || item.valor || '');
  }
  return replacements;
}

function fallbackLayoutFromReference(ref, idx) {
  return {
    _referenceIndex: ref.index || idx,
    _referenceOrder: idx,
    _layoutSource: 'fallback_raw',
    TITULO_PROYECTO: valueOrDash(ref.titulo || ('Referencia ' + idx)),
    CLIENTE: valueOrDash(ref.cliente),
    SECTOR: valueOrDash(ref.sector),
    PAIS_EJECUCION: valueOrDash(ref.pais),
    FECHA_INICIO: valueOrDash(ref.fechaInicio),
    FECHA_FIN: valueOrDash(ref.fechaFin),
    DURACION_MESES: valueOrDash(ref.duracion),
    IMPORTE_TOTAL: valueOrDash(ref.importe),
    VOLUMEN_USUARIOS: valueOrDash(ref.volumenUsuarios),
    IDIOMA_TRABAJO: valueOrDash(ref.idiomaTrabajo),
    TIPO_SERVICIO: valueOrDash(ref.tipoServicio),
    TIPO_PROYECTO: valueOrDash(ref.tipoProyecto),
    OBJETIVOS: valueOrDash(ref.objetivos),
    TAREAS: valueOrDash(ref.tareas),
    RESULTADOS: valueOrDash(ref.resultados),
    TECNOLOGIAS: valueOrDash(ref.tecnologias),
    METODOLOGIAS: valueOrDash(ref.metodologias),
    CPV: valueOrDash(ref.cpv),
    PALABRAS_CLAVE: valueOrDash(ref.palabrasClave),
    PERFILES_PROFESIONALES: valueOrDash(ref.perfilesProfesionales || ref.perfiles),
    FUENTES: Array.isArray(ref.fuentes) ? ref.fuentes.slice(0, 8).join(' | ') : valueOrDash(ref.fuentes),
    N: String(idx).padStart(2, '0')
  };
}

function buildReplacements(model) {
  const replacements = {};
  for (const key of PLACEHOLDERS) replacements['{{' + key + '}}'] = clean(model[key] || '-');

  replacements['{{REF_TITULO}}'] = replacements['{{TITULO_PROYECTO}}'];
  replacements['{{REF_CLIENTE}}'] = replacements['{{CLIENTE}}'];
  replacements['{{REF_SECTOR}}'] = replacements['{{SECTOR}}'];
  replacements['{{REF_PAIS}}'] = replacements['{{PAIS_EJECUCION}}'];
  replacements['{{REF_FECHA_INICIO}}'] = replacements['{{FECHA_INICIO}}'];
  replacements['{{REF_FECHA_FIN}}'] = replacements['{{FECHA_FIN}}'];
  replacements['{{REF_DURACION}}'] = replacements['{{DURACION_MESES}}'];
  replacements['{{REF_IMPORTE}}'] = replacements['{{IMPORTE_TOTAL}}'];
  replacements['{{REF_USUARIOS}}'] = replacements['{{VOLUMEN_USUARIOS}}'];
  replacements['{{REF_IDIOMA}}'] = replacements['{{IDIOMA_TRABAJO}}'];
  replacements['{{REF_TIPO_SERVICIO}}'] = replacements['{{TIPO_SERVICIO}}'];
  replacements['{{REF_TIPO_PROYECTO}}'] = replacements['{{TIPO_PROYECTO}}'];
  replacements['{{REF_OBJETIVOS}}'] = replacements['{{OBJETIVOS}}'];
  replacements['{{REF_CONTEXTO_RETOS}}'] = replacements['{{OBJETIVOS}}'];
  replacements['{{REF_TAREAS}}'] = replacements['{{TAREAS}}'];
  replacements['{{REF_ACTIVIDADES_CLAVE}}'] = replacements['{{TAREAS}}'];
  replacements['{{REF_RESULTADOS}}'] = replacements['{{RESULTADOS}}'];
  replacements['{{REF_TECNOLOGIAS}}'] = replacements['{{TECNOLOGIAS}}'];
  replacements['{{REF_METODOLOGIAS}}'] = replacements['{{METODOLOGIAS}}'];
  replacements['{{REF_CPV}}'] = replacements['{{CPV}}'];
  replacements['{{REF_KEYWORDS}}'] = replacements['{{PALABRAS_CLAVE}}'];
  replacements['{{REF_PALABRAS_CLAVE}}'] = replacements['{{PALABRAS_CLAVE}}'];
  replacements['{{REF_PERFILES}}'] = replacements['{{PERFILES_PROFESIONALES}}'];
  replacements['{{REF_FUENTES}}'] = replacements['{{FUENTES}}'];
  return replacements;
}

async function run() {
  const template = String(msg.payload?.template || msg.submission?.data?.template || msg.submission?.plantilla || msg.plantilla || '').trim();
  const filename = String(msg.payload?.filename || '').trim();
  const safeTemplate = path.basename(template);
  const safeFilename = path.basename(filename);
  const templatePath = path.join(TEMPLATES_DIR, safeTemplate);
  const outputPath = path.join(OUTPUT_DIR, safeFilename);

  if (!safeTemplate) throw new Error('Plantilla PPTX no informada');
  if (!safeFilename) throw new Error('Nombre de salida PPTX no informado');

  await fs.promises.access(templatePath);
  const zip = new AdmZip(templatePath);
  const data = msg.payload?.data || {};
  const slideFiles = listSlideFiles(zip);
  if (!slideFiles.length) throw new Error('No se encontraron slides en la plantilla PPTX');

  const templateSlide = detectTemplateSlide(zip, slideFiles);
  const templateXml = readEntryText(zip, templateSlide) || '';
  const templateSlideNo = slideNumber(templateSlide);
  const templateRelsName = 'ppt/slides/_rels/slide' + templateSlideNo + '.xml.rels';
  const templateRelsXml = readEntryText(zip, templateRelsName) || '';
  const hasReferenceTemplate = Boolean(templateXml.includes('{{TITULO_PROYECTO}}') || templateXml.includes('{{OBJETIVOS}}') || templateXml.includes('{{REF_'));

  node.warn('PPTX template slide=' + templateSlide + ', templateRels=' + templateRelsName + ', hasReferenceTemplate=' + hasReferenceTemplate);

  if (!hasReferenceTemplate) {
    const replacements = extractLegacyReplacements(data);
    if (msg.payload?.title) replacements['[TITLE]'] = String(msg.payload.title);
    for (const slideName of slideFiles) {
      const xml = readEntryText(zip, slideName);
      writeEntryText(zip, slideName, processSlideXml(xml, replacements, data.layoutProfile || msg.pptxLayoutProfile || {}));
    }
    await fs.promises.mkdir(OUTPUT_DIR, { recursive: true });
    await fs.promises.writeFile(outputPath, zip.toBuffer());
    msg.pptxFilename = safeFilename;
    msg.payload = { message: 'PPTX generado correctamente en modo legacy', filename: safeFilename, error: null };
    node.send([msg, null]);
    return;
  }

  const references = Array.isArray(data.references) ? data.references : [];
  const layoutReferences = Array.isArray(data.layoutReferences) && data.layoutReferences.length
    ? data.layoutReferences
    : references.map((ref, idx) => fallbackLayoutFromReference(ref || {}, idx + 1));

  if (!layoutReferences.length) throw new Error('No hay referencias o layoutReferences para generar la PPTX');

  const generationOrder = layoutReferences.map((model, i) => String(i + 1).padStart(2, '0') + ':' + (model._referenceType || model.referenceType || model.slideKind || (i === 0 ? 'general' : 'lote')) + ':' + (model.N || String(i + 1).padStart(2, '0')) + ':' + clean(model.TITULO_PROYECTO || 'Referencia')).join(' | ');
  node.warn('PPTX slide generation order=' + generationOrder);

  layoutReferences.forEach((model, i) => {
    const slideName = createOrReuseSlide(zip, templateSlide, i, templateXml, templateRelsXml);
    const xml = readEntryText(zip, slideName);
    const replacements = {
      ...buildReplacements(model),
      '{{PPTX_GENERATED_TITLE}}': msg.payload?.title || 'Referencias generadas'
    };
    writeEntryText(zip, slideName, processSlideXml(xml, replacements, data.layoutProfile || msg.pptxLayoutProfile || {}));
  });

  await fs.promises.mkdir(OUTPUT_DIR, { recursive: true });
  await fs.promises.writeFile(outputPath, zip.toBuffer());

  const warnings = Array.from(new Set([]
    .concat(msg.pptxLayoutWarnings || [])
    .concat(data.layoutAdaptation?.warnings || [])
    .filter(Boolean)
    .map((x) => String(x))));

  msg.pptxFilename = safeFilename;
  msg.generatedPptxFilename = safeFilename;
  msg.generatedPptxDir = OUTPUT_DIR;
  msg.pptxWarnings = warnings;
  msg.payload = {
    message: 'PPTX generado correctamente',
    filename: safeFilename,
    references: layoutReferences.length,
    slidesGenerated: layoutReferences.length,
    layoutAdaptation: data.layoutAdaptation || null,
    warnings,
    error: null
  };

  if (warnings.length) node.warn('PPTX generado con warnings: ' + JSON.stringify(warnings.slice(0, 20)));
  node.send([msg, null]);
}

run().catch((err) => {
  node.error('Error generando PPTX local: ' + err.message, msg);
  node.send([null, { payload: { message: 'Error generando PPTX local', error: err.message } }]);
});
return null;

