const fs = require("fs");
const path = require("path");

let JSZipMod;

try {
  JSZipMod = require("jszip");
} catch (err) {
  node.send([
    null,
    {
      payload: {
        message: "Error generando DOCX local",
        error: "No se pudo cargar jszip: " + err.message
      }
    }
  ]);

  return;
}

const OUTPUT_DIR = "/internal-storage-files/files/docxFiles";

function resolveJSZip(mod) {
  return mod && (mod.default || mod.JSZip || mod);
}

function createZip() {
  const JSZip = resolveJSZip(JSZipMod);

  if (typeof JSZip === "function") {
    return new JSZip();
  }

  throw new Error("JSZip incompatible: no constructor");
}

async function generateZipBuffer(zip) {
  if (zip && typeof zip.generateAsync === "function") {
    return zip.generateAsync({
      type: "nodebuffer",
      compression: "DEFLATE"
    });
  }

  if (zip && typeof zip.generate === "function") {
    const out = zip.generate({
      type: "nodebuffer",
      compression: "DEFLATE"
    });

    return Buffer.isBuffer(out) ? out : Buffer.from(out);
  }

  throw new Error("JSZip incompatible: no generate/generateAsync");
}

function safe(value) {
  return String(value ?? "");
}

function repairMojibake(text) {
  const value = safe(text);

  if (!value) {
    return value;
  }

  if (/[ÃÂâ�]/.test(value)) {
    try {
      const repaired = Buffer.from(value, "latin1").toString("utf8");

      if (repaired && repaired !== value) {
        return repaired;
      }
    } catch (_) { }
  }

  return value;
}

function normalizeText(input) {
  const raw = repairMojibake(input)
    .replace(/\r\n/g, "\n")
    .replace(/\t/g, "    ")
    .replace(/\u00A0/g, " ");

  const lines = raw.split("\n").map((line) => {
    const withoutRightSpaces = line.replace(/[ \t]+$/g, "");
    const bulletLine = withoutRightSpaces.match(/^(\s*)([-*•]|\d+[.)])\s+(.+)$/);

    if (bulletLine) {
      const indent = bulletLine[1] || "";
      const marker = bulletLine[2] || "-";
      const text = String(bulletLine[3] || "")
        .replace(/[ ]{2,}/g, " ")
        .replace(/\s+([,.;:!?])/g, "$1")
        .trim();

      return `${indent}${marker} ${text}`;
    }

    return withoutRightSpaces
      .trim()
      .replace(/[ ]{2,}/g, " ")
      .replace(/\s+([,.;:!?])/g, "$1");
  });

  return lines
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function cleanXmlText(value) {
  return safe(value).replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, "");
}

function xmlEscape(value) {
  return cleanXmlText(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function splitBlocks(text) {
  return normalizeText(text)
    .split(/\n{2,}/)
    .map((item) => item.replace(/^\n+|\n+$/g, ""))
    .filter((item) => item.trim());
}

function getBulletLevel(indentText) {
  const spaces = String(indentText || "").replace(/\t/g, "    ").length;

  if (spaces >= 6) {
    return 2;
  }

  if (spaces >= 2) {
    return 1;
  }

  return 0;
}

function reflowBlock(block) {
  const lines = block
    .split("\n")
    .map((line) => line.replace(/\t/g, "    ").replace(/[ \t]+$/g, ""))
    .filter((line) => line.trim());

  const result = [];
  let buffer = "";

  const flush = () => {
    if (buffer) {
      result.push({
        type: "text",
        text: buffer.trim()
      });

      buffer = "";
    }
  };

  for (const rawLine of lines) {
    const bulletMatch = rawLine.match(/^(\s*)[-*•]\s+(.+)$/);
    const numberedMatch = rawLine.match(/^(\s*)\d+[.)]\s+(.+)$/);

    if (bulletMatch) {
      flush();

      result.push({
        type: "bullet",
        level: getBulletLevel(bulletMatch[1]),
        text: String(bulletMatch[2] || "").trim()
      });

      continue;
    }

    if (numberedMatch) {
      flush();

      result.push({
        type: "bullet",
        level: getBulletLevel(numberedMatch[1]),
        text: String(numberedMatch[2] || "").trim()
      });

      continue;
    }

    const trimmed = rawLine.trim();
    buffer = buffer ? `${buffer} ${trimmed}` : trimmed;
  }

  flush();

  return result;
}

function getAnswerValue(value) {
  if (value == null) {
    return "";
  }

  if (typeof value !== "object" || Array.isArray(value)) {
    return safe(value);
  }

  const candidates = [
    value.aiSuggestion,
    value.respuesta,
    value.valor,
    value.answer,
    value.value,
    value.texto,
    value.text
  ];

  for (const candidate of candidates) {
    if (candidate !== undefined && candidate !== null) {
      return safe(candidate);
    }
  }

  return "";
}

function getRuleValue(item, fallback) {
  if (!item || typeof item !== "object") {
    return fallback;
  }

  const candidates = [
    item.rule,
    item.campo,
    item.key,
    item.nombre,
    item.name,
    item.label,
    fallback
  ];

  for (const candidate of candidates) {
    const text = normalizeText(candidate);

    if (text) {
      return text;
    }
  }

  return fallback;
}

function mapDataObjectToItems(obj) {
  const out = [];

  for (const [ruleRaw, value] of Object.entries(obj || {})) {
    if (ruleRaw === "_comment") {
      continue;
    }

    const rule = normalizeText(ruleRaw);

    if (!rule) {
      continue;
    }

    out.push({
      rule,
      aiSuggestion: getAnswerValue(value)
    });
  }

  return out;
}

function mapArrayToItems(arr) {
  return (Array.isArray(arr) ? arr : [])
    .map((item, index) => ({
      rule: getRuleValue(item, `Campo ${index + 1}`),
      aiSuggestion: getAnswerValue(item)
    }))
    .filter((item) => item.rule);
}

function isLotesFormat(data) {
  return (
    data &&
    typeof data === "object" &&
    !Array.isArray(data) &&
    data.general &&
    typeof data.general === "object" &&
    !Array.isArray(data.general)
  );
}

function pPrXml(opts = {}) {
  const parts = [];

  if (opts.style) {
    parts.push(`<w:pStyle w:val="${xmlEscape(opts.style)}"/>`);
  }

  if (opts.align) {
    parts.push(`<w:jc w:val="${xmlEscape(opts.align)}"/>`);
  }

  if (
    opts.spacingBefore !== undefined ||
    opts.spacingAfter !== undefined ||
    opts.line !== undefined
  ) {
    const attrs = [];

    if (opts.spacingBefore !== undefined) {
      attrs.push(`w:before="${Number(opts.spacingBefore) || 0}"`);
    }

    if (opts.spacingAfter !== undefined) {
      attrs.push(`w:after="${Number(opts.spacingAfter) || 0}"`);
    }

    if (opts.line !== undefined) {
      attrs.push(`w:line="${Number(opts.line) || 240}" w:lineRule="auto"`);
    }

    parts.push(`<w:spacing ${attrs.join(" ")}/>`);
  }

  if (opts.indentLeft !== undefined || opts.hanging !== undefined) {
    const attrs = [];

    if (opts.indentLeft !== undefined) {
      attrs.push(`w:left="${Number(opts.indentLeft) || 0}"`);
    }

    if (opts.hanging !== undefined) {
      attrs.push(`w:hanging="${Number(opts.hanging) || 0}"`);
    }

    parts.push(`<w:ind ${attrs.join(" ")}/>`);
  }

  if (opts.bottomBorder) {
    const color = opts.bottomBorderColor || "E5EAF1";

    parts.push(
      `<w:pBdr><w:bottom w:val="single" w:sz="4" w:space="1" w:color="${xmlEscape(color)}"/></w:pBdr>`
    );
  }

  if (!parts.length) {
    return "";
  }

  return `<w:pPr>${parts.join("")}</w:pPr>`;
}

function rPrXml(opts = {}) {
  const parts = [];

  if (opts.bold) {
    parts.push("<w:b/>");
  }

  if (opts.italic) {
    parts.push("<w:i/>");
  }

  if (opts.color) {
    parts.push(`<w:color w:val="${xmlEscape(opts.color)}"/>`);
  }

  if (opts.size) {
    const size = Number(opts.size) || 22;

    parts.push(`<w:sz w:val="${size}"/><w:szCs w:val="${size}"/>`);
  }

  if (!parts.length) {
    return "";
  }

  return `<w:rPr>${parts.join("")}</w:rPr>`;
}

function markdownInlineRuns(text) {
  const source = safe(text);
  const runs = [];
  let index = 0;
  let bold = false;

  while (index < source.length) {
    const markerIndex = source.indexOf("**", index);

    if (markerIndex === -1) {
      const tail = source.slice(index);

      if (tail) {
        runs.push({
          text: tail,
          bold
        });
      }

      break;
    }

    if (markerIndex > index) {
      runs.push({
        text: source.slice(index, markerIndex),
        bold
      });
    }

    bold = !bold;
    index = markerIndex + 2;
  }

  return runs
    .map((run) => ({
      text: run.text.replace(/\*\*/g, ""),
      bold: !!run.bold
    }))
    .filter((run) => run.text);
}

function runXml(text, opts = {}) {
  return `<w:r>${rPrXml(opts)}<w:t xml:space="preserve">${xmlEscape(text)}</w:t></w:r>`;
}

function paragraphRunsXml(runs, opts = {}) {
  const runParts = runs.map((run) => {
    return runXml(run.text, {
      ...opts,
      bold: !!opts.bold || !!run.bold
    });
  });

  return `<w:p>${pPrXml(opts)}${runParts.join("")}</w:p>`;
}

function paragraphXml(text, opts = {}) {
  return paragraphRunsXml(markdownInlineRuns(text), opts);
}

function emptyParagraphXml(after = 40) {
  return `<w:p><w:pPr><w:spacing w:after="${Number(after) || 0}"/></w:pPr></w:p>`;
}

function addAnswer(paragraphs, rawAnswer) {
  const blocks = splitBlocks(rawAnswer);

  if (!blocks.length) {
    paragraphs.push(
      paragraphXml("Sin respuesta.", {
        color: "334155",
        size: 22,
        spacingAfter: 140,
        line: 300
      })
    );

    return;
  }

  for (const block of blocks) {
    const parts = reflowBlock(block);

    for (const part of parts) {
      if (part.type === "bullet") {
        const level = Number(part.level || 0);
        const bulletSymbol = level === 0 ? "• " : level === 1 ? "◦ " : "▪ ";
        const indentLeft = 360 + level * 420;

        paragraphs.push(
          paragraphXml(bulletSymbol + part.text, {
            color: "1F2937",
            size: 22,
            spacingAfter: 90,
            line: 300,
            indentLeft,
            hanging: 180
          })
        );
      } else {
        paragraphs.push(
          paragraphXml(part.text, {
            color: "1F2937",
            size: 22,
            spacingAfter: 120,
            line: 320
          })
        );
      }
    }
  }
}

function addSectionTitle(paragraphs, text, first = false) {
  paragraphs.push(
    paragraphXml(normalizeText(text), {
      bold: true,
      color: "1E6FD1",
      size: 30,
      spacingBefore: first ? 120 : 300,
      spacingAfter: 120
    })
  );
}

function addItemsSection(paragraphs, items) {
  items.forEach((item, index) => {
    const rule = normalizeText(item.rule || `Campo ${index + 1}`);
    const answer = getAnswerValue(item);

    paragraphs.push(
      paragraphXml(`${index + 1}. ${rule}`, {
        bold: true,
        color: "0B2F55",
        size: 28,
        spacingBefore: index === 0 ? 60 : 260,
        spacingAfter: 80,
        bottomBorder: true,
        bottomBorderColor: "E5EAF1"
      })
    );

    paragraphs.push(
      paragraphXml("Respuesta", {
        bold: true,
        color: "1E6FD1",
        size: 22,
        spacingBefore: 90,
        spacingAfter: 80
      })
    );

    addAnswer(paragraphs, answer);
    paragraphs.push(emptyParagraphXml(40));
  });
}

