const fs = require('fs');
const path = require('path');
const processModule = require('process');

const __entryMs = Date.now();
function elapsedMs() { return Date.now() - __entryMs; }
function nowIso() { return new Date().toISOString(); }
function num(v) { const n = Number(v); return Number.isFinite(n) ? n : 0; }
function safeText(v, fallback = '') { const s = String(v ?? '').trim(); return s ? s : fallback; }

function deepMerge(target, source) {
    if (!source || typeof source !== 'object' || Array.isArray(source)) return target;
    for (const key of Object.keys(source)) {
        const value = source[key];
        if (value === undefined) continue;
        if (value && typeof value === 'object' && !Array.isArray(value)) {
            if (!target[key] || typeof target[key] !== 'object' || Array.isArray(target[key])) target[key] = {};
            deepMerge(target[key], value);
        } else {
            target[key] = value;
        }
    }
    return target;
}

function resolveSessionContext(msg) {
    const sessionId = msg.sessionId || msg.submission?.sessionId || msg.onInitSubmission?.sessionId || msg.payload?.data?.sessionId || msg.payload?.sessionId;
    const projectPath = msg.projectPath || msg.submission?.projectPath || msg.onInitSubmission?.projectPath || msg.payload?.data?.projectPath || msg.payload?.projectPath || (sessionId ? path.join('/internal-storage-files/files', 'codex-workspace', sessionId) : null);
    const projectDocsDir = projectPath ? path.join(projectPath, 'codex-docs') : null;
    const sessionStatePath = projectDocsDir ? path.join(projectDocsDir, 'SESSION_STATE.json') : null;
    return { sessionId, projectPath, projectDocsDir, sessionStatePath };
}

function readJson(filePath) {
    try {
        if (!filePath || !fs.existsSync(filePath)) return null;
        const raw = fs.readFileSync(filePath, 'utf8').trim();
        return raw ? JSON.parse(raw) : null;
    } catch (e) {
        node.warn(`⚠️ No se pudo leer ${filePath}: ${e.message}`);
        return null;
    }
}

function writeJsonAtomic(filePath, data) {
    const tmp = `${filePath}.${processModule.pid || 'fn'}.${Date.now()}.tmp`;
    fs.writeFileSync(tmp, JSON.stringify(data, null, 2), 'utf8');
    fs.renameSync(tmp, filePath);
}

function isManualStopRequested(state) {
    return (
        state?.execution?.stopRequested === true ||
        state?.execution?.reason === 'manual-stop' ||
        state?.runtime?.manualStop === true
    );
}

function countTasksFromPlan(content) {
    const pending = (content.match(/^\s*(?:[-*]\s*)?\[\s*\]\s+/gim) || []).length;
    const done = (content.match(/^\s*(?:[-*]\s*)?\[[xX]\]\s+/gim) || []).length;
    return { pending, done, total: pending + done };
}

function readPlanCountsSafe(planPath) {
    try { return countTasksFromPlan(fs.readFileSync(planPath, 'utf8')); }
    catch (_) { return { pending: 0, done: 0, total: 0 }; }
}

const { sessionId, projectPath, projectDocsDir, sessionStatePath } = resolveSessionContext(msg);
if (!sessionId || !projectPath || !projectDocsDir) {
    node.error('❌ Check status sin sessionId/projectPath');
    return [null, null, null, null];
}

const planPath = msg.planPath || path.join(projectDocsDir, 'PLAN.md');
const contextPath = msg.contextPath || path.join(projectDocsDir, 'CONTEXT.json');
const batchIteration = num(msg.batchIteration) || num(msg.codexWorker?.batchIteration) || num(msg.submission?.batchIteration) || num(msg.payload?.data?.batchIteration) || 1;
const batchDir = path.join(projectDocsDir, 'batches');
const donePath = msg.codexWorker?.donePath || path.join(batchDir, `batch-${batchIteration}.done.json`);
const pidPath = msg.codexWorker?.pidPath || path.join(batchDir, `batch-${batchIteration}.pid.json`);
const batchLogPath = msg.codexWorker?.batchLogPath || path.join(projectPath, `codex-phase2-batch${batchIteration}-${sessionId}.log`);
const workerLogPath = msg.codexWorker?.workerLogPath || path.join(batchDir, `batch-${batchIteration}.worker.log`);
const unifiedLogPath = path.join(projectPath, `codex-unified-${sessionId}.log`);

function writeUnifiedLog(message, source = 'CHECK', level = 'INFO') {
    try {
        fs.appendFileSync(unifiedLogPath, `[${nowIso()}] [BATCH-${batchIteration}] [${source}] [${level}] ${message}\n`, 'utf8');
    } catch (_) {}
}

function persistExecutionPatch(checkpoint, patch) {
    try {
        let state = readJson(sessionStatePath) || {};
        if (!state || typeof state !== 'object' || Array.isArray(state)) state = {};
        state._id = sessionId;
        state.sessionId = sessionId;
        if (!state.createdAt) state.createdAt = nowIso();
        state.updatedAt = nowIso();
        state.lastCheckpoint = checkpoint;
        state.timeline = Array.isArray(state.timeline) ? state.timeline : [];
        state.timeline.push({ checkpoint, ts: nowIso() });
        if (state.timeline.length > 300) state.timeline = state.timeline.slice(-300);
        deepMerge(state, patch || {});
        writeJsonAtomic(sessionStatePath, state);
    } catch (e) {
        node.warn(`⚠️ No se pudo persistir estado JSON: ${e.message}`);
    }
}

function tailFile(filePath, maxChars = 5000) {
    try {
        if (!filePath || !fs.existsSync(filePath)) return '';
        const stat = fs.statSync(filePath);
        const size = Math.min(stat.size, maxChars);
        const fd = fs.openSync(filePath, 'r');
        const buf = Buffer.alloc(size);
        fs.readSync(fd, buf, 0, size, Math.max(0, stat.size - size));
        fs.closeSync(fd);
        return buf.toString('utf8');
    } catch (_) {
        return '';
    }
}

function mirrorMsg(fields) {
    msg.sessionId = sessionId;
    msg.projectPath = projectPath;
    msg.projectDocsDir = projectDocsDir;
    msg.contextPath = contextPath;
    msg.planPath = planPath;
    msg.batchIteration = batchIteration;
    msg.submission = {
        ...(msg.submission || {}),
        sessionId,
        projectPath,
        batchIteration,
        ...(fields || {})
    };
    msg.onInitSubmission = {
        ...(msg.onInitSubmission || {}),
        ...msg.submission
    };
    msg.payload = msg.payload || {};
    msg.payload.sessionId = sessionId;
    msg.payload.projectPath = projectPath;
    msg.payload.data = { ...(msg.payload.data || {}), ...msg.submission };
    return msg;
}

const state = readJson(sessionStatePath) || {};
if (isManualStopRequested(state)) {
    writeUnifiedLog('Manual stop detectado en checker', 'CHECK', 'WARN');
    persistExecutionPatch('implementation-manual-stop-checker', {
        runtime: { status: 'Stopped by user', manualStop: true, completed: false, success: false },
        execution: { stopped: true, finished: true, shouldContinue: false, reason: 'manual-stop' }
    });
    const out = mirrorMsg({ completed: true, executionFailed: true, stoppedReason: 'manual-stop', resultReady: false });
    node.status({ fill: 'grey', shape: 'ring', text: 'manual stop' });
    return [null, null, null, out];
}

const counts = readPlanCountsSafe(planPath);
const progress = counts.total > 0 ? Math.max(1, Math.min(99, Math.round((counts.done / counts.total) * 100))) : num(state?.runtime?.progress);

persistExecutionPatch('implementation-checker-poll', {
    runtime: {
        status: fs.existsSync(donePath)
            ? `Batch ${batchIteration} finalizado. Validando...`
            : `Codex ejecutando batch ${batchIteration}: ${counts.done}/${counts.total} tareas...`,
        progress,
        completed: false,
        success: false
    },
    tasksLive: {
        completed: counts.done,
        total: counts.total,
        remaining: counts.pending,
        batch: batchIteration,
        timestamp: nowIso(),
        source: 'checker'
    },
    tasks: {
        completed: counts.done,
        total: counts.total,
        remaining: counts.pending,
        batch: batchIteration,
        live: true
    },
    execution: {
        batchIteration,
        donePath,
        pidPath,
        batchLogPath,
        workerLogPath
    }
});

if (!fs.existsSync(donePath)) {
    const launchTs = Date.parse(state?.execution?.process?.startedAt || state?.execution?.startedAt || state?.updatedAt || '');
    const ageMs = Number.isFinite(launchTs) ? (Date.now() - launchTs) : 0;
    const maxWithoutMarkerMs = 60 * 60 * 1000;

    if (ageMs > maxWithoutMarkerMs) {
        const reason = 'missing-done-marker-timeout';
        const wrapperTail = tailFile(workerLogPath);
        const batchTail = tailFile(batchLogPath);
        persistExecutionPatch('implementation-stopped', {
            runtime: {
                status: 'No se recibió done marker del worker tras 60 minutos',
                completed: true,
                success: false,
                error: reason
            },
            execution: {
                stopped: true,
                finished: true,
                shouldContinue: false,
                reason,
                batchIteration,
                donePath,
                pidPath,
                batchLogPath,
                workerLogPath
            },
            diagnostics: { wrapperTail, batchTail }
        });
        const out = mirrorMsg({ completed: true, executionFailed: true, stoppedReason: reason, resultReady: false, tasksDone: counts.done, tasksTotal: counts.total });
        node.status({ fill: 'red', shape: 'dot', text: reason });
        return [null, null, null, out];
    }

    writeUnifiedLog(`Batch todavía ejecutando tasks=${counts.done}/${counts.total} elapsedMs=${elapsedMs()}`, 'CHECK', 'INFO');
    node.status({ fill: 'blue', shape: 'ring', text: `running ${counts.done}/${counts.total}` });
    return [null, null, mirrorMsg({ progress, tasksDone: counts.done, tasksTotal: counts.total, tasksRemaining: counts.pending, completed: false, resultReady: false }), null];
}

const done = readJson(donePath) || {};
const exitCode = Number(done.exitCode);
const tasksDone = num(done.tasksDone ?? counts.done);
const tasksTotal = num(done.tasksTotal ?? counts.total);
const tasksRemaining = Math.max(0, num(done.tasksRemaining ?? counts.pending));
const elapsedBatchSeconds = num(done.elapsedBatchSeconds);

msg.cumulativeTime = Number((num(msg.cumulativeTime) + elapsedBatchSeconds).toFixed(2));
msg.phase2Elapsed = msg.cumulativeTime;
msg.finalTotalTime = msg.cumulativeTime;
msg.cumulativeCommands = num(msg.cumulativeCommands) + 1;
msg.finalBatchCount = batchIteration;
msg.tasksDone = tasksDone;
msg.tasksTotal = tasksTotal;
msg.tasksRemaining = tasksRemaining;
if (done.codexSessionId && !msg.codexSessionId) msg.codexSessionId = done.codexSessionId;

if (done.manualStop === true) {
    const reason = 'manual-stop';
    persistExecutionPatch('implementation-manual-stop', {
        runtime: { status: 'Stopped by user', manualStop: true, completed: false, success: false },
        tasks: { completed: tasksDone, total: tasksTotal, remaining: tasksRemaining, live: false },
        execution: { stopped: true, finished: true, shouldContinue: false, reason, lastExitCode: exitCode, batchIteration }
    });
    const out = mirrorMsg({ completed: true, executionFailed: true, stoppedReason: reason, resultReady: false, tasksDone, tasksTotal, tasksRemaining });
    node.status({ fill: 'grey', shape: 'dot', text: reason });
    return [null, null, null, out];
}

if (exitCode !== 0) {
    const reason = exitCode === 127 ? 'command-not-found' : 'codex-exit-error';
    const wrapperTail = tailFile(done.workerLogPath || workerLogPath);
    const batchTail = tailFile(done.batchLogPath || batchLogPath);
    persistExecutionPatch('implementation-command-error', {
        runtime: {
            status: `Codex falló con exitCode ${exitCode}`,
            completed: true,
            success: false,
            error: `Codex exitCode ${exitCode}`
        },
        tasks: { completed: tasksDone, total: tasksTotal, remaining: tasksRemaining, live: false },
        execution: {
            stopped: true,
            finished: true,
            shouldContinue: false,
            reason,
            lastExitCode: exitCode,
            batchIteration,
            elapsedBatchSeconds,
            batchLogPath: done.batchLogPath || batchLogPath,
            workerLogPath: done.workerLogPath || workerLogPath
        },
        diagnostics: {
            wrapperTail,
            batchTail,
            doneMarker: done
        }
    });
    writeUnifiedLog(`Batch error exitCode=${exitCode} reason=${reason}. No se lanzan más batches.`, 'CHECK', 'ERROR');
    const out = mirrorMsg({ completed: true, executionFailed: true, stoppedReason: reason, resultReady: false, tasksDone, tasksTotal, tasksRemaining, error: `Codex exitCode ${exitCode}` });
    node.status({ fill: 'red', shape: 'dot', text: `${reason} ${exitCode}` });
    return [null, null, null, out];
}

if (tasksTotal > 0 && tasksRemaining === 0) {
    persistExecutionPatch('implementation-complete', {
        runtime: {
            status: `Completado: ${tasksDone}/${tasksTotal} tareas`,
            progress: 100,
            completed: true,
            success: true
        },
        tasks: { completed: tasksDone, total: tasksTotal, remaining: 0, live: false },
        execution: {
            phase: 'implementation',
            batchIteration,
            codexSessionId: msg.codexSessionId || done.codexSessionId || null,
            finished: true,
            stopped: false,
            shouldContinue: false,
            lastExitCode: exitCode,
            elapsedBatchSeconds,
            cumulativeTime: msg.cumulativeTime,
            cumulativeCommands: msg.cumulativeCommands
        },
        progressView: { phaseStatus: { execute: 'done' } }
    });
    const out = mirrorMsg({ completed: true, resultReady: true, progress: 100, tasksDone, tasksTotal, tasksRemaining: 0 });
    out.allTasksComplete = true;
    out.submission.completed = true;
    out.submission.resultReady = true;
    node.status({ fill: 'green', shape: 'dot', text: 'complete' });
    writeUnifiedLog(`Batch complete and all tasks done tasks=${tasksDone}/${tasksTotal}`, 'CHECK', 'SUCCESS');
    return [out, null, null, null];
}

const progressed = tasksDone > num(state?.execution?.startDone);
if (!progressed) msg.noProgressBatches = num(msg.noProgressBatches) + 1;
else msg.noProgressBatches = 0;

if (msg.noProgressBatches >= 3) {
    const reason = 'no-progress';
    persistExecutionPatch('implementation-stopped', {
        runtime: { status: 'Sin progreso detectado', progress: 95, completed: true, success: false, error: reason },
        tasks: { completed: tasksDone, total: tasksTotal, remaining: tasksRemaining, live: false },
        execution: { stopped: true, finished: true, shouldContinue: false, reason, noProgressBatches: msg.noProgressBatches, lastExitCode: exitCode, batchIteration }
    });
    const out = mirrorMsg({ completed: true, executionFailed: true, stoppedReason: reason, resultReady: false, tasksDone, tasksTotal, tasksRemaining });
    node.status({ fill: 'red', shape: 'dot', text: reason });
    return [null, null, null, out];
}

if (batchIteration >= 30) {
    const reason = 'batch-limit';
    persistExecutionPatch('implementation-stopped', {
        runtime: { status: 'Límite de batches alcanzado', progress: 95, completed: true, success: false, error: reason },
        tasks: { completed: tasksDone, total: tasksTotal, remaining: tasksRemaining, live: false },
        execution: { stopped: true, finished: true, shouldContinue: false, reason, lastExitCode: exitCode, batchIteration }
    });
    const out = mirrorMsg({ completed: true, executionFailed: true, stoppedReason: reason, resultReady: false, tasksDone, tasksTotal, tasksRemaining });
    node.status({ fill: 'red', shape: 'dot', text: reason });
    return [null, null, null, out];
}

const nextBatchIteration = batchIteration + 1;
persistExecutionPatch('implementation-next-batch', {
    runtime: {
        status: `${tasksDone}/${tasksTotal} tareas - batch ${nextBatchIteration}...`,
        progress: tasksTotal > 0 ? Math.min(90, 40 + (tasksDone / tasksTotal) * 50) : 40,
        completed: false,
        success: false
    },
    tasks: { completed: tasksDone, total: tasksTotal, remaining: tasksRemaining, live: false },
    execution: {
        phase: 'implementation',
        batchIteration,
        nextBatchIteration,
        codexSessionId: msg.codexSessionId || done.codexSessionId || null,
        shouldContinue: true,
        lastExitCode: exitCode,
        elapsedBatchSeconds,
        cumulativeTime: msg.cumulativeTime,
        cumulativeCommands: msg.cumulativeCommands
    }
});

msg.batchIteration = nextBatchIteration;
msg.shouldContinue = true;
msg.tasksRemaining = tasksRemaining;
msg.tasksDone = tasksDone;
msg.tasksTotal = tasksTotal;
if (done.codexSessionId) msg.codexSessionId = done.codexSessionId;

writeUnifiedLog(`Batch ${batchIteration} OK. Siguiente batch ${nextBatchIteration}. tasks=${tasksDone}/${tasksTotal}`, 'CHECK', 'INFO');
node.status({ fill: 'green', shape: 'dot', text: `next ${nextBatchIteration}` });
return [null, mirrorMsg({ completed: false, resultReady: false, tasksDone, tasksTotal, tasksRemaining, batchIteration: nextBatchIteration }), null, null];

