            },
            runtime: {
                status: 'Configuracion completada',
                progress: 40
            }
        };

        return msg;

    } catch (error) {
        node.error('❌ setup-codex FATAL: ' + error.message + '\n' + error.stack);
        if (msg && msg.addProgressLog) {
            msg.addProgressLog('❌ setup-codex falló: ' + error.message, 'error', 'config');
        }
        return null;
    }
})();

