                item.name === 'codex-docs' ||
                item.name === 'node_modules' ||
                item.name.startsWith('.git')) {
                continue;
            }

            const itemPath = path.join(dir, item.name);

            if (item.isFile()) {
                count++;
            } else if (item.isDirectory()) {
                count += countProjectFiles(itemPath, depth + 1, maxDepth);
            }
        }

        return count;
    } catch (error) {
        return 0;
    }
}

// Contar archivos del proyecto (excluyendo carpetas Codex)
const totalProjectFiles = countProjectFiles(projectPath);

let markdownCount = 0;
try {
    markdownCount = fs.readdirSync(projectMarkdownDir, { withFileTypes: true })
        .filter(d => d.isFile() && d.name.toLowerCase().endsWith('.md')).length;
} catch (_) { }


// También contar carpetas de primer nivel (excluyendo Codex)
const projectItems = fs.readdirSync(projectPath, { withFileTypes: true });
const projectFolders = projectItems.filter(item =>
    item.isDirectory() &&
    item.name !== '.codex' &&
    item.name !== 'codex-docs' &&
    !item.name.startsWith('.')
);
const projectFiles = projectItems.filter(item =>
    item.isFile() &&
    !item.name.startsWith('.')
);

node.warn('═════════════════════════════════════════');
node.warn('📊 ANÁLISIS DEL WORKSPACE:');
node.warn(`   📝 Markdown en codex-docs/markdown: ${markdownCount}`);
node.warn(`   📁 Carpetas (top-level, sin codex): ${projectFolders.length}`);
node.warn(`   📄 Archivos (raíz): ${projectFiles.length}`);
node.warn(`   🧾 Archivos de código (estimado): ${totalProjectFiles}`);

if (projectFolders.length > 0) {
    node.warn('   📂 Carpetas encontradas:');
    projectFolders.forEach(folder => {
        const folderPath = path.join(projectPath, folder.name);
        const folderFiles = countProjectFiles(folderPath, 0, 2);
        node.warn(`      - ${folder.name}/ (${folderFiles} archivos)`);
    });
}

if (totalProjectFiles === 0 && projectFolders.length === 0) {
    node.warn('⚠️ PROYECTO VACÍO - No hay archivos ni carpetas');
    node.warn('   Codex generará código desde cero en esta ubicación');
} else {
    node.warn(`✅ PROYECTO CON CONTENIDO - ${totalProjectFiles} archivo(s) detectado(s)`);
    node.warn('   Codex modificará/añadirá archivos según documentación');
}
node.warn('═════════════════════════════════════════');

// 6️⃣ Guardar rutas y metadata para nodos siguientes
msg.projectPath = projectPath;
msg.projectCodexDir = projectCodexDir;
msg.projectDocsDir = projectDocsDir;
msg.projectMarkdownDir = projectMarkdownDir;

msg.existingProjectMode = true; // 🚩 Flag importante
msg.projectMetadata = {
    totalFiles: totalProjectFiles,
    topLevelFolders: projectFolders.length,
    topLevelFiles: projectFiles.length,
    isEmpty: (totalProjectFiles === 0 && projectFolders.length === 0)
};

// 🔑 GUARDAR sessionId EN msg y submission
msg.sessionId = sessionId;
msg.submission = msg.submission || {};
msg.submission.sessionId = sessionId;
msg.submission.projectPath = projectPath;

// 7️⃣ Log final
node.warn('═════════════════════════════════════════');
node.warn('✅ PROYECTO EXISTENTE PREPARADO');
node.warn(`🔑 Session ID: ${sessionId}`);
node.warn(`📁 Proyecto: ${projectPath}`);
node.warn(`📂 Config:   ${projectCodexDir}`);
node.warn(`📂 Docs:     ${projectDocsDir}`);
node.warn(`📊 Estado:   ${msg.projectMetadata.isEmpty ? 'VACÍO' : 'CON CONTENIDO'}`);
node.warn('═════════════════════════════════════════');

msg._sessionCheckpoint = 'resolve-output-path';
msg._sessionPatch = {
    workspace: {
        projectPath,
        projectCodexDir,
        projectDocsDir,
        projectMarkdownDir
    },
    projectMetadata: {
        totalFiles: totalProjectFiles,
        topLevelFolders: projectFolders.length,
        topLevelFiles: projectFiles.length,
        isEmpty: (totalProjectFiles === 0 && projectFolders.length === 0)
    },
    flags: {
        existingProjectMode: true
    }
};


return msg;

