// 📸 SAVE PROJECT SNAPSHOT - BEFORE
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const projectPath = msg.projectPath;
const snapshotFile = path.join(projectPath, '.codex-snapshot-before.json');

if (!fs.existsSync(projectPath)) {
    node.error(`❌ Proyecto no existe: ${projectPath}`);
    return null;
}

const snapshot = {
    timestamp: new Date().toISOString(),
    sessionId: msg.sessionId,
    files: {}
};

// Escanear recursivamente (excluyendo basura)
const excludeDirs = ['node_modules', '.git', '__pycache__', '.pytest_cache', '.codex'];

function scanDir(dir) {
    try {
        const items = fs.readdirSync(dir, { withFileTypes: true });
        for (const item of items) {
            const fullPath = path.join(dir, item.name);

            // Excluir directorios específicos
            if (excludeDirs.some(ex => item.name === ex)) continue;

            // Recursivo para directorios
            if (item.isDirectory()) {
                scanDir(fullPath);
            } 
            // Solo procesar archivos regulares
            else if (item.isFile()) {
                try {
                    const content = fs.readFileSync(fullPath, 'utf8');
                    snapshot.files[path.relative(projectPath, fullPath)] = {
                        hash: crypto.createHash('sha256').update(content).digest('hex'),
                        size: content.length
                    };
                } catch (readErr) {
                    // Ignorar archivos binarios o con errores de encoding
                    if (readErr.code !== 'EISDIR') {
                        node.warn(`⚠️ No se pudo leer: ${item.name} (${readErr.message})`);
                    }
                }
            }
            // Ignorar symlinks, sockets, etc.
        }
    } catch (dirErr) {
        node.warn(`⚠️ Error leyendo directorio: ${dir} (${dirErr.message})`);
    }
}

scanDir(projectPath);
fs.writeFileSync(snapshotFile, JSON.stringify(snapshot, null, 2));

node.warn(`✅ SNAPSHOT BEFORE guardado: ${Object.keys(snapshot.files).length} archivos`);
msg.snapshotBefore = snapshotFile;

msg._sessionCheckpoint = 'snapshot-before';
msg._sessionPatch = {
    artifacts: {
        snapshotBefore: snapshotFile
    }
};


return msg;

