const MODELS_URL = 'https://axet.nttdata.com/api/enabler-manager/llm-models/search';
const TOKEN_URL = 'https://login.microsoftonline.com/33dc4d26-e9c5-465c-9a04-f6f580dab432/oauth2/v2.0/token';

const FALLBACK_MODEL = 'gpt-5.3-codex';
const FALLBACK_REASONING = 'medium';
const REASONING_VALUES = ['low', 'medium', 'high'];
const ALLOWED_MODELS = ['gpt-5.5', 'gpt-5.4', 'gpt-5.2', 'gpt-5.3-codex', 'gpt-5.2-codex', 'gpt-5.6-sol'];
const GLOBAL_REASONING = String(global.get('codex_reasoning_default') || 'medium').toLowerCase().trim();
const GLOBAL_MODEL = String(global.get('codex_model_default') || FALLBACK_MODEL).toLowerCase().trim();

function readValue(v) {
  if (v && typeof v === 'object') {
    return v.value || v.id || v.model || v.modelName || v.label || '';
  }
  return v;
}

function normalizeRequestedModel(v) {
  let model = String(readValue(v) || FALLBACK_MODEL).toLowerCase().trim();
  if (!ALLOWED_MODELS.includes(model)) {
    model = FALLBACK_MODEL;
  }
  return model;
}

function pickArray(payload) {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.data)) return payload.data;
  return payload?.content || payload?.items || payload?.results || payload?.models ||
    payload?.data?.content || payload?.data?.items || payload?.data?.results || payload?.data?.models || [];
}

function normalizeModel(m) {
  const value = m?.model || m?.modelName || m?.name || m?.id || m?.value;
  if (!value) return null;

  const label = m?.displayName || m?.label || value;
  const enabled = !(m?.enabled === false || m?.active === false || String(m?.status || '').toLowerCase() === 'disabled');
  if (!enabled) return null;

  const reasoningRaw = m?.reasoningEfforts || m?.reasoningLevels || m?.supportedReasoning || m?.capabilities?.reasoning;
  const reasoning = Array.isArray(reasoningRaw) && reasoningRaw.length
    ? reasoningRaw.map(x => String(x).toLowerCase())
    : ['low', 'medium', 'high'];

  return { value: String(value), label: String(label), reasoning };
}

async function getServiceToken() {
  const cfg = global.get("env") || {};
  const clientId = cfg.AXET_CLIENT_ID;
  const clientSecret = cfg.AXET_CLIENT_SECRET;
  const scope = cfg.AXET_SCOPE || 'api://2f72c6d3-2d2e-4800-b458-1642e97f9dff/.default';
  if (!clientId || !clientSecret) return null;

  const body = new URLSearchParams({
    grant_type: 'client_credentials',
    client_id: clientId,
    client_secret: clientSecret,
    scope
  }).toString();

  const r = await axios.post(TOKEN_URL, body, {
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    timeout: 15000
  });

  return r.data?.access_token || null;
}

async function fetchCatalog(token) {
  const r = await axios.post(
    MODELS_URL,
    { search: {}, pagination: { size: 200, page: 0 } },
    {
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      timeout: 20000
    }
  );
  return r.data;
}

function applyRequestedSelection(msg) {
  const requestedModel = normalizeRequestedModel(
    msg.submission?.model_select ||
    msg.submission?.requestedModel ||
    msg.requestedModel ||
    GLOBAL_MODEL ||
    FALLBACK_MODEL
  );

  let requestedReasoning = String(
    msg.submission?.requestedReasoning ||
    msg.requestedReasoning ||
    GLOBAL_REASONING ||
    'medium'
  ).toLowerCase().trim();

  if (!REASONING_VALUES.includes(requestedReasoning)) {
    requestedReasoning = 'medium';
  }

  msg.requestedModel = requestedModel;
  msg.requestedReasoning = requestedReasoning;

  msg.submission = msg.submission || {};
  msg.submission.requestedModel = requestedModel;
  msg.submission.model_select = requestedModel;
  msg.submission.requestedReasoning = requestedReasoning;
  msg.submission.reasoningOptions = REASONING_VALUES;
  msg.submission.modelOptions = ALLOWED_MODELS;

  return msg;
}

(async () => {
  try {
    let token = msg.userAuth?.access_token;
    let data;

    try {
      data = await fetchCatalog(token);
      node.warn(`Top-level keys: ${Object.keys(data || {}).join(',')}`);
      node.warn(`Preview: ${JSON.stringify(data).slice(0, 800)}`);

    } catch (e) {
      const status = e?.response?.status;
      if (status === 401 || status === 403) {
        token = await getServiceToken();
        if (!token) throw new Error('401/403 y faltan AXET_CLIENT_ID / AXET_CLIENT_SECRET en env');
        data = await fetchCatalog(token);
      } else {
        throw e;
      }
    }

    const rawModels = pickArray(data);
    node.warn(`rawModels: ${rawModels.length}`);

    const catalog = rawModels.map(normalizeModel).filter(Boolean);
    node.warn(`catalog(normalized): ${catalog.length}`);

    const unique = Array.from(new Map(catalog.map(m => [m.value, m])).values())
      .sort((a, b) => a.label.localeCompare(b.label));

    if (!unique.length) throw new Error('Catálogo de modelos vacío');

    flow.set('codex_model_options', unique);

    msg.availableModels = unique;
    msg.availableModelValues = unique.map(m => m.value);
    msg.modelsFetchFailed = false;

    applyRequestedSelection(msg);

    node.warn(`🤖 Modelo solicitado/global: ${msg.requestedModel}`);
    node.warn(`🧠 Reasoning solicitado/global: ${msg.requestedReasoning}`);

    node.send(msg);

  } catch (err) {
    msg.modelsFetchFailed = true;
    msg.availableModels = [];
    msg.modelOptions = ALLOWED_MODELS.map(value => ({ label: value.toUpperCase(), value }));
    msg.fallbackModel = FALLBACK_MODEL;
    msg.fallbackReasoning = FALLBACK_REASONING;

    applyRequestedSelection(msg);

    node.warn(`⚠️ Falló catálogo de modelos, fallback ${FALLBACK_MODEL}/${FALLBACK_REASONING}: ${err.message}`);
    node.warn(`🤖 Modelo solicitado/global: ${msg.requestedModel}`);
    node.warn(`🧠 Reasoning solicitado/global: ${msg.requestedReasoning}`);

    node.send(msg);
  }
})();

return;

