const FALLBACK_MODEL = 'gpt-5.3-codex';
const REASONING_VALUES = ['low', 'medium', 'high'];
const ALLOWED_MODELS = ['gpt-5.5', 'gpt-5.4', 'gpt-5.2', 'gpt-5.3-codex', 'gpt-5.2-codex', 'gpt-5.6-sol'];

const catalog = msg.availableModels || flow.get('codex_model_options') || [];
const fetchFailed = !!msg.modelsFetchFailed;

const GLOBAL_MODEL = String(global.get('codex_model_default') || FALLBACK_MODEL).toLowerCase().trim();
const GLOBAL_REASONING = String(global.get('codex_reasoning_default') || 'medium').toLowerCase().trim();

function readValue(v) {
  if (v && typeof v === 'object') {
    return v.value || v.id || v.model || v.modelName || v.label || '';
  }
  return v;
}

function normalizeRequestedModel(v) {
  let model = String(readValue(v) || FALLBACK_MODEL).toLowerCase().trim();
  if (!ALLOWED_MODELS.includes(model)) {
    model = FALLBACK_MODEL;
  }
  return model;
}

const rawRequestedModel = normalizeRequestedModel(
  GLOBAL_MODEL ||
  msg.submission?.model_select ||
  msg.submission?.requestedModel ||
  msg.requestedModel ||

  FALLBACK_MODEL
);

const rawRequestedReasoning = String(
  msg.submission?.requestedReasoning ||
  msg.requestedReasoning ||
  GLOBAL_REASONING ||
  'medium'
).toLowerCase().trim();

function pickExact(catalogList, key) {
  const k = String(key || '').toLowerCase().trim();
  return catalogList.find(x => String(x.value).toLowerCase() === k) || null;
}

let selectedModel = FALLBACK_MODEL;

if (!fetchFailed && catalog.length) {
  const exact = pickExact(catalog, rawRequestedModel);

  if (exact) {
    selectedModel = exact.value;
  } else if (catalog.some(m => String(m.value).toLowerCase() === FALLBACK_MODEL)) {
    selectedModel = FALLBACK_MODEL;
  } else {
    selectedModel = catalog[0].value;
  }
} else {
  selectedModel = rawRequestedModel || FALLBACK_MODEL;
}

const selectedReasoning = REASONING_VALUES.includes(rawRequestedReasoning)
  ? rawRequestedReasoning
  : 'medium';

msg.modelSelect = selectedModel;
msg.reasoningLevel = selectedReasoning;

msg.submission = msg.submission || {};
msg.submission.modelSelect = selectedModel;
msg.submission.model_select = selectedModel;
msg.submission.requestedModel = rawRequestedModel;
msg.submission.reasoningLevel = selectedReasoning;
msg.submission.requestedReasoning = selectedReasoning;
msg.submission.reasoningOptions = REASONING_VALUES;
msg.submission.modelOptions = ALLOWED_MODELS;

node.warn(`🤖 Modelo final: ${selectedModel}`);
node.warn(`🧠 Reasoning final: ${selectedReasoning}`);

msg._sessionCheckpoint = 'apply-model-reasoning';
msg._sessionPatch = {
  selection: {
    modelSelect: selectedModel,
    reasoningLevel: selectedReasoning,
    requestedModel: rawRequestedModel,
    requestedReasoning: rawRequestedReasoning,
    globalModelDefault: GLOBAL_MODEL,
    globalReasoningDefault: GLOBAL_REASONING
  }
};

return msg;

