const querystring = require('querystring');
const https = require('https');
const { URL } = require('url');

const TOKEN_REFRESH_SKEW_SECONDS = 60;

// ── Helpers ──────────────────────────────────────────
function decodeJwtPayload(token) {
    const parts = String(token || '').split('.');
    if (parts.length < 2) return null;
    const payload = parts[1].replace(/-/g, '+').replace(/_/g, '/');
    const padded = payload.padEnd(payload.length + ((4 - (payload.length % 4)) % 4), '=');
    try { return JSON.parse(Buffer.from(padded, 'base64').toString('utf8')); }
    catch { return null; }
}

function shouldRefresh(accessToken) {
    const payload = decodeJwtPayload(accessToken);
    const exp = Number(payload?.exp);
    if (!Number.isFinite(exp) || exp <= 0) return false;
    const now = Math.floor(Date.now() / 1000);
    const secsLeft = exp - now;
    node.warn(`🔑 Token expira en ${secsLeft}s (skew: ${TOKEN_REFRESH_SKEW_SECONDS}s)`);
    return secsLeft <= TOKEN_REFRESH_SKEW_SECONDS;
}

function httpPost(url, body) {
    return new Promise((resolve, reject) => {
        const parsed = new URL(url);
        const options = {
            hostname: parsed.hostname,
            port: parsed.port || 443,
            path: parsed.pathname + (parsed.search || ''),
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
                'Content-Length': Buffer.byteLength(body)
            }
        };

        const req = https.request(options, (res) => {
            let data = '';
            res.on('data', chunk => data += chunk);
            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    try {
                        resolve(JSON.parse(data));
                    } catch (e) {
                        reject(new Error(`Respuesta no JSON: ${data}`));
                    }
                } else {
                    reject(new Error(`HTTP ${res.statusCode}: ${data}`));
                }
            });
        });

        req.on('error', reject);
        req.write(body);
        req.end();
    });
}

// ── Lógica principal ──────────────────────────────────
const secCtx = msg.__axetFlowsSecurityContext;
const idpInfo = secCtx?.externalIdpUserInfo;

if (!idpInfo) {
    node.warn('⚠️ Sin securityContext - saltando refresh frontend');
    return msg;
}

const accessToken = idpInfo.access_token || '';
const refreshToken = idpInfo.refresh_token || '';
const issuer = idpInfo.iss || '';
const clientId = idpInfo.cid || '';

if (!accessToken) {
    node.warn('⚠️ Sin access_token en securityContext');
    return msg;
}

if (!shouldRefresh(accessToken)) {
    node.warn('✅ Token frontend aún válido - sin renovación necesaria');
    return msg;
}

if (!refreshToken || !issuer || !clientId) {
    node.warn('⚠️ Faltan datos para renovar (refresh_token / issuer / clientId)');
    return msg;
}

const tokenUrl = `${issuer.replace(/\/+$/, '')}/v1/token`;
const bodyParams = querystring.stringify({
    grant_type: 'refresh_token',
    refresh_token: refreshToken,
    client_id: clientId,
    scope: 'offline_access openid email'
});

node.warn(`🔄 Renovando token frontend Okta... (${tokenUrl})`);

try {
    const tokenResponse = await httpPost(tokenUrl, bodyParams);

    if (!tokenResponse.access_token) {
        throw new Error('Respuesta sin access_token');
    }

    idpInfo.access_token = tokenResponse.access_token;
    if (tokenResponse.id_token) idpInfo.id_token = tokenResponse.id_token;
    if (tokenResponse.refresh_token) idpInfo.refresh_token = tokenResponse.refresh_token;
    if (tokenResponse.expires_in) {
        idpInfo.exp = Math.floor(Date.now() / 1000) + tokenResponse.expires_in;
    }
    secCtx.sessionUpdated = Date.now();

    node.warn(`✅ Token frontend renovado. Expira en ${tokenResponse.expires_in}s (${Math.floor(tokenResponse.expires_in / 60)} min)`);
    node.status({ fill: 'green', shape: 'dot', text: `renovado +${Math.floor(tokenResponse.expires_in / 60)}min` });

} catch (err) {
    node.warn(`⚠️ Error renovando token frontend: ${err.message}`);
    node.status({ fill: 'yellow', shape: 'ring', text: `refresh failed: ${err.message}` });
}

return msg;

