const fs = require('fs');
const path = require('path');

function failOrContinue(message) {
    node.warn(message);
    msg.sourceSummary = msg.sourceSummary || {};
    msg.sourceSummary.opportunity = msg.sourceSummary.opportunity || { active: true, files: [], errors: [], missing: [] };
    msg.sourceSummary.opportunity.errors.push(message);
    msg.opportunityDownloadError = message;
    msg.opportunitySourceDir = msg.inputOpportunityDir || msg.opportunitySourceDir;
    return msg;
}

function firstNonEmpty(...values) { for (const value of values) { const v = String(value || '').trim(); if (v) return v; } return ''; }
function normalizeGraphPath(rawPath) {
    let p = String(rawPath || '').trim();
    if (!p) return '/';
    p = p.replace(/\\/g, '/').replace(/\/+/g, '/');
    if (p.startsWith('/drive/root:')) p = p.replace('/drive/root:', '');
    if (!p.startsWith('/')) p = '/' + p;
    return p.replace(/\/+/g, '/').replace(/\/$/, '') || '/';
}
function normalizeFolderSegment(value) {
    return String(value || '').normalize('NFC').replace(/[\u200B-\u200D\uFEFF]/g, '').replace(/\u00A0/g, ' ').trim();
}
function buildChildPath(basePath, folderName) {
    const base = normalizeGraphPath(basePath || '/');
    const cleanName = normalizeFolderSegment(folderName);
    if (!cleanName) return '';
    return normalizeGraphPath(`${base === '/' ? '' : base}/${cleanName}`);
}

if (msg.includeOpportunity !== true) {
    return failOrContinue('⚠️ Prepare Mana Direct Path invocado sin includeOpportunity=true; se continúa sin descarga de oportunidad.');
}

const selectedOpportunity = msg.selectedOpportunity || {};
const expectedFolderName = normalizeFolderSegment(firstNonEmpty(
    selectedOpportunity.sharePointFolder,
    selectedOpportunity.folderName,
    selectedOpportunity.title,
    msg.opportunityFolderName,
    msg.opportunityName,
    msg.opportunityId
));

if (!expectedFolderName) {
    return failOrContinue('⚠️ La oportunidad seleccionada no tiene nombre/title para construir la ruta de Mana; se continúa con las otras fuentes.');
}

const defaultManaRootPath = '/General/10 Use Cases/Ejecutivos/2025/[EE-06] References Generation/Analysis/Mana';
const manaRootPath = normalizeGraphPath(firstNonEmpty(
    msg.sharePointManaPath,
    msg.sharePointOpportunitiesBasePath,
    msg.submission?.sharePointManaPath,
    msg.submission?.sharePointOpportunitiesBasePath,
    flow.get('sharePointManaPath'),
    flow.get('sharePointOpportunitiesBasePath'),
    global.get('sharePointManaPath'),
    global.get('sharePointOpportunitiesBasePath'),
    env.get('SHAREPOINT_MANA_PATH'),
    env.get('SHAREPOINT_OPPORTUNITIES_BASE_PATH'),
