// -- PDF support compatible con el nodo de procesado --
// pdf-parse puede cargar pdfjs en un entorno sin DOMMatrix. Este shim evita
// fallos de runtime en AxetFlows/Node-RED cuando DOMMatrix no existe.
const DOMMatrixShim = class DOMMatrix {
    constructor(init) {
        this.a = init?.a || 1; this.b = init?.b || 0;
        this.c = init?.c || 0; this.d = init?.d || 1;
        this.e = init?.e || 0; this.f = init?.f || 0;
        this.m11 = this.a; this.m12 = this.b;
        this.m21 = this.c; this.m22 = this.d;
        this.m41 = this.e; this.m42 = this.f;
    }
    translate(tx = 0, ty = 0) { this.e += tx; this.f += ty; this.m41 = this.e; this.m42 = this.f; return this; }
    scale(sx = 1, sy = sx) { this.a *= sx; this.d *= sy; this.m11 = this.a; this.m22 = this.d; return this; }
    rotate() { return this; }
    multiply() { return new DOMMatrixShim(); }
    invertSelf() { return this; }
    transformPoint(p) { return p; }
    toFloat32Array() { return new Float32Array([this.a, this.b, this.c, this.d, this.e, this.f]); }
};
if (typeof global.DOMMatrix === 'undefined') global.DOMMatrix = DOMMatrixShim;
if (typeof globalThis.DOMMatrix === 'undefined') globalThis.DOMMatrix = DOMMatrixShim;

function valueAtPath(rootValue, dottedPath) {
    if (!dottedPath) return rootValue;
    let currentValue = rootValue;
    for (const part of dottedPath.split('.')) {
        if (currentValue === null || currentValue === undefined) return undefined;
        currentValue = currentValue[part];
    }
    return currentValue;
}

function describeModuleExport(value) {
    if (value === null) return 'null';
    if (value === undefined) return 'undefined';
    const typeName = typeof value;
    if (typeName === 'function') return 'function:' + (value.name || 'anonymous');
    if (typeName !== 'object') return typeName;
    let keys = [];
    try { keys = Object.keys(value).slice(0, 20); } catch (_err) { keys = []; }
    return 'object keys=[' + keys.join(',') + ']';
}

function isProbablyPdfParseClass(fn, pathLabel) {
    if (typeof fn !== 'function') return false;
    const fnName = String(fn.name || '');
    if (fnName === 'PDFParse' || fnName === 'PdfParse') return true;
    if (String(pathLabel || '').split('.').pop() === 'PDFParse') return true;
    try {
        const src = Function.prototype.toString.call(fn);
        return /^class\s/.test(src);
    } catch (_err) {
        return false;
    }
}

function addPdfProcessor(processors, packageName, rootValue, dottedPath) {
    const candidateValue = valueAtPath(rootValue, dottedPath);
    if (typeof candidateValue !== 'function') return;

    const label = packageName + (dottedPath ? ':' + dottedPath : ':module');
    processors.push({
        label,
        type: isProbablyPdfParseClass(candidateValue, dottedPath) ? 'class' : 'function',
        fn: candidateValue
    });
}

function normalizePdfParsedResult(parsed) {
    if (!parsed) return '';
    if (typeof parsed === 'string') return parsed;
    if (typeof parsed.text === 'string') return parsed.text;
    if (typeof parsed.data?.text === 'string') return parsed.data.text;
    if (typeof parsed.result?.text === 'string') return parsed.result.text;

    if (Array.isArray(parsed.pages)) {
        const pageTexts = [];
        for (const page of parsed.pages) {
            if (typeof page === 'string') pageTexts.push(page);
            else if (typeof page?.text === 'string') pageTexts.push(page.text);
            else if (Array.isArray(page?.content)) {
                pageTexts.push(page.content.map(item => item?.str || item?.text || '').filter(Boolean).join(' '));
            }
        }
        return pageTexts.join('\n\n');
    }

    if (Array.isArray(parsed.content)) {
        return parsed.content.map(item => item?.str || item?.text || '').filter(Boolean).join(' ');
    }

    return '';
}

async function runPdfProcessor(processor, buffer) {
    if (processor.type === 'class') {
        const instance = new processor.fn({ data: buffer });
        try {
            let parsed;
            if (typeof instance.getText === 'function') parsed = await instance.getText();
            else if (typeof instance.parse === 'function') parsed = await instance.parse();
            else if (typeof instance.getTextContent === 'function') parsed = await instance.getTextContent();
            else throw new Error('clase sin getText/parse/getTextContent');
            return normalizePdfParsedResult(parsed);
        } finally {
            try {
                if (instance && typeof instance.destroy === 'function') await instance.destroy();
            } catch (_err) { }
        }
    }

    const parsed = await processor.fn(buffer);
    return normalizePdfParsedResult(parsed);
}

function loadPdfParseProcessors() {
    const processors = [];
    const errors = [];
    const packageNames = [
        'pdf-parse@1.1.1',
        'pdf-parse@1.1.1/lib/pdf-parse.js',
        'pdf-parse@1.1.1/index.js',
        'pdf-parse',
        'pdf-parse/lib/pdf-parse.js'
    ];
    const directPaths = [
