        'default',
        'default.default',
        'pdfParse',
        'default.pdfParse',
        'default.default.pdfParse',
        'parse',
        'default.parse',
        'default.default.parse',
        'PDFParse',
        'default.PDFParse',
        'default.default.PDFParse'
    ];

    for (const packageName of packageNames) {
        try {
            const packageExport = require(packageName);
            for (const dottedPath of directPaths) {
                addPdfProcessor(processors, packageName, packageExport, dottedPath);
            }
            if (!processors.some(p => p.label.startsWith(packageName + ':'))) {
                errors.push(packageName + ': export no reconocido (' + describeModuleExport(packageExport) + ')');
