async function extractPdfWithPdfParse(buffer) {
    const loaded = loadPdfParseProcessors();
    const errors = loaded.errors.slice();

    for (const processor of loaded.processors) {
        try {
            const text = normalizeMdText(await runPdfProcessor(processor, buffer));
            if (text && text.length >= 10) return { text, method: processor.label };
            errors.push(processor.label + ': sin texto util');
        } catch (err) {
            errors.push(processor.label + ': ' + err.message);
        }
    }

    throw new Error(errors.join('; '));
}

function loadPdfJsLib() {
    const errors = [];
    const packageNames = [
        'pdfjs-dist@3.11.174/legacy/build/pdf.js',
        'pdfjs-dist/legacy/build/pdf.js',
        'pdfjs-dist'
    ];

    for (const packageName of packageNames) {
        try {
            const pdfJsCandidate = require(packageName);
            const pdfJsLib = pdfJsCandidate.default || pdfJsCandidate;
            if (pdfJsLib && typeof pdfJsLib.getDocument === 'function') {
                return { pdfJsLib, packageName };
            }
            errors.push(packageName + ': sin getDocument (' + describeModuleExport(pdfJsCandidate) + ')');
        } catch (err) {
            errors.push(packageName + ': ' + err.message);
