async function extractPdfWithPdfJs(buffer) {
    const loaded = loadPdfJsLib();
    const pdfJsLib = loaded.pdfJsLib;

    if (pdfJsLib.GlobalWorkerOptions) {
        try { pdfJsLib.GlobalWorkerOptions.workerSrc = ''; } catch (_err) { }
    }

    const loadingTask = pdfJsLib.getDocument({
        data: new Uint8Array(buffer),
        disableWorker: true,
        useWorkerFetch: false,
        isEvalSupported: false
    });

    const pdfDoc = await loadingTask.promise;
    const chunks = [];

    for (let pageNum = 1; pageNum <= pdfDoc.numPages; pageNum++) {
        const page = await pdfDoc.getPage(pageNum);
        const content = await page.getTextContent();
        const text = (content.items || [])
            .map(item => item.str || '')
            .filter(Boolean)
            .join(' ')
            .replace(/\s+/g, ' ')
            .trim();
        if (text) chunks.push('## Pagina ' + pageNum + '\n\n' + text);
        try { if (typeof page.cleanup === 'function') page.cleanup(); } catch (_err) { }
    }

    try { if (typeof pdfDoc.destroy === 'function') await pdfDoc.destroy(); } catch (_err) { }

    return {
        text: normalizeMdText(chunks.join('\n\n')),
        method: loaded.packageName
    };
}

