async function extractPptx(filePath) {
    // Mismo enfoque que el nodo de procesado que ya funciona: adm-zip + lectura directa de ppt/slides/slide*.xml.
    // Evita depender de JSZip; en este runtime el paquete puede cargarse sin exponer la API asincrona esperada.
    const AdmZipModule = loadAdmZipModule();
    const zip = new AdmZipModule(fs.readFileSync(filePath));
    const entries = zip.getEntries();

    const slideEntries = entries
        .filter(entry => !entry.isDirectory && /^ppt\/slides\/slide\d+\.xml$/i.test(entry.entryName))
        .sort((a, b) => {
            const na = parseInt((a.entryName.match(/slide(\d+)\.xml/i) || [])[1] || '0', 10);
            const nb = parseInt((b.entryName.match(/slide(\d+)\.xml/i) || [])[1] || '0', 10);
            return na - nb;
        });

    if (!slideEntries.length) {
        throw new Error('PPTX sin slides detectables (ppt/slides/slide*.xml)');
    }

    let markdown = '# Presentacion (PPTX)\n\n';

    slideEntries.forEach((entry, index) => {
        const xml = entry.getData().toString('utf8');
        const texts = [];
        const re = /<a:t(?:\s[^>]*)?>([\s\S]*?)<\/a:t>/g;
        let match;

        while ((match = re.exec(xml)) !== null) {
            const text = decodeXmlEntitiesForOffice(match[1])
                .replace(/\s+/g, ' ')
                .trim();

            if (!text) continue;
            if (/^click to\s*$/i.test(text)) continue;
            if (/<[a-z]+:/i.test(text)) continue;

            texts.push(text);
        }

        markdown += '## Slide ' + (index + 1) + '\n\n';

        if (!texts.length) {
            markdown += '*Sin texto extraible*\n\n';
        } else {
            const compact = [];
            for (const text of texts) {
                if (compact.length === 0 || compact[compact.length - 1] !== text) {
                    compact.push(text);
                }
            }
            markdown += compact.map(text => '- ' + text).join('\n') + '\n\n';
        }
    });

    return markdown;
}
async function extractXlsx(filePath) {
    let ExcelJS;
    try { ExcelJS = require('exceljs@4.4.0'); }
    catch (e1) { try { ExcelJS = require('exceljs'); } catch (e2) { throw new Error('exceljs no disponible'); } }
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.readFile(filePath);
    const chunks = [];
    workbook.eachSheet((sheet) => {
        const lines = [`## Sheet: ${sheet.name}`];
        sheet.eachRow({ includeEmpty: false }, (row) => {
            const values = [];
            row.eachCell({ includeEmpty: true }, (cell) => {
                let value = cell.text || cell.value || '';
                if (value && typeof value === 'object') value = JSON.stringify(value);
                values.push(String(value).replace(/\r?\n/g, ' ').trim());
