}
async function extractPdf(filePath) {
    const buffer = fs.readFileSync(filePath);
    const errors = [];

    // 1) Igual que procesado, pero compatible con wrappers CJS/ESM y pdf-parse v2.
    try {
        const parsed = await extractPdfWithPdfParse(buffer);
        if (parsed.text && parsed.text.length >= 10) {
            return parsed.text;
        }
        errors.push('pdf-parse sin texto util');
    } catch (err) {
