    }

    // 2) Fallback JS puro con pdfjs-dist, por si pdf-parse no expone funcion callable.
    try {
        const parsed = await extractPdfWithPdfJs(buffer);
        if (parsed.text && parsed.text.length >= 10) {
            return parsed.text;
        }
        errors.push('pdfjs-dist sin texto util');
    } catch (err) {
        errors.push('pdfjs-dist: ' + err.message);
    }

    // 3) Fallback opcional si algun runtime trae poppler/pdftotext instalado.
    try {
        const out = childProcess.execFileSync('pdftotext', ['-layout', filePath, '-'], {
