        if (text && text.length >= 10) return text;
        errors.push('pdftotext sin texto util');
    } catch (err) {
        errors.push('pdftotext: ' + err.message);
    }

    throw new Error('sin conversor PDF disponible: ' + errors.join('; '));
}
