const fs = require('fs');
const path = require('path');

const FILES_ROOT = '/internal-storage-files/files';

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFC')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\u00A0/g, ' ')
    .trim();
}

function firstText() {
  for (const value of arguments) {
    if (value !== undefined && value !== null) {
      const text = normalizeText(value);
      if (text) return text;
    }
  }
  return '';
}

function normalizeTemplateCandidate(value) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value.trim();
  if (typeof value === 'object') {
    return firstText(value.value, value.label, value.name, value.filename, value.fileName, value.originalName, value.path);
  }
  return String(value).trim();
}

function isValidTemplateCandidate(value) {
  const s = normalizeTemplateCandidate(value);
  if (!s) return false;
  if (s === '__blank_docx__') return true;
  const ext = path.extname(s).toLowerCase();
  return ext === '.docx' || ext === '.pptx';
}

function inferOutputType(templateName) {
  const s = normalizeTemplateCandidate(templateName);
  if (!s || s === '__blank_docx__') return 'docx';
  return path.extname(s).toLowerCase() === '.pptx' ? 'pptx' : 'docx';
}

function resolveLiveTemplate(msg) {
  const candidates = [
    ['msg.payload.submission.plantilla', msg.payload?.submission?.plantilla],
    ['msg.payload.submission.template', msg.payload?.submission?.template],
    ['msg.payload.submission.data.plantilla', msg.payload?.submission?.data?.plantilla],
    ['msg.payload.submission.data.template', msg.payload?.submission?.data?.template],
    ['msg.payload.context.plantilla', msg.payload?.context?.plantilla],
    ['msg.payload.context.template', msg.payload?.context?.template],
    ['msg.payload.data.context.plantilla', msg.payload?.data?.context?.plantilla],
    ['msg.payload.data.context.template', msg.payload?.data?.context?.template],
    ['msg.payload.data.plantilla', msg.payload?.data?.plantilla],
    ['msg.payload.data.template', msg.payload?.data?.template],
    ['msg.payload.plantilla', msg.payload?.plantilla],
    ['msg.payload.template', msg.payload?.template],
    ['msg.submission.plantilla', msg.submission?.plantilla],
    ['msg.submission.template', msg.submission?.template],
    ['msg.submission.data.plantilla', msg.submission?.data?.plantilla],
    ['msg.submission.data.template', msg.submission?.data?.template],
    ['msg.plantilla', msg.plantilla],
    ['msg.template', msg.template]
  ];

  const valid = [];
  for (const [source, value] of candidates) {
    if (isValidTemplateCandidate(value)) {
      valid.push({ source, templateName: normalizeTemplateCandidate(value), outputType: inferOutputType(value) });
    }
  }

  if (!valid.length) return null;
  const chosen = valid[0];
  const uniqueValues = Array.from(new Set(valid.map((x) => x.templateName)));
  if (uniqueValues.length > 1) {
    node.warn('[TEMPLATE-LOCK-CONFLICT] chosen=' + chosen.templateName + ' from=' + chosen.source + ' candidates=' + valid.map((x) => x.source + '=' + x.templateName).join(' | '));
  }
  return chosen;
}

function deepMerge(target, source) {
  if (!source || typeof source !== 'object' || Array.isArray(source)) return target;
  for (const key of Object.keys(source)) {
    const value = source[key];
    if (value === undefined) continue;
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      if (!target[key] || typeof target[key] !== 'object' || Array.isArray(target[key])) target[key] = {};
      deepMerge(target[key], value);
    } else {
      target[key] = value;
    }
  }
  return target;
}

function resolveSessionStatePath(msg) {
  const explicit = firstText(
    msg.sessionStatePath,
    msg.payload?.sessionStatePath,
    msg.payload?.data?.sessionStatePath,
    msg.submission?.sessionStatePath,
    msg.onInitSubmission?.sessionStatePath
  );
  if (explicit) return explicit;

  const sessionId = firstText(
    msg.sessionId,
    msg.payload?.sessionId,
    msg.payload?.data?.sessionId,
    msg.submission?.sessionId,
    msg.onInitSubmission?.sessionId
  );
  const projectPath = firstText(
    msg.projectPath,
    msg.payload?.projectPath,
    msg.payload?.data?.projectPath,
    msg.submission?.projectPath,
    msg.onInitSubmission?.projectPath,
    sessionId ? path.join(FILES_ROOT, 'codex-workspace', sessionId) : ''
  );
  return sessionId && projectPath ? path.join(projectPath, 'codex-docs', 'SESSION_STATE.json') : '';
}

function saveSessionPatch(sessionStatePath, patch) {
  if (!sessionStatePath) return false;
  const dir = path.dirname(sessionStatePath);
  const tmpPath = path.join(dir, 'SESSION_STATE.tmp');
  /** @type {any} */

  let state = {};
  try {
    if (fs.existsSync(sessionStatePath)) {
      const raw = fs.readFileSync(sessionStatePath, 'utf8').trim();
      state = raw ? JSON.parse(raw) : {};
    }
  } catch (_err) {
    state = {};
  }
  if (!state || typeof state !== 'object' || Array.isArray(state)) state = {};
  state.updatedAt = new Date().toISOString();
  deepMerge(state, patch || {});
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(tmpPath, JSON.stringify(state, null, 2), 'utf8');
  fs.renameSync(tmpPath, sessionStatePath);
  return true;
}

function resolveSectorOutputFormat(msg) {
  const raw = firstText(
    msg.sector_outputformat,
    msg.payload?.submission?.sector_outputformat,
    msg.payload?.submission?.data?.sector_outputformat,
    msg.payload?.context?.sector_outputformat,
    msg.payload?.data?.sector_outputformat,
    msg.submission?.sector_outputformat,
    msg.submission?.data?.sector_outputformat,
    msg.context?.sector_outputformat,
    'general'
  ).toLowerCase();
  return ['general', 'sector_publico', 'sector_privado'].includes(raw) ? raw : 'general';
}

