        </div>
      </div>

      <p style="color:var(--muted);font-size:.875rem;line-height:1.55;margin:0">¿Qué quieres hacer?</p>
    </div>
  </div>
</div>`.trim();

return setChoiceHtml(msg, {
  choice_html: html,
