const fs = require('fs');
const path = require('path');

const ACTIVE_DIR = '/internal-storage-files/files/_active-sessions';
const WORKSPACE_DIR = '/internal-storage-files/files/codex-workspace';

function num(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
}

function clamp(v, min, max) {
    return Math.max(min, Math.min(max, v));
}

function ts(v) {
    const t = Date.parse(v || '');
    return Number.isFinite(t) ? t : 0;
}

function safeText(v, fallback = '') {
    if (v === null || v === undefined) return fallback;
    const s = String(v).trim();
    return s ? s : fallback;
}

function normalizeUserKey(v) {
    return safeText(v, '').toLowerCase();
}

function sameUser(a, b) {
    const aa = normalizeUserKey(a);
    const bb = normalizeUserKey(b);
    return !!aa && !!bb && aa === bb;
}

function getUserKey(msg) {
    const sec = msg.__axetFlowsSecurityContext || {};
    const idp = sec.externalIdpUserInfo || {};

    const value =
        msg.submission?.userKey ||
        msg.onInitSubmission?.userKey ||
        msg.payload?.data?.userKey ||
        idp.preferred_username ||
        idp.email ||
        idp.sub ||
        msg.req?.user?.email ||
        msg.req?.user?.id ||
        msg.userId ||
        '';

    return safeText(value, '');
}

function getProjectPath(sessionId) {
    return path.join(WORKSPACE_DIR, sessionId);
}

function readJson(filePath) {
    try {
        if (!filePath || !fs.existsSync(filePath)) return null;
        const raw = fs.readFileSync(filePath, 'utf8').trim();
        return raw ? JSON.parse(raw) : null;
    } catch (err) {
        node.warn(`⚠️ No se pudo leer JSON ${filePath}: ${err.message}`);
        return null;
    }
}

function readPlanCounts(projectPath) {
    if (!projectPath) return null;

    const planPath = path.join(projectPath, 'codex-docs', 'PLAN.md');
    if (!fs.existsSync(planPath)) return null;

    try {
        const txt = fs.readFileSync(planPath, 'utf8');
        const pending = (txt.match(/^\s*(?:[-*]\s*)?\[\s*\]\s+/gim) || []).length;
        const done = (txt.match(/^\s*(?:[-*]\s*)?\[[xX]\]\s+/gim) || []).length;
        const total = pending + done;

        if (total <= 0) return null;

        return {
            completed: done,
            total,
            remaining: pending,
            timestamp: new Date().toISOString(),
            source: 'PLAN.md'
        };
    } catch (err) {
        node.warn(`⚠️ No se pudo leer PLAN.md: ${err.message}`);
        return null;
    }
}

function pickBestTasks() {
    const candidates = Array.from(arguments)
        .filter(Boolean)
        .map((t) => ({
            raw: t,
            completed: num(t.completed),
            total: num(t.total),
            timestamp: ts(t.timestamp)
        }))
        .filter((x) => x.total > 0);

    if (!candidates.length) return null;

    candidates.sort((a, b) =>
        (b.completed - a.completed) ||
        (b.total - a.total) ||
        (b.timestamp - a.timestamp)
    );

    return candidates[0].raw;
}

function isResultReady(state) {
    return (
        state?.resultReady === true ||
        state?.readyToRedirect === true ||
        !!state?.result ||
        state?.runtime?.completed === true ||
        !!state?.artifacts?.executionReport ||
        state?.execution?.finished === true
    );
}

function isExecutionFailed(state) {
    return (
        state?.execution?.stopped === true ||
        state?.execution?.stopRequested === true ||
        state?.execution?.reason === 'manual-stop' ||
        state?.runtime?.manualStop === true ||
        state?.progressView?.phaseStatus?.execute === 'error' ||
        (
            state?.runtime?.success === false &&
            (
                !!state?.runtime?.error ||
                !!state?.execution?.reason
            )
        )
    );
}

function computeProgress(state, projectPath) {
    const planTasks = readPlanCounts(projectPath);
    const tasks = pickBestTasks(state?.tasksLive, state?.tasks, planTasks);

    const done = num(tasks?.completed);
    const total = num(tasks?.total);
    const remaining = Math.max(0, total - done);

    const taskProgress = total > 0
        ? Math.round((done / total) * 100)
        : 0;

    const runtimeProgress = Math.max(
        num(state?.runtime?.progress),
        num(state?.progress),
        num(state?.progressView?.progress),
        num(state?.payload?.progress)
    );

    const resultReady = isResultReady(state);
    const executionFailed = isExecutionFailed(state);

    let progress = clamp(Math.max(taskProgress, runtimeProgress), 0, 100);

    if (resultReady && !executionFailed && (total === 0 || done >= total || state?.runtime?.completed === true)) {
        progress = 100;
    }

    return {
        tasks,
        done,
        total,
        remaining,
        progress,
        resultReady,
        executionFailed,
        allTasksDone: total > 0 && done >= total
    };
}

function hydrateMsg(msg, data) {
    msg.sessionId = data.sessionId || '';
    msg.projectPath = data.projectPath || '';

    msg.submission = {
        ...(msg.submission || {}),
        ...data
    };

    msg.onInitSubmission = {
        ...(msg.onInitSubmission || {}),
        ...data
    };

    msg.payload = msg.payload || {};
    msg.payload.data = {
        ...(msg.payload.data || {}),
        ...data
    };

    return msg;
}

const userKey = getUserKey(msg);

if (!userKey) {
    node.warn('⚠️ Resume sin userKey real. No se usa anonymous y no se accede a _active-sessions.');

    hydrateMsg(msg, {
        userKey: '',
        sessionId: '',
        projectPath: '',
        resumeError: 'no-user-key',
        runtimeStatus: 'No se pudo identificar el usuario'
    });

    return [null, msg];
}

const activeFile = path.join(ACTIVE_DIR, `${userKey}.json`);
const active = readJson(activeFile);

if (!active || !active.sessionId) {
    node.warn(`⚠️ Resume sin sesión activa para ${userKey}`);

    hydrateMsg(msg, {
        userKey,
        sessionId: '',
        projectPath: '',
        resumeError: 'no-active-session',
        runtimeStatus: 'No se encontró sesión activa'
    });

    return [null, msg];
}

const sessionId = safeText(active.sessionId, '');
const projectPath = getProjectPath(sessionId);
const statePath = path.join(projectPath, 'codex-docs', 'SESSION_STATE.json');
const state = readJson(statePath);

if (!state) {
    node.warn(`⚠️ Resume con sesión activa, pero sin SESSION_STATE.json: ${sessionId}`);

    hydrateMsg(msg, {
        userKey,
        sessionId,
        projectPath,
        sessionStatePath: statePath,
        resumeError: 'state-missing',
        runtimeStatus: 'SESSION_STATE.json no disponible todavía',
        progress: 0
    });

    return [null, msg];
}

if (state.sessionId && state.sessionId !== sessionId) {
    node.warn(`⛔ Resume bloqueado por STATE MISMATCH: active=${sessionId} state=${state.sessionId}`);

    hydrateMsg(msg, {
        userKey,
        sessionId,
        projectPath,
        sessionStatePath: statePath,
        resumeError: 'state-mismatch',
        runtimeStatus: 'Inconsistencia de sessionId detectada',
        progress: 0
    });

    return [null, msg];
}

if (state.userKey && !sameUser(state.userKey, userKey)) {
    node.warn(`⛔ Resume bloqueado por USER MISMATCH: activeUser=${userKey} stateUser=${state.userKey}`);

    hydrateMsg(msg, {
        userKey,
        sessionId,
        projectPath,
        sessionStatePath: statePath,
        resumeError: 'user-mismatch',
        runtimeStatus: 'La sesión activa no corresponde a este usuario',
        progress: 0
    });

    return [null, msg];
}

const info = computeProgress(state, projectPath);

function fmtDate(v) {
    const t = Date.parse(v || '');
    if (!Number.isFinite(t)) return '-';

    return new Date(t).toLocaleString('es-ES', {
        day: '2-digit',
        month: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    });
}

function chipModel(modelInfo) {
    const model = safeText(modelInfo, '').toLowerCase();

    if (model.includes('mini')) {
        return { icon: '⚡', className: 'chip-model-mini' };
    }

    if (model.includes('gpt-5') || model.includes('gpt5')) {
        return { icon: '🤖', className: 'chip-model-flagship' };
    }

    if (model.includes('o3') || model.includes('o4') || model.includes('reason')) {
        return { icon: '🧭', className: 'chip-model-reasoning' };
    }

    return { icon: '🤖', className: 'chip-model-default' };
}

function chipReason(reasoningInfo) {
    const level = safeText(reasoningInfo, '').toLowerCase();

    if (level === 'low') return { icon: '🧠', className: 'chip-reason-low' };
    if (level === 'medium') return { icon: '🧠', className: 'chip-reason-medium' };
    if (level === 'high' || level === 'xhigh') return { icon: '🧠', className: 'chip-reason-high' };

    return { icon: '🧠', className: 'chip-reason-default' };
}

function phaseMeta(status) {
    if (status === 'completed') {
        return { icon: '✅', label: 'Completada', className: 'phase--completed' };
    }

    if (status === 'running') {
        return { icon: '🔄', label: 'En curso', className: 'phase--running' };
    }

    if (status === 'error') {
        return { icon: '❌', label: 'Error', className: 'phase--error' };
    }

    return { icon: '⏳', label: 'Pendiente', className: 'phase--pending' };
}

function staleMinutesFromActive(active) {
    const match = String(active?.staleReason || '').match(/(\d+)/);
    return match ? num(match[1]) : 0;
}

const tasksDone = num(info.done);
const tasksTotal = num(info.total);
const tasksRemaining = Math.max(0, tasksTotal - tasksDone);
const progress = num(info.progress);

const batchIteration = num(
    state?.execution?.batchIteration ||
    state?.tasksLive?.batch ||
    state?.tasks?.batch ||
    0
);

const uiCompleted = tasksTotal > 0 && tasksDone >= tasksTotal;

const stale =
    state?.runtime?.stale === true ||
    active?.status === 'stale';

const staleMinutes = Math.max(
    num(state?.runtime?.staleMinutes),
    active?.status === 'stale' ? staleMinutesFromActive(active) : 0
);

const executionFailed = info.executionFailed === true;

const resultReady =
    info.resultReady === true &&
    !executionFailed &&
    (
        tasksTotal === 0 ||
        uiCompleted ||
        progress >= 100 ||
        state?.runtime?.completed === true
    );

const completed = resultReady || executionFailed;

const modelInfo = safeText(
    state?.selection?.modelSelect ||
    state?.selection?.model ||
    state?.monitoring?.modelSelect,
    '-'
);

const reasoningInfo = safeText(
    state?.selection?.reasoningLevel ||
    state?.selection?.reasoning ||
    state?.monitoring?.reasoningLevel,
    '-'
);

const modelVisual = chipModel(modelInfo);
const reasoningVisual = chipReason(reasoningInfo);

const runtimeStatus = safeText(
    state?.runtime?.status ||
    active?.status,
    resultReady ? 'Resultado listo' : 'Reanudando sesión'
);

const statusLabel = resultReady
    ? '✅ Completado'
    : stale
        ? `⚠️ Sin actividad (${staleMinutes} min)`
        : executionFailed
            ? '⛔ Detenido'
            : uiCompleted
                ? '📦 Finalizando resultados'
                : '🔄 En proceso';

const statusClass = resultReady
    ? 'status--ok'
    : (stale || executionFailed)
        ? 'status--warn'
        : 'status--run';

const liveLabel = stale ? 'Stale' : 'Live';
const liveClass = stale ? 'live--warn' : '';

const currentTaskLabel = resultReady
    ? 'Resultado preparado'
    : executionFailed
        ? 'Ejecución detenida'
        : uiCompleted
            ? 'Generando resultados finales'
            : `Tarea ${Math.min(tasksDone + 1, Math.max(tasksTotal, 1))}`;

const currentTaskTitle = resultReady
    ? 'La salida final ya está lista para mostrarse'
    : executionFailed
        ? runtimeStatus
        : uiCompleted
            ? 'Preparando la salida final y validando el contenido generado'
            : 'Procesando tarea actual';

const currentTaskStepText = resultReady
    ? 'Finalizado'
    : tasksTotal > 0
        ? `${Math.min(tasksDone + 1, tasksTotal)}/${tasksTotal}`
        : '0/0';

const planningPhase =
    state?.progressView?.phaseStatus?.docs === 'done' ||
        tasksTotal > 0 ||
        progress > 0
        ? 'completed'
        : 'pending';

const implementationPhase = executionFailed
    ? 'error'
    : state?.progressView?.phaseStatus?.execute === 'done' || uiCompleted
        ? 'completed'
        : progress > 0 || batchIteration > 0 || runtimeStatus
            ? 'running'
            : 'pending';

const finalPhase = executionFailed
    ? 'error'
    : resultReady
        ? 'completed'
        : uiCompleted
            ? 'running'
            : 'pending';

const phase1 = phaseMeta(planningPhase);
const phase2 = phaseMeta(implementationPhase);
const phase3 = phaseMeta(finalPhase);

const progressUiData = {
    userKey,
    sessionId,
    projectPath,
    sessionStatePath: statePath,

    progress,
    tasksDone,
    tasksTotal,
    tasksRemaining,
    batchIteration,

    completed,
    resultReady,
    executionFailed,
    uiCompleted,

    runtimeStatus,
    statusLabel,
    statusClass,
    liveLabel,
    liveClass,

    stale,
    staleMinutes,

    sessionShort: sessionId.substring(0, 8),
    updatedAt: state?.updatedAt || active?.updatedAt || '',
    updatedAtDisplay: fmtDate(state?.updatedAt || active?.updatedAt || ''),
    lastCheckpoint: safeText(state?.lastCheckpoint, '-'),

    modelInfo,
    reasoningInfo,
    modelChipIcon: modelVisual.icon,
    modelChipClass: modelVisual.className,
    reasoningChipIcon: reasoningVisual.icon,
    reasoningChipClass: reasoningVisual.className,

    currentTaskLabel,
    currentTaskTitle,
    currentTaskStepText,

    phase1Icon: phase1.icon,
    phase1Label: phase1.label,
    phase1Class: phase1.className,

    phase2Icon: phase2.icon,
    phase2Label: phase2.label,
    phase2Class: phase2.className,

    phase3Icon: phase3.icon,
    phase3Label: phase3.label,
    phase3Class: phase3.className,

    refreshNonce: Date.now(),
    refreshTs: new Date().toISOString()
};

hydrateMsg(msg, progressUiData);

const goToResults =
    resultReady &&
    !executionFailed &&
    (
        tasksTotal === 0 ||
        uiCompleted ||
        progress >= 100 ||
        state?.runtime?.completed === true
    );

if (goToResults) {
    node.warn(`🏁 Resume → Results (${sessionId.slice(0, 8)}) progress=${progress}%`);
    return [msg, null];
}

node.warn(`🔄 Resume → Progress (${sessionId.slice(0, 8)}) progress=${progress}% tasks=${tasksDone}/${tasksTotal}`);
return [null, msg];

