/* Ocultar Welcome automático */
.sidebar li:first-child a[href*='welcome'],
.sidebar li:first-child,
.jstree li:first-child a[href*='welcome'],
.jstree li:first-child {
    display: none !important;
}

/* Reset estado activo roto */
.menu .active,
.menu .router-link-active,
.menu .router-link-exact-active,
.menu .selected,
.menu .current {
    background: transparent !important;
    box-shadow: none !important;
}

/* Hover limpio */
.menu a {
    border-radius: 8px !important;
    transition: all .15s ease;
}

.menu a:hover {
    background: rgba(30, 111, 209, .08) !important;
}

/* Activo SOLO en items reales */
.menu li:not(:first-child).active>a,
.menu li:not(:first-child).router-link-active>a,
.menu li:not(:first-child).router-link-exact-active>a,
.menu li:not(:first-child).selected>a,
.menu li:not(:first-child).current>a {
    background: rgba(30, 111, 209, .12) !important;
