const fs = require('fs');
const path = require('path');

function num(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
}

function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}

function ts(v) {
  const t = Date.parse(v || '');
  return Number.isFinite(t) ? t : 0;
}

function safeText(v, fallback) {
  if (v === null || v === undefined) return fallback;
  const s = String(v).trim();
  return s ? s : fallback;
}

function toNum(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
}

function getUserKey(msg) {
  const sec = msg.__axetFlowsSecurityContext || {};
  const idp = sec.externalIdpUserInfo || {};
  return (
    idp.preferred_username ||
    idp.email ||
    idp.sub ||
    msg.req?.user?.email ||
    msg.req?.user?.id ||
    msg.userId ||
    'anonymous'
  );
}

function getActiveSessionPath(userKey) {
  return path.join('/internal-storage-files/files/_active-sessions', `${userKey}.json`);
}

function resolveSessionContext(msg) {
  const sessionId =
    msg.sessionId ||
    msg.submission?.sessionId ||
    msg.onInitSubmission?.sessionId ||
    msg.req?.query?.sessionId ||
    msg.payload?.data?.sessionId ||
    msg.payload?.sessionId;

  const projectPath =
    msg.projectPath ||
    msg.submission?.projectPath ||
    msg.onInitSubmission?.projectPath ||
    msg.payload?.data?.projectPath ||
    msg.payload?.projectPath ||
    (sessionId ? path.join('/internal-storage-files/files', 'codex-workspace', sessionId) : null);

  const sessionStatePath =
    (typeof msg.sessionStatePath === 'string' && msg.sessionStatePath.trim())
      ? msg.sessionStatePath
      : (projectPath ? path.join(projectPath, 'codex-docs', 'SESSION_STATE.json') : null);

  return { sessionId, projectPath, sessionStatePath };
}



function loadJson(filePath) {
  try {
    if (filePath && fs.existsSync(filePath)) {
      const raw = fs.readFileSync(filePath, 'utf8').trim();
      return raw ? JSON.parse(raw) : {};
    }
  } catch (err) {
    node.warn('No se pudo leer ' + filePath + ': ' + err.message);
  }
  return null;
}

function saveJson(filePath, data) {
  try {
    fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf8');
  } catch (err) {
    node.warn('No se pudo guardar ' + filePath + ': ' + err.message);
  }
}

function clearLoopMarker(sessionId) {
  if (!sessionId) return;
  try {
    flow.set('lastSeenCompleted:' + sessionId, undefined);
  } catch (_e) { }
}

function readPlanCounts(projectPath) {
  if (!projectPath) return null;

  const planPath = path.join(projectPath, 'codex-docs', 'PLAN.md');
  if (!fs.existsSync(planPath)) return null;

  try {
    const txt = fs.readFileSync(planPath, 'utf8');
    const pending = (txt.match(/^\s*(?:[-*]\s*)?\[\s*\]\s+/gim) || []).length;
    const done = (txt.match(/^\s*(?:[-*]\s*)?\[[xX]\]\s+/gim) || []).length;
    const total = pending + done;

    if (total <= 0) return null;

    return {
      completed: done,
      total: total,
      remaining: pending,
      timestamp: new Date().toISOString()
    };
  } catch (err) {
    node.warn('No se pudo leer PLAN.md: ' + err.message);
    return null;
  }
}

function pickBestTasks() {
  const candidates = Array.from(arguments)
    .filter(Boolean)
    .map(function (t) {
      return {
        raw: t,
        completed: num(t.completed),
        total: num(t.total),
        timestamp: ts(t.timestamp)
      };
    })
    .filter(function (x) { return x.total > 0; });

  if (!candidates.length) return null;

  candidates.sort(function (a, b) {
    return (b.completed - a.completed) ||
      (b.total - a.total) ||
      (b.timestamp - a.timestamp);
  });

  return candidates[0].raw;
}

function buildMessage(baseMsg, sessionId, projectPath, sessionStatePath, uiData) {
  const refreshNonce = Date.now();
  const refreshTs = new Date().toISOString();
  const monitorCycle = num(baseMsg.monitorCycle) + 1;

  const mergedData = {
    ...((baseMsg.payload && baseMsg.payload.data) || {}),
    ...uiData,
    refreshNonce,
    refreshTs,
    monitorCycle
  };

  return {
    ...baseMsg,
    sessionId,
    projectPath,
    sessionStatePath,
    monitorCycle,
    completed: mergedData.completed === true,
    executionFailed: mergedData.executionFailed === true,
    progress: num(mergedData.progress),
    tasksDone: num(mergedData.tasksDone),
    tasksTotal: num(mergedData.tasksTotal),
    batchIteration: num(mergedData.batchIteration),
    payload: {
      ...(baseMsg.payload || {}),
      sessionId,
      projectPath,
      sessionStatePath,
      data: mergedData
    },
    submission: {
      ...(baseMsg.submission || {}),
      ...mergedData
    },
    onInitSubmission: {
      ...(baseMsg.onInitSubmission || {}),
      ...mergedData
    }
  };
}


function formatDate(v) {
  const t = Date.parse(v || '');
  if (!Number.isFinite(t)) return '-';
  return new Date(t).toLocaleString('es-ES', {
    day: '2-digit',
    month: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit'
  });
}

function phaseMeta(status) {
  if (status === 'completed') {
    return { icon: '✅', label: 'Completada', className: 'phase--completed' };
  }
  if (status === 'running') {
    return { icon: '🔄', label: 'En curso', className: 'phase--running' };
  }
  if (status === 'error') {
    return { icon: '❌', label: 'Error', className: 'phase--error' };
  }
  return { icon: '⏳', label: 'Pendiente', className: 'phase--pending' };
}

function normalizeVisualKey(v) {
  return safeText(v, '').toLowerCase();
}

function modelChipMeta(modelInfo) {
  const model = normalizeVisualKey(modelInfo);

  if (!model || model === '-') {
    return { icon: '🤖', className: 'chip-model-default' };
  }

  if (model.includes('mini')) {
    return { icon: '⚡', className: 'chip-model-mini' };
  }

  if (model.includes('gpt-5') || model.includes('gpt5')) {
    return { icon: '🤖', className: 'chip-model-flagship' };
  }

  if (model.includes('o3') || model.includes('o4') || model.includes('reason')) {
    return { icon: '🧭', className: 'chip-model-reasoning' };
  }

  return { icon: '🤖', className: 'chip-model-default' };
}

function reasoningChipMeta(reasoningInfo) {
  const level = normalizeVisualKey(reasoningInfo);

  if (level === 'low') {
    return { icon: '🧠', className: 'chip-reason-low' };
  }

  if (level === 'medium') {
    return { icon: '🧠', className: 'chip-reason-medium' };
  }

  if (level === 'high' || level === 'xhigh') {
    return { icon: '🧠', className: 'chip-reason-high' };
  }

  return { icon: '🧠', className: 'chip-reason-default' };
}

function buildStatusLabel(resultReady, stale, staleMinutes, executionFailed, uiCompleted) {
  if (resultReady) {
    return '✅ Completado';
  }

  if (stale) {
    return '⚠️ Sin actividad (' + staleMinutes + ' min)';
  }

  if (executionFailed) {
    return '⛔ Detenido';
  }

  if (uiCompleted) {
    return '📦 Finalizando resultados';
  }

  return '🔄 En proceso';
}

function isTerminalResult(progressData) {
  return (
    progressData?.resultReady === true ||
    progressData?.readyToRedirect === true ||
    !!progressData?.result ||
    progressData?.runtime?.completed === true ||
    !!progressData?.artifacts?.executionReport ||
    progressData?.execution?.finished === true
  );
}

function parseActiveStaleMinutes(active) {
  const reason = safeText(active?.staleReason, '');
  const match = reason.match(/(\d+)/);
  return match ? num(match[1]) : 0;
}

function humanizeStopReason(reason, ctx) {
  const staleMinutes = num(ctx?.staleMinutes);
  const batches = num(ctx?.batches);
  const tasksDone = num(ctx?.tasksDone);
  const tasksTotal = num(ctx?.tasksTotal);
  const runtimeError = safeText(ctx?.runtimeError, '');

  if (reason === 'stale-log') {
    return 'El log de ejecucion no se ha actualizado en los ultimos ' +
      staleMinutes + ' minuto' + (staleMinutes === 1 ? '' : 's') +
      '. Codex probablemente se ha quedado detenido o ha perdido la sesion.';
  }

  if (reason === 'no-progress') {
    return '3 batches seguidos sin progreso. Posible token expirado o error de conexion.';
  }

  if (reason === 'batch-limit') {
    return 'Limite maximo de batches alcanzado (' + batches + ').';
  }

  if (reason === 'active-session-replaced') {
    return 'Se detecto otra sesion activa para este usuario. El monitor ha cambiado a la nueva ejecucion.';
  }

  if (reason === 'active-session-missing') {
    return 'La sesion activa dejo de estar registrada antes de terminar. Es posible que se cancelara o fuera reemplazada.';
  }

  if (reason === 'manual-stop') {
    return 'La ejecucion se detuvo manualmente antes de terminar.';
  }

  if (reason === 'runtime-error') {
    return runtimeError
      ? 'La ejecucion devolvio un error: ' + runtimeError
      : 'La ejecucion devolvio un error en tiempo de ejecucion.';
  }

  if (reason === 'execute-error') {
    return 'La fase de implementacion reporto un error. Revisa los logs de Codex.';
  }

  if (reason) {
    return 'La ejecucion se detuvo por: ' + reason;
  }

  if (tasksTotal > 0) {
    return 'La ejecucion se detuvo con ' + tasksDone + ' de ' + tasksTotal + ' tareas completadas.';
  }

  return 'La ejecucion se detuvo antes de completarse.';
}

function readActiveSession(msg) {
  const userKey = getUserKey(msg);
  const activePath = getActiveSessionPath(userKey);
  const active = loadJson(activePath);
  return { userKey, activePath, active };
}

function persistStoppedState(progressData, sessionStatePath, options) {
  const reason = safeText(options?.reason, 'unknown');
  const status = safeText(options?.status, 'Ejecucion detenida');
  const stale = options?.stale === true;
  const staleMinutes = num(options?.staleMinutes);

  progressData.execution = progressData.execution || {};
  progressData.runtime = progressData.runtime || {};

  const prev = JSON.stringify({
    stopped: progressData.execution.stopped,
    reason: progressData.execution.reason,
    success: progressData.runtime.success,
    status: progressData.runtime.status,
    stale: progressData.runtime.stale,
    staleMinutes: progressData.runtime.staleMinutes
  });

  progressData.execution.stopped = true;
  progressData.execution.reason = reason;
  progressData.runtime.success = false;
  progressData.runtime.status = status;

  if (stale) {
    progressData.runtime.stale = true;
    progressData.runtime.staleMinutes = staleMinutes;
  }

  progressData.updatedAt = new Date().toISOString();

  const next = JSON.stringify({
    stopped: progressData.execution.stopped,
    reason: progressData.execution.reason,
    success: progressData.runtime.success,
    status: progressData.runtime.status,
    stale: progressData.runtime.stale,
    staleMinutes: progressData.runtime.staleMinutes
  });

  if (prev !== next) {
    saveJson(sessionStatePath, progressData);
  }
}

function syncActiveSessionStale(activePath, sessionId, projectPath, staleMinutes) {
  try {
    const active = loadJson(activePath);
    if (!active || active.sessionId !== sessionId) return;

    const staleReason = 'Log sin actividad ' + staleMinutes + ' min';
    const changed =
      active.status !== 'stale' ||
      active.projectPath !== projectPath ||
      active.staleReason !== staleReason;

    if (!changed) return;

    active.status = 'stale';
    active.projectPath = projectPath;
    active.updatedAt = new Date().toISOString();
    active.staleReason = staleReason;
    saveJson(activePath, active);
  } catch (err) {
    node.warn('No se pudo actualizar active session stale: ' + err.message);
  }
}

function detectAndPersistStale(projectPath, sessionId, sessionStatePath, progressData, activePath) {
  const thresholdMinutes = 5;
  const terminal = isTerminalResult(progressData);
  const alreadyStopped = progressData?.execution?.stopped === true;

  const fallbackLogPath = projectPath
    ? path.join(projectPath, 'codex-unified-' + sessionId + '.log')
    : '';

  const logPath = safeText(progressData?.execution?.unifiedLogPath, fallbackLogPath);
  const existingStale = progressData?.runtime?.stale === true;
  const existingMinutes = num(progressData?.runtime?.staleMinutes);
  const existingReason = safeText(progressData?.execution?.reason, '');

  if (!logPath || !fs.existsSync(logPath)) {
    return {
      stale: existingStale,
      staleMinutes: existingMinutes,
      reason: existingReason,
      logPath: logPath || ''
    };
  }

  try {
    const stat = fs.statSync(logPath);
    const computedMinutes = Math.max(0, Math.floor((Date.now() - stat.mtimeMs) / 60000));
    const stale = existingStale || (!terminal && !alreadyStopped && computedMinutes >= thresholdMinutes);
    const staleMinutes = stale ? Math.max(existingMinutes, computedMinutes) : existingMinutes;
    const reason = stale ? (existingReason || 'stale-log') : existingReason;

    if (stale && !terminal && !alreadyStopped) {
      persistStoppedState(progressData, sessionStatePath, {
        reason: reason,
        status: 'Codex sin actividad (' + staleMinutes + ' min)',
        stale: true,
        staleMinutes: staleMinutes
      });

      syncActiveSessionStale(activePath, sessionId, projectPath, staleMinutes);
    }

    return {
      stale: stale,
      staleMinutes: staleMinutes,
      reason: reason,
      logPath: logPath
    };
  } catch (err) {
    node.warn('No se pudo calcular stale del log: ' + err.message);
    return {
      stale: existingStale,
      staleMinutes: existingMinutes,
      reason: existingReason,
      logPath: logPath
    };
  }
}

const planTasks = [
  { num: 1, title: 'Lectura y validacion de documentacion base' },
  { num: 2, title: 'Analisis de estructura y referencias del proyecto' },
  { num: 3, title: 'Extraccion y normalizacion de contenido relevante' },
  { num: 4, title: 'Generacion de referencias y mapeos intermedios' },
  { num: 5, title: 'Validacion de consistencia y cobertura' },
  { num: 6, title: 'Construccion del fichero de respuestas final' },
  { num: 7, title: 'Empaquetado y revision de salida generada' }
];

function getCurrentTask(done, total, ready) {
  if (ready) {
    return {
      label: 'Resultado preparado',
      title: 'La salida final ya esta lista para mostrarse',
      stepText: 'Finalizado'
    };
  }

  if (total > 0 && done >= total) {
    return {
      label: 'Generando resultados finales',
      title: 'Preparando la salida final y validando el contenido generado',
      stepText: 'Paso final'
    };
  }

  const currentIndex = Math.min(done, planTasks.length - 1);
  const currentTask = planTasks[currentIndex] || {
    num: done + 1,
    title: 'Procesando tarea actual'
  };

  return {
    label: 'Tarea ' + currentTask.num,
    title: currentTask.title,
    stepText: Math.min(done, Math.max(total, currentTask.num)) + '/' + Math.max(total, currentTask.num)
  };
}

function buildFallbackData(sessionId, projectPath, overrides) {
  return {
    sessionId: sessionId || '',
    projectPath: projectPath || '',
    sessionShort: sessionId ? sessionId.substring(0, 8) : '-',
    progress: 0,
    tasksDone: 0,
    tasksTotal: 0,
    tasksRemaining: 0,
    batchIteration: 0,
    runtimeStatus: 'Esperando actualizacion',
    statusLabel: 'Iniciando',
    statusClass: 'status--run',
    liveLabel: 'Live',
    liveClass: '',
    completed: false,
    resultReady: false,
    uiCompleted: false,
    stale: false,
    staleMinutes: 0,
    executionFailed: false,
    stoppedReason: '',
    stoppedReasonText: '',
    updatedAt: '',
    updatedAtDisplay: '-',
    refreshNonce: 0,
    refreshTs: '',
    lastCheckpoint: '-',
    modelInfo: '-',
    reasoningInfo: '-',
    modelChipIcon: '🤖',
    modelChipClass: 'chip-model-default',
    reasoningChipIcon: '🧠',
    reasoningChipClass: 'chip-reason-default',
    currentTaskLabel: 'Preparando',
    currentTaskTitle: 'Preparando ejecucion...',
    currentTaskStepText: '0/0',
    phase1Icon: '...',
    phase1Label: 'Pendiente',
    phase1Class: 'phase--pending',
    phase2Icon: '...',
    phase2Label: 'Pendiente',
    phase2Class: 'phase--pending',
    phase3Icon: '...',
    phase3Label: 'Pendiente',
    phase3Class: 'phase--pending',
    ...(overrides || {})
  };
}

const activeInfo = readActiveSession(msg);
const requestedCtx = resolveSessionContext(msg);
node.warn(requestedCtx);

let sessionId = requestedCtx.sessionId;
let projectPath = requestedCtx.projectPath;
let sessionStatePath = requestedCtx.sessionStatePath;

const originallyRequestedSessionId = sessionId;
const activeMissingInitially = !activeInfo.active;

if ((!sessionId || !projectPath) && activeInfo.active?.sessionId) {
  sessionId = activeInfo.active.sessionId;
  projectPath = activeInfo.active.projectPath || path.join('/internal-storage-files/files', 'codex-workspace', sessionId);
  sessionStatePath = path.join(projectPath, 'codex-docs', 'SESSION_STATE.json');
}

const sessionWasReplaced =
  !!(originallyRequestedSessionId && activeInfo.active?.sessionId && activeInfo.active.sessionId !== originallyRequestedSessionId);

if (sessionWasReplaced) {
  node.warn(
    '🛡️ ZOMBIE REDIRECT: ' +
    originallyRequestedSessionId.substring(0, 8) +
    '… → activa ' +
    activeInfo.active.sessionId.substring(0, 8) +
    '…'
  );
  clearLoopMarker(originallyRequestedSessionId);
  sessionId = activeInfo.active.sessionId;
  projectPath = activeInfo.active.projectPath || path.join('/internal-storage-files/files', 'codex-workspace', sessionId);
  sessionStatePath = path.join(projectPath, 'codex-docs', 'SESSION_STATE.json');
}

if (!sessionId) {
  const uiData = buildFallbackData('', '', {
    runtimeStatus: 'Esperando sessionId',
    statusLabel: 'Sin sesion'
  });
  const outMsg = buildMessage(msg, '', '', '', uiData);
  node.status({ fill: 'yellow', shape: 'ring', text: 'sin sesion' });
  return [outMsg, outMsg];
}

let progressData = null;

if (!progressData) {
  if (activeMissingInitially && originallyRequestedSessionId) {
    clearLoopMarker(originallyRequestedSessionId);

    const stoppedReason = 'active-session-missing';
    const stoppedReasonText = humanizeStopReason(stoppedReason, {
      tasksDone: 0,
      tasksTotal: 0,
      batches: 0
    });

    const uiData = buildFallbackData(sessionId, projectPath, {
      completed: true,
      executionFailed: true,
      stoppedReason: stoppedReason,
      stoppedReasonText: stoppedReasonText,
      runtimeStatus: stoppedReasonText,
      statusLabel: 'Detenido',
      statusClass: 'status--warn',
      liveLabel: 'Stale',
      liveClass: 'live--warn',
      currentTaskLabel: 'Ejecucion detenida',
      currentTaskTitle: stoppedReasonText,
      currentTaskStepText: '-',
      phase2Icon: 'ERR',
      phase2Label: 'Error',
      phase2Class: 'phase--error',
      phase3Icon: 'ERR',
      phase3Label: 'Error',
      phase3Class: 'phase--error'
    });

    const loopMsg = buildMessage(msg, sessionId, projectPath, sessionStatePath, uiData);
    node.status({ fill: 'red', shape: 'dot', text: 'active missing' });
    return [null, loopMsg];
  }

  const uiData = buildFallbackData(sessionId, projectPath, {
    runtimeStatus: 'Esperando SESSION_STATE.json',
    statusLabel: 'Iniciando'
  });
  const uiMsg = buildMessage(msg, sessionId, projectPath, sessionStatePath, uiData);
  const loopMsg = buildMessage(msg, sessionId, projectPath, sessionStatePath, uiData);

  node.status({ fill: 'yellow', shape: 'ring', text: 'iniciando' });
  return [uiMsg, loopMsg];
}

const staleInfo = detectAndPersistStale(
  projectPath,
  sessionId,
  sessionStatePath,
  progressData,
  activeInfo.activePath
);

const tasksStable = progressData.tasks || null;
const tasksLive = progressData.tasksLive || null;
const tasksPlan = readPlanCounts(projectPath);
const tasks = pickBestTasks(tasksLive, tasksStable, tasksPlan);

const tasksDone = num(tasks?.completed);
const tasksTotal = num(tasks?.total);
const tasksRemaining = Math.max(0, tasksTotal - tasksDone);

const runtimeProgress = toNum(progressData?.runtime?.progress);
const taskProgress = tasksTotal > 0 ? Math.round((tasksDone / tasksTotal) * 100) : 0;
const derivedProgress = tasksTotal > 0 ? taskProgress : runtimeProgress;
const progress = clamp(derivedProgress, 0, 100);

const uiCompleted = tasksTotal > 0 && tasksDone >= tasksTotal;

let rawResultReady =
  progressData?.resultReady === true ||
  progressData?.readyToRedirect === true ||
  !!progressData?.result ||
  progressData?.runtime?.completed === true ||
  !!progressData?.artifacts?.executionReport;

if (!rawResultReady && projectPath) {
  const outJson = path.join(projectPath, 'codex-docs', 'output', 'respuestas.json');
  const reportMd = path.join(projectPath, 'codex-docs', 'EXECUTION_REPORT.md');
  if (fs.existsSync(outJson) || fs.existsSync(reportMd)) {
    rawResultReady = true;
  }
}

const stateTasksDone = num(progressData?.tasks?.completed);
const stateTasksTotal = num(progressData?.tasks?.total);

const taskGateSatisfied =
  tasksTotal > 0
    ? uiCompleted
    : stateTasksTotal > 0
      ? stateTasksDone >= stateTasksTotal
      : (progressData?.execution?.finished === true && progressData?.runtime?.completed === true);

const resultReady = rawResultReady && taskGateSatisfied;

const activeStatusStale =
  activeInfo.active?.sessionId === sessionId &&
  activeInfo.active?.status === 'stale';

const stale =
  progressData?.runtime?.stale === true ||
  staleInfo.stale === true ||
  activeStatusStale;

const staleMinutes = Math.max(
  num(progressData?.runtime?.staleMinutes),
  num(staleInfo.staleMinutes),
  activeStatusStale ? parseActiveStaleMinutes(activeInfo.active) : 0
);

const runtimeErrorText = safeText(progressData?.runtime?.error, '');
const explicitExecutionError = progressData?.progressView?.phaseStatus?.execute === 'error';

let stoppedReason = safeText(progressData?.execution?.reason || staleInfo.reason, '');

if (!resultReady && !stoppedReason && activeMissingInitially) {
  stoppedReason = 'active-session-missing';
  persistStoppedState(progressData, sessionStatePath, {
    reason: stoppedReason,
    status: humanizeStopReason(stoppedReason, {
      tasksDone: tasksDone,
      tasksTotal: tasksTotal,
      batches: num(progressData?.execution?.batchIteration || tasks?.batch)
    })
  });
}

if (!resultReady && !stoppedReason && runtimeErrorText) {
  stoppedReason = 'runtime-error';
  persistStoppedState(progressData, sessionStatePath, {
    reason: stoppedReason,
    status: 'Error de ejecucion'
  });
}

if (!resultReady && !stoppedReason && explicitExecutionError) {
  stoppedReason = 'execute-error';
  persistStoppedState(progressData, sessionStatePath, {
    reason: stoppedReason,
    status: 'Error en la fase de implementacion'
  });
}

if (activeMissingInitially && originallyRequestedSessionId) {
  clearLoopMarker(originallyRequestedSessionId);
}

const batchNum = progressData?.execution?.batchIteration || num(tasks?.batch);

const executionFailed =
  !resultReady &&
  (
    progressData?.execution?.stopped === true ||
    runtimeErrorText ||
    explicitExecutionError ||
    stoppedReason
  ) &&
  (
    progressData?.runtime?.success === false ||
    runtimeErrorText ||
    explicitExecutionError ||
    stoppedReason
  );

const completed = resultReady || executionFailed;

const stoppedReasonText = humanizeStopReason(stoppedReason, {
  staleMinutes: staleMinutes,
  batches: batchNum,
  tasksDone: tasksDone,
  tasksTotal: tasksTotal,
  runtimeError: runtimeErrorText
});

const modelInfo = safeText(progressData?.selection?.modelSelect || progressData?.selection?.model, '-');
const reasoningInfo = safeText(progressData?.selection?.reasoningLevel || progressData?.selection?.reasoning, '-');
const modelVisual = modelChipMeta(modelInfo);
const reasoningVisual = reasoningChipMeta(reasoningInfo);

const hasTasks = tasksTotal > 0;
const isDone = hasTasks && tasksDone >= tasksTotal;
const hasBatch = Number(batchNum || 0) > 0;
const hasLogs = Array.isArray(progressData.logs) && progressData.logs.length > 0;
const hasStatusText = typeof progressData?.runtime?.status === 'string' && progressData.runtime.status.trim().length > 0;
const implHasStarted = isDone || tasksDone > 0 || hasBatch || hasLogs || hasStatusText;

const planningPhase =
  progressData?.progressView?.phaseStatus?.docs === 'done'
    ? 'completed'
    : (hasTasks ? 'completed' : (progress > 0 ? 'running' : 'pending'));

const implPhase =
  executionFailed
    ? 'error'
    : progressData?.progressView?.phaseStatus?.execute === 'done'
      ? 'completed'
      : progressData?.progressView?.phaseStatus?.execute === 'error'
        ? 'error'
        : progressData?.progressView?.phaseStatus?.execute === 'current'
          ? 'running'
          : (isDone ? 'completed' : (implHasStarted ? 'running' : 'pending'));

const finalPhase =
  executionFailed
    ? 'error'
    : resultReady
      ? 'completed'
      : (uiCompleted ? 'running' : 'pending');

const phase1 = phaseMeta(planningPhase);
const phase2 = phaseMeta(implPhase);
const phase3 = phaseMeta(finalPhase);

const currentTask = executionFailed
  ? {
    label: stale ? 'Codex sin actividad' : 'Ejecucion detenida',
    title: stoppedReasonText,
    stepText: tasksTotal > 0 ? (tasksDone + '/' + tasksTotal) : '-'
  }
  : getCurrentTask(tasksDone, tasksTotal, resultReady);

const statusLabel = buildStatusLabel(
  resultReady,
  stale,
  staleMinutes,
  executionFailed,
  uiCompleted
);


const statusClass = resultReady
  ? 'status--ok'
  : (stale || executionFailed)
    ? 'status--warn'
    : 'status--run';

const liveLabel = stale ? 'Stale' : 'Live';
const liveClass = stale ? 'live--warn' : '';

const runtimeStatus = executionFailed
  ? (stale ? 'Codex sin actividad (' + staleMinutes + ' min)' : stoppedReasonText)
  : safeText(
    progressData?.runtime?.status,
    resultReady ? 'Resultado listo' : 'Actualizando progreso'
  );

const uiData = buildFallbackData(sessionId, projectPath, {
  progress: progress,
  tasksDone: tasksDone,
  tasksTotal: tasksTotal,
  tasksRemaining: tasksRemaining,
  batchIteration: batchNum,
  runtimeStatus: runtimeStatus,
  statusLabel: statusLabel,
  statusClass: statusClass,
  liveLabel: liveLabel,
  liveClass: liveClass,
  completed: completed,
  resultReady: resultReady,
  uiCompleted: uiCompleted,
  stale: stale,
  staleMinutes: staleMinutes,
  executionFailed: executionFailed,
  stoppedReason: stoppedReason,
  stoppedReasonText: stoppedReasonText,
  updatedAt: safeText(progressData?.updatedAt, ''),
  updatedAtDisplay: formatDate(progressData?.updatedAt),
  lastCheckpoint: safeText(progressData?.lastCheckpoint, '-'),
  modelInfo: modelInfo,
  reasoningInfo: reasoningInfo,
  modelChipIcon: modelVisual.icon,
  modelChipClass: modelVisual.className,
  reasoningChipIcon: reasoningVisual.icon,
  reasoningChipClass: reasoningVisual.className,
  currentTaskLabel: safeText(currentTask.label, 'Preparando'),
  currentTaskTitle: safeText(currentTask.title, 'Preparando ejecucion...'),
  currentTaskStepText: safeText(currentTask.stepText, '0/0'),
  phase1Icon: phase1.icon,
  phase1Label: phase1.label,
  phase1Class: phase1.className,
  phase2Icon: phase2.icon,
  phase2Label: phase2.label,
  phase2Class: phase2.className,
  phase3Icon: phase3.icon,
  phase3Label: phase3.label,
  phase3Class: phase3.className
});

const uiMsg = buildMessage(msg, sessionId, projectPath, sessionStatePath, uiData);
const loopMsg = buildMessage(msg, sessionId, projectPath, sessionStatePath, uiData);

node.warn(
  `[MONITOR POLL] cycle=${uiMsg.monitorCycle} sid=${sessionId.slice(0, 8)} ` +
  `progress=${progress}% tasks=${tasksDone}/${tasksTotal} batch=${batchNum} ` +
  `fileUpdated=${safeText(progressData?.updatedAt, '-')}`
);


node.status({
  fill: resultReady ? 'green' : executionFailed ? 'red' : stale ? 'yellow' : 'blue',
  shape: completed ? 'dot' : 'ring',
  text: executionFailed ? ('stop ' + progress + '%') : (progress + '%')
});

if (executionFailed) {
  return [null, loopMsg];
}

return [uiMsg, loopMsg];

