const fs = require('fs');
const path = require('path');
const env = global.get('env') || {};

const filesFolder = env.filesFolder || '/internal-storage-files/files';
const workspaceDir = path.join(filesFolder, 'codex-workspace');
const TAIL_BYTES = 48 * 1024;
const MAX_LINES = 100;

function num(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
}

function ts(v) {
  const t = Date.parse(v || '');
  return Number.isFinite(t) ? t : 0;
}

function esc(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function safeRead(filePath) {
  try {
    return fs.existsSync(filePath) ? fs.readFileSync(filePath, 'utf8') : '';
  } catch (_err) {
    return '';
  }
}

function safeJson(filePath) {
  try {
    const raw = safeRead(filePath).trim();
    return raw ? JSON.parse(raw) : {};
  } catch (_err) {
    return {};
  }
}

function formatSize(bytes) {
  const size = num(bytes);
  if (size < 1024) return size + ' B';
  if (size < 1024 * 1024) return (size / 1024).toFixed(1) + ' KB';
  return (size / (1024 * 1024)).toFixed(1) + ' MB';
}

function formatDate(ms) {
  if (!ms) return '-';
  try {
    return new Date(ms).toLocaleString('es-ES', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  } catch (_err) {
    return '-';
  }
}

function formatAge(ms) {
  if (!ms) return '-';
  const diff = Math.max(0, Date.now() - ms);
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'ahora';
  if (mins < 60) return mins + ' min';
  const hours = Math.floor(mins / 60);
  if (hours < 24) return hours + 'h ' + (mins % 60) + 'm';
  return Math.floor(hours / 24) + 'd';
}

function tailFile(filePath, bytes) {
  try {
    if (!filePath || !fs.existsSync(filePath)) return '';
    const stat = fs.statSync(filePath);
    const size = stat.size;
    if (size <= 0) return '';

    const start = Math.max(0, size - bytes);
    const length = size - start;
    const fd = fs.openSync(filePath, 'r');
    const buffer = Buffer.alloc(length);

    try {
      fs.readSync(fd, buffer, 0, length, start);
    } finally {
      fs.closeSync(fd);
    }

    let text = buffer.toString('utf8');
    if (start > 0) {
      const firstNl = text.indexOf('\n');
      if (firstNl >= 0) text = text.substring(firstNl + 1);
    }

    return text;
  } catch (_err) {
    return '';
  }
}

function getStatus(session) {
  if (session.stopped) return { label: 'Detenida', cls: 'stopped' };
  if (session.completed) return { label: 'Completada', cls: 'done' };
  if (session.hasLog) return { label: 'Con log', cls: 'run' };
  return { label: 'Sin log', cls: 'idle' };
}

function scanSessions() {
  const sessions = [];

  if (!fs.existsSync(workspaceDir)) return sessions;

  for (const dirName of fs.readdirSync(workspaceDir)) {
    const dirPath = path.join(workspaceDir, dirName);
    let dirStat;

    try {
      dirStat = fs.statSync(dirPath);
    } catch (_err) {
      continue;
    }

    if (!dirStat.isDirectory()) continue;

    let logName = '';
    let logPath = '';
    let logSize = 0;
    let logMtimeMs = 0;

    try {
      const logFiles = fs.readdirSync(dirPath)
        .filter(name => /^codex-unified-.*\.log$/i.test(name))
        .sort();

      if (logFiles.length > 0) {
        logName = logFiles[0];
        logPath = path.join(dirPath, logName);
        const stat = fs.statSync(logPath);
        logSize = stat.size;
        logMtimeMs = stat.mtimeMs;
      }
    } catch (_err) { }

    const state = safeJson(path.join(dirPath, 'codex-docs', 'SESSION_STATE.json'));
    const monitoring = state.monitoring || {};
    const selection = state.selection || {};
    const tasks = state.tasks || {};
    const execution = state.execution || {};
    const runtime = state.runtime || {};

    const updatedAtMs = Math.max(
      ts(state.updatedAt),
      ts(monitoring.timestamp),
      ts(state.createdAt),
      num(logMtimeMs)
    );

    const rawTail = logPath ? tailFile(logPath, TAIL_BYTES) : '';
    const tailLines = rawTail ? rawTail.split(/\r?\n/).slice(-MAX_LINES).join('\n') : '';

    sessions.push({
      sessionId: dirName,
      anchor: 'sess-' + dirName,
      hasLog: !!logPath,
      logName,
      logPath,
      logSize,
      updatedAtMs,
      model: selection.modelSelect || selection.model || monitoring.modelSelect || '-',
      reasoning: selection.reasoningLevel || selection.reasoning || monitoring.reasoningLevel || '-',
      statusText: runtime.status || monitoring.status || '',
      stopped: execution.stopped === true,
      completed: runtime.completed === true || state.resultReady === true || execution.finished === true,
      tasksDone: num(tasks.completed || monitoring.tasksCompleted),
      tasksTotal: num(tasks.total || monitoring.tasksTotal),
      batch: num(execution.batchIteration || tasks.batch),
      tailLines
    });
  }

  sessions.sort((a, b) => num(b.updatedAtMs) - num(a.updatedAtMs));
  return sessions;
}

const sessions = scanSessions();
const withLogs = sessions.filter(s => s.hasLog).length;

const listHtml = sessions.length
  ? sessions.map(session => {
    const status = getStatus(session);
    const taskText = session.tasksTotal > 0 ? (session.tasksDone + '/' + session.tasksTotal) : '-';

    return `<a href="#${esc(session.anchor)}" class="session-link" data-target="${esc(session.anchor)}">
        <div class="session-row-top">
          <div class="session-id">${esc(session.sessionId)}</div>
          <span class="session-badge ${esc(status.cls)}">${esc(status.label)}</span>
        </div>
        <div class="session-row-meta">${esc(taskText)} tareas · batch ${esc(String(session.batch || 0))}</div>
        <div class="session-row-sub">${esc(session.model)} · ${esc(session.reasoning)} · ${esc(formatAge(session.updatedAtMs))} · ${esc(formatSize(session.logSize))}</div>
      </a>`;
  }).join('')
  : '<div class="empty-box">No se encontraron sesiones en codex-workspace.</div>';

const logsHtml = sessions.length
  ? sessions.map(session => {
    const status = getStatus(session);
    const taskText = session.tasksTotal > 0 ? `${session.tasksDone}/${session.tasksTotal}` : '-';

    return `<section id="${esc(session.anchor)}" class="log-card">
        <div class="log-card-top">
          <div>
            <div class="log-title">${esc(session.sessionId)}</div>
            <div class="log-subtitle">${esc(session.logName || 'Sin codex-unified log')}</div>
          </div>
          <span class="status-pill ${esc(status.cls)}">${esc(status.label)}</span>
        </div>
        <div class="meta-row">
          <span class="meta-pill">Modelo ${esc(session.model)}</span>
          <span class="meta-pill">Reasoning ${esc(session.reasoning)}</span>
          <span class="meta-pill">Tareas ${esc(taskText)}</span>
          <span class="meta-pill">Batch ${esc(String(session.batch || 0))}</span>
          <span class="meta-pill">Tamano ${esc(formatSize(session.logSize))}</span>
          <span class="meta-pill">Actualizado ${esc(formatDate(session.updatedAtMs))}</span>
        </div>
        ${session.statusText ? `<div class="status-line">${esc(session.statusText)}</div>` : ''}
        ${session.hasLog
        ? `<pre class="log-box">${esc(session.tailLines || '(log vacio)')}</pre><div class="tail-note">Ultimas ${MAX_LINES} lineas.</div>`
        : `<div class="empty-box">No hay codex-unified log para esta sesion.</div>`}
      </section>`;
  }).join('')
  : '';

