const fs = require('fs');
const path = require('path');
const marked = require('marked@4.3.0');

function canonicalProjectPath(sessionId, fallback) {
    return sessionId
        ? path.join('/internal-storage-files/files', 'codex-workspace', sessionId)
        : (fallback || null);
}

function resolveSessionContext(msg) {
    const sessionId =
        msg.onInitSubmission?.sessionId ||
        msg.submission?.sessionId ||
        msg.req?.query?.sessionId ||
        msg.payload?.data?.sessionId ||
        msg.payload?.sessionId ||
        msg.sessionId;

    const incomingProjectPath =
        msg.onInitSubmission?.projectPath ||
        msg.submission?.projectPath ||
        msg.payload?.data?.projectPath ||
        msg.payload?.projectPath ||
        msg.projectPath ||
        null;

    const projectPath = canonicalProjectPath(sessionId, incomingProjectPath);
    const sessionStatePath = sessionId && projectPath
        ? path.join(projectPath, 'codex-docs', 'SESSION_STATE.json')
        : null;

    let state = null;
    try {
        if (sessionStatePath && fs.existsSync(sessionStatePath)) {
            const raw = fs.readFileSync(sessionStatePath, 'utf8').trim();
            state = raw ? JSON.parse(raw) : null;
        }
    } catch (err) {
        node.warn(`⚠️ No se pudo leer SESSION_STATE.json: ${err.message}`);
    }

    return { sessionId, projectPath, sessionStatePath, state };
}

function readFileContent(filePath) {
    try {
        if (fs.existsSync(filePath)) {
            return fs.readFileSync(filePath, 'utf-8');
        }
        return null;
    } catch (error) {
        return null;
    }
}

function markdownToStyledHtml(markdownContent) {
    if (!markdownContent) {
        return '<div style="padding:20px;text-align:center;color:#999;font-style:italic">No content available</div>';
    }

    const rawHtml = marked.parse(markdownContent);

    return `
<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;line-height:1.8;color:#333;background:#fafbfc;padding:25px;border-radius:12px;border:1px solid #e1e4e8;max-height:600px;overflow-y:auto">
<style>
