.md-content input[type="checkbox"]{margin-right:8px;transform:scale(1.2)}
</style>
<div class="md-content">${rawHtml}</div>
</div>`.trim();
}

function listFilesRecursive(dir, baseDir = dir, excludeDirs = []) {
    let fileList = [];
    try {
        const items = fs.readdirSync(dir);
        items.forEach(item => {
            const fullPath = path.join(dir, item);
            const stat = fs.statSync(fullPath);
            const relativePath = path.relative(baseDir, fullPath);

            if (stat.isDirectory()) {
                if (!excludeDirs.some(exclude => relativePath.startsWith(exclude))) {
                    fileList = fileList.concat(listFilesRecursive(fullPath, baseDir, excludeDirs));
                }
            } else {
                fileList.push(relativePath);
            }
        });
    } catch (error) {
        node.warn(`Error listing files: ${error.message}`);
    }
    return fileList;
}

const { sessionId, projectPath, sessionStatePath, state: progressData } = resolveSessionContext(msg);

if (!sessionId || !projectPath) {
    node.error('❌ No sessionId/projectPath encontrado');
    msg.payload = {
        data: {
            sessionId: '',
            projectPath: '',
            full_html: '<div style="text-align:center;padding:50px;color:red">ERROR: No project found</div>'
        }
    };
    return msg;
}

const resultReady =
    progressData?.resultReady === true ||
    progressData?.readyToRedirect === true ||
    !!progressData?.result ||
    progressData?.runtime?.completed === true ||
    !!progressData?.artifacts?.executionReport;

if (!progressData || !resultReady) {
    node.warn('⏳ Result aún no listo para project: ' + sessionId);
    msg.payload = {
        data: {
            sessionId,
            projectPath,
            full_html: '<div style="text-align:center;padding:50px;color:#1e6fd1">Preparando resultados finales...</div>'
        }
    };
    return msg;
}

const result = progressData.result || {
    success: progressData?.runtime?.success === true,
    elapsed_seconds: progressData?.execution?.totalElapsed || 0
};

const projectDocsDir = path.join(projectPath, 'codex-docs');

const planMd = readFileContent(path.join(projectDocsDir, 'PLAN.md'));
const cambiosMd = readFileContent(path.join(projectDocsDir, 'CAMBIOS.md'));
const resultadoMd = readFileContent(path.join(projectDocsDir, 'RESULTADO.md'));

const planHtml = markdownToStyledHtml(planMd);
const cambiosHtml = markdownToStyledHtml(cambiosMd);
const resultadoHtml = markdownToStyledHtml(resultadoMd);

let generatedFilesHtml = '<p style="color:#999;font-style:italic;text-align:center;padding:20px">No files found</p>';

if (fs.existsSync(projectPath)) {
    const files = listFilesRecursive(projectPath, projectPath, ['node_modules', '.git', 'codex-docs', '.codex']);

    if (files.length > 0) {
        const displayFiles = files.slice(0, 50);

        generatedFilesHtml = `
