    ${displayFiles.map(file => {
            const icon = file.endsWith('.java') ? '☕' :
                file.endsWith('.js') ? '🟨' :
                    file.endsWith('.py') ? '🐍' :
                        file.endsWith('.sql') ? '🗄️' :
                            file.endsWith('.md') ? '📄' :
                                file.endsWith('.xml') ? '📋' :
                                    file.endsWith('.json') ? '📋' :
                                        file.endsWith('.html') ? '🌐' :
                                            file.endsWith('.css') ? '🎨' : '📄';
            return `<div style="padding:8px 0;display:flex;align-items:center;gap:10px;border-bottom:1px solid #e1e4e8">
            <span style="font-size:20px">${icon}</span>
            <span style="color:#0366d6;font-weight:600;font-family:'SF Mono',Monaco,monospace;font-size:13px">${file}</span>
        </div>`;
        }).join('')}
    ${files.length > 50 ? `<div style="padding:15px;text-align:center;color:#666;font-style:italic">...y ${files.length - 50} archivos más</div>` : ''}
</div>`.trim();
    }
}

const elapsed = result.elapsed_seconds || 0;
const successText = result.success ? 'Success' : 'Completed with warnings';
const successColor = result.success ? '#10b981' : '#f59e0b';
const displayPath = projectPath.length > 60 ? '...' + projectPath.substring(projectPath.length - 57) : projectPath;

const originalPrompt =
    progressData?.prompt ||
    progressData?.context?.prompt ||
    'N/A';

const fullHtml = `
<style>
