const fs = require('fs');
const path = require('path');

function canonicalProjectPath(sessionId, fallback) {
    return sessionId
        ? path.join('/internal-storage-files/files', 'codex-workspace', sessionId)
        : (fallback || null);
}

function ensureDir(dir) {
    fs.mkdirSync(dir, { recursive: true });
}

function getUserKey(msg) {
    const sec = msg.__axetFlowsSecurityContext || {};
    const idp = sec.externalIdpUserInfo || {};
    return (
        msg.sessionUserKey ||
        msg.userKey ||
        msg.submission?.userKey ||
        msg.onInitSubmission?.userKey ||
        msg.payload?.data?.userKey ||
        msg.payload?.userKey ||
        idp.preferred_username ||
        idp.email ||
        idp.sub ||
        msg.req?.user?.email ||
        msg.req?.user?.id ||
        msg.userId ||
        'anonymous'
    );
}

function resolveSessionId(msg) {
    return (
        msg.sessionId ||
        msg.submission?.sessionId ||
        msg.onInitSubmission?.sessionId ||
        msg.payload?.sessionId ||
        null
    );
}

function resolveProjectPath(msg, sessionId) {
    const incomingProjectPath =
        msg.projectPath ||
        msg.submission?.projectPath ||
        msg.onInitSubmission?.projectPath ||
        null;
    return canonicalProjectPath(sessionId, incomingProjectPath);
}

function safeReadJson(filePath) {
    try {
        if (!fs.existsSync(filePath)) return null;
        const raw = fs.readFileSync(filePath, 'utf8').trim();
        return raw ? JSON.parse(raw) : null;
    } catch (err) {
        node.warn(`⚠️ Error leyendo ${filePath}: ${err.message}`);
        return null;
    }
}

function safeWriteJson(filePath, data) {
    const tmp = `${filePath}.tmp`;
    fs.writeFileSync(tmp, JSON.stringify(data, null, 2), 'utf8');
    fs.renameSync(tmp, filePath);
}

function isManualStopState(state) {
    return (
        state?.execution?.stopRequested === true ||
        state?.execution?.reason === 'manual-stop' ||
        state?.runtime?.manualStop === true
    );
}

const userKey = getUserKey(msg);
const sessionId = resolveSessionId(msg);
const projectPath = resolveProjectPath(msg, sessionId);
const isFailed = msg.submission?.executionFailed === true;

const storeDir = '/internal-storage-files/files/_active-sessions';
const filePath = path.join(storeDir, `${userKey}.json`);
const sessionStatePath = projectPath
    ? path.join(projectPath, 'codex-docs', 'SESSION_STATE.json')
    : null;

if (!sessionId) {
    node.warn(`⚠️ Finalize sin sessionId para ${userKey}`);
    return msg;
}

const currentActive = safeReadJson(filePath);
const sameActiveSession = currentActive?.sessionId === sessionId;
const sessionState = sessionStatePath ? safeReadJson(sessionStatePath) : null;

if (isManualStopState(sessionState)) {
    node.warn(`ℹ️ Finalize ignorado para ${userKey}: sesión en manual-stop`);
    return msg;
}

if (isFailed) {
    try {
        if (sameActiveSession && fs.existsSync(filePath)) {
            fs.unlinkSync(filePath);
            node.warn(`🗑️ Active session borrada para ${userKey} (executionFailed)`);
        } else {
            node.warn(`ℹ️ No se borra active session: ya no apunta a esta sesión`);
        }
    } catch (e) {
        node.warn(`⚠️ No se pudo borrar active session: ${e.message}`);
    }

    return msg;
}

if (currentActive?.sessionId && currentActive.sessionId !== sessionId) {
    node.warn(
        `ℹ️ Finalize ignorado para ${userKey}: active session actual apunta a ${currentActive.sessionId}`
    );
    return msg;
}

let current = currentActive || {};
current.userKey = userKey;
current.sessionId = sessionId;
current.projectPath = projectPath || current.projectPath || null;
current.status = 'completed';
current.updatedAt = new Date().toISOString();
current.source = 'finalize-monitor';

try {
    ensureDir(storeDir);
    safeWriteJson(filePath, current);
} catch (err) {
    node.warn(`⚠️ No se pudo finalizar active execution: ${err.message}`);
}

node.warn(`✅ Finalize: COMPLETED para ${userKey}`);
return msg;

