  msg.submission?.tasksDone ??
  msg.onInitSubmission?.tasksDone ??
  0;

const tasksTotal =
  msg.submission?.tasksTotal ??
  msg.onInitSubmission?.tasksTotal ??
  0;

const batches =
  msg.submission?.batchIteration ??
  msg.onInitSubmission?.batchIteration ??
  0;

const stale =
  msg.submission?.stale === true ||
  msg.onInitSubmission?.stale === true;

const staleMinutes =
  msg.submission?.staleMinutes ??
  msg.onInitSubmission?.staleMinutes ??
  0;

const stoppedReason =
  msg.submission?.stoppedReason ||
  msg.onInitSubmission?.stoppedReason ||
  '';

const stoppedReasonText =
  msg.submission?.stoppedReasonText ||
  msg.onInitSubmission?.stoppedReasonText ||
  '';

const runtimeStatus =
  msg.submission?.runtimeStatus ||
  msg.onInitSubmission?.runtimeStatus ||
  '';

function fallbackReasonText() {
  if (stoppedReason === 'stale-log') {
    return `El log de ejecucion no se ha actualizado en los ultimos ${staleMinutes} minuto${staleMinutes === 1 ? '' : 's'}. Codex probablemente se ha quedado detenido o ha perdido la sesion.`;
  }

  if (stoppedReason === 'no-progress') {
    return '3 batches seguidos sin progreso. Posible token expirado o error de conexion.';
  }

  if (stoppedReason === 'batch-limit') {
    return `Limite maximo de batches alcanzado (${batches}).`;
  }

  if (stoppedReason === 'active-session-missing') {
    return 'La sesion activa dejo de estar registrada antes de terminar. Es posible que se cancelara o fuera reemplazada.';
  }

  if (stoppedReason === 'active-session-replaced') {
    return 'Se detecto otra sesion activa para este usuario. El monitor ha cambiado a la nueva ejecucion.';
  }

  if (stoppedReason === 'manual-stop') {
    return 'La ejecucion se detuvo manualmente antes de terminar.';
  }

  if (stoppedReason === 'runtime-error') {
    return runtimeStatus || 'La ejecucion devolvio un error en tiempo de ejecucion.';
  }

  if (stoppedReason === 'execute-error') {
    return runtimeStatus || 'La fase de implementacion reporto un error. Revisa los logs de Codex.';
  }

  if (stoppedReason) {
    return 'La ejecucion se detuvo por: ' + stoppedReason;
  }

  if (stale) {
    return `El log de ejecucion no se ha actualizado en los ultimos ${staleMinutes} minuto${staleMinutes === 1 ? '' : 's'}.`;
  }

  return 'La ejecucion se detuvo antes de completarse.';
}

const reasonText = stoppedReasonText || fallbackReasonText();

const errorTitle = stale
  ? 'Ejecucion detenida por inactividad'
  : stoppedReason === 'active-session-missing'
    ? 'Sesion interrumpida'
    : stoppedReason === 'active-session-replaced'
      ? 'Sesion reemplazada'
      : 'Ejecucion detenida';

const summaryText = tasksTotal > 0
  ? `El proceso se detuvo con <strong>${tasksDone} de ${tasksTotal}</strong> tareas completadas en ${batches} batch${batches !== 1 ? 'es' : ''}.`
  : 'El proceso se detuvo antes de completar ninguna tarea.';

