const FILES_ROOT = '/internal-storage-files/files';
const indexPath = path.join(FILES_ROOT, 'opportunities_index.json');
const filtersPath = path.join(FILES_ROOT, 'opportunities_filters.json');
const TMP_DIR = path.join(FILES_ROOT, '_crud-upload-temp');

function nowIso() { return new Date().toISOString(); }
function normalizeText(v) { return String(v ?? '').normalize('NFC').replace(/[\u200B-\u200D\uFEFF]/g, '').replace(/\u00A0/g, ' ').trim(); }
function firstNonEmpty(...values) { for (const value of values) { const v = normalizeText(value); if (v) return v; } return ''; }
function readJsonSafe(filePath, fallback) {
