function choice(value, label) { const v = normalizeText(value); const l = normalizeText(label || value); return v && l ? { label: l, value: v } : null; }
function pushUnique(arr, item) { if (item && !arr.some(x => String(x.value) === String(item.value))) arr.push(item); }
function sortChoices(arr) { return (arr || []).sort((a, b) => String(a.label || '').localeCompare(String(b.label || ''), 'es')); }
function buildSelectorData() {
  const indexData = readJsonSafe(indexPath, { items: [] });
  const filtersData = readJsonSafe(filtersPath, { sectors: [] });
  const sectors = [], unitsBySector = {}, customersBySectorUnit = {}, opportunitiesByFilter = {}, opportunitiesById = {};

  for (const sectorEntry of (filtersData.sectors || [])) {
    const sectorName = normalizeText(sectorEntry.name);
    if (!sectorName) continue;
    pushUnique(sectors, choice(sectorName));
    if (!unitsBySector[sectorName]) unitsBySector[sectorName] = [];
    for (const unitEntry of (sectorEntry.units || [])) {
      const unitName = normalizeText(unitEntry.name);
      if (!unitName) continue;
      pushUnique(unitsBySector[sectorName], choice(unitName));
      const suKey = `${sectorName}||${unitName}`;
      if (!customersBySectorUnit[suKey]) customersBySectorUnit[suKey] = [];
      for (const customerRaw of (unitEntry.customers || [])) pushUnique(customersBySectorUnit[suKey], choice(customerRaw));
    }
  }

  for (const item of (indexData.items || [])) {
    const sector = normalizeText(item.sector);
    const unit = normalizeText(item.unit);
    const customer = normalizeText(item.customerName || item.customer);
    const opportunityId = normalizeText(item.opportunityId || item.id || item.salesforceOpportunityId || item.businessOpportunityId);
    const title = normalizeText(item.title || item.name || item.opportunityName || item.folderName || opportunityId);
    if (!opportunityId || !title) continue;
    opportunitiesById[opportunityId] = item;
    if (sector) pushUnique(sectors, choice(sector));
    if (sector && unit) { if (!unitsBySector[sector]) unitsBySector[sector] = []; pushUnique(unitsBySector[sector], choice(unit)); }
    if (sector && unit && customer) {
      const suKey = `${sector}||${unit}`;
      if (!customersBySectorUnit[suKey]) customersBySectorUnit[suKey] = [];
      pushUnique(customersBySectorUnit[suKey], choice(customer));
      const key = `${sector}||${unit}||${customer}`;
      if (!opportunitiesByFilter[key]) opportunitiesByFilter[key] = [];
      pushUnique(opportunitiesByFilter[key], { label: `${title} (${opportunityId})`, value: opportunityId });
    }
  }
  sortChoices(sectors);
  Object.keys(unitsBySector).forEach(k => sortChoices(unitsBySector[k]));
  Object.keys(customersBySectorUnit).forEach(k => sortChoices(customersBySectorUnit[k]));
  Object.keys(opportunitiesByFilter).forEach(k => sortChoices(opportunitiesByFilter[k]));
  return { sectores: sectors, unidadesPorSector: unitsBySector, clientesPorSectorUnidad: customersBySectorUnit, oportunidadesPorFiltro: opportunitiesByFilter, oportunidadesById: opportunitiesById };
}
