const fs = require('fs');
const path = require('path');

function num(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
}

function ts(v) {
    const t = Date.parse(v || '');
    return Number.isFinite(t) ? t : 0;
}

function pickBest() {
    const candidates = Array.from(arguments)
        .filter(Boolean)
        .map(t => ({
            raw: t,
            completed: num(t.completed),
            total: num(t.total),
            timestamp: ts(t.timestamp)
        }))
        .filter(x => x.total > 0);

    if (!candidates.length) return null;

    candidates.sort((x, y) =>
        (y.completed - x.completed) ||
        (y.total - x.total) ||
        (y.timestamp - x.timestamp)
    );

    return candidates[0].raw;
}

function canonicalProjectPath(sessionId, fallback) {
    return sessionId
        ? path.join('/internal-storage-files/files', 'codex-workspace', sessionId)
        : (fallback || null);
}

function resolveSessionContext(msg) {
    const sessionId =
        msg.sessionId ||
        msg.submission?.sessionId ||
        msg.onInitSubmission?.sessionId ||
        msg.payload?.data?.sessionId ||
        msg.payload?.sessionId;

    const incomingProjectPath =
        msg.projectPath ||
        msg.submission?.projectPath ||
        msg.onInitSubmission?.projectPath ||
        msg.payload?.data?.projectPath ||
        msg.payload?.projectPath ||
        null;

    const projectPath = canonicalProjectPath(sessionId, incomingProjectPath);
    return { sessionId, projectPath };
}

function loadSessionState(sessionId, projectPath) {
    const resolvedProjectPath = canonicalProjectPath(sessionId, projectPath);
    const sessionStatePath = path.join(resolvedProjectPath, 'codex-docs', 'SESSION_STATE.json');

    try {
        if (fs.existsSync(sessionStatePath)) {
            const raw = fs.readFileSync(sessionStatePath, 'utf8').trim();
            return {
                sessionStatePath,
                state: raw ? JSON.parse(raw) : {}
            };
        }
    } catch (err) {
        node.warn(`⚠️ Error leyendo SESSION_STATE.json: ${err.message}`);
    }

    return {
        sessionStatePath,
        state: {}
    };
}


function normalizeStopText(v) {
    return String(v || '').trim().toLowerCase();
}

function containsStopText(v) {
    const s = normalizeStopText(v);
    if (!s) return false;
    return (
        s === 'manual-stop' ||
        s === 'manual_stop' ||
        s === 'manual stop' ||
        s === 'cancelled' ||
        s === 'canceled' ||
        s === 'cancelada' ||
        s === 'cancelado' ||
        s === 'stopped' ||
        s === 'killed' ||
        s === 'aborted' ||
        s.includes('manual-stop') ||
        s.includes('manual stop') ||
        s.includes('manual_stop') ||
        s.includes('detenido manualmente') ||
        s.includes('detenida manualmente') ||
        s.includes('nueva ejecucion') ||
        s.includes('nueva ejecución') ||
        s.includes('cancel') ||
        s.includes('abort') ||
        s.includes('kill')
    );
}

function isStoppedState(state) {
    if (!state) return false;

    const flags = [
        state.frontStopRequested,
        state.cancelRequested,
        state.cancelled,
        state.canceled,
        state.killed,
        state.front?.stopRequested,
        state.front?.cancelRequested,
        state.execution?.stopRequested,
        state.execution?.cancelRequested,
        state.execution?.manualStop,
        state.execution?.killed,
        state.runtime?.manualStop,
        state.runtime?.stopRequested,
        state.runtime?.cancelRequested,
        state.runtime?.killed
    ];

    if (flags.some(v => v === true)) return true;

    const textFields = [
        state.status,
        state.reason,
        state.stopReason,
        state.stoppedReason,
        state.cancelReason,
        state.front?.status,
        state.front?.reason,
        state.execution?.status,
        state.execution?.reason,
        state.execution?.stopReason,
        state.execution?.stoppedReason,
        state.execution?.cancelReason,
        state.runtime?.status,
        state.runtime?.reason,
        state.runtime?.stopReason
    ];

    if (textFields.some(containsStopText)) return true;
    if (state.execution?.stopped === true && state.runtime?.success === false) return true;

    return false;
}

function isTerminalState(state, projectPath) {
    if (!state) return false;
    if (
        state.resultReady === true ||
        state.readyToRedirect === true ||
        !!state.result ||
        state.runtime?.completed === true ||
        state.execution?.finished === true ||
        !!state.artifacts?.executionReport
    ) {
        return true;
    }

    if (projectPath) {
        const out1 = path.join(projectPath, 'codex-docs', 'output', 'respuestas.json');
        const out2 = path.join(projectPath, 'codex-docs', 'EXECUTION_REPORT.md');
        if (fs.existsSync(out1) || fs.existsSync(out2)) return true;
    }

    return false;
}

function getUserKey(msg) {
    const sec = msg.__axetFlowsSecurityContext || {};
    const idp = sec.externalIdpUserInfo || {};
    const value =
        msg.sessionUserKey ||
        msg.userKey ||
        msg.submission?.userKey ||
        msg.onInitSubmission?.userKey ||
        msg.payload?.data?.userKey ||
        msg.payload?.userKey ||
        idp.preferred_username ||
        idp.email ||
        idp.sub ||
        msg.req?.user?.email ||
        msg.req?.user?.id ||
        msg.userId ||
        '';
    return String(value || '').trim();
}

function getActiveSessionPath(userKey) {
    if (!userKey) return null;
    return path.join('/internal-storage-files/files/_active-sessions', userKey + '.json');
}

function loadJson(filePath) {
    try {
        if (!filePath || !fs.existsSync(filePath)) return null;
        const raw = fs.readFileSync(filePath, 'utf8').trim();
        return raw ? JSON.parse(raw) : null;
    } catch (_err) {
        return null;
    }
}

function markStopped(userKey, sessionId, reason) {
    const marker = {
        stopped: true,
        reason: reason || 'manual-stop',
        sessionId,
        userKey: userKey || '',
        updatedAt: new Date().toISOString()
    };
    try {
        flow.set('__front_stop:' + sessionId, marker);
        if (userKey) flow.set('__front_stop:' + userKey + ':' + sessionId, marker);
        flow.set('lastSeenCompleted:' + sessionId, undefined);
    } catch (_err) { }
}

function readPlanCounts(projectPath, batch) {
    if (!projectPath) return null;

    const planPath = path.join(projectPath, 'codex-docs', 'PLAN.md');
    if (!fs.existsSync(planPath)) return null;

    const txt = fs.readFileSync(planPath, 'utf8');
    const pending = (txt.match(/^\s*(?:[-*]\s*)?\[\s*\]\s+/gim) || []).length;
    const done = (txt.match(/^\s*(?:[-*]\s*)?\[[xX]\]\s+/gim) || []).length;
    const total = pending + done;

    if (total <= 0) return null;

    return {
        completed: done,
        total,
        remaining: pending,
        batch: num(batch),
        timestamp: new Date().toISOString(),
        live: true,
        source: 'plan'
    };
}

function mirrorStateIntoMsg(msg, sessionId, projectPath, progress, tasksNow, resultReady) {
    const tasksDoneNow = num(tasksNow?.completed);
    const tasksTotal = num(tasksNow?.total);
    const tasksRemaining = Math.max(0, tasksTotal - tasksDoneNow);
    const allTasksComplete = tasksTotal > 0 && tasksDoneNow >= tasksTotal;

    const runtimeProgress = num(progress?.runtime?.progress);
    const taskProgress = tasksTotal > 0
        ? Math.round((tasksDoneNow / tasksTotal) * 100)
        : 0;

    const liveProgress = allTasksComplete
        ? 100
        : Math.max(runtimeProgress, taskProgress);

    const completed = allTasksComplete && resultReady;
    const success = completed && (
        progress?.runtime?.success === true ||
        progress?.success === true ||
        progress?.result?.success === true
    );

    const submission = {
        ...(msg.submission || {}),
        sessionId,
        projectPath,
        progress: liveProgress,
        completed,
        resultReady,
        success,
        uiCompleted: allTasksComplete,
        tasksDone: tasksDoneNow,
        tasksTotal,
        tasksRemaining,
        runtimeStatus: progress?.runtime?.status || '',
        batchIteration:
            progress?.execution?.batchIteration ||
            num(tasksNow?.batch),
        lastCheckpoint: progress?.lastCheckpoint || '',
        updatedAt: progress?.updatedAt || '',
        stale: progress?.runtime?.stale === true,
        staleMinutes: num(progress?.runtime?.staleMinutes),
        refreshNonce: Date.now(),
        refreshTs: new Date().toISOString()
    };

    msg.sessionId = sessionId;
    msg.projectPath = projectPath;
    msg.submission = submission;
    msg.onInitSubmission = {
        ...(msg.onInitSubmission || {}),
        ...submission
    };
    msg.payload = msg.payload || {};
    msg.payload.sessionId = sessionId;
    msg.payload.projectPath = projectPath;
    msg.payload.data = { ...submission };

    return {
        tasksDoneNow,
        tasksTotal,
        allTasksComplete
    };
}

const { sessionId, projectPath } = resolveSessionContext(msg);

if (!sessionId) {
    node.error('❌ No sessionId');
    return [null, msg];
}

const { sessionStatePath, state: progress } = loadSessionState(sessionId, projectPath);

const userKey = getUserKey(msg);
const activePath = getActiveSessionPath(userKey);
const active = loadJson(activePath);
const terminal = isTerminalState(progress, projectPath);
const flowStop =
    (userKey ? flow.get('__front_stop:' + userKey + ':' + sessionId) : null) ||
    flow.get('__front_stop:' + sessionId);

if (flowStop?.stopped === true || isStoppedState(progress)) {
    markStopped(userKey, sessionId, flowStop?.reason || 'SESSION_STATE');
    node.warn('🛑 Bucle de refresco cortado antes de redirigir | sid=' + sessionId.slice(0, 8));
    node.status({ fill: 'grey', shape: 'ring', text: 'manual stop' });
    return [null, null];
}

if (userKey && !terminal) {
    if (!active) {
        markStopped(userKey, sessionId, 'active-session-missing');
        node.warn('🛑 Bucle de refresco cortado: active session eliminada | sid=' + sessionId.slice(0, 8));
        node.status({ fill: 'grey', shape: 'ring', text: 'active missing' });
        return [null, null];
    }

    if (active.sessionId && active.sessionId !== sessionId) {
        markStopped(userKey, sessionId, 'active-session-replaced');
        node.warn('🛑 Bucle de refresco cortado: active session reemplazada | sid=' + sessionId.slice(0, 8));
        node.status({ fill: 'grey', shape: 'ring', text: 'active replaced' });
        return [null, null];
    }

    if (isStoppedState(active)) {
        markStopped(userKey, sessionId, 'active-session-stopped');
        node.warn('🛑 Bucle de refresco cortado por active session | sid=' + sessionId.slice(0, 8));
        node.status({ fill: 'grey', shape: 'ring', text: 'active stopped' });
        return [null, null];
    }
}

let tasksNow = pickBest(progress.tasksLive, progress.tasks);
const planCounts = readPlanCounts(projectPath, progress?.execution?.batchIteration);

if (planCounts) {
    tasksNow = pickBest(tasksNow, planCounts) || planCounts;
}

let resultReady =
    progress.resultReady === true ||
    progress.readyToRedirect === true ||
    !!progress.result ||
    progress.runtime?.completed === true ||
    !!progress.artifacts?.executionReport;

if (!resultReady && projectPath) {
    const out1 = path.join(projectPath, 'codex-docs', 'output', 'respuestas.json');
    const out2 = path.join(projectPath, 'codex-docs', 'EXECUTION_REPORT.md');
    if (fs.existsSync(out1) || fs.existsSync(out2)) {
        resultReady = true;
    }
}

const visual = mirrorStateIntoMsg(
    msg,
    sessionId,
    projectPath,
    progress,
    tasksNow,
    resultReady
);

if (!tasksNow) {
    node.warn(`⚠️ Sin tasks en SESSION_STATE ni PLAN | ${sessionStatePath}`);
    node.status({ fill: 'yellow', shape: 'ring', text: `runtime ${msg.submission.progress || 0}%` });
    return [null, msg];
}

if (visual.allTasksComplete && resultReady) {
    msg.submission.completed = true;
    msg.submission.progress = 100;
    msg.submission.resultReady = true;
    msg.onInitSubmission.completed = true;
    msg.onInitSubmission.progress = 100;
    msg.onInitSubmission.resultReady = true;
    msg.payload.data = { ...msg.submission };

    node.status({ fill: 'green', shape: 'dot', text: '100%' });
    return [null, msg];
}

const seenKey = `lastSeenCompleted:${sessionId}`;
const lastCount = num(flow.get(seenKey) || 0);

if (visual.tasksDoneNow > lastCount) {
    flow.set(seenKey, visual.tasksDoneNow);

    msg.newTasksData = {
        tasksDoneNow: visual.tasksDoneNow,
        tasksJustCompleted: visual.tasksDoneNow - lastCount,
        tasksTotal: visual.tasksTotal,
        batch: tasksNow?.batch || progress?.execution?.batchIteration || 0,
        timestamp: tasksNow?.timestamp || progress?.updatedAt || new Date().toISOString(),
        sessionId
    };

    node.status({ fill: 'green', shape: 'dot', text: `+${visual.tasksDoneNow - lastCount}` });
    return [msg, null];
}

node.status({ fill: 'blue', shape: 'ring', text: `${visual.tasksDoneNow}/${visual.tasksTotal}` });
return [null, msg];

