const fs = require('fs');
const path = require('path');

const WORKSPACE_DIR = '/internal-storage-files/files/codex-workspace';
const ACTIVE_SESSIONS_DIR = '/internal-storage-files/files/_active-sessions';

function safeText(v, fallback = '') {
    if (v === null || v === undefined) return fallback;
    const s = String(v).trim();
    return s ? s : fallback;
}

function norm(v) {
    return safeText(v, '').toLowerCase();
}

function containsStopText(v) {
    const s = norm(v);
    if (!s) return false;

    return (
        s === 'manual-stop' ||
        s === 'manual_stop' ||
        s === 'manual stop' ||
        s === 'cancelled' ||
        s === 'canceled' ||
        s === 'cancelada' ||
        s === 'cancelado' ||
        s === 'stopped' ||
        s === 'stopped-manually' ||
        s === 'killed' ||
        s === 'aborted' ||
        s.includes('manual-stop') ||
        s.includes('manual stop') ||
        s.includes('manual_stop') ||
        s.includes('detenido manualmente') ||
        s.includes('detenida manualmente') ||
        s.includes('nueva ejecucion') ||
        s.includes('nueva ejecución') ||
        s.includes('cancel') ||
        s.includes('abort') ||
        s.includes('kill')
    );
}

function canonicalProjectPath(sessionId, fallback) {
    return sessionId
        ? path.join(WORKSPACE_DIR, sessionId)
        : (fallback || '');
}

function getUserKey(msg) {
    const sec = msg.__axetFlowsSecurityContext || {};
    const idp = sec.externalIdpUserInfo || {};

    const value =
        msg.sessionUserKey ||
        msg.userKey ||
        msg.submission?.userKey ||
        msg.onInitSubmission?.userKey ||
        msg.payload?.data?.userKey ||
        msg.payload?.userKey ||
        idp.preferred_username ||
        idp.email ||
        idp.sub ||
        msg.req?.user?.email ||
        msg.req?.user?.id ||
        msg.userId ||
        '';

    return safeText(value, '');
}

function resolveRefreshContext(msg) {
    const sessionId = safeText(
        msg.sessionId ||
        msg.submission?.sessionId ||
        msg.onInitSubmission?.sessionId ||
        msg.payload?.data?.sessionId ||
        msg.payload?.sessionId ||
        '',
        ''
    );

    const incomingProjectPath =
        msg.projectPath ||
        msg.submission?.projectPath ||
        msg.onInitSubmission?.projectPath ||
        msg.payload?.data?.projectPath ||
        msg.payload?.projectPath ||
        '';

    const projectPath = canonicalProjectPath(sessionId, incomingProjectPath);

    return { sessionId, projectPath };
}

function loadJson(filePath) {
    try {
        if (!filePath || !fs.existsSync(filePath)) return null;
        const raw = fs.readFileSync(filePath, 'utf8').trim();
        return raw ? JSON.parse(raw) : null;
    } catch (err) {
        node.warn('[progress-refresh] no se pudo leer ' + filePath + ': ' + err.message);
        return null;
    }
}

function getActiveSessionPath(userKey) {
    if (!userKey) return null;
    return path.join(ACTIVE_SESSIONS_DIR, userKey + '.json');
}

function readActiveSession(userKey) {
    const activePath = getActiveSessionPath(userKey);
    const active = activePath ? loadJson(activePath) : null;
    return { activePath, active };
}

function isTerminalState(state, projectPath) {
    if (!state) return false;

    if (
        state.resultReady === true ||
        state.readyToRedirect === true ||
        !!state.result ||
        state.runtime?.completed === true ||
        state.execution?.finished === true ||
        !!state.artifacts?.executionReport
    ) {
        return true;
    }

    if (projectPath) {
        const outJson = path.join(projectPath, 'codex-docs', 'output', 'respuestas.json');
        const reportMd = path.join(projectPath, 'codex-docs', 'EXECUTION_REPORT.md');
        if (fs.existsSync(outJson) || fs.existsSync(reportMd)) return true;
    }

    return false;
}

function isCancelledState(state) {
    if (!state) return false;

    const explicitFlags = [
        state.frontStopRequested,
        state.cancelRequested,
        state.cancelled,
        state.canceled,
        state.killed,
        state.front?.stopRequested,
        state.front?.cancelRequested,
        state.execution?.stopRequested,
        state.execution?.cancelRequested,
        state.execution?.manualStop,
        state.execution?.killed,
        state.runtime?.manualStop,
        state.runtime?.stopRequested,
        state.runtime?.cancelRequested,
        state.runtime?.killed
    ];

    if (explicitFlags.some(v => v === true)) return true;

    const textFields = [
        state.status,
        state.reason,
        state.stopReason,
        state.stoppedReason,
        state.cancelReason,
        state.front?.status,
        state.front?.reason,
        state.execution?.status,
        state.execution?.reason,
        state.execution?.stopReason,
        state.execution?.stoppedReason,
        state.execution?.cancelReason,
        state.runtime?.status,
        state.runtime?.reason,
        state.runtime?.stopReason
    ];

    if (textFields.some(containsStopText)) return true;

    // Fallback para estados escritos como { execution: { stopped: true }, runtime: { success: false } }
    // sin razon textual. Esto es lo que evita que un Wait 15s pendiente reactive el front.
    if (state.execution?.stopped === true && state.runtime?.success === false) return true;

    return false;
}

function getFlowStop(userKey, sessionId) {
    if (!sessionId) return null;

    return (
        (userKey ? flow.get('__front_stop:' + userKey + ':' + sessionId) : null) ||
        flow.get('__front_stop:' + sessionId) ||
        null
    );
}

function markStopped(userKey, sessionId, reason) {
    const marker = {
        stopped: true,
        reason: reason || 'manual-stop',
        sessionId,
        userKey: userKey || '',
        updatedAt: new Date().toISOString()
    };

    try {
        flow.set('__front_stop:' + sessionId, marker);
        if (userKey) flow.set('__front_stop:' + userKey + ':' + sessionId, marker);
        flow.set('lastSeenCompleted:' + sessionId, undefined);
        if (userKey) flow.set('__loop_watch:' + userKey + ':' + sessionId, undefined);
        flow.set('__loop_watch:' + sessionId, undefined);
    } catch (_err) { }
}

function stopRefresh(userKey, sessionId, reason) {
    markStopped(userKey, sessionId, reason);
    node.warn(
        '[progress-refresh] loop cortado por ' + reason + ' ' +
        'sid=' + sessionId.substring(0, 8) + ' user=' + (userKey || '-')
    );
    node.status({ fill: 'grey', shape: 'ring', text: 'stop ' + reason });
    return null;
}

const userKey = getUserKey(msg);
const { sessionId, projectPath } = resolveRefreshContext(msg);
const now = Date.now();

if (!sessionId) {
    node.warn('[progress-refresh] sin sessionId; loop cortado');
    return null;
}

const sessionStatePath = path.join(projectPath, 'codex-docs', 'SESSION_STATE.json');
const state = loadJson(sessionStatePath);

const flowStop = getFlowStop(userKey, sessionId);
if (flowStop?.stopped === true) {
    return stopRefresh(userKey, sessionId, 'flow_stop');
}

if (isCancelledState(state)) {
    return stopRefresh(userKey, sessionId, 'SESSION_STATE');
}

const activeInfo = readActiveSession(userKey);
const terminal = isTerminalState(state, projectPath);

if (userKey && !terminal) {
    if (!activeInfo.active) {
        return stopRefresh(userKey, sessionId, 'active-session-missing');
    }

    if (activeInfo.active?.sessionId && activeInfo.active.sessionId !== sessionId) {
        return stopRefresh(userKey, sessionId, 'active-session-replaced');
    }

    if (isCancelledState(activeInfo.active)) {
        return stopRefresh(userKey, sessionId, 'active-session-stopped');
    }
}

const formData = {
    ...(msg.submission || {}),
    sessionId,
    projectPath,
    sessionStatePath,
    userKey,
    refreshNonce: now,
    refreshTs: new Date(now).toISOString()
};

msg.sessionId = sessionId;
msg.projectPath = projectPath;
msg.sessionStatePath = sessionStatePath;
msg.userKey = userKey;

msg.submission = formData;
msg.onInitSubmission = {
    ...(msg.onInitSubmission || {}),
    ...formData
};

msg.payload = msg.payload || {};
msg.payload.sessionId = sessionId;
msg.payload.projectPath = projectPath;
msg.payload.sessionStatePath = sessionStatePath;
msg.payload.userKey = userKey;
msg.payload.data = { ...formData };

const loopKey = userKey
    ? '__loop_watch:' + userKey + ':' + sessionId
    : '__loop_watch:' + sessionId;

const prevLoop = flow.get(loopKey) || {};
const loopSeq = Number(prevLoop.loopSeq || 0) + 1;

flow.set(loopKey, {
    loopSeq,
    lastUpdateTs: now,
    sessionId,
    projectPath,
    userKey,
    completed: formData.completed === true,
    resultReady: formData.resultReady === true,
    progress: Number(formData.progress || 0),
    updatedAt: new Date(now).toISOString()
});

node.warn(
    '[progress-refresh] sid=' + sessionId.substring(0, 8) + ' user=' + (userKey || '-') + ' ' +
    'progress=' + (formData.progress ?? '-') + ' completed=' + (formData.completed ?? false) + ' ' +
    'resultReady=' + (formData.resultReady ?? false) + ' loopSeq=' + loopSeq
);

return msg;

