const fs = require('fs');
const path = require('path');

const FILES_ROOT = '/internal-storage-files/files';
const indexPath = path.join(FILES_ROOT, 'opportunities_index.json');
const filtersPath = path.join(FILES_ROOT, 'opportunities_filters.json');
const statusPath = path.join(FILES_ROOT, 'opportunities_index_status.json');

function readJsonSafe(filePath, fallback) {
    try {
        if (!fs.existsSync(filePath)) return fallback;
        const raw = fs.readFileSync(filePath, 'utf8').trim();
        return raw ? JSON.parse(raw) : fallback;
    } catch (err) {
        node.warn(`No se pudo leer ${filePath}: ${err.message}`);
        return fallback;
    }
}

function asChoice(value) {
    const v = String(value || '').trim();
    if (!v) return null;
    return { label: v, value: v };
}

function pushUnique(arr, item) {
    if (!item) return;
    if (!arr.some(x => String(x.value) === String(item.value))) arr.push(item);
}

function sortChoices(arr) {
    return (arr || []).sort((a, b) => String(a.label || '').localeCompare(String(b.label || ''), 'es'));
}

function indexStatusText(indexData, filtersData) {
    const items = Array.isArray(indexData.items) ? indexData.items : [];
    const sectors = Array.isArray(filtersData.sectors) ? filtersData.sectors : [];
    let updatedAt = indexData.updatedAt || indexData.generatedAt || '';
    try {
        if (fs.existsSync(statusPath)) {
            const status = JSON.parse(fs.readFileSync(statusPath, 'utf8'));
            updatedAt = status.updatedAt || updatedAt;
        }
    } catch (_) {}

    return [
        `Índice: ${items.length} oportunidades`,
        `Sectores en filtros: ${sectors.length}`,
        `Actualizado: ${updatedAt || 'n/a'}`,
        `Ruta índice: ${indexPath}`,
        `Ruta filtros: ${filtersPath}`
    ].join('\n');
}

const indexData = readJsonSafe(indexPath, { items: [] });
const filtersData = readJsonSafe(filtersPath, { sectors: [] });

const sectors = [];
const unitsBySector = {};
const customersBySectorUnit = {};
const opportunitiesByFilter = {};
const opportunitiesById = {};

// Igual que en el formulario de ejecución: primero usa opportunities_filters.json
for (const sectorEntry of (filtersData.sectors || [])) {
    const sectorName = String(sectorEntry.name || '').trim();
    if (!sectorName) continue;

    pushUnique(sectors, asChoice(sectorName));
    if (!unitsBySector[sectorName]) unitsBySector[sectorName] = [];

    for (const unitEntry of (sectorEntry.units || [])) {
        const unitName = String(unitEntry.name || '').trim();
        if (!unitName) continue;

        pushUnique(unitsBySector[sectorName], asChoice(unitName));

        const sectorUnitKey = `${sectorName}||${unitName}`;
        if (!customersBySectorUnit[sectorUnitKey]) customersBySectorUnit[sectorUnitKey] = [];

        for (const customerNameRaw of (unitEntry.customers || [])) {
            const customerName = String(customerNameRaw || '').trim();
            if (!customerName) continue;
            pushUnique(customersBySectorUnit[sectorUnitKey], asChoice(customerName));
        }
    }
}

// Luego cruza con opportunities_index.json para construir oportunidad por filtro e índice por id
for (const item of (indexData.items || [])) {
    const sector = String(item.sector || '').trim();
    const unit = String(item.unit || '').trim();
    const customer = String(item.customerName || item.customer || '').trim();
    const opportunityId = String(item.opportunityId || item.id || item.salesforceOpportunityId || item.businessOpportunityId || '').trim();
    const title = String(item.title || item.name || item.opportunityName || item.folderName || opportunityId).trim();

    if (!opportunityId || !title) continue;

    opportunitiesById[opportunityId] = item;

    if (sector) pushUnique(sectors, asChoice(sector));
    if (sector && unit) {
        if (!unitsBySector[sector]) unitsBySector[sector] = [];
        pushUnique(unitsBySector[sector], asChoice(unit));
    }
    if (sector && unit && customer) {
        const sectorUnitKey = `${sector}||${unit}`;
        if (!customersBySectorUnit[sectorUnitKey]) customersBySectorUnit[sectorUnitKey] = [];
        pushUnique(customersBySectorUnit[sectorUnitKey], asChoice(customer));

        const key = `${sector}||${unit}||${customer}`;
        if (!opportunitiesByFilter[key]) opportunitiesByFilter[key] = [];
        pushUnique(opportunitiesByFilter[key], {
            label: `${title} (${opportunityId})`,
            value: opportunityId
        });
    }
}

sortChoices(sectors);
Object.keys(unitsBySector).forEach(key => sortChoices(unitsBySector[key]));
Object.keys(customersBySectorUnit).forEach(key => sortChoices(customersBySectorUnit[key]));
Object.keys(opportunitiesByFilter).forEach(key => sortChoices(opportunitiesByFilter[key]));

msg.payload = msg.payload || {};
msg.payload.data = msg.payload.data || {};

msg.payload.data.sectores = sectors;
msg.payload.data.unidadesPorSector = unitsBySector;
msg.payload.data.clientesPorSectorUnidad = customersBySectorUnit;
msg.payload.data.oportunidadesPorFiltro = opportunitiesByFilter;
msg.payload.data.oportunidadesById = opportunitiesById;

// Exponer también a nivel raíz, igual que en el formulario de ejecución
msg.payload.sectores = sectors;
msg.payload.unidadesPorSector = unitsBySector;
msg.payload.clientesPorSectorUnidad = customersBySectorUnit;
msg.payload.oportunidadesPorFiltro = opportunitiesByFilter;
msg.payload.oportunidadesById = opportunitiesById;

msg.payload.data.crudAction = msg.payload.data.crudAction || 'upload';
msg.payload.crudAction = msg.payload.data.crudAction;
msg.payload.data.crudStatus = msg.payload.data.crudStatus || 'Selecciona acción y oportunidad. Para comprobar, el flujo consultará SharePoint en vivo; para subir, adjunta documento(s).';
msg.payload.data.opportunityInfoTexto = msg.payload.data.opportunityInfoTexto || 'La información de la oportunidad seleccionada aparecerá tras ejecutar la acción.';
msg.payload.data.sharePointCheckTexto = msg.payload.data.sharePointCheckTexto || 'Selecciona una oportunidad y usa la acción de comprobación para ver si existen PDF y CSV en SharePoint.';
msg.payload.data.indexStatusResumen = msg.payload.data.indexStatusResumen || indexStatusText(indexData, filtersData);
msg.payload.crudStatus = msg.payload.data.crudStatus;
msg.payload.opportunityInfoTexto = msg.payload.data.opportunityInfoTexto;
msg.payload.sharePointCheckTexto = msg.payload.data.sharePointCheckTexto;
msg.payload.indexStatusResumen = msg.payload.data.indexStatusResumen;


// Marca de carga: el form muestra los selectores solo cuando el onInit ya ha refrescado datos.
const selectorsLoadedAt = new Date().toISOString();
msg.payload.data.opportunitySelectorsReady = true;
msg.payload.data.opportunitySelectorsLoadedAt = selectorsLoadedAt;
msg.payload.data.viewRefresh = Date.now();
msg.payload.opportunitySelectorsReady = true;
msg.payload.opportunitySelectorsLoadedAt = selectorsLoadedAt;
msg.payload.viewRefresh = msg.payload.data.viewRefresh;

// Update no destructivo: no enviar campos editables para no pisar selecciones hechas por el usuario
// entre el primer render del form y el refresh tardio del onInit.
for (const editableKey of [
    'sector',
    'unidadOportunidad',
    'cliente',
    'opportunityId',
    'uploadFile',
    'uploadSubmit'
]) {
    delete msg.payload.data[editableKey];
    delete msg.payload[editableKey];
}

node.warn(`Upload/check init selectors: sectores=${sectors.length}, oportunidades=${Object.keys(opportunitiesById).length}, filtros=${(filtersData.sectors || []).length}`);
return msg;

