const JSZipMod = require('jszip');

function resolveJSZip(mod) {
  return mod?.default || mod?.JSZip || mod;
}
const JSZip = resolveJSZip(JSZipMod);

async function readFileSafe(p) {
  return fs.promises.readFile(p);
}

async function generateZipBuffer(zip) {
  if (typeof zip.generateAsync === 'function') {
    return zip.generateAsync({ type: 'nodebuffer' }); // v3
  }

  if (typeof zip.generate === 'function') {
    const out = zip.generate({ type: 'nodebuffer' }); // v2
    if (Buffer.isBuffer(out)) return out;
    return Buffer.from(out, 'binary');
  }

  throw new Error('JSZip incompatible: no generate/generateAsync');
}

