} else if (templates.length && !templates.includes(selectedTemplate)) {
    selectedTemplate = templates[0] || '';
}

const templateOptions = templates.map(name => ({ label: name, value: name }));

msg.sessionId = sessionId;
msg.projectPath = projectPath;

msg.submission.sessionId = sessionId;
msg.submission.projectPath = projectPath;
msg.submission.data.pptxTemplates = templateOptions;
msg.submission.pptxTemplates = templateOptions;
msg.submission.data.plantillas = templateOptions;
msg.submission.plantillas = templateOptions;
msg.submission.data.template = selectedTemplate;
msg.submission.data.plantilla = selectedTemplate;
msg.submission.plantilla = selectedTemplate;
msg.plantilla = selectedTemplate;

msg.onInitSubmission.sessionId = sessionId;
msg.onInitSubmission.projectPath = projectPath;
msg.onInitSubmission.data.template = selectedTemplate;
