function documentXml(paragraphs) {
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:wpc="http://schemas.microsoft.com/office/word/2010/wordprocessingCanvas" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:wp14="http://schemas.microsoft.com/office/word/2010/wordprocessingDrawing" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:w10="urn:schemas-microsoft-com:office:word" xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:w14="http://schemas.microsoft.com/office/word/2010/wordml" xmlns:wpg="http://schemas.microsoft.com/office/word/2010/wordprocessingGroup" xmlns:wpi="http://schemas.microsoft.com/office/word/2010/wordprocessingInk" xmlns:wne="http://schemas.microsoft.com/office/word/2006/wordml" xmlns:wps="http://schemas.microsoft.com/office/word/2010/wordprocessingShape" mc:Ignorable="w14 wp14">
  <w:body>
    ${paragraphs.join("\n")}
    <w:sectPr>
      <w:pgSz w:w="11906" w:h="16838"/>
      <w:pgMar w:top="900" w:right="900" w:bottom="900" w:left="900" w:header="708" w:footer="708" w:gutter="0"/>
      <w:cols w:space="708"/>
      <w:docGrid w:linePitch="360"/>
    </w:sectPr>
  </w:body>
</w:document>`;
}

async function run() {
  const data = msg.payload && msg.payload.data ? msg.payload.data : {};

  let filename = path.posix.basename(
    String((msg.payload && msg.payload.filename) || "Referencias.docx")
  );

  if (!filename.toLowerCase().endsWith(".docx")) {
    filename = filename.replace(/\.[^.]+$/, "");
    filename = `${filename || "Referencias"}.docx`;
  }

  const title = normalizeText((msg.payload && msg.payload.title) || "Referencias");

  const generatedAt = new Intl.DateTimeFormat("es-ES", {
    timeZone: "Europe/Madrid",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false
  }).format(new Date());

  const paragraphs = [];

  paragraphs.push(
    paragraphXml(title, {
      bold: true,
      color: "0B2F55",
      size: 38,
      spacingAfter: 220
    })
  );

  paragraphs.push(
    paragraphXml(`Generado: ${generatedAt}`, {
      italic: true,
      color: "5B677A",
      size: 20,
      spacingAfter: 180
    })
  );

  let renderedAny = false;

  if (isLotesFormat(data)) {
    const generalItems = mapDataObjectToItems(data.general);

    if (generalItems.length) {
      addSectionTitle(paragraphs, "General", true);
      addItemsSection(paragraphs, generalItems);
      renderedAny = true;
    }

    (Array.isArray(data.lotes) ? data.lotes : []).forEach((lote, index) => {
      if (!lote || typeof lote !== "object") {
        return;
      }

      if (!lote.campos || typeof lote.campos !== "object" || Array.isArray(lote.campos)) {
        return;
      }

      const lotItems = mapDataObjectToItems(lote.campos);

      if (!lotItems.length) {
        return;
      }

      addSectionTitle(paragraphs, normalizeText(lote.lote || `Lote ${index + 1}`));
      addItemsSection(paragraphs, lotItems);
      renderedAny = true;
    });
  } else {
    let items = [];

    if (Array.isArray(data.items) && data.items.length) {
      items = mapArrayToItems(data.items);
    } else if (data && typeof data === "object" && !Array.isArray(data)) {
      items = mapDataObjectToItems(data);
    }

    if (!items.length) {
      throw new Error("No hay items para generar DOCX");
    }

    addItemsSection(paragraphs, items);
    renderedAny = true;
  }

  if (!renderedAny) {
    throw new Error("No hay contenido valido para generar DOCX");
  }

  const zip = createZip();

  zip.file("[Content_Types].xml", contentTypesXml());
  zip.file("_rels/.rels", rootRelsXml());
  zip.file("word/document.xml", documentXml(paragraphs));
  zip.file("word/_rels/document.xml.rels", documentRelsXml());
  zip.file("word/styles.xml", stylesXml());
  zip.file("docProps/core.xml", coreXml(title));
  zip.file("docProps/app.xml", appXml());

  const buffer = await generateZipBuffer(zip);

  await fs.promises.mkdir(OUTPUT_DIR, {
    recursive: true
  });

  await fs.promises.writeFile(path.posix.join(OUTPUT_DIR, filename), buffer);

  msg.generatedFilename = filename;
  msg.generatedDir = OUTPUT_DIR;

  msg.payload = {
    message: "DOCX generado correctamente",
    filename,
    error: null
  };

  node.send([msg, null]);
}

run().catch((err) => {
  const errorMsg = {
    ...msg,
    payload: {
      message: "Error generando DOCX local",
      error: err.message
    }
  };

  node.send([null, errorMsg]);
});

return;

