const fs = require('fs');
const path = require('path');
const os = require('os');
const { spawn } = require('child_process');

function ensureDir(dir) {
    fs.mkdirSync(dir, { recursive: true });
}

function getUserKey(msg) {
    const sec = msg.__axetFlowsSecurityContext || {};
    const idp = sec.externalIdpUserInfo || {};
    return (
        idp.preferred_username ||
        idp.email ||
        idp.sub ||
        msg.req?.user?.email ||
        msg.req?.user?.id ||
        msg.userId ||
        'anonymous'
    );
}

function safeReadJson(filePath) {
    try {
        if (!fs.existsSync(filePath)) return null;
        const raw = fs.readFileSync(filePath, 'utf8').trim();
        return raw ? JSON.parse(raw) : null;
    } catch (err) {
        node.warn(`⚠️ Error leyendo ${filePath}: ${err.message}`);
        return null;
    }
}

function safeWriteJson(filePath, data) {
    const tmp = `${filePath}.tmp`;
    fs.writeFileSync(tmp, JSON.stringify(data, null, 2), 'utf8');
    fs.renameSync(tmp, filePath);
}

function updateSessionState(projectPath, updater) {
    if (!projectPath) return null;

    const docsDir = path.join(projectPath, 'codex-docs');
    const statePath = path.join(docsDir, 'SESSION_STATE.json');
    ensureDir(docsDir);

    const state = safeReadJson(statePath) || {};
    const next = updater(state) || state;
    safeWriteJson(statePath, next);
    return next;
}

function killPidTree(pid) {
    if (!pid) return false;

    const platform = msg.platformInfo?.platform || os.platform();

    try {
        if (platform === 'win32') {
            spawn('taskkill', ['/PID', String(pid), '/T', '/F'], {
                detached: true,
                stdio: 'ignore'
            }).unref();
        } else {
            spawn('sh', ['-c',
                `pkill -TERM -P ${pid} 2>/dev/null; ` +
                `kill -TERM ${pid} 2>/dev/null; ` +
                `sleep 4; ` +
                `pkill -KILL -P ${pid} 2>/dev/null; ` +
                `kill -KILL ${pid} 2>/dev/null`
            ], {
                detached: true,
                stdio: 'ignore'
            }).unref();
        }

        return true;
    } catch (e) {
        node.warn(`   ⚠️ No se pudo matar PID ${pid}: ${e.message}`);
        return false;
    }
}

const userKey = getUserKey(msg);
const storeDir = '/internal-storage-files/files/_active-sessions';
const filePath = path.join(storeDir, `${userKey}.json`);

const previous = safeReadJson(filePath);

if (previous && previous.sessionId) {
    node.warn(`🧹 Limpiando sesión anterior para ${userKey}:`);
    node.warn(`   sessionId: ${previous.sessionId}`);
    node.warn(`   status: ${previous.status}`);
    node.warn(`   projectPath: ${previous.projectPath}`);

    let updatedState = null;

    try {
        updatedState = updateSessionState(previous.projectPath, (state) => {
            state._id = previous.sessionId;
            state.sessionId = previous.sessionId;
            state.execution = state.execution || {};
            state.runtime = state.runtime || {};
            state.execution.process = state.execution.process || {};

            state.execution.stopRequested = true;
            state.execution.stopRequestedAt = new Date().toISOString();
            state.execution.reason = 'manual-stop';
            state.execution.stopped = true;

            state.runtime.manualStop = true;
            state.runtime.success = false;
            state.runtime.completed = false;
            state.runtime.status = 'Stop requested by user for new execution';

            state.updatedAt = new Date().toISOString();
            return state;
        });

        node.warn(`   📝 SESSION_STATE marcado como manual-stop`);
    } catch (e) {
        node.warn(`   ⚠️ No se pudo persistir manual-stop: ${e.message}`);
    }

    const pid = Number(updatedState?.execution?.process?.pid) || null;
    const killRequested = pid ? killPidTree(pid) : false;

    if (killRequested) {
        node.warn(`   🛑 Kill solicitado para PID ${pid}`);
    } else if (pid) {
        node.warn(`   ⚠️ No se pudo solicitar kill para PID ${pid}`);
    } else {
        node.warn(`   ℹ️ No había PID registrado en SESSION_STATE`);
    }

    try {
        if (fs.existsSync(filePath)) {
            fs.unlinkSync(filePath);
            node.warn(`   🗑️ ${filePath} eliminado`);
        }
    } catch (e) {
        node.warn(`   ⚠️ No se pudo eliminar active session: ${e.message}`);
    }
} else {
    node.warn(`ℹ️ No hay sesión activa previa para ${userKey}`);
}

node.warn(`✅ Listo para iniciar nueva ejecución (${userKey})`);
return msg;

