const CACHE_KEY = 'referenceGenerator_selectors_v1';

function cloneJson(value) {
    return JSON.parse(JSON.stringify(value || {}));
}

msg.payload = msg.payload || {};
msg.payload.data = msg.payload.data || {};

const cache = global.get(CACHE_KEY);

if (!cache || !cache.selectorData) {
    msg.payload.data.mainSelectorsReady = false;
    msg.payload.data.selectorsReady = false;
    msg.payload.data.selectorsCacheMissing = true;
    msg.payload.mainSelectorsReady = false;
    msg.payload.selectorsReady = false;
    msg.payload.selectorsCacheMissing = true;

    node.warn(
        'Selectors cache missing. Revisa que el nodo "Init Refresh Selectors Global Cache" este desplegado.'
    );

    return msg;
}

const cachedSelectorData = cloneJson(cache.selectorData);
const selectorsLoadedAt = cache.builtAt || new Date().toISOString();
const viewRefreshValue = Date.now();

const selectorData = {
    ...cachedSelectorData,

    selectedSources: Array.isArray(msg.payload.data.selectedSources)
        ? msg.payload.data.selectedSources
        : [],

    mainSelectorsReady: true,
    selectorsReady: true,
    mainSelectorsLoadedAt: selectorsLoadedAt,
    selectorsLoadedAt: selectorsLoadedAt,
    selectorsCacheHit: true,
    selectorsCacheBuiltAt: cache.builtAt,
    selectorsCacheBuildReason: cache.buildReason,
    selectorsCacheBuildMs: cache.buildMs,
    selectorsCacheStats: cache.stats,
    viewRefresh: viewRefreshValue
};

if (!msg.payload.data.idioma) {
    selectorData.idioma = 'Español (ES)';
}

if (!msg.payload.data.sector_outputformat) {
    selectorData.sector_outputformat = 'general';
}

if (
    !msg.payload.data.plantilla &&
    Array.isArray(selectorData.plantillas) &&
    selectorData.plantillas.length
) {
    selectorData.plantilla = selectorData.plantillas[0].value;
}

for (const [key, value] of Object.entries(selectorData)) {
    msg.payload.data[key] = value;
    msg.payload[key] = value;
}

for (const editableKey of [
    'includeProcessed',
    'includeOpportunity',
    'includeUploads',
    'sector',
    'unidadOportunidad',
    'cliente',
    'opportunitySelectionMode',
    'businessOpportunityIdSearch',
    'opportunityId',
    'unidadProcesado',
    'proyectoProcesado',
    'uploadFiles',
    'instruccionEspecifica',
    'extract'
]) {
    delete msg.payload.data[editableKey];
    delete msg.payload[editableKey];
}

node.warn(
    'Build selectors from global cache: ' +
    `sectores=${cache.stats?.sectors || 0}, ` +
    `oportunidades=${cache.stats?.opportunities || 0}, ` +
    `businessIds=${cache.stats?.businessOpportunityIds || 0}, ` +
    `procesado=${cache.stats?.processedUnits || 0}, ` +
    `plantillas=${cache.stats?.templates || 0}, ` +
    `cacheBuiltAt=${cache.builtAt}, ` +
    `buildReason=${cache.buildReason}, ` +
    `ready=true, viewRefresh=${viewRefreshValue}`
);

return msg;

