const fs = require('fs');
const path = require('path');

const TEMPLATES_DIR = '/internal-storage-files/files/plantillas';

function resolveSessionContext(msg) {
    const sessionId =
        msg.onInitSubmission?.sessionId ||
        msg.submission?.sessionId ||
        msg.req?.query?.sessionId ||
        msg.payload?.sessionId ||
        msg.sessionId;

    const projectPath =
        msg.onInitSubmission?.projectPath ||
        msg.submission?.projectPath ||
        msg.projectPath ||
        (sessionId ? path.join('/internal-storage-files/files', 'codex-workspace', sessionId) : null);

    const sessionStatePath =
        sessionId && projectPath
            ? path.join(projectPath, 'codex-docs', 'SESSION_STATE.json')
            : null;

    return { sessionId, projectPath, sessionStatePath };
}

function loadSessionState(sessionStatePath) {
    try {
        if (sessionStatePath && fs.existsSync(sessionStatePath)) {
            const raw = fs.readFileSync(sessionStatePath, 'utf8').trim();
            return raw ? JSON.parse(raw) : {};
        }
    } catch (err) {
        node.warn(`⚠️ No se pudo leer SESSION_STATE.json: ${err.message}`);
    }
    return {};
}

function deepMerge(target, source) {
    if (!source || typeof source !== 'object' || Array.isArray(source)) return target;

    for (const key of Object.keys(source)) {
        const value = source[key];
        if (value === undefined) continue;

        if (value && typeof value === 'object' && !Array.isArray(value)) {
            if (!target[key] || typeof target[key] !== 'object' || Array.isArray(target[key])) {
                target[key] = {};
            }
            deepMerge(target[key], value);
        } else {
            target[key] = value;
        }
    }

    return target;
}

function saveSessionPatch(sessionId, sessionStatePath, patch) {
    if (!sessionId || !sessionStatePath) return;

    const dir = path.dirname(sessionStatePath);
    const tmpPath = path.join(dir, 'SESSION_STATE.tmp');
    const now = new Date().toISOString();

    /** @type {any} */
    let state = {};

    try {
        if (fs.existsSync(sessionStatePath)) {
            const raw = fs.readFileSync(sessionStatePath, 'utf8').trim();
            state = raw ? JSON.parse(raw) : {};
        }
    } catch (err) {
        node.warn(`⚠️ No se pudo leer estado previo: ${err.message}`);
        state = {};
    }

    if (!state || typeof state !== 'object' || Array.isArray(state)) {
        state = {};
    }

    state._id = state._id || sessionId;
    state.sessionId = state.sessionId || sessionId;
    state.createdAt = state.createdAt || now;
    state.updatedAt = now;

    deepMerge(state, patch || {});

    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(tmpPath, JSON.stringify(state, null, 2), 'utf8');
    fs.renameSync(tmpPath, sessionStatePath);
}


const { sessionId, projectPath, sessionStatePath } = resolveSessionContext(msg);
const state = loadSessionState(sessionStatePath);

let templates = [];
try {
    templates = fs.readdirSync(TEMPLATES_DIR)
        .filter(name => {
            const ext = path.extname(name).toLowerCase();
            return ext === '.pptx' || ext === '.docx';
        })
        .sort((a, b) => a.localeCompare(b));
} catch (err) {
    node.warn(`No se pudieron leer las plantillas en ${TEMPLATES_DIR}: ${err.message}`);
}

msg.submission = msg.submission || {};
msg.submission.data = msg.submission.data || {};
msg.onInitSubmission = msg.onInitSubmission || {};
msg.onInitSubmission.data = msg.onInitSubmission.data || {};

const storedTemplate =
    state?.selection?.plantilla ||
    state?.selection?.template ||
    null;

const incomingTemplate =
    storedTemplate ||
    msg.submission?.data?.plantilla ||
    msg.submission?.plantilla ||
    msg.onInitSubmission?.data?.plantilla ||
    msg.onInitSubmission?.plantilla ||
    msg.payload?.data?.plantilla ||
    msg.payload?.plantilla ||
    msg.plantilla ||
    null;

let selectedTemplate = String(incomingTemplate || '').trim();

if (!selectedTemplate) {
    selectedTemplate = templates[0] || '';
} else if (templates.length && !templates.includes(selectedTemplate)) {
    selectedTemplate = templates[0] || '';
}

const templateOptions = templates.map(name => ({ label: name, value: name }));

msg.sessionId = sessionId;
msg.projectPath = projectPath;

msg.submission.sessionId = sessionId;
msg.submission.projectPath = projectPath;
msg.submission.data.pptxTemplates = templateOptions;
msg.submission.pptxTemplates = templateOptions;
msg.submission.data.plantillas = templateOptions;
msg.submission.plantillas = templateOptions;
msg.submission.data.template = selectedTemplate;
msg.submission.data.plantilla = selectedTemplate;
msg.submission.plantilla = selectedTemplate;
msg.plantilla = selectedTemplate;

msg.onInitSubmission.sessionId = sessionId;
msg.onInitSubmission.projectPath = projectPath;
msg.onInitSubmission.data.template = selectedTemplate;
msg.onInitSubmission.data.plantilla = selectedTemplate;
msg.onInitSubmission.plantilla = selectedTemplate;

if (sessionId && sessionStatePath && selectedTemplate) {
    saveSessionPatch(sessionId, sessionStatePath, {
        selection: {
            template: selectedTemplate,
            plantilla: selectedTemplate
        }
    });
}

msg.payload = msg.submission;
return msg;

