node.warn('PPTX layout: parse LLM response v17 general/sectorial soft coverage');

const BULLET = String.fromCharCode(8226);

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFC')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\u00A0/g, ' ')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

function clean(value) {
  return normalizeText(value).replace(/[\t ]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}

function keyNorm(value) {
  return clean(value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
}

function isNoData(value) {
  const s = keyNorm(value);
  if (!s || ['no hallado', 'no encontrado', 'no disponible', 'n a', 'na', 'null', '-'].includes(s)) return true;
  return /^no exact\b/.test(s) || /^no explicit\b/.test(s) || /^no specific\b/.test(s) || /^not specified\b/.test(s) || /^not available\b/.test(s) || /^not found\b/.test(s) || /^not provided\b/.test(s) || /^no\s+.*\s+found\b/.test(s) || /^sin informacion\b/.test(s) || /^sin datos\b/.test(s) || /^no se ha encontrado\b/.test(s) || /^no se han encontrado\b/.test(s) || /^no se ha identificado\b/.test(s) || /^no se han identificado\b/.test(s) || /^no consta\b/.test(s);
}

function removeEllipses(value) {
  return clean(value).replace(/\.{3,}/g, '').replace(/\u2026/g, '').replace(/[\s,;:.\-]+$/g, '').trim();
}

function repairOpenTail(value) {
  let s = removeEllipses(value);
  const opens = (s.match(/\(/g) || []).length;
  const closes = (s.match(/\)/g) || []).length;
  if (opens > closes) {
    const idx = s.lastIndexOf('(');
    if (idx > 0) s = s.slice(0, idx).trim();
  }
  return s.replace(/\b(including|incluyendo|and|y|with|con|plus|mas|de|del|la|el|los|las|para|por|sobre|su|sus|fecha)$/i, '').trim();
}

function smartCut(value, maxChars) {
  let s = clean(value);
  if (!maxChars || s.length <= maxChars) return repairOpenTail(s);
  let cut = s.slice(0, maxChars).trim();
  const lastStop = Math.max(
    cut.lastIndexOf('. '),
    cut.lastIndexOf('; '),
    cut.lastIndexOf('\n'),
    cut.lastIndexOf(' - '),
    cut.lastIndexOf(' \u2014 ')
  );
  if (lastStop > Math.floor(maxChars * 0.55)) cut = cut.slice(0, lastStop + 1).trim();
  else {
    const lastSpace = cut.lastIndexOf(' ');
    if (lastSpace > Math.floor(maxChars * 0.68)) cut = cut.slice(0, lastSpace).trim();
  }
  return repairOpenTail(cut);
}

function splitCandidates(value) {
  if (Array.isArray(value)) return value.map(clean).filter((x) => x && !isNoData(x));
  const text = clean(value);
  if (!text || isNoData(text)) return [];
  let parts = text.split(/\n+/g).map((x) => x.replace(/^\s*[-*\u2022]+\s*/g, '').replace(/^\s*[0-9]+[.)]\s*/g, '').trim()).filter(Boolean);
  if (parts.length <= 1 && text.includes(';')) parts = text.split(/;\s*/g).map((x) => x.trim()).filter(Boolean);
  if (parts.length <= 1) parts = text.split(/(?<=[.!?])\s+(?=[A-Z0-9\u00c0-\u017f])/g).map((x) => x.trim()).filter(Boolean);
  const out = [];
  const seen = new Set();
  for (const item of parts) {
    const s = repairOpenTail(item);
    if (!s || isNoData(s)) continue;
    const k = keyNorm(s);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(s);
  }
  return out;
}

function limitLine(value, limit, fallback) {
  const s = clean(value);
  if (!s || isNoData(s)) return fallback || '-';
  return smartCut(s, limit?.maxChars || 200) || fallback || '-';
}

function limitParagraph(value, limit, fallback) {
  const s = clean(value);
  if (!s || isNoData(s)) return fallback || '-';
  // V15: el LLM ya ha resumido segun la caja real medida. El parser no vuelve
  // a recortar texto porque eso reintroduciria fragmentos como "A nivel de negocio".
  return s;
}

function limitBullets(value, limit, fallback) {
  const items = splitCandidates(value);
  if (!items.length) return fallback || '-';

  // V15: no se truncan ni se descartan bullets por numero de caracteres. La IA
  // recibe la capacidad real antes de redactar. Aqui solo normalizamos y dejamos
  // que el ajuste de fuente del inyector actue como ultimo margen de seguridad.
  const out = items.map(repairOpenTail).filter(Boolean);
  return out.length ? out.map((x) => BULLET + ' ' + x).join('\n') : (fallback || '-');
}

function parseTaskSectionsForCoverage(value) {
  const raw = normalizeText(value);
  if (!raw || isNoData(raw)) return [];
  const rows = [];
  for (const lineRaw of raw.split('\n')) {
    if (!lineRaw.trim()) continue;
    const bullet = lineRaw.match(/^(\s*)[-*\u2022]+\s+(.*)$/);
    if (bullet) {
      const indent = String(bullet[1] || '').replace(/\t/g, '    ').length;
      const text = clean(bullet[2]);
      if (text) rows.push({ indent, text });
      continue;
    }
    if (rows.length) rows[rows.length - 1].text = clean(rows[rows.length - 1].text + ' ' + lineRaw.trim());
  }
  if (!rows.length) return splitCandidates(raw).map((title) => ({ title, details: [] }));
  const minIndent = Math.min(...rows.map((x) => x.indent));
  const sections = [];
  for (const row of rows) {
    if (row.indent === minIndent || !sections.length) sections.push({ title: row.text, details: [] });
    else sections[sections.length - 1].details.push(row.text);
  }
  return sections;
}

function coverageAlternatives(title) {
  const k = keyNorm(title);
  if (/\bfase iii\b/.test(k)) return ['fase iii'];
  if (/\bfase ii\b/.test(k)) return ['fase ii'];
  if (/\bfase i\b/.test(k)) return ['fase i'];
  if (k.includes('migracion')) return ['migracion'];
  if (k.includes('metodolog') || k.includes('calidad')) return ['metodolog', 'calidad'];
  if (k.includes('pmo') || k.includes('gobierno')) return ['pmo', 'gobierno'];

  const stop = new Set(['de','del','la','el','los','las','y','a','en','por','para','con','sin','transversal','fase','fases']);
  const tokens = k.split(' ').filter((x) => x.length >= 4 && !stop.has(x));
  return tokens.slice(0, 2);
}

function validateTaskCoverage(sourceTasks, outputTasks) {
  const sections = parseTaskSectionsForCoverage(sourceTasks);
  if (sections.length <= 1) return { ok: true, missing: [], total: sections.length };
  const out = keyNorm(outputTasks);
  const missing = [];
  for (const section of sections) {
    const alts = coverageAlternatives(section.title);
    if (alts.length && !alts.some((x) => out.includes(x))) missing.push(section.title);
  }
  return { ok: missing.length === 0, missing, total: sections.length };
}

function visualCharCount(value) {
  return clean(value).replace(/^\s*[\u2022*-]\s*/gm, '').length;
}

function estimateVisualLines(value, limit) {
  const text = clean(value);
  const widthPt = Number(limit?.measuredWidthPt || 0);
  const pt = Number(limit?.targetFontPt || limit?.fontPt?.base || 0);
  if (!text || !widthPt || !pt) return null;
  const charsPerLine = Math.max(8, Math.floor(widthPt / (pt * 0.53)));
  return text.split(/\n+/g).filter(Boolean).reduce((sum, line) => {
    const len = line.replace(/^\s*[\u2022*-]\s*/, '').trim().length;
    return sum + Math.max(1, Math.ceil(len / charsPerLine));
  }, 0);
}

function capacityWarningsForReference(ref, profile, idx) {
  const warnings = [];
  const limits = profile?.limits || {};
  for (const field of ['OBJETIVOS','TAREAS','RESULTADOS','TECNOLOGIAS','METODOLOGIAS','PALABRAS_CLAVE','PERFILES_PROFESIONALES','FUENTES']) {
    const limit = limits[field] || {};
    if (limit.source !== 'runtime_template_geometry') continue;
    const value = ref?.[field];
    if (!value || value === '-') continue;
    const chars = visualCharCount(value);
    const target = Number(limit.maxTotalChars || limit.maxChars || 0);
    const hard = Number(limit.hardMaxTotalChars || limit.hardMaxChars || 0);
    const lines = estimateVisualLines(value, limit);
    const hardLines = Number(limit.hardLines || 0);
    if (hard && chars > hard) warnings.push('Referencia ' + idx + ' ' + field + ': la salida de IA supera la capacidad dura medida (' + chars + ' > ' + hard + ' chars).');
    if (hardLines && lines && lines > hardLines) warnings.push('Referencia ' + idx + ' ' + field + ': la salida de IA puede superar las lineas disponibles (' + lines + ' > ' + hardLines + ').');
    if (target && chars < Math.floor(target * 0.35) && chars > 30) warnings.push('Referencia ' + idx + ' ' + field + ': la IA ha usado poco espacio de la caja medida (' + chars + '/' + target + ' chars objetivo).');
  }
  return warnings;
}

function compactCountry(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  if (k.includes('union europea') || k.includes('european union') || k.includes('eu member states') || k.includes('estados miembros')) return 'EU Member States';
  return limitLine(raw.replace(/^main location:\s*/i, '').replace(/;\s*other locations:\s*/i, '; '), limit, '-');
}

function compactLanguage(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  if (k.includes('english') || k.includes('ingles')) return 'English';
  if (k.includes('spanish') || k.includes('espanol')) return 'Spanish';
  if (k.includes('french') || k.includes('frances')) return 'French';
  return limitLine(raw.replace(/^working language:\s*/i, '').replace(/^idioma de trabajo:\s*/i, ''), limit, '-');
}

function compactUsers(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  if (k.includes('4100') && k.includes('124') && (k.includes('4000') || k.includes('external'))) return '4,100+ (124 int.; 4,000+ ext.)';
  const m = raw.match(/over\s*([0-9.,+]+).*?including\s*([0-9.,+]+).*?internal.*?([0-9.,+]+).*?external/i);
  if (m) return String(m[1]).replace('.', ',') + '+ (' + m[2] + ' int.; ' + m[3] + ' ext.)';
  return limitLine(raw, limit, '-');
}

function compactTechnologies(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  const out = [];
  function add(label, cond) { if (cond && !out.includes(label)) out.push(label); }
  add('Azure', k.includes('azure'));
  add('Databricks', k.includes('databricks'));
  add('Angular/eUI', k.includes('angular') || k.includes('eui'));
  add('Spring Boot', k.includes('spring boot'));
  add('SQL stack', k.includes('sql') || k.includes('postgres') || k.includes('mysql') || k.includes('mariadb'));
  add('Synapse/Data Lake', k.includes('synapse') || k.includes('data lake'));
  add('Docker/Kubernetes', k.includes('docker') || k.includes('kubernetes'));
  add('Azure DevOps', k.includes('devops'));
  add('Camunda/BPMN', k.includes('camunda') || k.includes('bpmn') || k.includes('dmn'));
  add('EU tools', k.includes('eu login') || k.includes('eu survey') || k.includes('eu send'));
  add('OpenSearch/Elastic', k.includes('opensearch') || k.includes('elasticsearch'));
  add('Kafka', k.includes('kafka'));
  if (!out.length) return limitLine(Array.isArray(value) ? value.join(', ') : value, limit, '-');
  return smartCut(out.join(', '), limit?.maxChars || 270);
}

function compactProfiles(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  const out = [];
  function add(label, cond) { if (cond && !out.includes(label)) out.push(label); }
  add('Project/Service Mgmt', k.includes('project') || k.includes('service manager') || k.includes('quality manager') || k.includes('quality assurance'));
  add('Scrum/Agile', k.includes('scrum') || k.includes('agile') || k.includes('methodology'));
  add('BA/TA', k.includes('business analyst') || k.includes('technical analyst') || k.includes('technical manager') || k.includes('functional'));
  add('Solution Architecture', k.includes('solution architect') || k.includes('architecture'));
  add('DevOps/Release', k.includes('devops') || k.includes('release'));
  add('QA/Testing', k.includes('testing') || k.includes('qa') || k.includes('cross testing'));
  add('Data Protection/Cybersecurity', k.includes('data protection') || k.includes('cyber') || k.includes('security') || k.includes('privacy'));
  add('Health Data/MCM experts', k.includes('health data') || k.includes('mcm') || k.includes('epidemiologist') || k.includes('supply chain') || k.includes('simulation'));
  add('Help Desk/Support', k.includes('help desk') || k.includes('helpdesk') || k.includes('support'));
  if (!out.length) return limitLine(Array.isArray(value) ? value.join(', ') : value, limit, '-');
  return smartCut(out.join('; '), limit?.maxChars || 250);
}

function compactKeywords(value, limit) {
  const items = splitCandidates(value);
  return smartCut(items.slice(0, limit?.maxItems || 11).join(', '), limit?.maxChars || 190) || '-';
}

function compactSources(value, limit) {
  const items = splitCandidates(Array.isArray(value) ? value.join('\n') : String(value || '').replace(/\|/g, '\n'));
  return smartCut(items.slice(0, limit?.maxItems || 4).join(' | '), limit?.maxChars || 190) || '-';
}

function extractTextFromResponse(data) {
  if (!data) return '';
  if (typeof data === 'string') return data;
  if (typeof data.output_text === 'string') return data.output_text;
  if (typeof data.text === 'string') return data.text;
  if (typeof data.content === 'string') return data.content;
  if (Array.isArray(data.choices) && data.choices[0]?.message?.content) return String(data.choices[0].message.content);

  const pieces = [];
  function walk(x) {
    if (!x) return;
    if (typeof x === 'string') { pieces.push(x); return; }
    if (Array.isArray(x)) { x.forEach(walk); return; }
    if (typeof x === 'object') {
      if (typeof x.text === 'string') pieces.push(x.text);
      if (typeof x.output_text === 'string') pieces.push(x.output_text);
      if (typeof x.content === 'string') pieces.push(x.content);
      if (Array.isArray(x.content)) walk(x.content);
      if (Array.isArray(x.output)) walk(x.output);
      if (Array.isArray(x.message?.content)) walk(x.message.content);
    }
  }
  walk(data.output || data);
  return pieces.join('\n').trim();
}

function parseJsonFromText(text) {
  let s = clean(text);
  const fence = String.fromCharCode(96) + String.fromCharCode(96) + String.fromCharCode(96);
  if (s.toLowerCase().startsWith(fence + 'json')) s = s.slice(7).trim();
  if (s.startsWith(fence)) s = s.slice(3).trim();
  if (s.endsWith(fence)) s = s.slice(0, -3).trim();
  try { return JSON.parse(s); } catch (_err) {}
  const first = s.indexOf('{');
  const last = s.lastIndexOf('}');
  if (first >= 0 && last > first) return JSON.parse(s.slice(first, last + 1));
  throw new Error('No valid JSON object found in LLM response');
}

function arrayByIndex(layoutReferences) {
  const map = new Map();
  for (const item of layoutReferences || []) {
    const idx = Number(item._referenceIndex || item.index || item.N || 0);
    if (idx) map.set(idx, item);
  }
  return map;
}

function sanitizeLayout(out, profile) {
  const limits = profile?.limits || {};
  out.TITULO_PROYECTO = limitLine(out.TITULO_PROYECTO, limits.TITULO_PROYECTO, '-');
  out.CLIENTE = limitLine(out.CLIENTE, limits.CLIENTE, '-');
  out.SECTOR = limitLine(out.SECTOR, limits.SECTOR, '-');
  out.PAIS_EJECUCION = compactCountry(out.PAIS_EJECUCION, limits.PAIS_EJECUCION);
  out.FECHA_INICIO = limitLine(out.FECHA_INICIO, limits.FECHA_INICIO, '-');
  out.FECHA_FIN = limitLine(out.FECHA_FIN, limits.FECHA_FIN, '-');
  out.DURACION_MESES = limitLine(out.DURACION_MESES, limits.DURACION_MESES, '-');
  out.IMPORTE_TOTAL = limitLine(out.IMPORTE_TOTAL, limits.IMPORTE_TOTAL, '-');
  out.VOLUMEN_USUARIOS = compactUsers(out.VOLUMEN_USUARIOS, limits.VOLUMEN_USUARIOS);
  out.IDIOMA_TRABAJO = compactLanguage(out.IDIOMA_TRABAJO, limits.IDIOMA_TRABAJO);
  out.TIPO_SERVICIO = limitLine(out.TIPO_SERVICIO, limits.TIPO_SERVICIO, '-');
  out.TIPO_PROYECTO = limitLine(out.TIPO_PROYECTO, limits.TIPO_PROYECTO, '-');
  out.OBJETIVOS = limitParagraph(out.OBJETIVOS, limits.OBJETIVOS, '-');
  out.TAREAS = limitBullets(out.TAREAS, limits.TAREAS, '-');
  out.RESULTADOS = limitBullets(out.RESULTADOS, limits.RESULTADOS, '-');
  out.TECNOLOGIAS = compactTechnologies(out.TECNOLOGIAS, limits.TECNOLOGIAS);
  out.METODOLOGIAS = limitLine(out.METODOLOGIAS, limits.METODOLOGIAS, '-');
  out.CPV = limitLine(out.CPV, limits.CPV, '-');
  out.PALABRAS_CLAVE = compactKeywords(out.PALABRAS_CLAVE, limits.PALABRAS_CLAVE);
  out.PERFILES_PROFESIONALES = compactProfiles(out.PERFILES_PROFESIONALES, limits.PERFILES_PROFESIONALES);
  out.FUENTES = compactSources(out.FUENTES, limits.FUENTES);
  return out;
}

function mergeAdapted(base, adapted, profile) {
  const limits = profile?.limits || {};
  const out = { ...base };
  const fields = {
    TITULO_PROYECTO: adapted.TITULO_PROYECTO || adapted.tituloProyecto || adapted.titulo || adapted.title,
    PAIS_EJECUCION: adapted.PAIS_EJECUCION || adapted.paisEjecucion || adapted.pais || adapted.country,
    IMPORTE_TOTAL: adapted.IMPORTE_TOTAL || adapted.importeTotal || adapted.importe || adapted.amount,
    VOLUMEN_USUARIOS: adapted.VOLUMEN_USUARIOS || adapted.volumenUsuarios || adapted.usuarios || adapted.users,
    IDIOMA_TRABAJO: adapted.IDIOMA_TRABAJO || adapted.idiomaTrabajo || adapted.idioma || adapted.language,
    OBJETIVOS: adapted.OBJETIVOS || adapted.objetivos || adapted.contextoRetos || adapted.contexto,
    TAREAS: adapted.TAREAS || adapted.tareas || adapted.actividadesClave || adapted.actividades,
    RESULTADOS: adapted.RESULTADOS || adapted.resultados || adapted.results,
    TECNOLOGIAS: adapted.TECNOLOGIAS || adapted.tecnologias || adapted.technologies,
    METODOLOGIAS: adapted.METODOLOGIAS || adapted.metodologias || adapted.methodologies,
    PALABRAS_CLAVE: adapted.PALABRAS_CLAVE || adapted.palabrasClave || adapted.keywords,
    PERFILES_PROFESIONALES: adapted.PERFILES_PROFESIONALES || adapted.perfilesProfesionales || adapted.perfiles,
    FUENTES: adapted.FUENTES || adapted.fuentes || adapted.sources
  };

  if (fields.TITULO_PROYECTO) out.TITULO_PROYECTO = limitLine(fields.TITULO_PROYECTO, limits.TITULO_PROYECTO, out.TITULO_PROYECTO);
  if (fields.PAIS_EJECUCION) out.PAIS_EJECUCION = compactCountry(fields.PAIS_EJECUCION, limits.PAIS_EJECUCION);
  if (fields.IMPORTE_TOTAL) out.IMPORTE_TOTAL = limitLine(fields.IMPORTE_TOTAL, limits.IMPORTE_TOTAL, out.IMPORTE_TOTAL);
  if (fields.VOLUMEN_USUARIOS) out.VOLUMEN_USUARIOS = compactUsers(fields.VOLUMEN_USUARIOS, limits.VOLUMEN_USUARIOS);
  if (fields.IDIOMA_TRABAJO) out.IDIOMA_TRABAJO = compactLanguage(fields.IDIOMA_TRABAJO, limits.IDIOMA_TRABAJO);
  if (fields.OBJETIVOS) out.OBJETIVOS = limitParagraph(fields.OBJETIVOS, limits.OBJETIVOS, out.OBJETIVOS);
  if (fields.TAREAS) out.TAREAS = limitBullets(fields.TAREAS, limits.TAREAS, out.TAREAS);
  if (fields.RESULTADOS) out.RESULTADOS = limitBullets(fields.RESULTADOS, limits.RESULTADOS, out.RESULTADOS);
  if (fields.TECNOLOGIAS) out.TECNOLOGIAS = compactTechnologies(Array.isArray(fields.TECNOLOGIAS) ? fields.TECNOLOGIAS.join(', ') : fields.TECNOLOGIAS, limits.TECNOLOGIAS);
  if (fields.METODOLOGIAS) out.METODOLOGIAS = limitLine(Array.isArray(fields.METODOLOGIAS) ? fields.METODOLOGIAS.join(', ') : fields.METODOLOGIAS, limits.METODOLOGIAS, out.METODOLOGIAS);
  if (fields.PALABRAS_CLAVE) out.PALABRAS_CLAVE = compactKeywords(Array.isArray(fields.PALABRAS_CLAVE) ? fields.PALABRAS_CLAVE.join(', ') : fields.PALABRAS_CLAVE, limits.PALABRAS_CLAVE);
  if (fields.PERFILES_PROFESIONALES) out.PERFILES_PROFESIONALES = compactProfiles(Array.isArray(fields.PERFILES_PROFESIONALES) ? fields.PERFILES_PROFESIONALES.join(', ') : fields.PERFILES_PROFESIONALES, limits.PERFILES_PROFESIONALES);
  if (fields.FUENTES) out.FUENTES = compactSources(fields.FUENTES, limits.FUENTES);

  out._layoutSource = 'llm_v15_runtime_measured';
  out._llmOverflowNotes = Array.isArray(adapted.overflowNotes) ? adapted.overflowNotes.map(clean).filter(Boolean) : [];
  return sanitizeLayout(out, profile);
}

function dedupeWarnings(warnings) {
  const seen = new Set();
  const out = [];
  for (const w of warnings || []) {
    const s = String(w || '').trim();
    if (!s || seen.has(s)) continue;
    seen.add(s);
    out.push(s);
  }
  return out;
}

if (msg.payload?.outputType !== 'pptx') return msg;

const data = msg.payload.data || {};
const layout = msg._pptxLayout || {};
const variant = layout.variant === 'sectorial' ? 'sectorial' : 'general';
const sectorOutputFormat = layout.sectorOutputFormat || data.sector_outputformat || msg.sector_outputformat || 'general';
const profile = layout.profile || data.layoutProfile || {};
let layoutReferences = Array.isArray(data.layoutReferences) ? data.layoutReferences : [];
const byIndex = arrayByIndex(layoutReferences);
const sourceByIndex = new Map();
for (let i = 0; i < (data.references || []).length; i++) {
  const src = data.references[i] || {};
  const idx = Number(src.index || i + 1);
  sourceByIndex.set(idx, src);
}
const warnings = dedupeWarnings(layout.warnings || []);
let adaptedCount = 0;

for (const raw of layout.llmRawResponses || []) {
  try {
    const text = extractTextFromResponse(raw.data);
    const parsed = parseJsonFromText(text);
    const arr = Array.isArray(parsed.references) ? parsed.references : (Array.isArray(parsed) ? parsed : []);
    for (const adapted of arr) {
      const idx = Number(adapted.index || adapted._referenceIndex || 0);
      if (!idx || !byIndex.has(idx)) continue;
      const base = byIndex.get(idx);
      const merged = mergeAdapted(base, adapted, profile);

      const adaptedTasks = adapted.TAREAS || adapted.tareas || adapted.actividadesClave || adapted.actividades;
      if (variant === 'general' && adaptedTasks) {
        // V17: la cobertura de secciones/fases deja de ser un bloqueo duro.
        // El LLM puede agrupar o reformular varias secciones en una misma idea,
        // por lo que una comprobacion literal no debe descartar una buena sintesis.
        // Conservamos la salida del LLM siempre que sea valida; el control real
        // queda en el prompt, la capacidad medida de la plantilla y las warnings
        // de overflow/frases incompletas.
        const coverage = validateTaskCoverage(sourceByIndex.get(idx)?.tareas, merged.TAREAS);
        if (!coverage.ok) {
          warnings.push('Referencia ' + idx + ' TAREAS: algunos bloques de origen no aparecen explicitamente en la sintesis (' + coverage.missing.join(' | ') + '). La salida de IA se conserva porque pueden haber sido agrupados o reformulados semanticamente.');
          merged._layoutSource = 'llm_v17_general_soft_coverage';
        }
      } else if (variant === 'sectorial' && adaptedTasks) {
        const taskKey = keyNorm(merged.TAREAS);
        const phaseMentions = (taskKey.match(/\bfase\s+(?:i{1,3}|[0-9]+)\b/g) || []).length;
        if (phaseMentions >= 2) {
          warnings.push('Referencia ' + idx + ' TAREAS sectorial: la reformulacion sigue demasiado centrada en fases (' + phaseMentions + ' menciones). Se conserva la salida de IA pero se recomienda revisar el prompt/evidencia.');
        }
      }

      byIndex.set(idx, merged);
      adaptedCount++;
    }
  } catch (err) {
    warnings.push('Could not parse LLM layout response: ' + err.message);
    node.warn('PPTX layout parse failed: ' + err.message);
  }
}

layoutReferences = layoutReferences.map((item) => {
  const idx = Number(item._referenceIndex || item.index || item.N || 0);
  const current = sanitizeLayout(byIndex.get(idx) || item, profile);
  warnings.push(...capacityWarningsForReference(current, profile, idx));
  return current;
});

data.layoutReferences = layoutReferences;
if (variant === 'sectorial' && Boolean(layout.candidates && layout.candidates.length) && !layout.llmUsed) {
  warnings.push('Modo sectorial: no se pudo aplicar la reformulacion comercial del LLM; se usara el fallback determinista disponible.');
}

data.layoutAdaptation = {
  strategy: profile.strategy || 'runtime_template_geometry_fit',
  variant,
  sectorOutputFormat,
  llmRequested: Boolean(layout.candidates && layout.candidates.length),
  llmUsed: Boolean(layout.llmUsed),
  llmModel: layout.llmModel || profile.llm?.model || null,
  adaptedCount,
  templateMeasurement: profile.templateMeasurement || null,
  warnings: dedupeWarnings(warnings),
  contentFitVersion: 'v17_general_sectorial_soft_parser_coverage'
};

msg.pptxLayoutWarnings = data.layoutAdaptation.warnings;
msg.payload.data = data;
node.warn('PPTX layout v17 parsed: variant=' + variant + ', sector_outputformat=' + sectorOutputFormat + ', llmUsed=' + Boolean(layout.llmUsed) + ', adapted=' + adaptedCount + ', refs=' + layoutReferences.length);
return msg;

node.warn('PPTX layout: call LLM enabler v16 shared general/sectorial');

const axios = require('axios');

const AXET_BASE_URL = 'https://axet.nttdata.com';
const LLM_URL = AXET_BASE_URL + '/api/llm-enabler/v3/ntt/v1/responses';
const ASSETS_URL = AXET_BASE_URL + '/api/core/v1/assets/search';

/**
 * Cambia estos flags si necesitas más o menos ruido en logs.
 * No se imprime el bearer token completo nunca.
 */
const DEBUG_LLM = true;
const DEBUG_PROMPT = false;
const DEBUG_RESPONSE = true;
const MAX_LOG_CHARS = 6000;

function firstValue() {
  for (const v of arguments) {
    if (v !== undefined && v !== null && String(v).trim()) {
      return String(v).trim();
    }
  }

  return '';
}

function firstValueWithSource(candidates) {
  for (const item of candidates) {
    if (!item) continue;

    const value = item.value;

    if (value !== undefined && value !== null && String(value).trim()) {
      return {
        value: String(value).trim(),
        source: item.source || 'unknown'
      };
    }
  }

  return {
    value: '',
    source: 'missing'
  };
}

function truncate(value, maxChars) {
  const text = typeof value === 'string' ? value : safeStringify(value);
  const limit = Number(maxChars || MAX_LOG_CHARS);

  if (!text || text.length <= limit) {
    return text;
  }

  return text.slice(0, limit) + '... [truncated ' + (text.length - limit) + ' chars]';
}

function safeStringify(value, maxChars) {
  let text = '';

  try {
    text = JSON.stringify(value, null, 2);
  } catch (err) {
    text = String(value);
  }

  return maxChars ? truncate(text, maxChars) : text;
}

function mask(value, visibleStart, visibleEnd) {
  const text = String(value || '');

  if (!text) {
    return '';
  }

  const start = Number(visibleStart ?? 6);
  const end = Number(visibleEnd ?? 4);

  if (text.length <= start + end) {
    return text[0] + '***' + text[text.length - 1];
  }

  return text.slice(0, start) + '...' + text.slice(-end);
}

function maskToken(value) {
  const text = String(value || '');

  if (!text) {
    return '';
  }

  return mask(text, 10, 8) + ' len=' + text.length;
}

function maskHeaders(headers) {
  const out = { ...(headers || {}) };

  if (out.Authorization) {
    out.Authorization = 'Bearer ' + maskToken(String(out.Authorization).replace(/^Bearer\s+/i, ''));
  }

  if (out.authorization) {
    out.authorization = 'Bearer ' + maskToken(String(out.authorization).replace(/^Bearer\s+/i, ''));
  }

  if (out['axet-project-id']) {
    out['axet-project-id'] = mask(out['axet-project-id'], 8, 6);
  }

  if (out['axet-user-id']) {
    out['axet-user-id'] = mask(out['axet-user-id'], 8, 6);
  }

  if (out['axet-asset-id']) {
    out['axet-asset-id'] = mask(out['axet-asset-id'], 8, 6);
  }

  return out;
}

function logBlock(title, value, maxChars) {
  if (!DEBUG_LLM) {
    return;
  }

  node.warn('===== ' + title + ' =====');
  node.warn(truncate(typeof value === 'string' ? value : safeStringify(value), maxChars || MAX_LOG_CHARS));
  node.warn('===== /' + title + ' =====');
}

function getLoginKey(msg) {
  const sec = msg.__axetFlowsSecurityContext || {};
  const idp = sec.externalIdpUserInfo || {};
  const raw = firstValue(sec.login, idp.preferred_username, idp.email, msg.axet_user_id, msg.userId, 'anonymous');

  return raw.includes('@') ? raw.split('@')[0] : raw;
}

async function resolveAssetIdIfNeeded(security, msg) {
  if (security.assetId) {
    node.warn('PPTX layout: assetId already available from ' + security.sources.assetId + ' -> ' + mask(security.assetId, 8, 6));
    return security.assetId;
  }

  if (!security.bearerToken) {
    node.warn('PPTX layout: assetId lookup skipped because bearerToken is missing');
    return '';
  }

  const userKey = getLoginKey(msg);
  const cache = global.get('assetId_cache') || {};

  if (cache[userKey]) {
    node.warn('PPTX layout: assetId cache HIT for ' + userKey + ' -> ' + mask(cache[userKey], 8, 6));
    security.sources.assetId = 'global.assetId_cache[' + userKey + ']';
    return cache[userKey];
  }

  node.warn('PPTX layout: assetId cache MISS for ' + userKey + '. Calling assets/search...');

  const headers = {
    authorization: 'Bearer ' + security.bearerToken,
    'content-type': 'application/json'
  };

  logBlock('ASSET LOOKUP REQUEST', {
    url: ASSETS_URL,
    method: 'POST',
    headers: maskHeaders(headers),
    payload: { search: {} }
  }, 3000);

  try {
    const rsp = await axios.post(ASSETS_URL, { search: {} }, {
      headers,
      timeout: 30000,
      validateStatus: () => true
    });

    logBlock('ASSET LOOKUP RESPONSE SUMMARY', {
      status: rsp.status,
      statusText: rsp.statusText,
      dataKeys: rsp.data && typeof rsp.data === 'object' ? Object.keys(rsp.data) : [],
      dataPreview: truncate(safeStringify(rsp.data), 3000)
    }, 5000);

    if (rsp.status < 200 || rsp.status >= 300) {
      node.warn('PPTX layout: assetId lookup HTTP error status=' + rsp.status + ' statusText=' + rsp.statusText);
      return '';
    }

    const arr = Array.isArray(rsp?.data?.data) ? rsp.data.data : [];

    node.warn('PPTX layout: assets/search returned ' + arr.length + ' assets');

    const assetSummary = arr.slice(0, 20).map((x) => ({
      id: mask(x?.id, 8, 6),
      code: x?.code,
      displayName: x?.displayName
    }));

    logBlock('ASSET LOOKUP ASSETS SUMMARY', assetSummary, 4000);

    const core = arr.find((x) => {
      return String(x.code || '').toUpperCase() === 'CORE' || String(x.displayName || '').toLowerCase() === 'core';
    });

    if (core && core.id) {
      cache[userKey] = core.id;
      global.set('assetId_cache', cache);
      security.sources.assetId = 'assets/search CORE';
      node.warn('PPTX layout: assetId resolved from CORE -> ' + mask(core.id, 8, 6));

      return core.id;
    }

    node.warn('PPTX layout: assetId lookup did not find CORE asset');
  } catch (err) {
    logAxiosError('ASSET LOOKUP ERROR', err, {
      url: ASSETS_URL,
      method: 'POST',
      headers: maskHeaders(headers),
      payload: { search: {} }
    });

    node.warn('PPTX layout: assetId lookup failed: ' + err.message);
  }

  return '';
}

async function resolveSecurity(msg) {
  const sec = msg.__axetFlowsSecurityContext || {};
  const idp = sec.externalIdpUserInfo || {};
  const loginKey = getLoginKey(msg);
  const globalSec = global.get('axetFlowsSecurityContext_' + loginKey) || {};
  const credentials = msg.credentials || msg.submission?.talkg_credentials || msg.onInitSubmission?.talkg_credentials || {};

  const bearer = firstValueWithSource([
    { source: 'msg.__axetFlowsSecurityContext.externalIdpUserInfo.access_token', value: idp.access_token },
    { source: 'msg.__axetFlowsSecurityContext.externalIdpUserInfo.access_token_alt', value: sec.externalIdpUserInfo?.access_token },
    { source: 'msg.credentials.bearer_token', value: credentials.bearer_token },
    { source: 'msg.credentials.bearerToken', value: credentials.bearerToken },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.bearerToken', value: globalSec.bearerToken },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.bearer_token', value: globalSec.bearer_token }
  ]);

  const user = firstValueWithSource([
    { source: 'msg.__axetFlowsSecurityContext.axetUserId', value: sec.axetUserId },
    { source: 'msg.axet_user_id', value: msg.axet_user_id },
    { source: 'msg.credentials.axet_user_id', value: credentials.axet_user_id },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.axet_user_id', value: globalSec.axet_user_id },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.user_id', value: globalSec.user_id }
  ]);

  const project = firstValueWithSource([
    { source: 'msg.__axetFlowsSecurityContext.axetProject.id', value: sec.axetProject?.id },
    { source: 'msg.axet_project_id', value: msg.axet_project_id },
    { source: 'msg.credentials.axet_project_id', value: credentials.axet_project_id },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.axet_project_id', value: globalSec.axet_project_id }
  ]);

  const asset = firstValueWithSource([
    { source: 'msg.assetId', value: msg.assetId },
    { source: 'msg.credentials.assetId', value: credentials.assetId },
    { source: 'msg.credentials.asset_id', value: credentials.asset_id },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.asset_id', value: globalSec.asset_id },
    { source: 'global.axetFlowsSecurityContext_' + loginKey + '.assetId', value: globalSec.assetId }
  ]);

  const security = {
    bearerToken: bearer.value,
    userId: user.value,
    projectId: project.value,
    assetId: asset.value,
    sources: {
      bearerToken: bearer.source,
      userId: user.source,
      projectId: project.source,
      assetId: asset.source
    },
    loginKey
  };

  security.assetId = await resolveAssetIdIfNeeded(security, msg);

  return security;
}

function chunkArray(arr, size) {
  const out = [];

  for (let i = 0; i < arr.length; i += size) {
    out.push(arr.slice(i, i + size));
  }

  return out;
}

function slimProfile(profile, layout) {
  const limits = profile?.limits || {};
  const keep = [
    'TITULO_PROYECTO', 'CLIENTE', 'SECTOR', 'PAIS_EJECUCION', 'FECHA_INICIO', 'FECHA_FIN',
    'DURACION_MESES', 'IMPORTE_TOTAL', 'VOLUMEN_USUARIOS', 'IDIOMA_TRABAJO', 'TIPO_SERVICIO',
    'TIPO_PROYECTO', 'OBJETIVOS', 'TAREAS', 'RESULTADOS', 'TECNOLOGIAS', 'METODOLOGIAS',
    'CPV', 'PALABRAS_CLAVE', 'PERFILES_PROFESIONALES', 'FUENTES'
  ];
  const outLimits = {};
  for (const key of keep) {
    if (limits[key]) outLimits[key] = limits[key];
  }

  return {
    templateCode: profile?.templateCode || 'PPTX_runtime_layout',
    strategy: profile?.strategy || 'runtime_template_geometry_fit',
    variant: layout?.variant || profile?.variant || 'general',
    sectorOutputFormat: layout?.sectorOutputFormat || profile?.sectorOutputFormat || 'general',
    instruction: layout?.profileInstruction || 'Fit output to the runtime-measured PowerPoint boxes without truncating facts.',
    limits: outLimits,
    fontRules: profile?.fontRules || {},
    instanceFontRules: profile?.instanceFontRules || {},
    shapeGeometry: profile?.shapeGeometry || {},
    templateMeasurement: profile?.templateMeasurement || null
  };
}

function extractResponseText(data) {
  if (!data) {
    return '';
  }

  if (typeof data === 'string') {
    return data;
  }

  if (typeof data.output_text === 'string') {
    return data.output_text;
  }

  if (typeof data.text === 'string') {
    return data.text;
  }

  if (typeof data.content === 'string') {
    return data.content;
  }

  if (Array.isArray(data.choices) && data.choices[0]?.message?.content) {
    return String(data.choices[0].message.content);
  }

  const pieces = [];

  function walk(x) {
    if (!x) return;

    if (typeof x === 'string') {
      pieces.push(x);
      return;
    }

    if (Array.isArray(x)) {
      x.forEach(walk);
      return;
    }

    if (typeof x === 'object') {
      if (typeof x.text === 'string') pieces.push(x.text);
      if (typeof x.output_text === 'string') pieces.push(x.output_text);
      if (typeof x.content === 'string') pieces.push(x.content);
      if (Array.isArray(x.content)) walk(x.content);
      if (Array.isArray(x.output)) walk(x.output);
      if (Array.isArray(x.message?.content)) walk(x.message.content);
    }
  }

  walk(data.output || data);

  return pieces.join('\n').trim();
}

function buildErrorDetail(err) {
  const status = err.response?.status;
  const statusText = err.response?.statusText;
  const responseData = err.response?.data;
  const responseHeaders = err.response?.headers;
  const requestId =
    responseHeaders?.['x-request-id'] ||
    responseHeaders?.['x-correlation-id'] ||
    responseHeaders?.['x-amzn-requestid'] ||
    responseHeaders?.['x-ms-request-id'] ||
    '';

  return {
    message: err.message,
    code: err.code,
    name: err.name,
    status,
    statusText,
    requestId,
    responseData,
    responseHeaders,
    isAxiosError: Boolean(err.isAxiosError)
  };
}

function logAxiosError(title, err, requestSummary) {
  const detail = buildErrorDetail(err);

  logBlock(title, {
    error: {
      message: detail.message,
      code: detail.code,
      name: detail.name,
      isAxiosError: detail.isAxiosError,
      status: detail.status,
      statusText: detail.statusText,
      requestId: detail.requestId
    },
    responseHeaders: detail.responseHeaders,
    responseData: detail.responseData,
    request: requestSummary
  }, MAX_LOG_CHARS);

  if (detail.status === 401) {
    node.warn('PPTX layout LLM auth hint: 401 Unauthorized. Token may be expired or invalid.');
  }

  if (detail.status === 403) {
    node.warn('PPTX layout LLM auth hint: 403 Forbidden. Token is present but user/project/asset/model may not be authorized.');
  }

  if (detail.status === 404) {
    node.warn('PPTX layout LLM auth hint: 404 Not Found. Check endpoint URL or API route.');
  }

  if (detail.status === 429) {
    node.warn('PPTX layout LLM auth hint: 429 Rate limit/quota issue.');
  }

  if (detail.status >= 500) {
    node.warn('PPTX layout LLM auth hint: server-side error from enabler.');
  }
}

function dedupeWarnings(warnings) {
  const seen = new Set();
  const out = [];

  for (const warning of warnings || []) {
    const text = String(warning || '').trim();

    if (!text || seen.has(text)) {
      continue;
    }

    seen.add(text);
    out.push(text);
  }

  return out;
}

