function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFC')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\u00A0/g, ' ')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

function clean(value) {
  return normalizeText(value)
    .replace(/[\t ]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function keyNorm(value) {
  return clean(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}


function nodeLocalNameForMeasure(node) {
  return String(node?.localName || node?.nodeName || '').split(':').pop();
}

function firstDescendantForMeasure(node, localName) {
  if (!node) return null;
  const queue = [];
  for (let child = node.firstChild; child; child = child.nextSibling) queue.push(child);
  while (queue.length) {
    const cur = queue.shift();
    if (nodeLocalNameForMeasure(cur) === localName) return cur;
    for (let child = cur.firstChild; child; child = child.nextSibling) queue.push(child);
  }
  return null;
}

function readShapeGeomForMeasure(sp) {
  const xfrm = firstDescendantForMeasure(sp, 'xfrm');
  if (!xfrm) return null;
  let off = null;
  let ext = null;
  for (let child = xfrm.firstChild; child; child = child.nextSibling) {
    if (nodeLocalNameForMeasure(child) === 'off') off = child;
    if (nodeLocalNameForMeasure(child) === 'ext') ext = child;
  }
  if (!off || !ext) return null;
  const geom = {
    x: Number(off.getAttribute('x') || 0),
    y: Number(off.getAttribute('y') || 0),
    cx: Number(ext.getAttribute('cx') || 0),
    cy: Number(ext.getAttribute('cy') || 0)
  };
  if (!(geom.cx > 0 && geom.cy > 0)) return null;
  return geom;
}

function readInsetsForMeasure(sp) {
  const bodyPr = firstDescendantForMeasure(sp, 'bodyPr');
  // Defaults habituales de DrawingML cuando no hay atributo explicito.
  const defaults = { lIns: 91440, rIns: 91440, tIns: 45720, bIns: 45720 };
  if (!bodyPr) return defaults;
  const out = { ...defaults };
  for (const key of Object.keys(out)) {
    const raw = bodyPr.getAttribute(key);
    if (raw !== null && raw !== '') {
      const n = Number(raw);
      if (Number.isFinite(n) && n >= 0) out[key] = n;
    }
  }
  return out;
}

function median(values) {
  const arr = (values || []).filter((x) => Number.isFinite(x) && x > 0).sort((a, b) => a - b);
  if (!arr.length) return null;
  const mid = Math.floor(arr.length / 2);
  return arr.length % 2 ? arr[mid] : (arr[mid - 1] + arr[mid]) / 2;
}

function readFontPtForMeasure(sp, fallbackPt) {
  const props = xpath.select(".//*[local-name()='rPr' or local-name()='defRPr' or local-name()='endParaRPr']", sp) || [];
  const sizes = [];
  for (const pr of props) {
    const raw = pr.getAttribute && pr.getAttribute('sz');
    if (!raw) continue;
    const pt = Number(raw) / 100;
    if (Number.isFinite(pt) && pt >= 5 && pt <= 40) sizes.push(pt);
  }
  return median(sizes) || Number(fallbackPt || 8);
}

function placeholderCanonicalKey(token) {
  const map = {
    REF_OBJETIVOS: 'OBJETIVOS',
    REF_CONTEXTO_RETOS: 'OBJETIVOS',
    REF_TAREAS: 'TAREAS',
    REF_ACTIVIDADES_CLAVE: 'TAREAS',
    REF_RESULTADOS: 'RESULTADOS',
    REF_TECNOLOGIAS: 'TECNOLOGIAS',
    REF_METODOLOGIAS: 'METODOLOGIAS',
    REF_KEYWORDS: 'PALABRAS_CLAVE',
    REF_PALABRAS_CLAVE: 'PALABRAS_CLAVE',
    REF_PERFILES: 'PERFILES_PROFESIONALES',
    REF_FUENTES: 'FUENTES'
  };
  return map[token] || token;
}

function capacityFromShape(field, shapeText, geom, insets, targetFontPt, minFontPt) {
  const usableCx = Math.max(12700, Number(geom.cx || 0) - Number(insets.lIns || 0) - Number(insets.rIns || 0));
  const usableCy = Math.max(12700, Number(geom.cy || 0) - Number(insets.tIns || 0) - Number(insets.bIns || 0));
  const widthPt = usableCx / EMU_PER_PT;
  const heightPt = usableCy / EMU_PER_PT;
  const targetPt = Math.max(5, Number(targetFontPt || 8));
  const minPt = Math.max(5, Math.min(targetPt, Number(minFontPt || targetPt * 0.84)));
  const isBullets = field === 'TAREAS' || field === 'RESULTADOS';
  const wrapFactor = isBullets ? 0.55 : 0.51;
  const fillFactor = isBullets ? 0.78 : 0.86;
  const lineHeightFactor = isBullets ? 1.24 : 1.20;

  const charsPerLine = Math.max(8, Math.floor(widthPt / (targetPt * wrapFactor)));
  const targetLines = Math.max(1, Math.floor(heightPt / (targetPt * lineHeightFactor)));
  const hardCharsPerLine = Math.max(charsPerLine, Math.floor(widthPt / (minPt * wrapFactor)));
  const hardLines = Math.max(targetLines, Math.floor(heightPt / (minPt * 1.16)));

  const placeholderRx = /\{\{[A-Z0-9_]+\}\}/g;
  const staticText = clean(String(shapeText || '').replace(placeholderRx, ' '));
  const staticCost = staticText.length;

  const targetCapacity = Math.max(24, Math.floor(charsPerLine * targetLines * fillFactor) - staticCost);
  const hardCapacity = Math.max(targetCapacity, Math.floor(hardCharsPerLine * hardLines * Math.min(0.91, fillFactor + 0.08)) - staticCost);

  return {
    field,
    x: geom.x,
    y: geom.y,
    cx: geom.cx,
    cy: geom.cy,
    widthPt: Math.round(widthPt * 10) / 10,
    heightPt: Math.round(heightPt * 10) / 10,
    targetFontPt: Math.round(targetPt * 100) / 100,
    minFontPt: Math.round(minPt * 100) / 100,
    charsPerLine,
    targetLines,
    hardLines,
    targetCapacityChars: targetCapacity,
    hardCapacityChars: hardCapacity,
    staticTextChars: staticCost,
    measuredFromTemplate: true
  };
}

function templateNameFromMsg(msg) {
  return String(
    msg.payload?.template ||
    msg.submission?.data?.template ||
    msg.submission?.plantilla ||
    msg.plantilla ||
    ''
  ).trim();
}

function measureTemplateRuntime(msg, profile) {
  const warnings = [];
  const template = templateNameFromMsg(msg);
  if (!template) {
    return { ok: false, template: '', slide: '', fields: {}, presentPlaceholders: [], warnings: ['No se pudo medir la plantilla: template no informado. Se usaran limites fallback.'] };
  }

  const safeTemplate = path.basename(template);
  const templatePath = path.join(TEMPLATES_DIR, safeTemplate);
  if (!fs.existsSync(templatePath)) {
    return { ok: false, template: safeTemplate, slide: '', fields: {}, presentPlaceholders: [], warnings: ['No se pudo medir la plantilla: no existe ' + templatePath + '. Se usaran limites fallback.'] };
  }

  try {
    const zip = new AdmZipForMeasure(templatePath);
    const slideEntries = zip.getEntries()
      .map((e) => e.entryName)
      .filter((n) => /^ppt\/slides\/slide\d+\.xml$/i.test(n))
      .sort((a, b) => {
        const na = Number((a.match(/slide(\d+)\.xml/i) || [0, 0])[1]);
        const nb = Number((b.match(/slide(\d+)\.xml/i) || [0, 0])[1]);
        return na - nb;
      });

    let chosen = null;
    for (const slideName of slideEntries) {
      const xml = zip.getEntry(slideName)?.getData().toString('utf8') || '';
      if (RUNTIME_MEASURED_FIELDS.some((key) => xml.includes('{{' + key + '}}')) || xml.includes('{{REF_')) {
        chosen = { slideName, xml };
        break;
      }
    }

    if (!chosen) {
      return { ok: false, template: safeTemplate, slide: '', fields: {}, presentPlaceholders: [], warnings: ['No se encontro en la plantilla una slide con placeholders de referencia. Se usaran limites fallback.'] };
    }

    const doc = new DOMParser().parseFromString(chosen.xml, 'text/xml');
    const shapes = xpath.select("//*[local-name()='sp']", doc) || [];
    const fields = {};
    const presentPlaceholderSet = new Set();
    const presentRx = /\{\{([A-Z0-9_]+)\}\}/g;
    let presentMatch;
    while ((presentMatch = presentRx.exec(chosen.xml)) !== null) {
      presentPlaceholderSet.add(placeholderCanonicalKey(presentMatch[1]));
    }
    const presentPlaceholders = Array.from(presentPlaceholderSet);

    for (const sp of shapes) {
      const tNodes = xpath.select(".//*[local-name()='t']", sp) || [];
      if (!tNodes.length) continue;
      const text = tNodes.map((n) => String(n.textContent || '')).join('');
      const tokens = [];
      const rx = /\{\{([A-Z0-9_]+)\}\}/g;
      let m;
      while ((m = rx.exec(text)) !== null) tokens.push(placeholderCanonicalKey(m[1]));
      if (!tokens.length) continue;

      const geom = readShapeGeomForMeasure(sp);
      if (!geom) continue;
      const insets = readInsetsForMeasure(sp);

      for (const field of tokens) {
        if (!RUNTIME_MEASURED_FIELDS.includes(field)) continue;
        const fallbackRule = profile.fontRules?.[field] || {};
        const targetPt = readFontPtForMeasure(sp, fallbackRule.base || profile.limits?.[field]?.fontPt?.base || 8);
        const minPt = Math.min(targetPt, Number(fallbackRule.min || profile.limits?.[field]?.fontPt?.min || targetPt * 0.84));
        const cap = capacityFromShape(field, text, geom, insets, targetPt, minPt);

        // Si un placeholder aparece varias veces, usamos la caja mas restrictiva
        // para garantizar que el contenido quepa en todas sus apariciones.
        if (!fields[field] || cap.targetCapacityChars < fields[field].targetCapacityChars) {
          fields[field] = cap;
        }
      }
    }

    for (const field of RUNTIME_MEASURED_FIELDS) {
      if (presentPlaceholderSet.has(field) && !fields[field]) {
        warnings.push('No se pudo medir el placeholder ' + field + ' en ' + chosen.slideName + '; se mantiene su fallback.');
      }
    }

    return {
      ok: Object.keys(fields).length > 0,
      template: safeTemplate,
      templatePath,
      slide: chosen.slideName,
      fields,
      presentPlaceholders,
      warnings
    };
  } catch (err) {
    return { ok: false, template: safeTemplate, slide: '', fields: {}, presentPlaceholders: [], warnings: ['Error midiendo la plantilla PPTX: ' + err.message + '. Se usaran limites fallback.'] };
  }
}

function applyRuntimeMeasurement(profile, measurement) {
  const out = {
    ...profile,
    limits: { ...(profile.limits || {}) },
    fontRules: { ...(profile.fontRules || {}) },
    templateMeasurement: {
      ok: Boolean(measurement?.ok),
      template: measurement?.template || '',
      slide: measurement?.slide || '',
      fields: measurement?.fields || {},
      presentPlaceholders: measurement?.presentPlaceholders || [],
      measuredAtRuntime: true
    }
  };

  for (const [field, cap] of Object.entries(measurement?.fields || {})) {
    const oldLimit = out.limits[field] || {};
    const oldRule = out.fontRules[field] || {};
    const isBullets = field === 'TAREAS' || field === 'RESULTADOS';
    const maxBullets = isBullets
      ? Math.max(2, Math.min(8, Math.floor(cap.targetLines / 2) || Number(oldLimit.maxBullets || 5)))
      : oldLimit.maxBullets;

    out.limits[field] = {
      ...oldLimit,
      source: 'runtime_template_geometry',
      measuredWidthPt: cap.widthPt,
      measuredHeightPt: cap.heightPt,
      targetFontPt: cap.targetFontPt,
      minFontPt: cap.minFontPt,
      targetLines: cap.targetLines,
      hardLines: cap.hardLines,
      maxChars: cap.targetCapacityChars,
      hardMaxChars: cap.hardCapacityChars,
      ...(isBullets ? {
        maxBullets,
        maxTotalChars: cap.targetCapacityChars,
        hardMaxTotalChars: cap.hardCapacityChars,
        maxCharsPerBullet: Math.max(55, Math.floor(cap.targetCapacityChars / Math.max(1, maxBullets) * 0.93))
      } : {}),
      fontPt: {
        min: cap.minFontPt,
        base: cap.targetFontPt,
        max: Math.max(cap.targetFontPt, Number(oldLimit.fontPt?.max || oldRule.max || cap.targetFontPt))
      }
    };

    out.fontRules[field] = {
      ...oldRule,
      min: cap.minFontPt,
      base: cap.targetFontPt,
      max: Math.max(cap.targetFontPt, Number(oldRule.max || cap.targetFontPt)),
      soft: cap.targetCapacityChars,
      hard: cap.hardCapacityChars,
      targetLines: cap.targetLines,
      maxLines: cap.hardLines,
      measuredWidthPt: cap.widthPt,
      measuredHeightPt: cap.heightPt,
      source: 'runtime_template_geometry'
    };
  }

  return out;
}

function fitTargetForPrompt(profile, field) {
  const l = profile?.limits?.[field] || {};
  return {
    source: l.source || 'fallback_profile',
    widthPt: l.measuredWidthPt || null,
    heightPt: l.measuredHeightPt || null,
    targetFontPt: l.targetFontPt || l.fontPt?.base || null,
    minFontPt: l.minFontPt || l.fontPt?.min || null,
    targetLines: l.targetLines || l.maxLines || profile?.fontRules?.[field]?.targetLines || null,
    hardLines: l.hardLines || profile?.fontRules?.[field]?.maxLines || null,
    targetChars: l.maxTotalChars || l.maxChars || null,
    hardChars: l.hardMaxTotalChars || l.hardMaxChars || profile?.fontRules?.[field]?.hard || null,
    maxBullets: l.maxBullets || null,
    maxCharsPerBullet: l.maxCharsPerBullet || null
  };
}

function isNoData(value) {
  const raw = clean(value);
  const s = keyNorm(raw);
  if (!s || ['no hallado', 'no encontrado', 'no disponible', 'n a', 'na', 'null', '-'].includes(s)) {
    return true;
  }

  const noDataPatterns = [
    /^no exact\b/,
    /^no explicit\b/,
    /^no specific\b/,
    /^not specified\b/,
    /^not available\b/,
    /^not found\b/,
    /^not identified\b/,
    /^not provided\b/,
    /^no\s+.*\s+found\b/,
    /^no\s+cpv\b/,
    /\bwas not found\b/,
    /\bwas found in the parseable documentation\b/,
    /\bprovided documentation\b.*\bdoes not specify\b/,
    /^sin informacion\b/,
    /^sin datos\b/,
    /^no se ha encontrado\b/,
    /^no se han encontrado\b/,
    /^no se ha identificado\b/,
    /^no se han identificado\b/,
    /^no se encontro\b/,
    /^no consta\b/
  ];

  return noDataPatterns.some((rx) => rx.test(s));
}

function removeEllipses(value) {
  return clean(value)
    .replace(/\.{3,}/g, '')
    .replace(/\u2026/g, '')
    .replace(/[\s,;:.\-]+$/g, '')
    .trim();
}

function repairOpenTail(value) {
  let s = removeEllipses(value);
  const opens = (s.match(/\(/g) || []).length;
  const closes = (s.match(/\)/g) || []).length;
  if (opens > closes) {
    // Si un corte deja un parentesis abierto, retiramos el bloque parentetico completo.
    // Es preferible una frase mas corta pero cerrada que una enumeracion a medias.
    const idx = s.lastIndexOf('(');
    if (idx > 0) {
      s = s.slice(0, idx).trim();
    }
  }
  s = s.replace(/\b(including|incluyendo|and|y|with|con|plus|mas|de|del|la|el|los|las|para|por|sobre|su|sus|fecha)$/i, '').trim();
  return s;
}

function smartCut(value, maxChars) {
  let s = clean(value);
  if (!maxChars || s.length <= maxChars) return repairOpenTail(s);

  let cut = s.slice(0, maxChars).trim();

  // No usamos la coma como punto de corte: era la causa directa de fragmentos
  // como "A nivel de negocio" y de enumeraciones de TAREAS partidas a mitad.
  const lastStop = Math.max(
    cut.lastIndexOf('. '),
    cut.lastIndexOf('; '),
    cut.lastIndexOf('\n'),
    cut.lastIndexOf(' - '),
    cut.lastIndexOf(' \u2014 ')
  );

  if (lastStop > Math.floor(maxChars * 0.55)) {
    cut = cut.slice(0, lastStop + 1).trim();
  } else {
    const lastSpace = cut.lastIndexOf(' ');
    if (lastSpace > Math.floor(maxChars * 0.68)) cut = cut.slice(0, lastSpace).trim();
  }

  return repairOpenTail(cut);
}

function valueOrDash(value, limit) {
  let s = clean(value);
  if (isNoData(s)) return '-';
  const max = limit && limit.maxChars ? Number(limit.maxChars) : null;
  if (max && s.length > max) s = smartCut(s, max);
  return repairOpenTail(s) || '-';
}

function splitCandidates(value) {
  if (Array.isArray(value)) {
    return value.map(clean).filter((x) => x && !isNoData(x));
  }

  const text = clean(value);
  if (!text || isNoData(text)) return [];

  let parts = text
    .split(/\n+/g)
    .map((line) => line.replace(/^\s*[-*\u2022]+\s*/g, '').replace(/^\s*[0-9]+[.)]\s*/g, '').trim())
    .filter(Boolean);

  if (parts.length <= 1 && text.includes(';')) {
    parts = text.split(/;\s*/g).map((x) => x.trim()).filter(Boolean);
  }

  if (parts.length <= 1) {
    parts = text.split(/(?<=[.!?])\s+(?=[A-Z0-9\u00c0-\u017f])/g).map((x) => x.trim()).filter(Boolean);
  }

  const out = [];
  const seen = new Set();
  for (const item of parts) {
    const s = clean(item);
    if (!s || isNoData(s)) continue;
    const k = keyNorm(s);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(s);
  }
  return out;
}


function parseTaskSections(value) {
  if (Array.isArray(value)) {
    return value
      .map((item) => {
        if (item && typeof item === 'object') {
          const title = clean(item.title || item.heading || item.name || item.fase || item.section || '');
          const detailsRaw = item.details || item.items || item.children || item.subtasks || [];
          const details = Array.isArray(detailsRaw) ? detailsRaw.map(clean).filter(Boolean) : splitCandidates(detailsRaw);
          return title ? { title, details } : null;
        }
        const title = clean(item);
        return title ? { title, details: [] } : null;
      })
      .filter(Boolean);
  }

  const raw = normalizeText(value);
  if (!raw || isNoData(raw)) return [];

  const rows = [];
  for (const lineRaw of raw.split('\n')) {
    if (!lineRaw.trim()) continue;
    const bullet = lineRaw.match(/^(\s*)[-*\u2022]+\s+(.*)$/);
    if (bullet) {
      const indent = String(bullet[1] || '').replace(/\t/g, '    ').length;
      const text = clean(bullet[2]);
      if (text) rows.push({ indent, text });
      continue;
    }

    // Si una linea viene envuelta sin marcador, la anexamos al elemento anterior.
    if (rows.length) {
      rows[rows.length - 1].text = clean(rows[rows.length - 1].text + ' ' + lineRaw.trim());
    }
  }

  if (!rows.length) {
    return splitCandidates(raw).map((title) => ({ title, details: [] }));
  }

  const minIndent = Math.min(...rows.map((x) => x.indent));
  const sections = [];
  for (const row of rows) {
    if (row.indent === minIndent || !sections.length) {
      sections.push({ title: row.text, details: [] });
    } else {
      sections[sections.length - 1].details.push(row.text);
    }
  }
  return sections;
}

function formatTaskBullets(value, limit) {
  const opts = limit || {};
  const configuredMaxBullets = opts.maxBullets || 6;
  const maxTotalChars = opts.maxTotalChars || opts.maxChars || 650;
  const hardLines = opts.hardLines || 20;
  const sections = parseTaskSections(value);
  const hasHierarchy = sections.length > 1 && sections.some((s) => Array.isArray(s.details) && s.details.length);

  if (!hasHierarchy) {
    return formatBullets(value, limit);
  }

  const maxBullets = sections.length <= hardLines ? Math.max(configuredMaxBullets, sections.length) : configuredMaxBullets;
  const perSectionBudget = Math.max(45, Math.floor(maxTotalChars / Math.max(1, Math.min(sections.length, maxBullets))) - 3);
  const selected = [];

  for (const section of sections.slice(0, maxBullets)) {
    const title = repairOpenTail(section.title);
    let item = title;
    const firstDetail = section.details?.[0] ? repairOpenTail(section.details[0]) : '';
    if (firstDetail) {
      const candidate = title + ': ' + firstDetail;
      if (candidate.length <= perSectionBudget) item = candidate;
    }
    selected.push(item);
  }

  const rawText = normalizeText(value);
  const totalChars = rawText.length;
  return {
    text: selected.map((x) => BULLET + ' ' + x).join('\n') || '-',
    items: selected,
    rawCount: sections.length,
    totalChars,
    overflow: totalChars > maxTotalChars || sections.length > configuredMaxBullets,
    utilization: maxTotalChars ? Math.max(sections.length / Math.max(1, configuredMaxBullets), totalChars / maxTotalChars) : 1,
    hierarchical: true,
    sections
  };
}

function formatBullets(value, limit) {
  const opts = limit || {};
  const maxBullets = opts.maxBullets || 5;
  const maxCharsPerBullet = opts.maxCharsPerBullet || 105;
  const maxTotalChars = opts.maxTotalChars || (maxBullets * maxCharsPerBullet);
  const items = splitCandidates(value);

  if (!items.length) {
    return { text: '-', items: [], rawCount: 0, totalChars: 0, overflow: false, utilization: 0 };
  }

  const selected = [];
  let used = 0;
  let overflow = false;

  for (const raw of items) {
    let item = repairOpenTail(raw);
    if (item.length > maxCharsPerBullet) {
      item = smartCut(item, maxCharsPerBullet);
      overflow = true;
    }

    const projected = used + item.length + 3;
    if (selected.length < maxBullets && projected <= maxTotalChars) {
      selected.push(item);
      used = projected;
    } else {
      overflow = true;
    }
  }

  return {
    text: selected.map((x) => BULLET + ' ' + x).join('\n') || '-',
    items: selected,
    rawCount: items.length,
    totalChars: items.join(' ').length,
    overflow,
    utilization: Math.max(items.length / maxBullets, items.join(' ').length / maxTotalChars)
  };
}

function uniqueItems(values, maxItems) {
  const out = [];
  const seen = new Set();
  for (const raw of values || []) {
    const s = repairOpenTail(raw);
    if (!s || isNoData(s)) continue;
    const k = keyNorm(s);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(s);
    if (maxItems && out.length >= maxItems) break;
  }
  return out;
}

function formatListText(value, limit) {
  const opts = limit || {};
  const maxItems = opts.maxItems || 8;
  const maxChars = opts.maxChars || 180;
  const rawItems = splitCandidates(value);
  const items = uniqueItems(rawItems, maxItems);
  const joined = items.length ? items.join(', ') : clean(value);
  const text = isNoData(joined) ? '-' : smartCut(joined, maxChars);

  return {
    text,
    rawChars: clean(value).length,
    rawCount: rawItems.length,
    utilization: maxChars ? clean(value).length / maxChars : 0,
    overflow: clean(value).length > maxChars || rawItems.length > maxItems
  };
}

function splitSentencesComplete(text) {
  return clean(text)
    .split(/(?<=[.!?])\s+(?=[A-Z0-9\u00c0-\u017f])/g)
    .map((x) => clean(x))
    .filter(Boolean);
}

function balancedParagraphFit(value, maxChars) {
  const raw = normalizeText(value);
  if (!maxChars || raw.length <= maxChars) return clean(raw);

  const paragraphs = raw.split(/\n\s*\n/g).map(clean).filter(Boolean);
  if (!paragraphs.length) return clean(raw);
  const sentenceGroups = paragraphs.map(splitSentencesComplete);
  const selected = sentenceGroups.map(() => []);
  let used = 0;

  // Primera pasada: conserva al menos una idea completa de cada parrafo/dimension.
  for (let i = 0; i < sentenceGroups.length; i++) {
    const first = sentenceGroups[i][0];
    if (!first) continue;
    const extra = first.length + (used ? 2 : 0);
    if (used + extra <= maxChars || selected.every((x) => x.length === 0)) {
      selected[i].push(first);
      used += extra;
    }
  }

  // Segunda pasada: rellena el espacio con frases completas en orden de origen.
  let progressed = true;
  while (progressed) {
    progressed = false;
    for (let i = 0; i < sentenceGroups.length; i++) {
      const next = sentenceGroups[i][selected[i].length];
      if (!next) continue;
      const extra = next.length + (used ? 1 : 0);
      if (used + extra <= maxChars) {
        selected[i].push(next);
        used += extra;
        progressed = true;
      }
    }
  }

  const out = selected.map((arr) => arr.join(' ')).filter(Boolean).join('\n\n');
  return out || clean(raw);
}

function formatParagraph(value, limit) {
  const opts = limit || {};
  const maxChars = opts.maxChars || 640;
  const text = clean(value);
  if (isNoData(text)) {
    return { text: '-', rawChars: 0, overflow: false, utilization: 0 };
  }

  const rawChars = text.length;
  const overflow = rawChars > maxChars;
  const fitted = overflow ? balancedParagraphFit(text, maxChars) : text;
  return { text: fitted, rawChars, overflow, utilization: maxChars ? rawChars / maxChars : 0 };
}

function compactCountry(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  if (k.includes('union europea') || k.includes('european union') || k.includes('eu member states') || k.includes('estados miembros')) {
    return 'EU Member States';
  }
  return valueOrDash(raw.replace(/^main location:\s*/i, '').replace(/;\s*other locations:\s*/i, '; '), limit);
}

function compactLanguage(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  if (k.includes('english') || k.includes('ingles')) return 'English';
  if (k.includes('spanish') || k.includes('espanol')) return 'Spanish';
  if (k.includes('french') || k.includes('frances')) return 'French';
  return valueOrDash(raw.replace(/^working language:\s*/i, '').replace(/^idioma de trabajo:\s*/i, ''), limit);
}

function compactUsers(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  if (k.includes('4100') && k.includes('124') && (k.includes('4000') || k.includes('external'))) {
    return '4,100+ (124 int.; 4,000+ ext.)';
  }
  const m = raw.match(/over\s*([0-9.,+]+).*?including\s*([0-9.,+]+).*?internal.*?([0-9.,+]+).*?external/i);
  if (m) return String(m[1]).replace('.', ',') + '+ (' + m[2] + ' int.; ' + m[3] + ' ext.)';
  return valueOrDash(raw, limit);
}

function parseAmount(value) {
  const raw = clean(value);
  if (isNoData(raw)) return null;
  const m = raw.match(/([0-9]{1,3}(?:[.,][0-9]{3})*(?:[.,][0-9]{2})?)\s*(eur|euro|euros|\u20ac)?/i);
  if (!m) return null;
  let numText = m[1];
  if (numText.includes('.') && numText.includes(',')) numText = numText.replace(/\./g, '').replace(',', '.');
  else if (numText.includes(',') && /,\d{2}$/.test(numText)) numText = numText.replace(/\./g, '').replace(',', '.');
  else numText = numText.replace(/,/g, '');
  const n = Number(numText);
  if (!Number.isFinite(n)) return null;
  return n;
}

function formatAmountShort(n) {
  if (!Number.isFinite(n)) return '';
  if (n >= 1000000) return (Math.round((n / 1000000) * 100) / 100).toFixed(2).replace(/\.00$/, '') + 'M EUR';
  if (n >= 1000) return (Math.round((n / 1000) * 10) / 10).toFixed(1).replace(/\.0$/, '') + 'k EUR';
  return String(Math.round(n)) + ' EUR';
}

function compactAmount(value, limit, ref, allRefs, idx) {
  const raw = clean(value);
  if (!isNoData(raw)) return valueOrDash(raw, limit);

  const isGeneral = ref && (ref.referenceKind === 'general' || ref.tipoReferencia === 'general' || ref.lote === 'General' || idx === 1);
  if (isGeneral && Array.isArray(allRefs) && allRefs.length > 1) {
    const parts = [];
    for (let i = 1; i < allRefs.length; i++) {
      const amount = parseAmount(allRefs[i] && allRefs[i].importe);
      if (amount) parts.push('L' + i + ': ' + formatAmountShort(amount));
      if (parts.length >= 3) break;
    }
    if (parts.length) return smartCut(parts.join('; '), limit && limit.maxChars ? limit.maxChars : 56);
  }

  return '-';
}

function compactTechnologies(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  const out = [];
  function add(label, cond) { if (cond && !out.includes(label)) out.push(label); }
  add('Azure', k.includes('azure'));
  add('Databricks', k.includes('databricks'));
  add('Angular/eUI', k.includes('angular') || k.includes('eui'));
  add('Spring Boot', k.includes('spring boot'));
  add('SQL stack', k.includes('sql') || k.includes('postgres') || k.includes('mysql') || k.includes('mariadb'));
  add('Synapse/Data Lake', k.includes('synapse') || k.includes('data lake'));
  add('Docker/Kubernetes', k.includes('docker') || k.includes('kubernetes'));
  add('Azure DevOps', k.includes('devops'));
  add('Camunda/BPMN', k.includes('camunda') || k.includes('bpmn') || k.includes('dmn'));
  add('EU tools', k.includes('eu login') || k.includes('eu survey') || k.includes('eu send'));
  add('OpenSearch/Elastic', k.includes('opensearch') || k.includes('elasticsearch'));
  add('Kafka', k.includes('kafka'));

  if (!out.length) return formatListText(raw, limit).text;
  return smartCut(out.join(', '), limit && limit.maxChars ? limit.maxChars : 270);
}

function compactProfiles(value, limit) {
  const raw = clean(value);
  if (isNoData(raw)) return '-';
  const k = keyNorm(raw);
  const out = [];
  function add(label, cond) { if (cond && !out.includes(label)) out.push(label); }
  add('Project/Service Mgmt', k.includes('project') || k.includes('service manager') || k.includes('quality manager') || k.includes('quality assurance'));
  add('Scrum/Agile', k.includes('scrum') || k.includes('agile') || k.includes('methodology'));
  add('BA/TA', k.includes('business analyst') || k.includes('technical analyst') || k.includes('technical manager') || k.includes('functional'));
  add('Solution Architecture', k.includes('solution architect') || k.includes('architecture'));
  add('DevOps/Release', k.includes('devops') || k.includes('release'));
  add('QA/Testing', k.includes('testing') || k.includes('qa') || k.includes('cross testing'));
  add('Data Protection/Cybersecurity', k.includes('data protection') || k.includes('cyber') || k.includes('security') || k.includes('privacy'));
  add('Health Data/MCM experts', k.includes('health data') || k.includes('mcm') || k.includes('epidemiologist') || k.includes('supply chain') || k.includes('simulation'));
  add('Help Desk/Support', k.includes('help desk') || k.includes('helpdesk') || k.includes('support'));

  if (!out.length) return formatListText(raw, limit).text;
  return smartCut(out.join('; '), limit && limit.maxChars ? limit.maxChars : 250);
}

function compactKeywords(value, limit) {
  const rawItems = splitCandidates(value);
  const preferred = [];
  const seen = new Set();
  for (const item of rawItems) {
    const k = keyNorm(item);
    if (!k || seen.has(k)) continue;
    seen.add(k);
    preferred.push(item);
  }
  return smartCut(preferred.slice(0, (limit && limit.maxItems) || 11).join(', '), (limit && limit.maxChars) || 190) || '-';
}

function uniqueSources(ref, profile) {
  const limit = profile.limits.FUENTES || {};
  const maxItems = limit.maxItems || 4;
  const sources = [];
  const seen = new Set();
  const fromFuentes = Array.isArray(ref.fuentes) ? ref.fuentes : String(ref.fuentes || '').split('|');
  const fromFragments = Array.isArray(ref.fragmentosDeReferencia) ? ref.fragmentosDeReferencia.map((f) => f && f.fuente) : [];

  for (const v of [...fromFuentes, ...fromFragments]) {
    let s = clean(v).replace(/\|+$/g, '').trim();
    if (!s || isNoData(s)) continue;
    const k = keyNorm(s);
    if (seen.has(k)) continue;
    seen.add(k);
    sources.push(s);
    if (sources.length >= maxItems) break;
  }

  return smartCut(sources.join(' | '), limit.maxChars || 190) || '-';
}

function buildLayoutReference(ref, idx, total, profile, allRefs) {
  const l = profile.limits || DEFAULT_PROFILE.limits;
  const objetivos = formatParagraph(ref.objetivos, l.OBJETIVOS);
  const tareas = formatTaskBullets(ref.tareas, l.TAREAS);
  const resultados = formatBullets(ref.resultados, l.RESULTADOS);
  const tecnologiasText = compactTechnologies(ref.tecnologias, l.TECNOLOGIAS);
  const metodologias = formatListText(ref.metodologias, l.METODOLOGIAS);
  const palabrasClaveText = compactKeywords(ref.palabrasClave, l.PALABRAS_CLAVE);
  const perfilesText = compactProfiles(ref.perfilesProfesionales || ref.perfiles, l.PERFILES_PROFESIONALES);

  const techRaw = clean(ref.tecnologias).length;
  const perfilesRaw = clean(ref.perfilesProfesionales || ref.perfiles).length;
  const riskThreshold = profile.llm && profile.llm.riskThreshold ? profile.llm.riskThreshold : 0.82;
  const risks = [];
  if (objetivos.overflow || objetivos.utilization >= riskThreshold) risks.push('OBJETIVOS');
  if (tareas.overflow || tareas.utilization >= riskThreshold) risks.push('TAREAS');
  if (resultados.overflow || resultados.utilization >= riskThreshold) risks.push('RESULTADOS');
  if (techRaw > (l.TECNOLOGIAS.maxChars || 270)) risks.push('TECNOLOGIAS');
  if (metodologias.overflow || metodologias.utilization >= 1.05) risks.push('METODOLOGIAS');
  if (clean(ref.palabrasClave).length > (l.PALABRAS_CLAVE.maxChars || 190)) risks.push('PALABRAS_CLAVE');
  if (perfilesRaw > (l.PERFILES_PROFESIONALES.maxChars || 250)) risks.push('PERFILES_PROFESIONALES');

  return {
    _referenceIndex: ref.index || idx,
    _referenceOrder: idx,
    _referenceKind: ref.referenceKind || ref.tipoReferencia || (idx === 1 && total > 1 ? 'general' : 'lote'),
    _layoutSource: 'deterministic_v15_runtime_measured',
    _fit: {
      needsLlm: risks.length > 0,
      riskFields: risks,
      metrics: {
        objetivosChars: objetivos.rawChars,
        tareasRawCount: tareas.rawCount,
        tareasChars: tareas.totalChars,
        resultadosRawCount: resultados.rawCount,
        resultadosChars: resultados.totalChars,
        tecnologiasRawChars: techRaw,
        perfilesRawChars: perfilesRaw
      }
    },
    TITULO_PROYECTO: valueOrDash(ref.titulo || ('Referencia ' + idx), l.TITULO_PROYECTO),
    CLIENTE: valueOrDash(ref.cliente, l.CLIENTE),
    SECTOR: valueOrDash(ref.sector, l.SECTOR),
    PAIS_EJECUCION: compactCountry(ref.pais, l.PAIS_EJECUCION),
    FECHA_INICIO: valueOrDash(ref.fechaInicio, l.FECHA_INICIO),
    FECHA_FIN: valueOrDash(ref.fechaFin, l.FECHA_FIN),
    DURACION_MESES: valueOrDash(ref.duracion, l.DURACION_MESES),
    IMPORTE_TOTAL: compactAmount(ref.importe, l.IMPORTE_TOTAL, ref, allRefs, idx),
    VOLUMEN_USUARIOS: compactUsers(ref.volumenUsuarios, l.VOLUMEN_USUARIOS),
    IDIOMA_TRABAJO: compactLanguage(ref.idiomaTrabajo, l.IDIOMA_TRABAJO),
    TIPO_SERVICIO: valueOrDash(ref.tipoServicio, l.TIPO_SERVICIO),
    TIPO_PROYECTO: valueOrDash(ref.tipoProyecto, l.TIPO_PROYECTO),
    OBJETIVOS: objetivos.text,
    TAREAS: tareas.text,
    RESULTADOS: resultados.text,
    TECNOLOGIAS: tecnologiasText,
    METODOLOGIAS: metodologias.text,
    CPV: valueOrDash(ref.cpv, l.CPV),
    PALABRAS_CLAVE: palabrasClaveText,
    PERFILES_PROFESIONALES: perfilesText,
    FUENTES: uniqueSources(ref, profile),
    N: String(idx).padStart(2, '0')
  };
}

function promptText(value, maxChars) {
  const s = clean(value);
  if (!s || isNoData(s)) return '';
  return s.length > maxChars ? s.slice(0, maxChars).trim() + '...' : s;
}

function referenceForPrompt(ref, layoutRef, profile) {
