}

function normalizeFilePath(filePath) {
  if (typeof filePath !== 'string') return null;
  const trimmed = filePath.trim();
  return trimmed ? path.normalize(trimmed) : null;
}

function pathStartsWith(parentPath, childPath) {
  const parent = normalizeFilePath(parentPath);
  const child = normalizeFilePath(childPath);
  if (!parent || !child) return false;
  const rel = path.relative(parent, child);
  return rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel));
}

function isValidRespuestasPath(filePath, sessionId, projectPath) {
  const candidate = normalizeFilePath(filePath);
  if (!candidate || path.basename(candidate) !== 'respuestas.json') return false;

  const allowedDirs = [
    sessionId ? path.join(FILES_ROOT, 'codex-workspace', sessionId, 'codex-docs', 'output') : null,
    projectPath ? path.join(projectPath, 'codex-docs', 'output') : null
  ].filter(Boolean);

  return allowedDirs.some((dir) => pathStartsWith(dir, candidate));
}

function shortId(value) {
