    if (fs.existsSync(sessionStatePath)) {
      const raw = fs.readFileSync(sessionStatePath, 'utf8').trim();
      state = raw ? JSON.parse(raw) : {};
    }
  } catch (_err) {
    state = {};
  }

  if (!state || typeof state !== 'object' || Array.isArray(state)) {
    state = {};
  }

  state._id = state._id || sessionId;
  state.sessionId = state.sessionId || sessionId;
  state.createdAt = state.createdAt || now;
  state.updatedAt = now;

  deepMerge(state, patch || {});

  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(tmpPath, JSON.stringify(state, null, 2), 'utf8');
  fs.renameSync(tmpPath, sessionStatePath);
}

function asArray(v) {
  if (Array.isArray(v)) return v;
  if (v && typeof v === 'object') return [v];
  return [];
}

function normalizePart(v, fallback) {
  const s = String(v || fallback || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .toLowerCase();

  return s || fallback;
}

function normalizeText(v) {
  return String(v ?? '')
    .normalize('NFC')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\u00A0/g, ' ')
    .trim();
}

function firstText() {
  for (const value of arguments) {
    if (value !== undefined && value !== null) {
      const text = normalizeText(value);
      if (text) return text;
    }
  }
  return '';
}

function keyNorm(value) {
  return normalizeText(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function getRuleFromEntry(entry, fallback) {
  if (!entry || typeof entry !== 'object') return fallback;

  return firstText(
    entry.rule,
    entry.campo,
    entry.key,
    entry.nombre,
    entry.name,
    entry.header,
    entry.label,
    fallback
  );
}

function getRespuestaValue(value) {
  if (value == null) return '';

  if (typeof value !== 'object' || Array.isArray(value)) {
    return String(value ?? '');
  }

  const candidates = [
    value.respuesta,
    value.valor,
    value.aiSuggestion,
    value.answer,
    value.value,
    value.texto,
    value.text
  ];

  for (const candidate of candidates) {
    if (candidate !== undefined && candidate !== null) {
      return String(candidate);
    }
  }

  return '';
}

function normalizeFragment(frag) {
  if (!frag) return null;

  if (typeof frag !== 'object' || Array.isArray(frag)) {
    const text = normalizeText(frag);
    return text ? { fuente: '', texto: text } : null;
  }

  const fuente = firstText(
    frag.fuente,
    frag.source,
    frag.referencePage,
    frag.page,
    frag.file,
    frag.document,
    frag.filename
  );

  const texto = firstText(
    frag.texto,
    frag.text,
    frag.fragmento,
    frag.fragment,
    frag.content,
    frag.value
  );

  if (!fuente && !texto) return null;

  return { fuente, texto };
}

function getFragmentosValue(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return [];

  const raw =
    value.fragmentosDeReferencia ||
    value.fragments ||
    value.references ||
    value.fragmentos ||
    [];

  return asArray(raw)
    .map(normalizeFragment)
    .filter(Boolean);
}

function buildReferenceTextForAi(fragmentos) {
  return fragmentos
    .map((f) => [f.fuente, f.texto].filter(Boolean).join(': '))
    .filter(Boolean)
    .join('\n\n');
}

function buildReferencePage(fragmentos) {
  return fragmentos
    .map((f) => f.fuente)
    .filter(Boolean)
    .join(' | ');
}

function canonicalItem(ruleRaw, value, fallbackRule) {
  const rule = normalizeText(ruleRaw || fallbackRule || 'Campo');
  const respuesta = getRespuestaValue(value);
  const fragmentos = getFragmentosValue(value);
  const referenceTextForAi = buildReferenceTextForAi(fragmentos);
  const referencePage = buildReferencePage(fragmentos);

  return {
    rule,
    respuesta,
    valor: respuesta,
    aiSuggestion: respuesta,
    fragmentosDeReferencia: fragmentos,
    referenceTextForAi,
    referencePage: referencePage || ''
  };
}

function normalizeDataObjectToObject(obj) {
  const out = {};
  for (const [ruleRaw, value] of Object.entries(obj || {})) {
    if (ruleRaw === '_comment') continue;
    const rule = normalizeText(ruleRaw);
    if (!rule) continue;
    out[rule] = canonicalItem(rule, value, rule);
  }
  return out;
}

function normalizeArrayToItems(arr) {
  const items = [];
  (Array.isArray(arr) ? arr : []).forEach((entry, i) => {
    if (!entry || typeof entry !== 'object') return;
    const rule = getRuleFromEntry(entry, 'Campo_' + (i + 1));
    if (!rule) return;
    items.push(canonicalItem(rule, entry, 'Campo_' + (i + 1)));
  });
  return items;
}

function normalizePlainObjectToItems(obj) {
  const items = [];
  for (const [ruleRaw, value] of Object.entries(obj || {})) {
    if (ruleRaw === '_comment') continue;
    const rule = normalizeText(ruleRaw);
    if (!rule) continue;
    items.push(canonicalItem(rule, value, rule));
  }
  return items;
}

function flattenLotesForTemplates(generalObj, lotesArr) {
  const items = [];
  for (const [rule, value] of Object.entries(generalObj || {})) {
    if (rule === '_comment') continue;
    items.push(canonicalItem(rule, value, rule));
  }
  (Array.isArray(lotesArr) ? lotesArr : []).forEach((lote, loteIdx) => {
    const loteName = normalizeText(lote?.lote || 'Lote ' + (loteIdx + 1));
    const campos = lote?.campos || {};
    for (const [rule, value] of Object.entries(campos || {})) {
      if (rule === '_comment') continue;
      const item = canonicalItem(rule, value, rule);
      item.lote = loteName;
      items.push(item);
    }
  });
  return items;
}

