function isNoDataText(value) {
  const s = keyNorm(value);
  return !s || s === 'no hallado' || s === 'no encontrado' || s === 'no disponible' || s === 'n a' || s === 'na' || s === 'null' || s === '-';
}

function buildFieldMap(obj) {
  const map = new Map();
  for (const [rawKey, value] of Object.entries(obj || {})) {
    const nk = keyNorm(rawKey);
    if (!nk) continue;
    map.set(nk, value);
  }
  return map;
}

function findItemInObject(obj, aliases) {
  const map = buildFieldMap(obj);
  const normalizedAliases = (aliases || []).map(keyNorm).filter(Boolean);
  for (const alias of normalizedAliases) {
    if (map.has(alias)) return map.get(alias);
  }
  for (const [key, value] of map.entries()) {
    if (normalizedAliases.some((alias) => key.includes(alias) || alias.includes(key))) {
      return value;
    }
  }
  return null;
}

function pickItem(localObj, generalObj, fieldName) {
  const aliases = FIELD_ALIASES[fieldName] || [fieldName];
  const local = findItemInObject(localObj, aliases);
  if (local && !isNoDataText(local.respuesta)) return local;
  const general = findItemInObject(generalObj, aliases);
  if (general && !isNoDataText(general.respuesta)) return general;
  return local || general || canonicalItem(FIELD_LABELS[fieldName] || fieldName, { respuesta: '' }, FIELD_LABELS[fieldName] || fieldName);
}

function itemText(localObj, generalObj, fieldName) {
  const item = pickItem(localObj, generalObj, fieldName);
  return normalizeText(item?.respuesta || '');
}

function itemFragments(localObj, generalObj, fieldName) {
  const item = pickItem(localObj, generalObj, fieldName);
  return asArray(item?.fragmentosDeReferencia).filter(Boolean);
}

function uniqueStrings(values, maxCount) {
  const seen = new Set();
  const out = [];
  for (const value of values || []) {
    const s = normalizeText(value);
    if (!s) continue;
    const k = keyNorm(s);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(s);
    if (maxCount && out.length >= maxCount) break;
  }
  return out;
}

function collectSources(fragments, maxCount) {
  return uniqueStrings((fragments || []).map((f) => f && f.fuente), maxCount || 10);
}

function buildPptxReference(localObj, generalObj, label, index) {
  const allFragments = [];
  for (const fieldName of Object.keys(FIELD_ALIASES)) {
    allFragments.push(...itemFragments(localObj, generalObj, fieldName));
  }

  const titulo = itemText(localObj, generalObj, 'titulo') || normalizeText(label) || 'Referencia ' + index;
  const cliente = itemText(localObj, generalObj, 'cliente');
  const sector = itemText(localObj, generalObj, 'sector');
  const pais = itemText(localObj, generalObj, 'pais');
  const fechaInicio = itemText(localObj, generalObj, 'fechaInicio');
  const fechaFin = itemText(localObj, generalObj, 'fechaFin');
  const duracion = itemText(localObj, generalObj, 'duracion');
  const importe = itemText(localObj, generalObj, 'importe');
  const volumenUsuarios = itemText(localObj, generalObj, 'volumenUsuarios');
  const idiomaTrabajo = itemText(localObj, generalObj, 'idiomaTrabajo');
  const tipoServicio = itemText(localObj, generalObj, 'tipoServicio');
  const tipoProyecto = itemText(localObj, generalObj, 'tipoProyecto');

  return {
    index,
    lote: normalizeText(label || ''),
    titulo,
    cliente,
    sector,
    pais,
    fechaInicio,
    fechaFin,
    fechas: [fechaInicio, fechaFin].filter(Boolean).join(' - '),
    duracion,
    importe,
    volumenUsuarios,
    idiomaTrabajo,
    tipoServicio,
    tipoProyecto,
    objetivos: itemText(localObj, generalObj, 'objetivos'),
    tareas: itemText(localObj, generalObj, 'tareas'),
    resultados: itemText(localObj, generalObj, 'resultados'),
    tecnologias: itemText(localObj, generalObj, 'tecnologias'),
    metodologias: itemText(localObj, generalObj, 'metodologias'),
    cpv: itemText(localObj, generalObj, 'cpv'),
    palabrasClave: itemText(localObj, generalObj, 'palabrasClave'),
    perfilesProfesionales: itemText(localObj, generalObj, 'perfiles'),
    fuentes: collectSources(allFragments, 12),
    fragmentosDeReferencia: allFragments,
    rawFields: {
      ...(generalObj || {}),
      ...(localObj || {})
    }
  };
}

function buildReferencesFromPayload(normalizedGeneral, normalizedLotes, simpleObj) {
  if (Array.isArray(normalizedLotes) && normalizedLotes.length > 0) {
    const refs = [];

    const generalRef = buildPptxReference(normalizedGeneral || {}, {}, 'General', 1);
    generalRef.slideKind = 'general';
    generalRef.referenceType = 'general';
    generalRef.isGeneral = true;
    generalRef.lote = 'General';
    generalRef.loteIndex = 0;
    refs.push(generalRef);

    normalizedLotes.forEach((lote, idx) => {
      const loteName = normalizeText(lote?.lote || ('Lote ' + (idx + 1)));
      const ref = buildPptxReference(lote.campos || {}, normalizedGeneral || {}, loteName, idx + 2);
      ref.slideKind = 'lote';
      ref.referenceType = 'lote';
      ref.isGeneral = false;
      ref.lote = loteName;
      ref.loteIndex = idx + 1;
      refs.push(ref);
    });

    return refs;
  }

  if (normalizedGeneral && Object.keys(normalizedGeneral).length) {
    const ref = buildPptxReference(normalizedGeneral, {}, '', 1);
    ref.slideKind = 'single';
    ref.referenceType = 'single';
    ref.isGeneral = false;
    return [ref];
  }

  const ref = buildPptxReference(simpleObj || {}, {}, '', 1);
  ref.slideKind = 'single';
  ref.referenceType = 'single';
  ref.isGeneral = false;
  return [ref];
}

const { userKey, sessionId, projectPath, sessionStatePath } = resolveSessionContext(msg);

if (!sessionId) {
  node.error('No sessionId available', msg);
  return null;
}

msg.sessionId = sessionId;
msg.projectPath = projectPath;
msg.sessionStatePath = sessionStatePath;

const requestedPath = normalizeFilePath(msg.respuestasJsonPath);
const submissionPath = normalizeFilePath(msg.submission?.respuestasJsonPath);

if (requestedPath && !isValidRespuestasPath(requestedPath, sessionId, projectPath)) {
  node.warn('[ANTI-CONTAMINATION] plantilla ignored msg.respuestasJsonPath for ' + userKey + ': ' + requestedPath);
}

if (submissionPath && !isValidRespuestasPath(submissionPath, sessionId, projectPath)) {
  node.warn('[ANTI-CONTAMINATION] plantilla ignored submission.respuestasJsonPath for ' + userKey + ': ' + submissionPath);
}

const respuestasPath = [
  isValidRespuestasPath(requestedPath, sessionId, projectPath) ? requestedPath : null,
  isValidRespuestasPath(submissionPath, sessionId, projectPath) ? submissionPath : null,
  sessionId ? path.join(FILES_ROOT, 'codex-workspace', sessionId, 'codex-docs', 'output', 'respuestas.json') : null,
  projectPath ? path.join(projectPath, 'codex-docs', 'output', 'respuestas.json') : null
].filter(Boolean).find((candidate) => fs.existsSync(candidate));

if (!respuestasPath) {
  node.error('No respuestas.json resolved for user=' + userKey + ' session=' + sessionId, msg);
  return null;
}

let parsed;
try {
  parsed = JSON.parse(fs.readFileSync(respuestasPath, 'utf8'));
} catch (err) {
  node.error('Error reading/parsing respuestas.json: ' + err.message, msg);
  return null;
}

const isLotesFormat =
  parsed &&
  typeof parsed === 'object' &&
  !Array.isArray(parsed) &&
  parsed.general &&
  typeof parsed.general === 'object' &&
  !Array.isArray(parsed.general);

let payloadData;
let itemCount = 0;
let loteCount = 0;
let references = [];

if (isLotesFormat) {
  if (parsed.lotes != null && !Array.isArray(parsed.lotes)) {
    node.error('Invalid lotes format: lotes must be an array', msg);
    return null;
  }

  const normalizedGeneral = normalizeDataObjectToObject(parsed.general || {});
  const normalizedLotes = (Array.isArray(parsed.lotes) ? parsed.lotes : [])
    .filter((lote) => lote && typeof lote === 'object')
    .map((lote, idx) => {
      const loteName = normalizeText(lote.lote || lote.nombre || lote.name || 'Lote ' + (idx + 1));
      const campos = lote.campos && typeof lote.campos === 'object' && !Array.isArray(lote.campos)
        ? normalizeDataObjectToObject(lote.campos)
        : {};
      return { ...lote, lote: loteName, campos };
    });

  const flatItems = flattenLotesForTemplates(normalizedGeneral, normalizedLotes);
  references = buildReferencesFromPayload(normalizedGeneral, normalizedLotes, null);

  payloadData = {
    general: normalizedGeneral,
    lotes: normalizedLotes,
    items: flatItems,
    references,
    referenceGeneration: {
      mode: 'general_lotes',
      inheritGeneralFields: true,
      generalSlide: true,
      lotesCount: normalizedLotes.length,
      fields: FIELD_LABELS
    },
    slideOrder: references.map((ref) => ({
      index: ref.index,
      type: ref.slideKind || ref.referenceType || 'reference',
      label: ref.lote || ref.titulo || ('Referencia ' + ref.index)
    }))
  };

  itemCount = flatItems.length;
  loteCount = normalizedLotes.length;
} else {
  let items = [];
  let simpleObj = {};

  if (Array.isArray(parsed)) {
    items = normalizeArrayToItems(parsed);
    for (const item of items) simpleObj[item.rule] = item;
  } else if (parsed && typeof parsed === 'object') {
    items = normalizePlainObjectToItems(parsed);
    simpleObj = normalizeDataObjectToObject(parsed);
  } else {
    node.error('Unsupported respuestas.json format', msg);
    return null;
  }

  if (!items.length) {
    node.error('No items generated from respuestas.json', msg);
    return null;
  }

  references = buildReferencesFromPayload(null, null, simpleObj);

  payloadData = {
    items,
    references,
    referenceGeneration: {
      mode: 'single',
      inheritGeneralFields: false,
      fields: FIELD_LABELS
    }
  };

  itemCount = items.length;
}

const state = loadSessionState(sessionStatePath);

function normalizeTemplateCandidate(value) {
  if (value === undefined || value === null) return '';

  if (typeof value === 'string') {
    return value.trim();
  }

  if (typeof value === 'object') {
    return firstText(
      value.value,
      value.label,
      value.name,
      value.filename,
      value.fileName,
      value.originalName,
      value.path
    );
  }

  return String(value).trim();
}

function isValidTemplateCandidate(value) {
  const s = normalizeTemplateCandidate(value);
  if (!s) return false;
  if (s === '__blank_docx__') return true;
  const ext = path.extname(s).toLowerCase();
  return ext === '.docx' || ext === '.pptx';
}

function inferOutputTypeFromTemplate(templateName) {
  const s = normalizeTemplateCandidate(templateName);
  if (!s || s === '__blank_docx__') return 'docx';
  const ext = path.extname(s).toLowerCase();
  return ext === '.pptx' ? 'pptx' : 'docx';
}

function resolveSelectedTemplate(msg, state) {
  const candidates = [
    // 1) Seleccion viva del formulario. En este flujo la plantilla real llega aqui:
    //    msg.payload.submission.plantilla = "PPTX_General.pptx".
    ['msg.payload.submission.plantilla', msg.payload?.submission?.plantilla],
    ['msg.payload.submission.template', msg.payload?.submission?.template],
    ['msg.payload.submission.data.plantilla', msg.payload?.submission?.data?.plantilla],
    ['msg.payload.submission.data.template', msg.payload?.submission?.data?.template],
    ['msg.payload.context.plantilla', msg.payload?.context?.plantilla],
    ['msg.payload.context.template', msg.payload?.context?.template],
    ['msg.payload.data.context.plantilla', msg.payload?.data?.context?.plantilla],
    ['msg.payload.data.context.template', msg.payload?.data?.context?.template],
    ['msg.payload.data.plantilla', msg.payload?.data?.plantilla],
    ['msg.payload.data.template', msg.payload?.data?.template],
    ['msg.payload.plantilla', msg.payload?.plantilla],
    ['msg.payload.template', msg.payload?.template],

    // 2) Campos explicitos ya sincronizados por el lock de plantilla.
    ['msg.selectedTemplate', msg.selectedTemplate],
    ['msg.templateName', msg.templateName],
    ['msg.context.plantilla', msg.context?.plantilla],
    ['msg.context.template', msg.context?.template],
    ['msg.plantilla', msg.plantilla],
    ['msg.template', msg.template],

    // 3) Seleccion bloqueada en SESSION_STATE al lanzar la ejecucion.
    ['state.context.plantilla', state?.context?.plantilla],
    ['state.context.template', state?.context?.template],
    ['state.selection.plantilla', state?.selection?.plantilla],
    ['state.selection.template', state?.selection?.template],

    // 4) Fallback legacy. Lo dejamos al final porque en Results puede venir con defaults antiguos.
    ['msg.submission.plantilla', msg.submission?.plantilla],
    ['msg.submission.template', msg.submission?.template],
    ['msg.submission.data.plantilla', msg.submission?.data?.plantilla],
    ['msg.submission.data.template', msg.submission?.data?.template],
    ['msg.onInitSubmission.plantilla', msg.onInitSubmission?.plantilla],
    ['msg.onInitSubmission.template', msg.onInitSubmission?.template],
    ['msg.onInitSubmission.data.plantilla', msg.onInitSubmission?.data?.plantilla],
    ['msg.onInitSubmission.data.template', msg.onInitSubmission?.data?.template]
  ];

  const valid = [];
  for (const [source, value] of candidates) {
    if (isValidTemplateCandidate(value)) {
      valid.push({
        source,
        templateName: normalizeTemplateCandidate(value),
        outputType: inferOutputTypeFromTemplate(value)
      });
    }
  }

  if (!valid.length) {
    return { templateName: '', source: 'not_found', candidates: [] };
  }

  const chosen = valid[0];
  const uniqueValues = Array.from(new Set(valid.map((x) => x.templateName)));
  if (uniqueValues.length > 1) {
    node.warn('[TEMPLATE-CONFLICT] chosen=' + chosen.templateName + ' from=' + chosen.source + ' candidates=' + valid.map((x) => x.source + '=' + x.templateName).join(' | '));
  }

  return {
    templateName: chosen.templateName,
    source: chosen.source,
    candidates: valid
  };
}

function resolveSectorOutputFormat(msg, state) {
  const candidates = [
    msg.sector_outputformat,
    msg.payload?.sector_outputformat,
    msg.payload?.submission?.sector_outputformat,
    msg.payload?.submission?.data?.sector_outputformat,
    msg.payload?.context?.sector_outputformat,
    msg.payload?.data?.sector_outputformat,
    msg.submission?.sector_outputformat,
    msg.submission?.data?.sector_outputformat,
    msg.onInitSubmission?.sector_outputformat,
    msg.onInitSubmission?.data?.sector_outputformat,
    msg.context?.sector_outputformat,
    state?.selection?.sector_outputformat,
    state?.context?.sector_outputformat,
    'general'
  ];

  for (const value of candidates) {
    const raw = normalizeText(value).toLowerCase();
    if (['general', 'sector_publico', 'sector_privado'].includes(raw)) return raw;
  }

  return 'general';
}

const selectedTemplateInfo = resolveSelectedTemplate(msg, state);
const templateName = selectedTemplateInfo.templateName;
const selectedTemplateSource = selectedTemplateInfo.source;
const sector_outputformat = resolveSectorOutputFormat(msg, state);

if (!templateName) {
  node.error('Template not selected', msg);
  return null;
}

const templateExt = path.extname(templateName).toLowerCase();
if (templateName !== '__blank_docx__' && !['.docx', '.pptx'].includes(templateExt)) {
  node.error('Invalid template: ' + templateName, msg);
  return null;
}

const outputType = (templateName === '__blank_docx__' || templateExt === '.docx') ? 'docx' : 'pptx';

const rawUnidad = msg.unit || msg.submission?.unidad || msg.submission?.data?.unidad ||
  msg.onInitSubmission?.unidad || msg.onInitSubmission?.data?.unidad ||
  state?.context?.unidad || state?.context?.unit || 'unidad';

const rawProyecto = msg.project || msg.submission?.proyecto || msg.submission?.data?.proyecto ||
  msg.onInitSubmission?.proyecto || msg.onInitSubmission?.data?.proyecto ||
  state?.context?.proyecto || state?.context?.project || 'proyecto';

const unidad = normalizePart(rawUnidad, 'unidad');
const proyecto = normalizePart(rawProyecto, 'proyecto');

// --- Naming por fuente (unidad/cliente/proyecto/oportunidad) ---
