const ctxNaming = (state && state.context) ? state.context : {};
let selectedSourcesNaming = Array.isArray(ctxNaming.selectedSources) && ctxNaming.selectedSources.length
    ? ctxNaming.selectedSources
    : (Array.isArray(msg.selectedSources) && msg.selectedSources.length
        ? msg.selectedSources
        : (Array.isArray(msg.submission?.selectedSources) && msg.submission.selectedSources.length
            ? msg.submission.selectedSources
            : [String(ctxNaming.sourceType || msg.sourceType || 'processed')]));
const hasProcessed = selectedSourcesNaming.indexOf('processed') >= 0;
const hasOpportunity = selectedSourcesNaming.indexOf('opportunity') >= 0;

const rawCliente = normalizeText(firstRef.cliente) || ctxNaming.opportunityCustomer || msg.customerName || 'cliente';
const rawOportunidad = ctxNaming.opportunityTitle || msg.selectedOpportunity?.title || rawProyecto || 'oportunidad';
const rawTitulo = normalizeText(firstRef.titulo) || rawProyecto;

const cliente = normalizePart(rawCliente, 'cliente');
const oportunidad = normalizePart(rawOportunidad, 'oportunidad');
const proyectoDoc = normalizePart(rawTitulo, 'proyecto');

const now = new Date();
const pad = n => String(n).padStart(2, '0');
const stamp = pad(now.getMonth() + 1) + pad(now.getDate()) + '_' + pad(now.getHours()) + pad(now.getMinutes()) + pad(now.getSeconds());

let nameParts;
if (hasOpportunity) {
    // Oportunidad sola o mezclada -> unidad_cliente_oportunidad
    nameParts = [unidad, cliente, oportunidad];
} else if (selectedSourcesNaming.length === 1 && hasProcessed) {
    // Solo procesado -> unidad_proyecto
    nameParts = [unidad, proyecto];
