const outputFilename = nameParts.filter(Boolean).join('_') + '_' + stamp + '.' + outputType;

node.warn('[naming] plantilla sources=' + selectedSourcesNaming.join(',') + ' -> ' + outputFilename);

msg.unit = rawUnidad;
msg.project = rawProyecto;
msg.plantilla = templateName;
msg.templateName = templateName;
msg.selectedTemplateSource = selectedTemplateSource;
msg.sector_outputformat = sector_outputformat;
msg.outputType = outputType;
msg.references = references;

msg.submission = msg.submission || {};
msg.submission.data = msg.submission.data || {};
msg.submission.data.template = templateName;
msg.submission.data.plantilla = templateName;
msg.submission.plantilla = templateName;
msg.submission.outputType = outputType;
msg.submission.sector_outputformat = sector_outputformat;
msg.submission.data.sector_outputformat = sector_outputformat;
msg.submission.unidad = msg.submission.unidad || rawUnidad;
msg.submission.proyecto = msg.submission.proyecto || rawProyecto;

saveSessionPatch(sessionId, sessionStatePath, {
  selection: {
    template: templateName,
    plantilla: templateName,
    outputType,
    sector_outputformat,
    source: selectedTemplateSource
  },
  context: {
    unidad: rawUnidad,
    proyecto: rawProyecto,
    unit: rawUnidad,
    project: rawProyecto,
    template: templateName,
    plantilla: templateName,
    outputType,
