  },
  output: {
    pptxReferenceCount: references.length,
    pptxReferenceMode: payloadData.referenceGeneration?.mode || 'unknown'
  }
});

payloadData.sector_outputformat = sector_outputformat;

if (outputType === 'pptx') {
  payloadData.layoutProfile = PPTX_LAYOUT_PROFILE;
  msg.pptxLayoutProfile = PPTX_LAYOUT_PROFILE;
}

msg.payload = {
  outputType,
  template: templateName,
  filename: outputFilename,
  title: 'Referencias generadas',
  data: payloadData,
  templateSource: selectedTemplateSource,
  sector_outputformat
};

const slideOrderLog = references.map((ref) => String(ref.index).padStart(2, '0') + ':' + (ref.slideKind || ref.referenceType || 'reference') + ':' + (ref.lote || ref.titulo || 'Referencia')).join(' | ');
node.warn('Payload ' + outputType.toUpperCase() + ' prepared for ' + userKey + ': items=' + itemCount + ', lotes=' + loteCount + ', references=' + references.length + ', template=' + templateName + ', templateSource=' + selectedTemplateSource + ', sector_outputformat=' + sector_outputformat + ', slideOrder=' + slideOrderLog);
return msg;

